using INPS.DNA.Data;
using INPS.DNA.Logging;
using INPS.Pensioni.Liquidazione.BLCommon;
using INPS.Pensioni.Liquidazione.DataCommon;
using INPS.Pensioni.Liquidazione.ServiceReferences.WebDom;
using System;
using System.Collections;
using System.Collections.Generic;
using System.Configuration;
using System.Data;
using System.Linq;
using System.Reflection;
using System.Transactions;

namespace INPS.Pensioni.Liquidazione
{
    public class GestioneAreaRiepilogo
    {
        #region public members
        public static bool GetRiepilogo(Entity.ParametriARCA parametriARCA, short sedeOperatore, short centroOperativoOperatore, string matricolaOperatore, string chiaveRicerca,
            Utility.TipoAppartenenza tipoAppRuolo, Utility.Ruolo ruolo, bool isPaginaConferma, bool isConsultazione, byte? progStorico, Entity.DatiPersonaliParziali datiParzialiDA,
            out List<Entity.Anagrafica> elencoAnagrafiche, out List<Entity.Domanda> elencoDomande, out List<Entity.Pensione> elencoPensioni,
            out GestioneEsitoCalcolo.DatiEsitoCalcolo datiEsitoCalcolo, out Utility.TipoAppartenenza? tipoAppartenenza, out Utility.TipoFondo? tipoFondo, out bool isDomandaDB,
            out string urlDPI, out bool isDomandaENPALS, out bool isDomandaINPDAP, out bool isDomandaCalcolataProvvisoria, out bool isDomandaRiapertura,
            out string sedeDiversa, out bool isRicercaManualeDA, out bool isNuovoCertificatoGeneratoEnpals, out string errori, out string msgNonBloccante,
            out bool mostraPanelloMessBloccantePensioniOvunque, out string sedePensioneGP1ALZ6, out string codCategoriaPensione, out string certificatoInseguimentoPensione,
            bool isPaginaVisualizzazioneStatoPratiche, out bool mostraPopupMemo239, out bool mostraPopupMemo312023)
        {
            errori = string.Empty;
            msgNonBloccante = string.Empty;
            elencoAnagrafiche = null;
            elencoDomande = null;
            elencoPensioni = null;
            datiEsitoCalcolo = null;
            tipoAppartenenza = null;
            tipoFondo = null;
            isDomandaDB = false;
            urlDPI = string.Empty;
            isDomandaENPALS = false;
            isDomandaINPDAP = false;
            isDomandaRiapertura = false;
            isDomandaCalcolataProvvisoria = false;
            sedeDiversa = string.Empty;
            isRicercaManualeDA = false;
            bool isDomandaLavorabilePerEccezione = false;
            bool? isPLUnicarpeFromDB = null;
            bool? isPLPrepensionamentoEditoriaTipo0162FiltroEAA = null;
            bool? isPLPrepensionamentoEditoriaTipo0162FiltroEBA = null;
            bool? isPLESPAFiltroL26 = null;
            bool? isPLVESO33FiltroDAP = null;
            isNuovoCertificatoGeneratoEnpals = false;
            //ENG - Pensioni Ovunque: gestione nuovo pannello
            mostraPanelloMessBloccantePensioniOvunque = false;
            sedePensioneGP1ALZ6 = string.Empty;
            codCategoriaPensione = string.Empty;
            certificatoInseguimentoPensione = string.Empty;
            string codTipoRichiesta = string.Empty;
            mostraPopupMemo239 = false;
            mostraPopupMemo312023 = false;

            try
            {
                List<ServiceReferences.WebDom.DatiDomanda> elencoDatiDomanda = null;
                bool bTest = false;
                Int64 result = 0;

                //se la chiave di ricerca è un intero, allora la chiave di ricerca è il numero domanda
                if (Int64.TryParse(chiaveRicerca, out result))
                {
                    List<GestionePensione.DatiPensione> listaDatiDomandaDB = null;
                    GestionePensione.DatiPensione datiDomandaDB = null;
                    //Recupero i dati della domanda dal DB
                    if (progStorico.HasValue)
                        GestionePensione.GetPensioneByNumeroDomandaAndProg(Int64.Parse(chiaveRicerca), progStorico, out datiDomandaDB);
                    else
                    {
                        GestionePensione.GetPensioniByNumeroDomanda(Int64.Parse(chiaveRicerca), out listaDatiDomandaDB);

                        // Se è presente la domanda con ProgStorico pari a NULL elaboro quella, altrimenti elaboro quella con ProgStorico più grande
                        if (listaDatiDomandaDB != null && listaDatiDomandaDB.Count > 0)
                        {
                            datiDomandaDB = listaDatiDomandaDB.Find(x => !x.ProgStorico.HasValue);
                            if (datiDomandaDB == null)
                                datiDomandaDB = listaDatiDomandaDB.OrderByDescending(x => x.ProgStorico.Value).First();
                        }
                    }

                    //BLOCCO DOMANDE NON LAVORABILI
                    if (datiDomandaDB != null && datiDomandaDB.StatoPensione == (int)Utility.StatoPensione.NonLavorabile)
                    {
                        errori = "Domanda " + datiDomandaDB.NDomus + " nello stato 'NON LAVORABILE'. Eliminarla prima di poterla riacquisire.";
                        return true;
                    }

                    ServiceReferences.WebDom.DatiDomanda datiDomandaWebDom = null;
                    string siglaCategoriaPensione = string.Empty;
                    short sedePensione = 0;
                    int nCertificatoPensione = 0;

                    if (datiDomandaDB != null && datiDomandaDB.StatoPensione == (int)Utility.StatoPensione.Calcolata &&
                        (Utility.GetTipoDomanda(datiDomandaDB.Gruppo, datiDomandaDB.Prodotto) == Utility.TipoDomanda.Normale ||
                        Utility.GetTipoDomanda(datiDomandaDB.Gruppo, datiDomandaDB.Prodotto) == Utility.TipoDomanda.Ripristino || Utility.GetTipoDomanda(datiDomandaDB.Gruppo, datiDomandaDB.Prodotto) == Utility.TipoDomanda.Riliquidazione ||
                        Utility.GetTipoDomanda(datiDomandaDB.Gruppo, datiDomandaDB.Prodotto) == Utility.TipoDomanda.Riliquidazione || Utility.GetTipoDomanda(datiDomandaDB.Gruppo, datiDomandaDB.Prodotto) == Utility.TipoDomanda.RiliquidazioneSuperstiti ||
                        (Utility.GetTipoDomanda(datiDomandaDB.Gruppo, datiDomandaDB.Prodotto) == Utility.TipoDomanda.Superstiti && !Utility.IsDomandaReversibilita(datiDomandaDB))))
                    {
                        GestioneWebDom.CodiceAttivita codAttivita = GestioneWebDom.GetAttivitaDiChiusura(datiDomandaDB);

                        switch (codAttivita)
                        {
                            case GestioneWebDom.CodiceAttivita.CalcoloProvvisorio:
                                GestioneWebDom.GetDomandaPerDomus(chiaveRicerca, out datiDomandaWebDom, out errori);

                                if (datiDomandaWebDom != null && datiDomandaWebDom.Dati != null && datiDomandaWebDom.Dati.Fase != null && datiDomandaWebDom.Dati.Fase.Count > 0 &&
                                    datiDomandaWebDom.Dati.Fase.LastOrDefault().CodFase == "0060")
                                    isDomandaCalcolataProvvisoria = true;
                                break;
                            case GestioneWebDom.CodiceAttivita.CalcoloProvvisorioEMENS:
                                GestioneWebDom.GetDomandaPerDomus(chiaveRicerca, out datiDomandaWebDom, out errori);

                                if (datiDomandaWebDom != null && datiDomandaWebDom.Dati != null && datiDomandaWebDom.Dati.Fase != null && datiDomandaWebDom.Dati.Fase.Count > 0 &&
                                    datiDomandaWebDom.Dati.Fase.LastOrDefault().CodFase == "0062")
                                    isDomandaCalcolataProvvisoria = true;
                                break;
                            case GestioneWebDom.CodiceAttivita.CalcoloProvvisorioDMAG:
                                GestioneWebDom.GetDomandaPerDomus(chiaveRicerca, out datiDomandaWebDom, out errori);

                                if (datiDomandaWebDom != null && datiDomandaWebDom.Dati != null && datiDomandaWebDom.Dati.Fase != null && datiDomandaWebDom.Dati.Fase.Count > 0 &&
                                    datiDomandaWebDom.Dati.Fase.LastOrDefault().CodFase == "0063")
                                    isDomandaCalcolataProvvisoria = true;
                                break;
                        }

                        if (!CheckTrasformazioniAbilitate(datiDomandaDB, isDomandaCalcolataProvvisoria))
                            isDomandaCalcolataProvvisoria = false;
                        else if (!isConsultazione && !string.IsNullOrEmpty(errori))
                            return false;
                        else
                            errori = string.Empty;

                        if (datiDomandaWebDom != null)
                        {
                            if (isDomandaCalcolataProvvisoria)
                            {
                                ServiceReferences.WebDom.DataSetDomanda.PensioneGenerataRow pensioneGenerata = datiDomandaWebDom.Dati.PensioneGenerata.FirstOrDefault(x => x.IndAnnullata == "0");
                                siglaCategoriaPensione = pensioneGenerata.SiglaCatLav;
                                short.TryParse((pensioneGenerata.CodProvinciaGenAttuale.Substring(1) + pensioneGenerata.CodZonaGenAttuale.Substring(1)).PadLeft(4, '0'), out sedePensione);
                                int.TryParse(pensioneGenerata.NumCertificatoGenAttuale.PadLeft(8, '0'), out nCertificatoPensione);
                            }
                        }
                    }

                    if (datiDomandaDB != null && datiDomandaDB.StatoPensione != (int)Utility.StatoPensione.NonLavorabile && (!isPaginaConferma || !(isDomandaCalcolataProvvisoria && !isConsultazione)))
                    {
                        isDomandaRiapertura = Utility.IsRiaperturaDomanda(datiDomandaDB.Id);

                        tipoAppartenenza = Utility.GetTipoAppartenenza(datiDomandaDB.IndConvInt, datiDomandaDB.Gestione);
                        //Controllo se la domanda è lavorabile da parte dell'operatore
                        if (tipoAppRuolo != tipoAppartenenza)
                        {
                            errori = "Ruolo Utente non abilitato alla lavorazione della domanda.";
                            return true;
                        }

                        if (Utility.IsRicostituzioneOrRiapertura(datiDomandaDB, isDomandaRiapertura))
                        {
                            if (Utility.IsPensioniOvunqueAttiva(tipoAppartenenza))
                            {
                                if (!datiDomandaDB.CodiceSedeGP1ALZ6.HasValue)
                                {
                                    if (datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.Calcolata
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoWebDom
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoFelpe
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoOneri
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoSAI
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoStazLavoro
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoTotal
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoSIN
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoBooking
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoTot
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoNoteDebito
                                        && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNo6Scatti)
                                    {
                                        errori = "In seguito alle modifiche relative al trasferimento di sede delle pensioni comunicato con avviso del 15 maggio 2023 è necessario cancellare e riprelevare la ricostituzione";
                                        return true;
                                    }
                                }
                            }
                            else
                            {
                                if (datiDomandaDB.CodiceSedeGP1ALZ6.HasValue)
                                {
                                    if (datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.Calcolata)
                                    {
                                        errori = "Il processo di Pensioni Ovunque non è attivo. Si prega di cancellare e riprelevare la domanda.";
                                        return true;
                                    }
                                }
                            }
                        }

                        //ENG - Aggiornamento Memo86
                        if (Utility.IsRicostituzione(datiDomandaDB.Gruppo) && !Utility.IsDomandaEccezioneMemo86(datiDomandaDB)
                            && Utility.DataStrettamenteSuccessivaA(datiDomandaDB.DataPresentazioneDomanda, new DateTime(2022, 02, 20)))
                        {
                            GestioneControlliDinamici.ControlloDinamico controlloDinamicoAggiornamentoMemo86 = null;
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DataAttivazioneMemo86Del12_06_2023", out controlloDinamicoAggiornamentoMemo86);

                            if (controlloDinamicoAggiornamentoMemo86 != null && !String.IsNullOrEmpty(controlloDinamicoAggiornamentoMemo86.ValoreControllo) && !String.IsNullOrEmpty(controlloDinamicoAggiornamentoMemo86.ValoreControllo.Trim()))
                            {
                                DateTime? dataAttivazioneAggiornamentoMemo86 = Utility.DataFromString(controlloDinamicoAggiornamentoMemo86.ValoreControllo.Trim(), Utility.FormatoData.AAAAmmGG);
                                DateTime? dataPrelievoDomanda = null;
                                GestioneLogSoap.GetTimestampMinimo(datiDomandaDB.NDomus, out dataPrelievoDomanda);

                                if (dataAttivazioneAggiornamentoMemo86.HasValue && dataPrelievoDomanda.HasValue && !Utility.DataSuccessivaA(dataPrelievoDomanda.Value, dataAttivazioneAggiornamentoMemo86.Value)
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.Calcolata
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoWebDom
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoFelpe
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoOneri
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoSAI
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoStazLavoro
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoTotal
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoSIN
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoBooking
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoTot
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNoNoteDebito
                                    && datiDomandaDB.StatoPensione.GetValueOrDefault() != (byte)Utility.StatoPensione.CalcolataNo6Scatti)
                                {
                                    errori = "In seguito all'aggiornamento del Memo 86 del 12 Giugno 2023 è necessario cancellare e riprelevare la domanda";
                                    return true;
                                }
                            }
                        }

                        short sedeDomandaDB = Utility.GetCodiceSedeLavorazione(datiDomandaDB, isDomandaRiapertura);
                        byte? centroOperativoDomandaDB = Utility.GetCentroOperativoLavorazione(datiDomandaDB, isDomandaRiapertura);
                        short sedeChiavePensioneDB = (datiDomandaDB.CodiceSedeDestinazione.HasValue) ? datiDomandaDB.CodiceSedeDestinazione.Value : datiDomandaDB.CodiceSede;
                        //controllo sede operatore - sede domanda
                        if (ConfigurationManager.AppSettings["BypassControlloSedi"] == null ||
                                ConfigurationManager.AppSettings["BypassControlloSedi"] != "SI")
                        {
                            //controllo sede operatore - sede domanda
                            if (isDomandaCalcolataProvvisoria && !isConsultazione)
                            {
                                //controllo sede operatore - sede domanda
                                short sedeDomanda = 0;
                                short centroOperativoDomanda = 0;
                                bool isErroreSedeDiversa = false;
                                if (!CheckSedi(datiDomandaWebDom, sedeOperatore, centroOperativoOperatore, out sedeDomanda, out centroOperativoDomanda))
                                {
                                    isErroreSedeDiversa = true;
                                    if (!GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiDomandaDB, GestioneBypassControllo.NomeBypass.Eliminazione_Controllo_Sede.ELIMINAZIONE_CONTROLLO_SEDE)
                                        || !isPaginaVisualizzazioneStatoPratiche)
                                    {
                                        errori = "La sede dell'operatore non coincide con la sede della domanda selezionata (" +
                                            sedeDomanda.ToString().PadLeft(4, '0') + centroOperativoDomanda.ToString().PadLeft(2, '0') + ").";
                                        sedeDiversa = sedeDomanda.ToString().PadLeft(4, '0') + centroOperativoDomanda.ToString().PadLeft(2, '0');
                                        return true;
                                    }
                                }
                                if (!isErroreSedeDiversa || !GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiDomandaDB, GestioneBypassControllo.NomeBypass.Eliminazione_Controllo_Sede.ELIMINAZIONE_CONTROLLO_SEDE) ||
                                    !isPaginaVisualizzazioneStatoPratiche)
                                {
                                    datiDomandaDB.CodiceSede = sedeDomanda;
                                    datiDomandaDB.CentroOperativo = (byte)centroOperativoDomanda;
                                }
                            }
                            else if (!CheckSedi(sedeDomandaDB, (centroOperativoDomandaDB.HasValue ? centroOperativoDomandaDB.Value : (short)0), sedeOperatore, centroOperativoOperatore))
                            {
                                errori = "La sede dell'operatore non coincide con la sede della domanda selezionata (" +
                                    sedeDomandaDB.ToString().PadLeft(4, '0') +
                                    (centroOperativoDomandaDB.HasValue ? centroOperativoDomandaDB.Value.ToString().PadLeft(2, '0') : "00") + ").";
                                sedeDiversa = sedeDomandaDB.ToString().PadLeft(4, '0') + centroOperativoDomandaDB.ToString().PadLeft(2, '0');
                                return true;
                            }
                        }

                        isDomandaLavorabilePerEccezione = BLCommon.GestioneCtrlBypassTipologieNonAbilitate.IsDomandaLavorabilePerEccezione(tipoAppartenenza, sedeDomandaDB, datiDomandaDB.Gruppo,
                            datiDomandaDB.Prodotto, datiDomandaDB.Tipo, datiDomandaDB.SiglaCategoria, datiDomandaDB.CodiceTipoRichiesta, Utility.IsDomandaINPDAP(datiDomandaDB.Gestione));

                        if (!isDomandaLavorabilePerEccezione)
                        {
                            //controllo Liquidazione abilitata
                            if (ConfigurationManager.AppSettings["BypassLiquidazioniAbilitate"] == null ||
                                ConfigurationManager.AppSettings["BypassLiquidazioniAbilitate"] != "SI")
                            {
                                //controllo Liquidazione abilitata
                                if (!CheckLiquidazioniAbilitate(datiDomandaDB, isDomandaRiapertura))
                                {
                                    errori = "La tipologia di domanda selezionata non è abilitata alla liquidazione.";
                                    return true;
                                }
                            }

                            if (!CheckTrasformazioniAbilitate(datiDomandaDB, isDomandaRiapertura))
                            {
                                errori = "La tipologia di domanda selezionata non è abilitata alla Trasformazione da provvisoria a definitiva.";
                                return true;
                            }
                        }

                        if (Utility.IsBloccoLavorazioneManuali_Opzione(datiDomandaDB))
                        {
                            errori = "La tipologia di domanda selezionata non è abilitata alla liquidazione (manuale con opzione)";
                            return true;
                        }

                        //controllo RIC domanda a DB in lavorazione su stessa sede
                        if (CheckDomandaSuStessaPensione(datiDomandaDB, sedeChiavePensioneDB, out errori))
                            return true;

                        if (!isDomandaLavorabilePerEccezione)
                        {
                            //Controllo domande lavorabili
                            IsDomandaLavorabileDB(datiDomandaDB.IndConvInt, datiDomandaDB.Gestione, datiDomandaDB.SiglaCategoria, datiDomandaDB.Gruppo, datiDomandaDB.Prodotto, datiDomandaDB.Tipo,
                                datiDomandaDB.CodiceTipoRichiesta, out errori);
                            if (!string.IsNullOrEmpty(errori))
                                return true;
                        }

                        //Blocco Lavorazione
                        Utility.StatoPensione? stato = Utility.GetStatoPensioneByCodice(datiDomandaDB.StatoPensione.GetValueOrDefault());
                        string gruppo = "";
                        if (datiDomandaDB != null && !string.IsNullOrEmpty(datiDomandaDB.Gruppo))
                            gruppo = datiDomandaDB.Gruppo;
                        else
                            gruppo = datiDomandaWebDom.Dati.Istanza[0].CodGruppo;

                        switch (stato.GetValueOrDefault())
                        {
                            case Utility.StatoPensione.Calcolata:
                            case Utility.StatoPensione.CalcolataNoWebDom:
                            case Utility.StatoPensione.CalcolataNoFelpe:
                            case Utility.StatoPensione.CalcolataNoOneri:
                            case Utility.StatoPensione.CalcolataNoSAI:
                            case Utility.StatoPensione.CalcolataNoStazLavoro:
                            case Utility.StatoPensione.CalcolataNoTotal:
                            case Utility.StatoPensione.CalcolataNoTot:
                            case Utility.StatoPensione.CalcolataNoSIN:
                            case Utility.StatoPensione.CalcolataNoNoteDebito:
                            case Utility.StatoPensione.CalcolataNo6Scatti:
                                break;
                            default:
                                if (Utility.IsBloccoLavorazione(tipoAppartenenza, gruppo, isDomandaRiapertura))
                                {
                                    errori = "Lavorazione al momento non disponibile";
                                    return true;
                                }
                                break;
                        }

                        //controllo matricola operatore 
                        if (ConfigurationManager.AppSettings["BypassControlloMatricola"] == null ||
                                ConfigurationManager.AppSettings["BypassControlloMatricola"] != "SI")
                        {
                            if (!isDomandaCalcolataProvvisoria || sedeOperatore != sedeDomandaDB)
                            {
                                bool isGestionePubblica = datiDomandaDB.Gestione == "019";
                                bool isAutomatizzata = datiDomandaDB.TipoAutomazione != null;
                                if (!GestioneAreaRiepilogo.CheckMatricolaAcquisizione(matricolaOperatore, datiDomandaDB.MatricolaUtenteAcquisizione, ruolo, isAutomatizzata, isGestionePubblica, tipoAppartenenza))
                                {
                                    errori = "Domanda in carico alla matricola " + datiDomandaDB.MatricolaUtenteAcquisizione + ". Non è possibile lavorarla";
                                    return true;
                                }
                            }
                        }

                        if (Utility.IsRicEsenzioneFiscaleVittimeDelDovere(datiDomandaDB))
                        {
                            if (datiDomandaDB.SiglaCategoria.Trim().Equals("VOCRED") || datiDomandaDB.SiglaCategoria.Trim().Equals("VOCOOP") || datiDomandaDB.SiglaCategoria.Trim().Equals("VOESO")
                                || datiDomandaDB.SiglaCategoria.Trim().Equals("VESO33") || datiDomandaDB.SiglaCategoria.Trim().Equals("VESO92") || datiDomandaDB.SiglaCategoria.Trim().Equals("CRED27")
                                || datiDomandaDB.SiglaCategoria.Trim().Equals("COOP28"))
                            {
                                errori = "La ricostituzione non può essere applicata alla domanda con categoria" + datiDomandaDB.SiglaCategoria;
                                return true;
                            }
                        }

                        // la domanda è stata trovata sul database "locale" dell'applicazione
                        List<GestionePensione.DatiPensione> elencoDomandeDB = new List<GestionePensione.DatiPensione>();
                        elencoDomandeDB.Add(datiDomandaDB);
                        GestioneAnagrafica.DatiAnagrafici datiAnagraficiDB = null;
                        // dopo aver recuperato i dati sulla domanda, recupero quelli sull'anagrafica del titolare della domanda
                        GestioneAnagrafica.GetAnagraficaByIdPensione(datiDomandaDB.Id, out datiAnagraficiDB);

                        if (!ValorizzaRiepilogoFromDB(parametriARCA, elencoDomandeDB, datiAnagraficiDB, chiaveRicerca, matricolaOperatore, out elencoAnagrafiche, out elencoDomande, out elencoPensioni, out errori))
                            return false;

                        if (!String.IsNullOrEmpty(errori))
                            return true;

                        elencoDomande.First().SiglaCategoriaPensione = (!String.IsNullOrEmpty(siglaCategoriaPensione)) ? siglaCategoriaPensione : datiDomandaDB.SiglaCategoria;
                        elencoDomande.First().SedePensione = (sedePensione > 0) ? sedePensione.ToString().PadLeft(4, '0') : datiDomandaDB.CodiceSede.ToString().PadLeft(4, '0');
                        elencoDomande.First().CertificatoPensione = (nCertificatoPensione > 0) ? nCertificatoPensione.ToString().PadLeft(8, '0') : datiDomandaDB.NCertificato.GetValueOrDefault().ToString().PadLeft(8, '0');
                        elencoDomande.First().SedeDaVisualizzare = sedeDomandaDB.ToString().PadLeft(4, '0');
                        elencoDomande.First().CentroOperativoDaVisualizzare = centroOperativoDomandaDB.ToString().PadLeft(2, '0');

                        GestioneEsitoCalcolo.GetEsitoCalcoloByIdPensione(datiDomandaDB.Id, out datiEsitoCalcolo);
                        tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiDomandaDB.SiglaCategoria);

                        isDomandaDB = true;

                        urlDPI = CostruisciURLProceduraDPI(datiDomandaDB);
                        isDomandaENPALS = Utility.IsDomandaENPALS(datiDomandaDB.Gestione);
                        isDomandaINPDAP = Utility.IsDomandaINPDAP(datiDomandaDB.Gestione);
                    }
                    else
                    {
                        // la domanda non è presente nel database "locale", la cerco su WebDom
                        if (datiDomandaWebDom == null)
                        {
                            bTest = GestioneWebDom.GetDomandaPerDomus(chiaveRicerca, out datiDomandaWebDom, out errori);
                            if (!bTest || !String.IsNullOrEmpty(errori))
                                return true;
                        }
                        if (datiDomandaWebDom != null)
                        {
                            if (datiDomandaWebDom.Dati != null && datiDomandaWebDom.Dati.Domanda != null && datiDomandaWebDom.Dati.Domanda.Count == 0)
                            {
                                errori = "Domanda non presente su WebDom";
                                return true;
                            }

                            if (datiDomandaWebDom.Dati.Istanza != null && datiDomandaWebDom.Dati.Istanza.Count > 0)
                            {
                                codTipoRichiesta = GestioneWebDom.GetCodTipoRichiesta(datiDomandaWebDom.Dati);
                                bool? IndConvInt = (!string.IsNullOrEmpty(datiDomandaWebDom.Dati.Istanza[0].IndConvInt) && datiDomandaWebDom.Dati.Istanza[0].IndConvInt.Trim() == "1") ? true : (!string.IsNullOrEmpty(datiDomandaWebDom.Dati.Istanza[0].IndConvInt) && datiDomandaWebDom.Dati.Istanza[0].IndConvInt.Trim() == "0") ? false : (bool?)null;
                                tipoAppartenenza = Utility.GetTipoAppartenenza(IndConvInt, datiDomandaWebDom.Dati.Istanza[0].CodGestione);
                                short codiceSede = short.Parse(datiDomandaWebDom.Dati.Domanda[0].CodProvincia.Substring(1, 2) + datiDomandaWebDom.Dati.Domanda[0].CodZona.Substring(1, 2));

                                isDomandaINPDAP = Utility.IsDomandaINPDAP(datiDomandaWebDom.Dati.Istanza[0].CodGestione);
                                isDomandaLavorabilePerEccezione = GestioneCtrlBypassTipologieNonAbilitate.IsDomandaLavorabilePerEccezione(tipoAppartenenza, codiceSede, datiDomandaWebDom.Dati.Istanza[0].CodGruppo,
                                        datiDomandaWebDom.Dati.Istanza[0].CodProdotto, datiDomandaWebDom.Dati.Istanza[0].CodTipo, datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav, codTipoRichiesta,
                                        isDomandaINPDAP);

                                if (datiDomandaWebDom.Dati.Fase != null)
                                {
                                    //Controllo domande lavorabili
                                    string codSituazione = datiDomandaWebDom.Dati.Fase[datiDomandaWebDom.Dati.Fase.Count - 1].CodSituazione;
                                    string codFase = datiDomandaWebDom.Dati.Fase[datiDomandaWebDom.Dati.Fase.Count - 1].CodFase;
                                    IsDomandaLavorabile(codSituazione, codFase, IndConvInt, datiDomandaWebDom.Dati.Istanza[0].CodGestione, datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav,
                                        datiDomandaWebDom.Dati.Istanza[0].CodGruppo, datiDomandaWebDom.Dati.Istanza[0].CodProdotto, datiDomandaWebDom.Dati.Istanza[0].CodTipo, codTipoRichiesta,
                                        isDomandaLavorabilePerEccezione, out errori);
                                    if (!string.IsNullOrEmpty(errori))
                                        return true;
                                }

                                //Controllo se la domanda è lavorabile da parte dell'operatore
                                if (tipoAppRuolo != tipoAppartenenza)
                                {
                                    errori = "Ruolo Utente non abilitato alla lavorazione della domanda.";
                                    return true;
                                }

                                string gruppo = "";
                                if (datiDomandaDB != null && !string.IsNullOrEmpty(datiDomandaDB.Gruppo))
                                    gruppo = datiDomandaDB.Gruppo;
                                else
                                    gruppo = datiDomandaWebDom.Dati.Istanza[0].CodGruppo;

                                //Blocco Lavorazione
                                if (Utility.IsBloccoLavorazione(tipoAppartenenza, gruppo, isDomandaRiapertura))
                                {
                                    errori = "Acquisizione al momento non disponibile";
                                    return true;
                                }
                            }

                            if (ConfigurationManager.AppSettings["BypassControlloSedi"] == null ||
                                ConfigurationManager.AppSettings["BypassControlloSedi"] != "SI")
                            {
                                //controllo sede operatore - sede domanda
                                short sedeDomanda = 0;
                                short centroOperativoDomanda = 0;
                                if (!CheckSedi(datiDomandaWebDom, sedeOperatore, centroOperativoOperatore, out sedeDomanda, out centroOperativoDomanda))
                                {
                                    errori = "La sede dell'operatore non coincide con la sede della domanda selezionata (" +
                                        sedeDomanda.ToString().PadLeft(4, '0') + centroOperativoDomanda.ToString().PadLeft(2, '0') + ").";
                                    sedeDiversa = sedeDomanda.ToString().PadLeft(4, '0') + centroOperativoDomanda.ToString().PadLeft(2, '0');
                                    return true;
                                }
                            }

                            //controllo RIC domanda a DB in lavorazione su stessa sede
                            if (CheckDomandaSuStessaPensione(datiDomandaWebDom, tipoAppartenenza, out isPLUnicarpeFromDB, out isPLPrepensionamentoEditoriaTipo0162FiltroEAA, out isPLPrepensionamentoEditoriaTipo0162FiltroEBA, out isPLESPAFiltroL26, out isPLVESO33FiltroDAP, out errori))
                                return true;

                            //Controllo presa in carico WebDom
                            //if (!isDomandaINPDAP)
                            if (!IsPresaInCaricoWebDom(datiDomandaWebDom, out errori))
                                return true;

                            //Check esistenza Prodotto e Tipo
                            if (!CheckEsistenzaProdottoTipo(datiDomandaWebDom))
                            {
                                errori = "La tipologia di domanda selezionata (Gruppo: "
                                    + datiDomandaWebDom.Dati.Istanza[0].CodGruppo + "; Prodotto: " + datiDomandaWebDom.Dati.Istanza[0].CodProdotto +
                                    "; Tipo: " + datiDomandaWebDom.Dati.Istanza[0].CodTipo +
                                    ") non è al momento abilitata alla liquidazione. Si prega di inviare segnalazione all'indirizzo email istituzionale.";
                                return true;
                            }
                        }

                        if (IsRicEsenzioneFiscaleVittimeDelDovereWebDom(datiDomandaWebDom))
                        {
                            if (datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav.Trim().Equals("VOCRED") || datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav.Trim().Equals("VOCOOP") || datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav.Trim().Equals("VOESO")
                                || datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav.Trim().Equals("VESO33") || datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav.Trim().Equals("VESO92") || datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav.Trim().Equals("CRED27")
                                || datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav.Trim().Equals("COOP28"))
                            {
                                errori = "La ricostituzione non può essere applicata alla domanda con categoria" + datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav;
                                return true;
                            }
                        }

                        //salvataggio dati db pensione + anagrafica + eventuale dante causa + eventuali familiari

                        //Se provengo dalla pagina di conferma, eseguo il salvataggio sul database "locale", altrimenti non scrivo nulla
                        if (isPaginaConferma)
                        {
                            DateTime dataSistema = GestioneControlliDinamici.GetDataSistema(tipoAppartenenza);
                            if (!SalvaRiepilogo(datiDomandaWebDom, matricolaOperatore, sedeOperatore, centroOperativoOperatore, parametriARCA, isDomandaCalcolataProvvisoria,
                                dataSistema, isPLUnicarpeFromDB, datiParzialiDA, isPLPrepensionamentoEditoriaTipo0162FiltroEAA, isPLPrepensionamentoEditoriaTipo0162FiltroEBA, isPLESPAFiltroL26, isPLVESO33FiltroDAP, codTipoRichiesta, out isRicercaManualeDA, out isNuovoCertificatoGeneratoEnpals, out errori, out msgNonBloccante,
                                out mostraPanelloMessBloccantePensioniOvunque, out sedePensioneGP1ALZ6, out codCategoriaPensione, out certificatoInseguimentoPensione, out mostraPopupMemo239, out mostraPopupMemo312023))
                                return false;
                            //Gestione errore video
                            if (!String.IsNullOrEmpty(errori))
                                return true;

                            isDomandaDB = true;
                        }
                        else
                            isDomandaDB = false;

                        if (datiDomandaWebDom != null)
                        {
                            if (elencoDatiDomanda == null)
                                elencoDatiDomanda = new List<INPS.Pensioni.Liquidazione.ServiceReferences.WebDom.DatiDomanda>();
                            elencoDatiDomanda.Add(datiDomandaWebDom);
                        }

                        if (!ValorizzaRiepilogo(parametriARCA, elencoDatiDomanda, chiaveRicerca, isPaginaConferma, out elencoAnagrafiche, out elencoDomande, out elencoPensioni, out errori))
                            return false;

                        if (isDomandaDB)
                        {
                            foreach (Entity.Domanda domanda in elencoDomande)
                            {
                                domanda.IsMatchMatricola = true;
                                domanda.MatricolaUtenteAcquisizione = matricolaOperatore;
                            }
                        }

                        if (datiDomandaWebDom != null && datiDomandaWebDom.Dati != null && datiDomandaWebDom.Dati.Istanza != null &&
                            datiDomandaWebDom.Dati.Istanza.Count > 0)
                        {
                            bool? indConvInt = datiDomandaWebDom.Dati.Istanza[0].IndConvInt == "1";
                            tipoAppartenenza = Utility.GetTipoAppartenenza(indConvInt, datiDomandaWebDom.Dati.Istanza[0].CodGestione);
                            tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiDomandaWebDom.Dati.Istanza[0].SiglaCatLav);
                        }

                        urlDPI = CostruisciURLProceduraDPI(datiDomandaWebDom);
                        if (datiDomandaWebDom != null && datiDomandaWebDom.Dati != null && datiDomandaWebDom.Dati.Istanza != null && datiDomandaWebDom.Dati.Istanza.Count > 0)
                        {
                            isDomandaENPALS = Utility.IsDomandaENPALS(datiDomandaWebDom.Dati.Istanza[0].CodGestione);
                            isDomandaINPDAP = Utility.IsDomandaINPDAP(datiDomandaWebDom.Dati.Istanza[0].CodGestione);
                        }

                        if (datiDomandaWebDom.Dati != null && datiDomandaWebDom.Dati.Fase != null && datiDomandaWebDom.Dati.Fase.Count > 0)
                            isDomandaRiapertura = Utility.IsRiaperturaDomanda(datiDomandaWebDom.Dati.Fase.LastOrDefault().CodFase);
                    }
                }
                else
                // la chiave di ricerca non è un intero, quindi la chiave di ricerca è il codice fiscale
                {
                    //Recupero Anagrafia DB
                    GestioneAnagrafica.DatiAnagrafici datiAnagraficiDB = null;
                    GestioneAnagrafica.GetAnagraficaByCodiceFiscale(chiaveRicerca.ToUpperInvariant(), out datiAnagraficiDB);

                    string messaggioVideo = string.Empty;
                    if (datiAnagraficiDB != null)
                    {
                        List<GestionePensione.DatiPensione> elencoDomandeDB = null;
                        // ho già recuperato i dati anagrafici dal db locale, ora recupero i dati sulla pensione
                        GestionePensione.GetPensioniByCodiceFiscale(chiaveRicerca, out elencoDomandeDB);

                        if (!ValorizzaRiepilogoFromDB(parametriARCA, elencoDomandeDB, datiAnagraficiDB, chiaveRicerca, matricolaOperatore, out elencoAnagrafiche, out elencoDomande, out elencoPensioni, out errori))
                            return false;
                        if (!String.IsNullOrEmpty(errori))
                            return true;

                        // cerco su WebDom eventuali altre domande collegate ai dati anagrafici correnti
                        GestioneWebDom.GetDomandePerCodiceFiscale(chiaveRicerca, "TI", out elencoDatiDomanda, out messaggioVideo);

                        if (!UnisciDomandeRecuperate(ref elencoDomande, elencoDatiDomanda, out errori))
                            return false;
                        errori = messaggioVideo;
                    }
                    else
                    {
                        GestioneWebDom.GetDomandePerCodiceFiscale(chiaveRicerca, "TI", out elencoDatiDomanda, out messaggioVideo);

                        if (!ValorizzaRiepilogo(parametriARCA, elencoDatiDomanda, chiaveRicerca, isPaginaConferma, out elencoAnagrafiche, out elencoDomande, out elencoPensioni, out errori))
                            return false;
                        errori = messaggioVideo;
                    }
                }
            }
            catch (Exception Ex)
            {
                errori = Ex.Message;
                GestioneLogGenerico.SalvaLogGenerico(0, MethodBase.GetCurrentMethod().Name, Utility.TipoLogGenerico.ErroreApplicativo, Ex != null ? Ex.Message : string.Empty, chiaveRicerca, Ex.StackTrace);
                INPS.DNA.Logging.Logger.LogException(Ex);
                return false;
            }

            return true;
        }

        public static bool GetRiepilogo(Entity.ParametriARCA parametriARCA, short sedeOperatore, short centroOperativoOperatore, string matricolaOperatore,
            Entity.DatiPersonaliParziali datiParziali, Utility.TipoAppartenenza tipoAppRuolo, Utility.Ruolo ruolo, bool isPaginaConferma, bool isConsultazione,
            Entity.DatiPersonaliParziali datiParzialiDA, out List<Entity.Anagrafica> elencoAnagrafiche, out List<Entity.Domanda> elencoDomande,
            out List<Entity.Pensione> elencoPensioni, out bool isDomandaDB, out string urlDPI, out bool isDomandaENPALS, out bool isDomandaINPDAP,
            out bool isDomandaCalcolataProvvisoria, out bool isDomandaRiapertura, out string sedeDiversa, out bool isRicercaManualeDA, out bool isNuovoCertificatoGeneratoEnpals, out string errori, out string msgNonBloccante,
            out bool mostraPanelloMessBloccantePensioniOvunque, out string sedePensioneGP1ALZ6, out string codCategoriaPensione, out string certificatoInseguimentoPensione,
            bool isPaginaVisualizzazioneStatoPratiche, out bool mostraPopupMemo239, out bool mostraPopupMemo312023)
        {
            errori = "";
            msgNonBloccante = "";
            elencoAnagrafiche = null;
            elencoDomande = null;
            elencoPensioni = null;
            isDomandaDB = false;
            urlDPI = string.Empty;
            isDomandaENPALS = false;
            isDomandaINPDAP = false;
            isDomandaRiapertura = false;
            isDomandaCalcolataProvvisoria = false;
            sedeDiversa = string.Empty;
            isRicercaManualeDA = false;
            GestioneEsitoCalcolo.DatiEsitoCalcolo datiEsitoCalcolo = null;
            Utility.TipoAppartenenza? tipoAppartenenza = null;
            Utility.TipoFondo? tipoFondo = null;
            isNuovoCertificatoGeneratoEnpals = false;
            //ENG - Pensioni Ovunque: gestione nuovo pannello
            mostraPanelloMessBloccantePensioniOvunque = false;
            sedePensioneGP1ALZ6 = string.Empty;
            codCategoriaPensione = string.Empty;
            certificatoInseguimentoPensione = string.Empty;
            mostraPopupMemo239 = false;
            mostraPopupMemo312023 = false;

            try
            {
                if (datiParziali == null || String.IsNullOrEmpty(datiParziali.Nome) && String.IsNullOrEmpty(datiParziali.Cognome) && datiParziali.DataNascita == null)
                {
                    errori = "Chiave di ricerca non assegnata correttamente. Non è possibile recuperare i dati richiesti";
                    return false;
                }
                if (datiParziali.Nome == null)
                    datiParziali.Nome = "";
                if (datiParziali.Cognome == null)
                    datiParziali.Cognome = "";

                DataTable anagrafica = null;
                DataTable pensioniRiferimento = null;
                DataTable sinonimi = null;

                GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
                richiestaArca.Applicazione = parametriARCA.Applicazione;
                richiestaArca.Matricola = parametriARCA.Matricola;
                richiestaArca.Provenienza = parametriARCA.Provenienza;
                richiestaArca.Ruolo = parametriARCA.Ruolo;
                richiestaArca.CodiceFiscaleRichiedente = parametriARCA.CodiceFiscaleRichiedente;
                richiestaArca.Nome = datiParziali.Nome;
                richiestaArca.Cognome = datiParziali.Cognome;
                richiestaArca.DataNascita = datiParziali.DataNascita;
                bool bTest = GestioneARCA.GetAreaArcaByDatiPersonaliParziali(richiestaArca, 0.ToString(), out anagrafica, out pensioniRiferimento, out sinonimi, out errori);
                if (!bTest)
                    return false;
                if (!String.IsNullOrEmpty(errori))
                    return true;

                if (anagrafica != null && anagrafica.Rows.Count > 0 && sinonimi == null)
                {
                    if (!GetRiepilogo(parametriARCA, sedeOperatore, centroOperativoOperatore, matricolaOperatore, anagrafica.Rows[0]["CodiceFiscale"].ToString(),
                        tipoAppRuolo, ruolo, isPaginaConferma, isConsultazione, null, datiParzialiDA, out elencoAnagrafiche, out elencoDomande, out elencoPensioni,
                        out datiEsitoCalcolo, out tipoAppartenenza, out tipoFondo, out isDomandaDB, out urlDPI, out isDomandaENPALS,
                        out isDomandaINPDAP, out isDomandaCalcolataProvvisoria, out isDomandaRiapertura, out sedeDiversa, out isRicercaManualeDA, out isNuovoCertificatoGeneratoEnpals, out errori, out msgNonBloccante,
                        out mostraPanelloMessBloccantePensioniOvunque, out sedePensioneGP1ALZ6, out codCategoriaPensione, out certificatoInseguimentoPensione, isPaginaVisualizzazioneStatoPratiche, out mostraPopupMemo239, out mostraPopupMemo312023))
                        return false;
                }
                else if (sinonimi != null && sinonimi.Rows.Count > 0)
                {
                    if (!ValorizzaSinonimi(sinonimi, out elencoAnagrafiche, out errori))
                        return false;
                }
            }
            catch (Exception Ex)
            {
                errori = "Errore tecnico durante il recupero delle informazioni anagrafiche";
                string messaggio = Utility.GetMessageFromException(Ex);
                string parametri = string.Format("Cognome: {0}; Nome: {1}; Data Nascita: {2:dd/MM/yyyy}", datiParziali.Cognome, datiParziali.Nome, datiParziali.DataNascita);
                GestioneLogGenerico.SalvaLogGenerico(0, MethodBase.GetCurrentMethod().Name, Utility.TipoLogGenerico.ErroreApplicativo, messaggio, parametri, Ex.StackTrace);
                Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        public static bool GetDatiParziali(Entity.ParametriARCA parametriARCA, string nome, string cognome, DateTime? dataNascita, string sesso, string numDomanda, out List<Entity.Anagrafica> elencoAnagrafiche, out string errori)
        {
            errori = "";
            elencoAnagrafiche = null;

            if (string.IsNullOrEmpty(nome) || string.IsNullOrEmpty(cognome) || dataNascita == null)
            {
                errori = "Chiave di ricerca non assegnata correttamente. Non è possibile recuperare i dati richiesti";
                return false;
            }

            if (sesso == null)
                sesso = "";

            DataTable anagrafica = null;
            DataTable pensioniRiferimento = null;
            DataTable sinonimi = null;

            GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
            richiestaArca.Applicazione = parametriARCA.Applicazione;
            richiestaArca.Matricola = parametriARCA.Matricola;
            richiestaArca.Provenienza = parametriARCA.Provenienza;
            richiestaArca.Ruolo = parametriARCA.Ruolo;
            richiestaArca.CodiceFiscaleRichiedente = parametriARCA.CodiceFiscaleRichiedente;
            richiestaArca.Nome = nome;
            richiestaArca.Cognome = cognome;
            richiestaArca.DataNascita = dataNascita;
            richiestaArca.Sesso = sesso;
            bool bTest = GestioneARCA.GetAreaArcaByDatiPersonaliParziali(richiestaArca, numDomanda, out anagrafica, out pensioniRiferimento, out sinonimi, out errori);
            if (!bTest)
                return false;
            if (!String.IsNullOrEmpty(errori))
                return true;

            if (anagrafica != null && anagrafica.Rows.Count > 0 && sinonimi == null)
            {
                Entity.Anagrafica anagNormalizzata = null;
                GestioneARCA.NormalizzaAnagraficaArcaToDB(anagrafica.Rows[0], out anagNormalizzata);
                if (anagNormalizzata != null)
                {
                    if (elencoAnagrafiche == null)
                        elencoAnagrafiche = new List<INPS.Pensioni.Liquidazione.Entity.Anagrafica>();
                    elencoAnagrafiche.Add(anagNormalizzata);
                }
            }
            else if (sinonimi != null && sinonimi.Rows.Count > 0)
            {
                if (!ValorizzaSinonimi(sinonimi, out elencoAnagrafiche, out errori))
                    return false;
            }
            return true;
        }
        #endregion public members

        #region private members
        private static bool CheckEsistenzaProdottoTipo(ServiceReferences.WebDom.DatiDomanda datiDomanda)
        {
            if (datiDomanda == null || datiDomanda.Dati == null || datiDomanda.Dati.Istanza == null || datiDomanda.Dati.Istanza.Count == 0)
                return true;

            return GestioneDecodifica.CheckProdottoTipo(datiDomanda.Dati.Istanza[0].CodProdotto, datiDomanda.Dati.Istanza[0].CodTipo);
        }

        private static bool IsRicEsenzioneFiscaleVittimeDelDovereWebDom(ServiceReferences.WebDom.DatiDomanda datiDomanda)
        {
            string errori = string.Empty;
            GestionePensione.DatiPensione datiPensione = null;

            bool isRiapertura = false;
            if (datiDomanda.Dati != null && datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Count > 0)
                isRiapertura = Utility.IsRiaperturaDomanda(datiDomanda.Dati.Fase.LastOrDefault().CodFase);

            if (!ValorizzaPensioneToDB(datiDomanda, isRiapertura, out datiPensione, out errori))
                throw new INPS.DNA.DnaValidationException(errori);

            if (datiPensione == null)
                return false;

            if ((Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione) &&
                ((datiPensione.Gruppo == "0031" && datiPensione.Prodotto == "0108" && datiPensione.Tipo == "0166") ||
                 (datiPensione.Gruppo == "0031" && datiPensione.Prodotto == "0308" && datiPensione.Tipo == "0166") ||
                 (datiPensione.Gruppo == "0031" && datiPensione.Prodotto == "0408" && datiPensione.Tipo == "0166")))
                return true;

            return false;
        }

        private static bool UnisciDomandeRecuperate(ref List<Entity.Domanda> elencoDomande, List<ServiceReferences.WebDom.DatiDomanda> elencoDatiDomanda, out string errori)
        {
            errori = "";
            try
            {
                if (elencoDomande != null && elencoDomande.Count > 0)
                {
                    List<Entity.Domanda> elencoDomandeDaWebDom = null;
                    if (!ValorizzaDomandeWebDom(elencoDatiDomanda, false, out elencoDomandeDaWebDom, out errori))
                        return false;
                    elencoDomande.All(x => { if (!String.IsNullOrEmpty(x.Sede)) x.SedeDaVisualizzare = x.Sede.PadLeft(4, '0'); if (!String.IsNullOrEmpty(x.CentroOperativo)) x.CentroOperativoDaVisualizzare = x.CentroOperativo.PadLeft(2, '0'); return true; });
                    if (elencoDomandeDaWebDom != null)
                    {
                        foreach (Entity.Domanda dW in elencoDomandeDaWebDom)
                        {
                            bool IsContain = false;
                            foreach (Entity.Domanda d in elencoDomande)
                            {
                                if (d.NumeroDomanda == dW.NumeroDomanda)
                                {
                                    if (d.Stato == Utility.GetDescription(Utility.StatoPensione.NonLavorabile))
                                    {
                                        d.Categoria = dW.Categoria;
                                        d.Certificato = dW.Certificato;
                                        d.Sede = dW.Sede;
                                        d.Stato = dW.Stato;
                                        d.Tipo = dW.Tipo;
                                    }

                                    Entity.Domanda domandaTrfDB = elencoDomande.Find(x => x.Tipo == "TRF" && x.NumeroDomanda == d.NumeroDomanda);
                                    if (domandaTrfDB == null)
                                    {
                                        if (dW.Tipo == "TRF")
                                        {
                                            if (!String.IsNullOrEmpty(d.Sede) && !String.IsNullOrEmpty(d.Sede.Trim()) && !String.IsNullOrEmpty(d.CentroOperativo) && !String.IsNullOrEmpty(d.CentroOperativo.Trim())
                                            && !String.IsNullOrEmpty(dW.Sede) && !String.IsNullOrEmpty(dW.Sede.Trim()) && !String.IsNullOrEmpty(dW.CentroOperativo) && !String.IsNullOrEmpty(dW.CentroOperativo.Trim()) && (d.Sede.Trim().PadLeft(4, '0') != dW.Sede.Trim().PadLeft(4, '0') || d.CentroOperativo.Trim().PadLeft(2, '0') != dW.CentroOperativo.Trim().PadLeft(2, '0')))
                                            {
                                                d.SedeDaVisualizzare = d.Sede.Trim().PadLeft(4, '0');
                                                d.CentroOperativoDaVisualizzare = d.CentroOperativo.Trim().PadLeft(2, '0');
                                                d.Sede = dW.Sede.Trim().PadLeft(4, '0');
                                                d.CentroOperativo = dW.CentroOperativo.Trim().PadLeft(2, '0');
                                            }
                                        }
                                    }
                                    else if (d.Tipo == "PL" && !String.IsNullOrEmpty(d.Sede) && !String.IsNullOrEmpty(d.Sede.Trim()) && !String.IsNullOrEmpty(d.CentroOperativo) && !String.IsNullOrEmpty(d.CentroOperativo.Trim())
                                        && !String.IsNullOrEmpty(domandaTrfDB.Sede) && !String.IsNullOrEmpty(domandaTrfDB.Sede.Trim()) && !String.IsNullOrEmpty(domandaTrfDB.CentroOperativo) && !String.IsNullOrEmpty(domandaTrfDB.CentroOperativo.Trim()))
                                    {
                                        d.isConsultazioneDomandaTRF = true;
                                        if (d.Sede.Trim().PadLeft(4, '0') != domandaTrfDB.Sede.Trim().PadLeft(4, '0') || d.CentroOperativo.Trim().PadLeft(2, '0') != domandaTrfDB.CentroOperativo.Trim().PadLeft(2, '0'))
                                        {
                                            d.SedeDaVisualizzare = d.Sede.Trim().PadLeft(4, '0');
                                            d.CentroOperativoDaVisualizzare = d.CentroOperativo.Trim().PadLeft(2, '0');
                                            d.Sede = domandaTrfDB.Sede.Trim().PadLeft(4, '0');
                                            d.CentroOperativo = domandaTrfDB.CentroOperativo.Trim().PadLeft(2, '0');
                                        }
                                    }

                                    IsContain = true;
                                }

                            }
                            if (!IsContain)
                                elencoDomande.Add(dW);
                        }
                    }
                }
                else
                {
                    if (!ValorizzaDomandeWebDom(elencoDatiDomanda, false, out elencoDomande, out errori))
                        return false;
                }
            }
            catch (Exception Ex)
            {
                errori = Ex.Message;
                INPS.DNA.Logging.Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        private static bool ValorizzaRiepilogo(Entity.ParametriARCA parametriARCA, List<ServiceReferences.WebDom.DatiDomanda> elencoDatiDomanda, string chiaveRicerca, bool isPaginaConferma,
            out List<Entity.Anagrafica> elencoAnagrafiche, out List<Entity.Domanda> elencoDomande, out List<Entity.Pensione> elencoPensioni, out string errori)
        {
            errori = "";
            elencoAnagrafiche = null;
            elencoDomande = null;
            elencoPensioni = null;
            try
            {
                if (elencoDatiDomanda != null && elencoDatiDomanda.Count > 0)
                {
                    if (!ValorizzaDomandeWebDom(elencoDatiDomanda, isPaginaConferma, out elencoDomande, out errori))
                        return false;
                }
                Int64 r = 0;
                if (elencoDatiDomanda != null && elencoDatiDomanda.Count > 0 &&
                    elencoDatiDomanda[0].Dati.Soggetto != null && elencoDatiDomanda[0].Dati.Soggetto.Rows.Count > 0)
                {
                    DataRow rigaTitolare = null;
                    if (elencoDatiDomanda[0].Dati.Soggetto.Rows.Count > 0)
                    {
                        string idTitolare = "";
                        foreach (ServiceReferences.WebDom.DataSetDomanda.RelazioneSoggettoRow riga in elencoDatiDomanda[0].Dati.RelazioneSoggetto.Rows)
                        {
                            if (riga["CodRelazioneSoggetto"] != null && riga["CodRelazioneSoggetto"].ToString() == "TI")
                            {
                                idTitolare = riga["IdSoggetto"] != null ? riga["IdSoggetto"].ToString() : "";
                                break;
                            }
                        }
                        if (idTitolare != "")
                        {
                            foreach (ServiceReferences.WebDom.DataSetDomanda.SoggettoRow riga in elencoDatiDomanda[0].Dati.Soggetto.Rows)
                            {
                                if (riga["IdSoggetto"] != null && riga["IdSoggetto"].ToString() == idTitolare)
                                {
                                    rigaTitolare = riga;
                                    break;
                                }
                            }
                        }
                    }

                    if (Int64.TryParse(chiaveRicerca, out r) && rigaTitolare != null && rigaTitolare.Table.Columns.Contains("CodiceFiscale"))
                    {
                        //Recupero anagrafica DB che ha la priorità su quella di WebDom
                        GestioneAnagrafica.DatiAnagrafici datiAnagraficiDB = null;
                        GestioneAnagrafica.GetAnagraficaByCodiceFiscale(rigaTitolare["CodiceFiscale"].ToString().ToUpperInvariant(), out datiAnagraficiDB);

                        if (datiAnagraficiDB != null)
                        {
                            if (!ValorizzaAnagraficaFromDB(datiAnagraficiDB, out elencoAnagrafiche, out errori))
                                return false;
                        }
                        else
                        {
                            if (!ValorizzaAnagrafica(rigaTitolare, out elencoAnagrafiche, out errori))
                                return false;
                        }
                    }
                    //ricerca pensioni solo per ricerca per codice fiscale
                    else
                    {
                        DataTable anagrafica = null;
                        DataTable pensioniRiferimento = null;
                        GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
                        richiestaArca.Applicazione = parametriARCA.Applicazione;
                        richiestaArca.Provenienza = parametriARCA.Provenienza;
                        richiestaArca.Ruolo = parametriARCA.Ruolo;
                        richiestaArca.Matricola = parametriARCA.Matricola;
                        richiestaArca.CodiceFiscaleRichiedente = chiaveRicerca.ToUpperInvariant();
                        richiestaArca.CodiceFiscale = chiaveRicerca.ToUpperInvariant();
                        if (!GestioneARCA.GetAreaArcaByCodiceFiscale(richiestaArca, 0.ToString(), out anagrafica, out pensioniRiferimento, out errori))
                            return false;
                        if (!string.IsNullOrEmpty(errori))
                            return true;

                        if (!ValorizzaPensioni(pensioniRiferimento, out elencoPensioni, out errori))
                            return false;
                    }
                }
            }
            catch (Exception Ex)
            {
                string messaggio = Utility.GetMessageFromException(Ex);
                errori = "Errore tecnico durante la valorizzazione dei dati";
                string parametri = string.Format("Chiave di ricerca: {0}", chiaveRicerca);
                long numeroDomanda = 0;
                long.TryParse(chiaveRicerca, out numeroDomanda);
                GestioneLogGenerico.SalvaLogGenerico(numeroDomanda, MethodBase.GetCurrentMethod().Name, Utility.TipoLogGenerico.ErroreApplicativo, messaggio, parametri, Ex.StackTrace);
                Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        private static bool ValorizzaDomandeWebDom(List<ServiceReferences.WebDom.DatiDomanda> elencoDatiDomanda, bool isPaginaConferma, out List<Entity.Domanda> elencoDomande, out string errori)
        {
            errori = "";
            elencoDomande = null;

            bool isRiapertura = false;

            try
            {
                if (elencoDatiDomanda != null && elencoDatiDomanda.Count > 0)
                {
                    List<GestioneDecodifica.Prodotto> elencoProdotto = null;
                    GestioneDecodifica.GetProdotto(out elencoProdotto);

                    List<GestioneDecodifica.Tipo> elencoTipo = null;
                    GestioneDecodifica.GetTipo(out elencoTipo);

                    GestioneControlliDinamici.ControlloDinamico cdDataCalcoloDefinitivoINDCOM = null;

                    foreach (ServiceReferences.WebDom.DatiDomanda dati in elencoDatiDomanda)
                    {
                        if (dati.Dati.Domanda != null && dati.Dati.Domanda.Rows.Count > 0)
                        {
                            Entity.Domanda domanda = new Entity.Domanda();
                            domanda.NumeroDomanda = dati.Dati.Domanda[0].NumDomanda.PadLeft(13, '0');
                            domanda.Sede = dati.Dati.Domanda[0].CodProvincia.Substring(1, 2) + dati.Dati.Domanda[0].CodZona.Substring(1, 2);
                            domanda.CentroOperativo = dati.Dati.Domanda[0].CodCentroOperativo.Substring(1, 2);
                            domanda.SedeDaVisualizzare = dati.Dati.Domanda[0].CodProvincia.Substring(1, 2) + dati.Dati.Domanda[0].CodZona.Substring(1, 2);
                            domanda.CentroOperativoDaVisualizzare = dati.Dati.Domanda[0].CodCentroOperativo.Substring(1, 2);
                            //// Recupero la descrizione della tipologia di domanda
                            GestioneDecodifica.Prodotto prodotto = elencoProdotto.Find(x => x.CodProdotto == dati.Dati.Istanza[0].CodProdotto);
                            domanda.DescProdotto = prodotto != null ? prodotto.DescProdotto : string.Empty;
                            GestioneDecodifica.Tipo tipo = elencoTipo.Find(x => x.CodTipo == dati.Dati.Istanza[0].CodTipo);
                            domanda.DescTipo = tipo != null ? tipo.DescTipo : string.Empty;

                            domanda.DataAcquisizione = Utility.DataFromString(dati.Dati.Domanda[0].DataInserimento, Utility.FormatoData.AAAAmmGG).Value;

                            if (prodotto == null)
                                Logger.LogException(new DNA.DnaApplicationException("Prodotto mancante: " + dati.Dati.Istanza[0].CodProdotto));
                            if (tipo == null)
                                Logger.LogException(new DNA.DnaApplicationException("Tipo mancante: " + dati.Dati.Istanza[0].CodTipo));

                            Utility.TipoDomanda? tipoDomanda = null;

                            if (dati.Dati.Fase != null && dati.Dati.Fase.Rows.Count > 0)
                                isRiapertura = Utility.IsRiaperturaDomanda(dati.Dati.Fase.LastOrDefault().CodFase);

                            if (dati.Dati.Istanza != null && dati.Dati.Istanza.Rows.Count > 0)
                            {
                                domanda.Categoria = dati.Dati.Istanza[0].SiglaCatLav;
                                tipoDomanda = Utility.GetTipoDomanda(dati.Dati.Istanza[0].CodGruppo, dati.Dati.Istanza[0].CodProdotto);
                                if (tipoDomanda.HasValue && tipoDomanda.Value == Utility.TipoDomanda.Ricostituzione)
                                    domanda.Tipo = "RIC";
                                else if (isRiapertura)
                                    domanda.Tipo = "TRF";
                                else
                                    domanda.Tipo = "PL";

                                domanda.CodGruppo = dati.Dati.Istanza[0].CodGruppo;
                                domanda.CodProdotto = dati.Dati.Istanza[0].CodProdotto;
                                domanda.CodTipo = dati.Dati.Istanza[0].CodTipo;
                            }
                            else
                            {
                                domanda.Tipo = "";
                            }
                            string decodificaStatoPensione = "";
                            byte idStatoPensione = (int)Utility.StatoPensione.DaAcquisire; //DA ACQUISIRE
                            if (domanda.Categoria != null && domanda.Categoria.Trim().EndsWith("TELE"))
                                idStatoPensione = (int)Utility.StatoPensione.NonLavorabile; //NON LAVORABILE

                            GestioneDecodifica.GetStatoPensioneById(idStatoPensione, out decodificaStatoPensione);
                            domanda.Stato = decodificaStatoPensione;

                            GestionePensione.DatiPensione datiDomandaDB = null;
                            GestionePensione.GetPensioneByNumeroDomandaAndProg(Convert.ToInt64(domanda.NumeroDomanda), null, out datiDomandaDB);
                            if (datiDomandaDB != null)
                                domanda.Certificato = datiDomandaDB.NCertificato.ToString().PadLeft(8, '0');

                            string descIstanza = string.Empty;
                            GestioneDecodifica.GetDescrizioneIstanza(domanda.CodGruppo, domanda.CodProdotto, domanda.CodTipo, out descIstanza);
                            domanda.DescrizioneIstanza = descIstanza;

                            if (tipoDomanda == Utility.TipoDomanda.Superstiti || tipoDomanda == Utility.TipoDomanda.Ricostituzione || tipoDomanda == Utility.TipoDomanda.Ripristino ||
                                tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti || isRiapertura)
                            {
                                //riapertura
                                if (isRiapertura)
                                {
                                    ServiceReferences.WebDom.DataSetDomanda.PensioneGenerataRow pensioneGenerata = dati.Dati.PensioneGenerata.FirstOrDefault(x => x.IndAnnullata == "0");
                                    domanda.SiglaCategoriaPensione = pensioneGenerata.SiglaCatLav;
                                    short sede = 0;
                                    short.TryParse((pensioneGenerata.CodProvinciaGenAttuale.Substring(1) + pensioneGenerata.CodZonaGenAttuale.Substring(1)), out sede);
                                    domanda.SedePensione = sede.ToString().PadLeft(4, '0');
                                    int certificato = 0;
                                    int.TryParse(pensioneGenerata.NumCertificatoGenAttuale, out certificato);
                                    domanda.CertificatoPensione = certificato.ToString().PadLeft(8, '0');
                                }
                                else
                                    //diverso da reversibilità e indiretta
                                    if (!(tipoDomanda == Utility.TipoDomanda.Superstiti && (dati.Dati.PensioneRiferimento.Rows.Count == 0 || isPensioneRiferimentoNull(dati.Dati.PensioneRiferimento[0]))))
                                    {
                                        domanda.SiglaCategoriaPensione = dati.Dati.PensioneRiferimento[0].SiglaCatLav;
                                        short sede = 0;
                                        short.TryParse((dati.Dati.PensioneRiferimento[0].CodProvinciaRifAttuale.Substring(1) + dati.Dati.PensioneRiferimento[0].CodZonaRifAttuale.Substring(1)), out sede);
                                        domanda.SedePensione = sede.ToString().PadLeft(4, '0');
                                        int certificato = 0;
                                        int.TryParse(dati.Dati.PensioneRiferimento[0].NumCertificatoRifAttuale, out certificato);
                                        domanda.CertificatoPensione = certificato.ToString().PadLeft(8, '0');
                                    }
                            }

                            domanda.CodiceTipoRichiesta = GestioneWebDom.GetCodTipoRichiesta(dati.Dati);
                            bool? IndConvInt = (!string.IsNullOrEmpty(dati.Dati.Istanza[0].IndConvInt) && dati.Dati.Istanza[0].IndConvInt.Trim() == "1") ? true : (!string.IsNullOrEmpty(dati.Dati.Istanza[0].IndConvInt) && dati.Dati.Istanza[0].IndConvInt.Trim() == "0") ? false : (bool?)null;
                            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(IndConvInt, dati.Dati.Istanza[0].CodGestione);

                            if (!isPaginaConferma && tipoAppartenenza == Utility.TipoAppartenenza.AGO && (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura))
                            {
                                string chiavePensione = null;
                                if (isRiapertura)
                                {
                                    int certificato = 0;
                                    short categoria = 0;
                                    ServiceReferences.WebDom.DataSetDomanda.PensioneGenerataRow pensioneGenerata = dati.Dati.PensioneGenerata.FirstOrDefault(x => x.IndAnnullata == "0");
                                    int.TryParse(pensioneGenerata.NumCertificatoGenAttuale, out certificato);
                                    short.TryParse(pensioneGenerata.CodCatPensioneGenAttuale, out categoria);
                                    chiavePensione = categoria.ToString().PadLeft(3, '0') +
                                        (pensioneGenerata.CodProvinciaGenAttuale.Substring(1) + pensioneGenerata.CodZonaGenAttuale.Substring(1)).PadLeft(4, '0') +
                                        certificato.ToString().PadLeft(8, '0');
                                }
                                else
                                {
                                    int certificato = 0;
                                    short categoria = 0;
                                    ServiceReferences.WebDom.DataSetDomanda.PensioneRiferimentoRow pensioneRiferimento = dati.Dati.PensioneRiferimento[0];
                                    int.TryParse(pensioneRiferimento.NumCertificatoRifAttuale, out certificato);
                                    short.TryParse(pensioneRiferimento.CodCatPensioneRifAttuale, out categoria);
                                    chiavePensione = categoria.ToString().PadLeft(3, '0') +
                                        (pensioneRiferimento.CodProvinciaRifAttuale.Substring(1) + pensioneRiferimento.CodZonaRifAttuale.Substring(1)).PadLeft(4, '0') +
                                        certificato.ToString().PadLeft(8, '0');
                                }
                            }
                            if (isPaginaConferma && tipoAppartenenza == Utility.TipoAppartenenza.AGO && (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura))
                            {
                                if (datiDomandaDB != null)
                                {
                                    GestioneDatiStoricoGP.DatiStoricoGP datiStoricoGP = null;
                                    GestioneDatiStoricoGP.GetDatiStoricoGPByIdPensione(datiDomandaDB.Id, out datiStoricoGP);
                                    if (datiStoricoGP != null)
                                    {
                                        domanda.GP1ALB1 = datiStoricoGP.GP1ALB1;
                                        domanda.GP2BB05 = datiStoricoGP.GP2BB05;
                                        domanda.GP1AXE3 = datiStoricoGP.GP1AXE3;
                                        domanda.IsScadenzaAssegnoConGiorno = datiStoricoGP.IsScadenzaAssegnoConGiorno;
                                        domanda.DataEliminazioneContabile = datiStoricoGP.DataEliminazioneContabile;
                                    }
                                }
                            }

                            domanda.DataPresentazionePreAcquisizione = dati.Dati.Istanza[0].DataPresentazione != null ? Utility.DataFromString(dati.Dati.Istanza[0].DataPresentazione, Utility.FormatoData.AAAAmmGG) : null;

                            if (dati.Dati.RequisitoParticolare != null && dati.Dati.RequisitoParticolare.Count > 0 && dati.Dati.RequisitoParticolare[0] != null)
                                domanda.DecorrenzaFinestra = dati.Dati.RequisitoParticolare[0].DecorrenzaFinestra;
                            if (datiDomandaDB != null)
                            {
                                GestioneLavorazione.DatiLavorazione datiLavorazione = new GestioneLavorazione.DatiLavorazione();
                                GestioneLavorazione.GetLavorazioneByIdPensione(datiDomandaDB.Id, out datiLavorazione);
                                if (datiLavorazione.CodFase != null)
                                    domanda.CodFase = datiLavorazione.CodFase;
                            }
                            if (Utility.IsDomandaINDCOM175(domanda.Categoria, domanda.CodTipo) && cdDataCalcoloDefinitivoINDCOM == null)
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DataCalcoloDefinitivoINDCOM", out cdDataCalcoloDefinitivoINDCOM);

                            domanda.DataCalcoloDefinitivoINDCOM = cdDataCalcoloDefinitivoINDCOM != null ? Utility.DataFromString(cdDataCalcoloDefinitivoINDCOM.ValoreControllo, Utility.FormatoData.GGmmAAAA) : null;

                            //ENG - Implementazione Meta Processo
                            GestioneControlliDinamici.ControlloDinamico ctrlMetaProcesso = null;
                            if (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura)
                            {
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("SbloccaMetaProcesso", out ctrlMetaProcesso);
                                if (ctrlMetaProcesso != null && !String.IsNullOrEmpty(ctrlMetaProcesso.ValoreControllo) && ctrlMetaProcesso.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                                {
                                    //Il codice sede lavorazione è il codProvincia e codZona che provengono da webdom
                                    domanda.CodiceSedeLavorazione = short.Parse(dati.Dati.Domanda[0].CodProvincia.Substring(1, 2) + dati.Dati.Domanda[0].CodZona.Substring(1, 2));
                                }
                            }


                            if (elencoDomande == null)
                                elencoDomande = new List<Entity.Domanda>();
                            elencoDomande.Add(domanda);
                        }
                    }
                }
            }
            catch (Exception Ex)
            {
                errori = Ex.Message;
                INPS.DNA.Logging.Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        private static bool ValorizzaSinonimi(DataTable sinonimi, out List<Entity.Anagrafica> elencoAnagrafiche, out string errori)
        {
            errori = "";
            elencoAnagrafiche = null;
            try
            {
                if (sinonimi != null && sinonimi.Rows.Count > 0)
                {
                    foreach (DataRow rigaSinonimi in sinonimi.Rows)
                    {
                        Entity.Anagrafica anagrafica = new INPS.Pensioni.Liquidazione.Entity.Anagrafica();
                        anagrafica.MatricolaArca = rigaSinonimi["ChiaveArca"].ToString();
                        anagrafica.CodiceFiscale = rigaSinonimi["CodiceFiscale"].ToString();
                        anagrafica.Cognome = rigaSinonimi["Cognome"].ToString();
                        anagrafica.Nome = rigaSinonimi["Nome"].ToString();
                        anagrafica.DataNascita = Utility.DataFromString(rigaSinonimi["DataNascita"].ToString(), Utility.FormatoData.AAAAmmGG);
                        anagrafica.CodiceComuneNascita = rigaSinonimi["CodiceComuneNascita"] != null ? rigaSinonimi["CodiceComuneNascita"].ToString() : "";
                        if (elencoAnagrafiche == null)
                            elencoAnagrafiche = new List<INPS.Pensioni.Liquidazione.Entity.Anagrafica>();
                        elencoAnagrafiche.Add(anagrafica);
                    }
                }
            }
            catch (Exception Ex)
            {
                errori = Ex.Message;
                INPS.DNA.Logging.Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        private static bool ValorizzaAnagrafica(DataRow anagrafica, out List<Entity.Anagrafica> elencoAnagrafiche, out string errori)
        {
            errori = "";
            elencoAnagrafiche = null;
            try
            {
                if (anagrafica != null)
                {
                    Entity.Anagrafica anag = new INPS.Pensioni.Liquidazione.Entity.Anagrafica();
                    anag.CodiceFiscale = anagrafica["CodiceFiscale"] != null ? anagrafica["CodiceFiscale"].ToString() : "";
                    anag.Cognome = anagrafica["Cognome"] != null ? anagrafica["Cognome"].ToString() : "";
                    anag.Nome = anagrafica["Nome"] != null ? anagrafica["Nome"].ToString() : "";
                    anag.CognomeAcquisito = anagrafica["CognomeAcquisito"] != null ? anagrafica["CognomeAcquisito"].ToString() : "";
                    anag.Sesso = Utility.StringToNullableChar(anagrafica["Sesso"] != null ? anagrafica["Sesso"].ToString() : "");
                    anag.DataNascita = Utility.DataFromString(anagrafica["DataNascita"] != null ? anagrafica["DataNascita"].ToString() : "", Utility.FormatoData.AAAAmmGG);
                    anag.ComuneNascita = anagrafica["ComuneNascita"] != null ? anagrafica["ComuneNascita"].ToString() : "";
                    anag.CodiceComuneNascita = anagrafica["CodComuneNascita"] != null ? anagrafica["CodComuneNascita"].ToString() : "";
                    anag.ProvinciaNascita = anagrafica["SiglaProvinciaNascita"] != null ? anagrafica["SiglaProvinciaNascita"].ToString() : "";
                    anag.Indirizzo = anagrafica["Indirizzo1"] != null ? anagrafica["Indirizzo1"].ToString() : "";
                    anag.NCivico = anagrafica["NumeroCivico"] != null ? anagrafica["NumeroCivico"].ToString() : "";
                    anag.CAP = anagrafica["CapResidenza"] != null ? anagrafica["CapResidenza"].ToString() : "";
                    anag.ComuneResidenza = anagrafica["ComuneResidenza"] != null ? anagrafica["ComuneResidenza"].ToString() : "";
                    anag.CodiceComuneResidenza = anagrafica["CodComuneResidenza"] != null ? anagrafica["CodComuneResidenza"].ToString() : "";
                    anag.FrazioneResidenza = anagrafica["FrazioneResidenza"] != null ? anagrafica["FrazioneResidenza"].ToString() : "";
                    anag.ProvinciaResidenza = anagrafica["SiglaProvinciaResidenza"] != null ? anagrafica["SiglaProvinciaResidenza"].ToString() : "";
                    anag.Tel = anagrafica["NumeroTelefono1"] != null ? anagrafica["NumeroTelefono1"].ToString() : "";
                    anag.Cell = anagrafica["NumeroTelefono2"] != null ? anagrafica["NumeroTelefono2"].ToString() : "";
                    anag.EMail = anagrafica["IndirizzoEmail"] != null ? anagrafica["IndirizzoEmail"].ToString() : "";
                    anag.CodiceStatoCivile = anagrafica["StatoCivile"] != null ? Utility.StringToNullableChar(anagrafica["StatoCivile"].ToString()) : null;
                    anag.DecorrenzaStatoCivile = anagrafica["DataDecorrStatoCivile"] != null ? Utility.DataFromString(anagrafica["DataDecorrStatoCivile"] != null ? anagrafica["DataDecorrStatoCivile"].ToString() : "", Utility.FormatoData.AAAAmmGG) : null;
                    anag.DataMorte = anagrafica["DataMorte"] != null ? Utility.DataFromString(anagrafica["DataMorte"] != null ? anagrafica["DataMorte"].ToString() : string.Empty, Utility.FormatoData.AAAAmmGG) : null;

                    if (!anag.CodiceComuneNascita.ToUpperInvariant().StartsWith("Z"))
                        anag.IsNatoInItalia = true;
                    else
                        anag.IsNatoInItalia = false;
                    if (anagrafica["IndResidenteEstero"] != null && anagrafica["IndResidenteEstero"].ToString() == "1")
                        anag.IsResidenteInItalia = true;
                    else
                        anag.IsResidenteInItalia = false;
                    if (elencoAnagrafiche == null)
                        elencoAnagrafiche = new List<INPS.Pensioni.Liquidazione.Entity.Anagrafica>();
                    elencoAnagrafiche.Add(anag);
                }
            }
            catch (Exception Ex)
            {
                errori = Ex.Message;
                INPS.DNA.Logging.Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        internal static bool ValorizzaPensioni(DataTable pensioniRiferimento, out List<Entity.Pensione> elencoPensioni, out string errori)
        {
            errori = "";
            elencoPensioni = null;
            try
            {
                if (pensioniRiferimento != null && pensioniRiferimento.Rows.Count > 0)
                {
                    foreach (DataRow pensione in pensioniRiferimento.Rows)
                    {
                        Entity.Pensione p = new INPS.Pensioni.Liquidazione.Entity.Pensione();
                        p.Categoria = pensione["Categoria"].ToString();
                        p.Certificato = pensione["NumeroCertificato"].ToString();
                        p.DataCalcolo = Utility.DataFromString(pensione["Decorrenza"].ToString(), Utility.FormatoData.AAAAmmGG);
                        if (!p.DataCalcolo.HasValue)
                        {
                            try
                            {
                                short anno = short.Parse("20" + pensione["Decorrenza"].ToString().Substring(0, 2));
                                short mese = short.Parse(pensione["Decorrenza"].ToString().Substring(2, 2));
                                if (anno > DateTime.Now.Year)
                                    anno -= 100;
                                p.DataCalcolo = Utility.DataFromInt(anno, mese, 1);
                            }
                            catch (Exception)
                            {
                                // Eccezione ignorata
                            }
                        }
                        p.Sede = pensione["Sede"].ToString();
                        p.TipoComponente = pensione["TipoComponente"] != DBNull.Value ? char.Parse(pensione["TipoComponente"].ToString()) : (char?)null;
                        p.Eliminazione = pensione["FlagEliminazione"] != DBNull.Value ? pensione["FlagEliminazione"].ToString().Trim() : string.Empty;
                        //TODO definire quando pensione è ricostituibile
                        p.IsRicostituibile = false;
                        if (elencoPensioni == null)
                            elencoPensioni = new List<INPS.Pensioni.Liquidazione.Entity.Pensione>();
                        elencoPensioni.Add(p);
                    }
                }
            }
            catch (Exception Ex)
            {
                errori = Ex.Message;
                INPS.DNA.Logging.Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        private static bool ValorizzaRiepilogoFromDB(Entity.ParametriARCA parametriARCA, List<GestionePensione.DatiPensione> elencoDatiDomandaDB,
            GestioneAnagrafica.DatiAnagrafici anagraficaDB, string chiaveRicerca, string matricolaOperatore, out List<Entity.Anagrafica> elencoAnagrafiche,
            out List<Entity.Domanda> elencoDomande, out List<Entity.Pensione> elencoPensioni, out string errori)
        {
            errori = "";
            elencoAnagrafiche = null;
            elencoDomande = null;
            elencoPensioni = null;
            try
            {

                if (elencoDatiDomandaDB != null && elencoDatiDomandaDB.Count > 0)
                {
                    List<GestioneDecodifica.Prodotto> elencoProdotto = null;
                    GestioneDecodifica.GetProdotto(out elencoProdotto);

                    List<GestioneDecodifica.Tipo> elencoTipo = null;
                    GestioneDecodifica.GetTipo(out elencoTipo);

                    GestioneControlliDinamici.ControlloDinamico cdDataCalcoloDefinitivoINDCOM = null;

                    foreach (GestionePensione.DatiPensione dati in elencoDatiDomandaDB)
                    {
                        if (dati != null)
                        {
                            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(dati.IndConvInt, dati.Gestione);
                            Entity.Domanda domanda = new INPS.Pensioni.Liquidazione.Entity.Domanda();
                            domanda.NumeroDomanda = dati.NDomus.ToString().PadLeft(13, '0');
                            domanda.ProgStorico = dati.ProgStorico;
                            domanda.Sede = Utility.GetCodiceSedeLavorazione(dati, Utility.IsRiaperturaDomanda(dati.Id)).ToString().PadLeft(4, '0');
                            domanda.CentroOperativo = Utility.GetCentroOperativoLavorazione(dati, Utility.IsRiaperturaDomanda(dati.Id)).ToString().PadLeft(2, '0');
                            domanda.Categoria = dati.SiglaCategoria;
                            domanda.Certificato = dati.NCertificato.ToString().PadLeft(8, '0');
                            domanda.MatricolaUtenteAcquisizione = dati.MatricolaUtenteAcquisizione;
                            domanda.CodGruppo = dati.Gruppo;
                            domanda.CodProdotto = dati.Prodotto;
                            domanda.CodTipo = dati.Tipo;
                            domanda.CodiceTipoRichiesta = dati.CodiceTipoRichiesta;
                            domanda.TipoAutomazione = dati.TipoAutomazione;
                            if (dati.CodiceSedeDestinazione.HasValue)
                            {
                                domanda.SedeDestinazione = dati.CodiceSedeDestinazione.ToString().PadLeft(4, '0');
                                domanda.CentroOperativoDestinazione = dati.CentroOperativoDestinazione.HasValue ? dati.CentroOperativo.Value.ToString().PadLeft(2, '0') : "00";
                            }

                            string descIstanza = string.Empty;
                            GestioneDecodifica.GetDescrizioneIstanza(domanda.CodGruppo, domanda.CodProdotto, domanda.CodTipo, out descIstanza);
                            domanda.DescrizioneIstanza = descIstanza;

                            //// Recupero la descrizione dellla tipologia di domanda
                            domanda.DescProdotto = elencoProdotto.Find(x => x.CodProdotto == dati.Prodotto).DescProdotto;
                            domanda.DescTipo = elencoTipo.Find(x => x.CodTipo == dati.Tipo).DescTipo;

                            if (matricolaOperatore == dati.MatricolaUtenteAcquisizione)
                                domanda.IsMatchMatricola = true;
                            else
                                domanda.IsMatchMatricola = false;

                            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(dati.Gruppo, dati.Prodotto);
                            bool isRiaperturaDomanda = Utility.IsRiaperturaDomanda(dati.Id);
                            if (tipoDomanda == Utility.TipoDomanda.Ricostituzione)
                                domanda.Tipo = "RIC";
                            else if (isRiaperturaDomanda)
                                domanda.Tipo = "TRF";
                            else
                                domanda.Tipo = "PL";

                            string decodificaStatoPensione = "";
                            if (dati.StatoPensione.HasValue)
                            {
                                BLCommon.GestioneDecodifica.GetStatoPensioneById(dati.StatoPensione.Value, out decodificaStatoPensione);
                                domanda.Stato = decodificaStatoPensione;
                            }
                            else
                                domanda.Stato = "";

                            if (tipoAppartenenza == Utility.TipoAppartenenza.AGO && (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiaperturaDomanda))
                            {
                                GestioneDatiStoricoGP.DatiStoricoGP datiStoricoGP = null;
                                GestioneDatiStoricoGP.GetDatiStoricoGPByIdPensione(dati.Id, out datiStoricoGP);
                                if (datiStoricoGP != null)
                                {
                                    domanda.GP1ALB1 = datiStoricoGP.GP1ALB1;
                                    domanda.GP2BB05 = datiStoricoGP.GP2BB05;
                                    domanda.GP1AXE3 = datiStoricoGP.GP1AXE3;
                                    domanda.IsScadenzaAssegnoConGiorno = datiStoricoGP.IsScadenzaAssegnoConGiorno;
                                    domanda.DataEliminazioneContabile = datiStoricoGP.DataEliminazioneContabile;
                                }
                            }

                            if (Utility.IsDomandaINDCOM175(domanda.Categoria, domanda.CodTipo) && cdDataCalcoloDefinitivoINDCOM == null)
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DataCalcoloDefinitivoINDCOM", out cdDataCalcoloDefinitivoINDCOM);

                            domanda.DataCalcoloDefinitivoINDCOM = cdDataCalcoloDefinitivoINDCOM != null ? Utility.DataFromString(cdDataCalcoloDefinitivoINDCOM.ValoreControllo, Utility.FormatoData.AAAAmmGG) : null;

                            domanda.DataAcquisizione = dati.DataAcquisizione;

                            //ENG - Implementazione Meta processo
                            GestioneControlliDinamici.ControlloDinamico ctrlDinamicoSbloccaMetaProcesso = null;
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("SbloccaMetaProcesso", out ctrlDinamicoSbloccaMetaProcesso);
                            if (ctrlDinamicoSbloccaMetaProcesso != null && !String.IsNullOrEmpty(ctrlDinamicoSbloccaMetaProcesso.ValoreControllo) &&
                                ctrlDinamicoSbloccaMetaProcesso.ValoreControllo.Trim().ToUpperInvariant() == "SI" &&
                                (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiaperturaDomanda))
                            {
                                domanda.CodiceSedeLavorazione = dati.CodiceSedeLavorazione;
                            }

                            if (elencoDomande == null)
                                elencoDomande = new List<INPS.Pensioni.Liquidazione.Entity.Domanda>();
                            elencoDomande.Add(domanda);
                        }
                    }
                }
                long res = 0;
                if (Int64.TryParse(chiaveRicerca, out res))
                {
                    if (!ValorizzaAnagraficaFromDB(anagraficaDB, out elencoAnagrafiche, out errori))
                        return false;
                }
                else
                {
                    DataTable anagrafica = null;
                    DataTable pensioniRiferimento = null;
                    GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
                    richiestaArca.Applicazione = parametriARCA.Applicazione;
                    richiestaArca.Provenienza = parametriARCA.Provenienza;
                    richiestaArca.Ruolo = parametriARCA.Ruolo;
                    richiestaArca.Matricola = parametriARCA.Matricola;
                    richiestaArca.CodiceFiscaleRichiedente = chiaveRicerca;
                    richiestaArca.CodiceFiscale = chiaveRicerca;

                    if (!GestioneARCA.GetAreaArcaByCodiceFiscale(richiestaArca, 0.ToString(), out anagrafica, out pensioniRiferimento, out errori))
                        return false;
                    if (!string.IsNullOrEmpty(errori))
                        return true;

                    if (anagrafica != null && anagrafica.Rows.Count > 0)
                    {
                        Entity.Anagrafica anag = new INPS.Pensioni.Liquidazione.Entity.Anagrafica();
                        GestioneARCA.NormalizzaAnagraficaArcaToDB(anagrafica.Rows[0], out anag);

                        if (elencoAnagrafiche == null)
                            elencoAnagrafiche = new List<INPS.Pensioni.Liquidazione.Entity.Anagrafica>();
                        elencoAnagrafiche.Add(anag);
                    }

                    if (!ValorizzaPensioni(pensioniRiferimento, out elencoPensioni, out errori))
                        return false;
                }
            }
            catch (Exception Ex)
            {
                string messaggio = Utility.GetMessageFromException(Ex);
                errori = "Errore tecnico nel recupero dei dati";
                string parametri = string.Format("Chiave di ricerca: {0}", chiaveRicerca);
                long numeroDomanda = 0;
                long.TryParse(chiaveRicerca, out numeroDomanda);
                GestioneLogGenerico.SalvaLogGenerico(numeroDomanda, MethodBase.GetCurrentMethod().Name, Utility.TipoLogGenerico.ErroreApplicativo, messaggio, parametri, Ex.StackTrace);
                Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        internal static bool ValorizzaAnagraficaFromDB(GestioneAnagrafica.DatiAnagrafici anagrafica, out List<Entity.Anagrafica> elencoAnagrafiche, out string errori)
        {
            errori = "";
            elencoAnagrafiche = null;
            try
            {
                if (anagrafica != null)
                {
                    Entity.Anagrafica anag = new INPS.Pensioni.Liquidazione.Entity.Anagrafica();
                    Utility.ValorizzaOggetti(anagrafica, anag);
                    if (anag.CodiceComuneNascita != null && !anag.CodiceComuneNascita.StartsWith("Z"))
                        anag.IsNatoInItalia = true;
                    else
                        anag.IsNatoInItalia = false;
                    if (anag.CodiceComuneResidenza != null && !anag.CodiceComuneResidenza.StartsWith("Z"))
                        anag.IsResidenteInItalia = true;
                    else
                        anag.IsResidenteInItalia = false;
                    if (elencoAnagrafiche == null)
                        elencoAnagrafiche = new List<INPS.Pensioni.Liquidazione.Entity.Anagrafica>();
                    elencoAnagrafiche.Add(anag);
                }
            }
            catch (Exception Ex)
            {
                errori = Ex.Message;
                INPS.DNA.Logging.Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        private static bool SalvaRiepilogo(ServiceReferences.WebDom.DatiDomanda datiDomanda, string matricolaOperatore, short sedeOperatore, short centroOperativoOperatore,
            Entity.ParametriARCA parametriARCA, bool isDomandaCalcolataProvvisoria, DateTime dataSistema, bool? isPLUnicarpeFromDB, Entity.DatiPersonaliParziali datiParzialiDA,
            bool? isPLPrepensionamentoEditoriaTipo0162FiltroEAA, bool? isPLPrepensionamentoEditoriaTipo0162FiltroEBA, bool? isPLESPAFiltroL26, bool? isPLVESO33FiltroDAP, string codTipoRichiesta, out bool isRicercaManualeDA, out bool isNuovoCertificatoGeneratoEnpals, out string errori, out string msgNonBloccante,
            out bool mostraPanelloMessBloccantePensioniOvunque, out string sedePensioneGP1ALZ6, out string codCategoriaPensione, out string certificatoInseguimentoPensione, out bool mostraPopupMemo239, out bool mostraPopupMemo312023)
        {
            errori = string.Empty;
            msgNonBloccante = string.Empty;
            isRicercaManualeDA = false;
            string chiavePensione = string.Empty;
            GestioneControlliDinamici.ControlloDinamico controlloDinamico = null;
            string nomeControlloDinamico = string.Empty;
            Utility.TipoDomanda tipoDomanda = Utility.TipoDomanda.Normale;
            short sedeChiavePensione = 0;
            isNuovoCertificatoGeneratoEnpals = false;
            DateTime? maxDecDatiCalcoloAnte96 = null;
            bool noDanteCausaAnte96 = false;
            bool isAnte96Ci = false;
            //ENG - Pensioni Ovunque: gestione nuovo pannello
            mostraPanelloMessBloccantePensioniOvunque = false;
            sedePensioneGP1ALZ6 = string.Empty;
            codCategoriaPensione = string.Empty;
            certificatoInseguimentoPensione = string.Empty;
            mostraPopupMemo239 = false;
            bool isDetrazioniObbligatorio = false;
            mostraPopupMemo312023 = false;

            try
            {
                if (datiDomanda != null && datiDomanda.Dati != null && datiDomanda.Dati.Domanda != null &&
                    datiDomanda.Dati.Domanda.Rows.Count > 0)
                {
                    bool isRiapertura = false;
                    if (datiDomanda.Dati != null && datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Count > 0)
                        isRiapertura = Utility.IsRiaperturaDomanda(datiDomanda.Dati.Fase.LastOrDefault().CodFase);

                    GestionePensione.DatiPensione datiPensione = null;
                    if (!ValorizzaPensioneToDB(datiDomanda, isRiapertura, out datiPensione, out errori))
                        return false;

                    Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
                    Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);


                    // Blocco Prestazioni Pl
                    GestioneControlliDinamici.ControlloDinamico bloccoPrestazioniPL = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("BloccoPrestazioniPL", out bloccoPrestazioniPL);
                    if (Utility.IsDomandaPL(datiPensione) && Utility.IsDomandaBloccoPrestazioniPL(datiPensione) && bloccoPrestazioniPL != null && !String.IsNullOrEmpty(bloccoPrestazioniPL.ValoreControllo) && bloccoPrestazioniPL.ValoreControllo == "SI")
                    {
                        errori = "La domanda non può essere definita in quanto sono in corso aggiornamenti della procedura";
                        return true;
                    }

                    // ENG - Introdotto messaggio bloccante in fase di prelievo per le domande del vecchio prepensionamento editoria con il filtro vuoto
                    if (tipoAppartenenza == Utility.TipoAppartenenza.AGO)
                    {
                        if (Utility.IsPrepensionamentoEditoriaTipo0162(datiPensione) && String.IsNullOrEmpty(datiPensione.GetFiltro()))
                        {
                            errori = "Domanda attualmente non lavorabile. Per procedere occorre utilizzare la funzione 'Modifica' presente in Webdom nella schermata di riepilogo di tale domus, in modo che sia aggiunto il campo 'Tipologia'";
                            return true;
                        }
                    }

                    //ENG - Inserito blocco per gruppo 0002 e prodotto 0011
                    if (Utility.IsAssegnoInvalidita(datiPensione))
                    {
                        GestioneControlliDinamici.ControlloDinamico ctrlMemo239_2025 = null;
                        GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DataAbilitazioneMemo239_2025", out ctrlMemo239_2025);

                        if (ctrlMemo239_2025 != null && !String.IsNullOrEmpty(ctrlMemo239_2025.ValoreControllo) && !String.IsNullOrEmpty(ctrlMemo239_2025.ValoreControllo.Trim()))
                        {
                            DateTime? dataAperturaMemoProduzione = Utility.DataFromString(ctrlMemo239_2025.ValoreControllo.Trim(), Utility.FormatoData.AAAAmmGG);
                            if (dataAperturaMemoProduzione != null && Utility.DataSuccessivaA(datiPensione.DataPresentazioneDomanda, dataAperturaMemoProduzione.GetValueOrDefault()))
                            {

                                ServiceReferences.WebDom.RispostaEsiti rispostaEsiti = null;
                                if (GestioneWebDom.GetEsitiSanitario(datiPensione.NDomus.ToString(), out rispostaEsiti, out errori))
                                {
                                    if (rispostaEsiti == null || String.IsNullOrEmpty(rispostaEsiti.CodEsitoInvalidita) || String.IsNullOrEmpty(rispostaEsiti.CodEsitoInvalidita.Trim())
                                        || rispostaEsiti.CodEsitoInvalidita.Trim() != "2")
                                    {
                                        //ENG - Eseguo il messaggio bloccante se non è attivo il Popup
                                        GestioneControlliDinamici.ControlloDinamico ctrlMemo239_2025_AttivaPopup = null;
                                        GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("MEMO_239_2025_Attivapopup", out ctrlMemo239_2025_AttivaPopup);
                                        if (ctrlMemo239_2025_AttivaPopup == null || String.IsNullOrEmpty(ctrlMemo239_2025_AttivaPopup.ValoreControllo) || ctrlMemo239_2025_AttivaPopup.ValoreControllo.Trim().ToUpperInvariant() == "NO")
                                        {
                                            errori = "ATTENZIONE: Lavorazione non consentita. Verificare la corretta valorizzazione dei campi relativi al giudizio medico legale su Webdom";
                                            return true;
                                        }
                                        else
                                        {
                                            mostraPopupMemo239 = true;
                                        }
                                    }
                                }
                                else
                                    return true;
                            }
                        }
                    }

                    Entity.Anagrafica anagraficaDA = null;
                    BLCommon.GestioneDanteCausa.DatiDanteCausa danteCausa = null;
                    List<BLCommon.GestioneDatiContributiviCi.DatiPostDecOriginaria> listaDatiPostDecOriginaria = null;
                    bool isRicRev = false;
                    bool isDiretta = false;
                    bool isResEsteroPerRic = false;
                    bool isSupplementiPerRic = false;
                    bool isSupplementiPerRev = false;
                    bool isBancRicTrf = false;
                    GestioneCtrlRic.ControlTabRic controlTabRic = null;
                    object prelievo = null;

                    GestioneControlliDinamici.ControlloDinamico controlloDinamicoSpacchettate024 = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneSpacchettate024", out controlloDinamicoSpacchettate024);

                    //ENG - MEMO 74_2023
                    GestioneControlliDinamici.ControlloDinamico ctrlMemo74_2023 = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo74_2023", out ctrlMemo74_2023);

                    //ENG - Memo 123/2024
                    GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

                    //ENG - Memo 123/2024
                    GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

                    if (isRiapertura)
                        GestioneCtrlRic.GetCtrlTabRic("0107", tipoAppartenenza, out controlTabRic); // Le riaperture vengono trattate come ricostituzioni per motivi contributivi (Prodotto = 0107)
                    else
                        GestioneCtrlRic.GetCtrlTabRic(datiPensione.Prodotto, tipoAppartenenza, out controlTabRic);

                    if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) && Utility.IsDomandaBancari(datiPensione.SiglaCategoria))
                    {
                        isBancRicTrf = true;
                    }

                    #region Domanda LIPE

                    if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO && Utility.AbilitaControlloLIPE())
                        if (IsDomandaLIPE(datiPensione, isDiretta, out errori))
                            return true;

                    #endregion Domanda LIPE

                    GestioneLavorazione.DatiLavorazione datiLavorazione = new GestioneLavorazione.DatiLavorazione();
                    if (datiDomanda.Dati != null && datiDomanda.Dati.Istanza != null && datiDomanda.Dati.Istanza.Rows.Count > 0)
                    {
                        tipoDomanda = Utility.GetTipoDomanda(datiDomanda.Dati.Istanza[0].CodGruppo, datiDomanda.Dati.Istanza[0].CodProdotto);
                        if (tipoDomanda == Utility.TipoDomanda.Superstiti || tipoDomanda == Utility.TipoDomanda.Ricostituzione || tipoDomanda == Utility.TipoDomanda.Ripristino ||
                            tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti || tipoDomanda == Utility.TipoDomanda.Riliquidazione || tipoDomanda == Utility.TipoDomanda.RiliquidazioneSuperstiti || isRiapertura)
                        {
                            // Per le domande ai superstiti senza pensione di riferimento non effettu o il blocco
                            if (!(tipoDomanda == Utility.TipoDomanda.Superstiti && (datiDomanda.Dati.PensioneRiferimento.Rows.Count == 0 || isPensioneRiferimentoNull(datiDomanda.Dati.PensioneRiferimento[0]))))
                                nomeControlloDinamico = GetNameControlloDinamico(tipoDomanda, tipoAppartenenza, isRiapertura);
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo(nomeControlloDinamico, out controlloDinamico);
                            if (controlloDinamico != null && controlloDinamico.ValoreControllo == "SI")
                            {
                                errori = "Prelievo al momento non disponibile";
                                return true;
                            }
                            switch (tipoAppartenenza)
                            {
                                case Utility.TipoAppartenenza.FS:
                                    if (!PrelevaFs(parametriARCA, datiDomanda, sedeOperatore, centroOperativoOperatore, parametriARCA, tipoDomanda, datiPensione,
                                        ref datiLavorazione, ref chiavePensione, out anagraficaDA, out danteCausa, out prelievo, out isRicRev, out isDiretta,
                                        out isResEsteroPerRic, out isSupplementiPerRic, out errori, out mostraPanelloMessBloccantePensioniOvunque, out sedePensioneGP1ALZ6, out codCategoriaPensione))
                                        return false;
                                    break;
                                case Utility.TipoAppartenenza.CI:
                                    if (!PrelevaCi(parametriARCA, datiDomanda, sedeOperatore, centroOperativoOperatore, parametriARCA, tipoDomanda, datiPensione,
                                        ref datiLavorazione, out anagraficaDA, out danteCausa, out listaDatiPostDecOriginaria, out prelievo, out isRicRev, out isDiretta, out errori,
                                        out mostraPanelloMessBloccantePensioniOvunque, out sedePensioneGP1ALZ6, out codCategoriaPensione, out isAnte96Ci))
                                        return false;
                                    break;
                                case Utility.TipoAppartenenza.AGO:
                                    if (!PrelevaAgo(parametriARCA, datiDomanda, sedeOperatore, centroOperativoOperatore, parametriARCA, tipoDomanda, datiPensione, datiParzialiDA,
                                        ref chiavePensione, ref datiLavorazione, out anagraficaDA, out danteCausa, out prelievo, out isRicRev, out isDiretta, out isRicercaManualeDA, out maxDecDatiCalcoloAnte96, out errori, out msgNonBloccante,
                                        out mostraPanelloMessBloccantePensioniOvunque, out sedePensioneGP1ALZ6, out codCategoriaPensione, out certificatoInseguimentoPensione))
                                        return false;
                                    break;
                            }

                            if (!String.IsNullOrEmpty(errori))
                                return true;

                            if (maxDecDatiCalcoloAnte96 != null && isRicercaManualeDA)
                            {
                                noDanteCausaAnte96 = true;
                                isRicercaManualeDA = false;
                            }

                            if (isAnte96Ci)
                                noDanteCausaAnte96 = true;

                            if ((Utility.IsRicostituzione(datiPensione.Gruppo) || isRiapertura) && Utility.IsPensioniOvunqueAttiva(Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione)))
                            {
                                //ENG - Per la linea AGO c'è un discorso diverso a causa dell'inseguimento della Pensione
                                if (tipoAppartenenza == Utility.TipoAppartenenza.AGO)
                                {
                                    if (prelievo != null)
                                    {
                                        ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                                        sedeChiavePensione = prelievoAgo.Risposta.SedePensione;
                                    }
                                }
                                else
                                {
                                    if (Utility.IsRicostituzione(datiPensione.Gruppo))
                                        short.TryParse((datiDomanda.Dati.PensioneRiferimento[0].CodProvinciaRifAttuale.Substring(1) + datiDomanda.Dati.PensioneRiferimento[0].CodZonaRifAttuale.Substring(1)), out sedeChiavePensione);
                                    else
                                        short.TryParse((datiDomanda.Dati.PensioneGenerata[0].CodProvinciaGenAttuale.Substring(1) + datiDomanda.Dati.PensioneGenerata[0].CodZonaGenAttuale.Substring(1)), out sedeChiavePensione);
                                }
                            }
                        }
                        else if (datiDomanda.Dati != null && datiDomanda.Dati.Istanza != null && datiDomanda.Dati.Istanza.Rows.Count > 0 &&
                            tipoAppartenenza == Utility.TipoAppartenenza.FS)
                        {
                            datiLavorazione.TipoReversibilita = null;
                            datiLavorazione.TipoLiquidazione = "A1";
                        }
                    }

                    //ENG - SOPGI
                    if (Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, danteCausa))
                    {
                        if (prelievo != null)
                        {
                            ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;

                            if (prelievoAgo.Risposta != null && (prelievoAgo.Risposta.DatiPensione == null || (!prelievoAgo.Risposta.DatiPensione.TipoCalcolo.HasValue
                                && !prelievoAgo.Risposta.DatiPensione.InizioAssicurazione.HasValue && !prelievoAgo.Risposta.DatiPensione.FineAssicurazione.HasValue))
                                && (prelievoAgo.Risposta.DatiIstruttoria == null || !prelievoAgo.Risposta.DatiIstruttoria.NSettimaneOBG.HasValue || prelievoAgo.Risposta.DatiIstruttoria.NSettimaneOBG.Value == 0)
                                && (prelievoAgo.Risposta.ListaCalcoloContributivo == null || prelievoAgo.Risposta.ListaCalcoloContributivo.Count() == 0)
                                && (prelievoAgo.Risposta.ListaCalcoloRetributivo == null || prelievoAgo.Risposta.ListaCalcoloRetributivo.Count() == 0)
                                && (prelievoAgo.Risposta.ListaDatiRetributiviINPGI == null || prelievoAgo.Risposta.ListaDatiRetributiviINPGI.Count() == 0)
                                && (prelievoAgo.Risposta.ListaDatiContributiviINPGI == null || prelievoAgo.Risposta.ListaDatiContributiviINPGI.Count() == 0))
                            {
                                errori = "Pensione diretta liquidata su sistema proprietario INPGI. La pensione di reversibilità dovrà essere lavorata sullo stesso sistema";
                                return true;
                            }

                        }
                    }

                    //ENG - Inserimento Chiave per apertura/chiusura RIC/TRF
                    if ((Utility.IsRicostituzione(datiPensione.Gruppo) || isRiapertura) && prelievo != null)
                    {
                        List<GestioneDecodifica.GruppoOneri> elencoGruppoOneri = null;
                        GestioneDecodifica.GetGruppoOneri(out elencoGruppoOneri);

                        List<GestioneDecodifica.SottoGruppoOneri> elencoSottoGruppoOneri = null;
                        GestioneDecodifica.GetSottoGruppoOneri(out elencoSottoGruppoOneri);

                        GestioneOneri.DatiOneri[] listaOneriDaPrelievo = null;
                        string naturaPensioneDaPrelievo = string.Empty;
                        switch (tipoAppartenenza)
                        {
                            case Utility.TipoAppartenenza.AGO:
                                ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                                if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.ListaDatiOneri != null)
                                    listaOneriDaPrelievo = prelievoAgo.Risposta.ListaDatiOneri;
                                if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiPensione != null && !String.IsNullOrEmpty(prelievoAgo.Risposta.DatiPensione.NaturaPensione))
                                    naturaPensioneDaPrelievo = prelievoAgo.Risposta.DatiPensione.NaturaPensione;
                                break;
                            case Utility.TipoAppartenenza.FS:
                                ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFs = (ServiceReferences.LiquidazioneFs.AreaPrelievo)prelievo;
                                if (prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.ListaDatiOneri != null)
                                    listaOneriDaPrelievo = prelievoFs.Risposta.ListaDatiOneri;
                                if (prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiPensione != null && !String.IsNullOrEmpty(prelievoFs.Risposta.DatiPensione.NaturaPensione))
                                    naturaPensioneDaPrelievo = prelievoFs.Risposta.DatiPensione.NaturaPensione;
                                break;
                            case Utility.TipoAppartenenza.CI:
                                ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoCi = (ServiceReferences.LiquidazioneCi.AreaPrelievo)prelievo;
                                if (prelievoCi != null && prelievoCi.Risposta != null && prelievoCi.Risposta.ListaDatiOneri != null)
                                    listaOneriDaPrelievo = prelievoCi.Risposta.ListaDatiOneri;
                                if (prelievoCi != null && prelievoCi.Risposta != null && prelievoCi.Risposta.DatiPensione != null && !String.IsNullOrEmpty(prelievoCi.Risposta.DatiPensione.NaturaPensione))
                                    naturaPensioneDaPrelievo = prelievoCi.Risposta.DatiPensione.NaturaPensione;
                                break;
                        }

                        if (listaOneriDaPrelievo != null && listaOneriDaPrelievo.Count() > 0)
                        {
                            bool isOpzioneDonna2023 = false;
                            bool isPrepensionamentoFiltroEAA = false;
                            bool isPrepensionamnetoFiltroEBA = false;
                            bool isDomandaAnticipataFlessibile = false;
                            bool isDomandaAnticipataFlessibileOpzioneContributivo = false;
                            bool isDomandaAnticipataFlessibileLeggeBilancio2024 = false;
                            bool isDomandaAnticipataFlessibileOpzioneContributivoOpzioneContributivoLeggeBilancio2024 = false;

                            if (elencoGruppoOneri.Exists(y => y.Code == "5900") && elencoSottoGruppoOneri.Exists(y => y.Code == "5901") && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeGruppo == elencoGruppoOneri.Find(y => y.Code == "5900").Id) && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeSottoGruppo == elencoSottoGruppoOneri.Find(y => y.Code == "5901").Id))
                                isOpzioneDonna2023 = true;
                            else if (elencoGruppoOneri.Exists(y => y.Code == "0900") && elencoSottoGruppoOneri.Exists(y => y.Code == "0903") && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeGruppo == elencoGruppoOneri.Find(y => y.Code == "0900").Id) && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeSottoGruppo == elencoSottoGruppoOneri.Find(y => y.Code == "0903").Id))
                                isPrepensionamentoFiltroEAA = true;
                            else if (elencoGruppoOneri.Exists(y => y.Code == "0900") && elencoSottoGruppoOneri.Exists(y => (y.Code == "0907" || y.Code == "0908")) && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeGruppo == elencoGruppoOneri.Find(y => y.Code == "0900").Id) && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeSottoGruppo == elencoSottoGruppoOneri.Find(y => (y.Code == "0907" || y.Code == "0908")).Id))
                                isPrepensionamnetoFiltroEBA = true;
                            else if (elencoGruppoOneri.Exists(y => y.Code == "6000") && elencoSottoGruppoOneri.Exists(y => (y.Code == "6001" || y.Code == "6002"))
                                    && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeGruppo == elencoGruppoOneri.Find(y => y.Code == "6000").Id)
                                    && (listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeSottoGruppo == elencoSottoGruppoOneri.Find(y => y.Code == "6001").Id) || listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeSottoGruppo == elencoSottoGruppoOneri.Find(y => y.Code == "6002").Id))
                                     && !String.IsNullOrEmpty(naturaPensioneDaPrelievo) && naturaPensioneDaPrelievo.Length == 3 && naturaPensioneDaPrelievo.Substring(1, 1) == "J")
                                isDomandaAnticipataFlessibileOpzioneContributivo = true;
                            else if (elencoGruppoOneri.Exists(y => y.Code == "6000") && elencoSottoGruppoOneri.Exists(y => (y.Code == "6001" || y.Code == "6002")) && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeGruppo == elencoGruppoOneri.Find(y => y.Code == "6000").Id) && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeSottoGruppo == elencoSottoGruppoOneri.Find(y => (y.Code == "6001" || y.Code == "6002")).Id))
                                isDomandaAnticipataFlessibile = true;
                            else if (elencoGruppoOneri.Exists(y => y.Code == "6100") && elencoSottoGruppoOneri.Exists(y => (y.Code == "6101" || y.Code == "6102"))
                                  && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeGruppo == elencoGruppoOneri.Find(y => y.Code == "6100").Id)
                                  && (listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeSottoGruppo == elencoSottoGruppoOneri.Find(y => y.Code == "6101").Id) || listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeSottoGruppo == elencoSottoGruppoOneri.Find(y => y.Code == "6102").Id))
                                   && !String.IsNullOrEmpty(naturaPensioneDaPrelievo) && naturaPensioneDaPrelievo.Length == 3 && naturaPensioneDaPrelievo.Substring(1, 1) == "J")
                                isDomandaAnticipataFlessibileOpzioneContributivoOpzioneContributivoLeggeBilancio2024 = true;
                            else if (elencoGruppoOneri.Exists(y => y.Code == "6100") && elencoSottoGruppoOneri.Exists(y => (y.Code == "6101" || y.Code == "6102")) && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeGruppo == elencoGruppoOneri.Find(y => y.Code == "6100").Id) && listaOneriDaPrelievo.ToList().Exists(x => x.IdCodeSottoGruppo == elencoSottoGruppoOneri.Find(y => (y.Code == "6101" || y.Code == "6102")).Id))
                                isDomandaAnticipataFlessibileLeggeBilancio2024 = true;

                            GestioneControlliDinamici.ControlloDinamico controlloDinamicoRICeTRF = null;

                            if (isOpzioneDonna2023)
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("RICeTRFOpzioneDonna2023", out controlloDinamicoRICeTRF);
                            else if (isPrepensionamentoFiltroEAA)
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("RICeTRFPoligrafici162EAA", out controlloDinamicoRICeTRF);
                            else if (isPrepensionamnetoFiltroEBA)
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("RICeTRFPoligrafici162EBA", out controlloDinamicoRICeTRF);
                            else if (isDomandaAnticipataFlessibile)
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("RICeTRFQuota103", out controlloDinamicoRICeTRF);
                            else if (isDomandaAnticipataFlessibileOpzioneContributivo)
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("RICeTRFQuotaAnticipataFlessibileOpzioneContr", out controlloDinamicoRICeTRF);
                            else if (isDomandaAnticipataFlessibileLeggeBilancio2024)
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out controlloDinamicoRICeTRF);
                            else if (isDomandaAnticipataFlessibileOpzioneContributivoOpzioneContributivoLeggeBilancio2024)
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out controlloDinamicoRICeTRF);

                            if (isOpzioneDonna2023)
                            {
                                DateTime? dataPerfezionamentoRequisiti = null;
                                if (tipoAppartenenza == Utility.TipoAppartenenza.AGO)
                                {
                                    ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                                    if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiPensione != null && prelievoAgo.Risposta.DatiPensione.DataPerfezionamentoRequisiti != null)
                                        dataPerfezionamentoRequisiti = prelievoAgo.Risposta.DatiPensione.DataPerfezionamentoRequisiti;
                                }
                                else if (tipoAppartenenza == Utility.TipoAppartenenza.CI)
                                {
                                    ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoCi = (ServiceReferences.LiquidazioneCi.AreaPrelievo)prelievo;
                                    if (prelievoCi != null && prelievoCi.Risposta != null && prelievoCi.Risposta.DatiPensione != null && prelievoCi.Risposta.DatiPensione.DataPerfezionamentoRequisiti != null)
                                        dataPerfezionamentoRequisiti = prelievoCi.Risposta.DatiPensione.DataPerfezionamentoRequisiti;
                                }
                                else if (tipoAppartenenza == Utility.TipoAppartenenza.FS)
                                {
                                    ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFs = (ServiceReferences.LiquidazioneFs.AreaPrelievo)prelievo;
                                    if (prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiPensione != null && prelievoFs.Risposta.DatiPensione.DataPerfezionamentoRequisiti != null)
                                        dataPerfezionamentoRequisiti = prelievoFs.Risposta.DatiPensione.DataPerfezionamentoRequisiti;
                                }

                                if (controlloDinamicoRICeTRF != null && !String.IsNullOrEmpty(controlloDinamicoRICeTRF.ValoreControllo) && !String.IsNullOrEmpty(controlloDinamicoRICeTRF.ValoreControllo.Trim()) &&
                                    controlloDinamicoRICeTRF.ValoreControllo == "NO" && dataPerfezionamentoRequisiti.HasValue && Utility.DataSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2024, 01, 01)))
                                {
                                    errori = "Prelievo al momento non disponibile";
                                    return true;
                                }
                            }
                            else if (controlloDinamicoRICeTRF != null && !String.IsNullOrEmpty(controlloDinamicoRICeTRF.ValoreControllo) && !String.IsNullOrEmpty(controlloDinamicoRICeTRF.ValoreControllo.Trim()) &&
                                controlloDinamicoRICeTRF.ValoreControllo == "NO")
                            {
                                errori = "Prelievo al momento non disponibile";
                                return true;
                            }
                        }
                    }

                    //ENG - Inserimento Blocco RIC 024 Reversibilita
                    if (Utility.IsRicostituzione(datiPensione.Gruppo) && (Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, danteCausa, datiLavorazione) || ((datiPensione != null && datiPensione.SiglaCategoria != null) && (datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SFS" || datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SPT")))
                        && tipoAppartenenza == Utility.TipoAppartenenza.FS && tipoFondo.HasValue
                        && (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT))
                    {
                        ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFs = (ServiceReferences.LiquidazioneFs.AreaPrelievo)prelievo;
                        GestioneControlliDinamici.ControlloDinamico controlloDinamicoRICRevers024 = null;
                        GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("BloccoRicReversib024", out controlloDinamicoRICRevers024);
                        GestioneControlliDinamici.ControlloDinamico controlloDinamicoDecorrenzaBloccoRicReversib024 = null;
                        GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DecorrenzaBloccoRicReversib024", out controlloDinamicoDecorrenzaBloccoRicReversib024);

                        if (controlloDinamicoDecorrenzaBloccoRicReversib024 != null && !String.IsNullOrEmpty(controlloDinamicoDecorrenzaBloccoRicReversib024.ValoreControllo) && !String.IsNullOrEmpty(controlloDinamicoDecorrenzaBloccoRicReversib024.ValoreControllo.Trim()))
                        {
                            DateTime? dataDecorrenzaBloccoRicReversib024 = Utility.DataFromString(controlloDinamicoDecorrenzaBloccoRicReversib024.ValoreControllo.Trim(), Utility.FormatoData.AAAAmmGG);

                            if (controlloDinamicoRICRevers024 != null && !String.IsNullOrEmpty(controlloDinamicoRICRevers024.ValoreControllo)
                                && !String.IsNullOrEmpty(controlloDinamicoRICRevers024.ValoreControllo.Trim())
                                && controlloDinamicoRICRevers024.ValoreControllo.Trim().ToUpperInvariant() == "SI" && dataDecorrenzaBloccoRicReversib024.HasValue && datiPensione != null && datiPensione.DecorrenzaOriginaria.HasValue && Utility.DataSuccessivaA(dataDecorrenzaBloccoRicReversib024.GetValueOrDefault(), datiPensione.DecorrenzaOriginaria.GetValueOrDefault()))
                            {
                                errori = "Prelievo al momento non disponibile";
                                return true;
                            }

                        }
                    }

                    //ENG - Inserito blocco in fase di prelievo per le RIC/TRF con tipoSettimaneBeneficio = 16 o 17 e controllo dinamico AbilitazioneRIC_TRFMemo16_2020 = NO
                    if (tipoAppartenenza == Utility.TipoAppartenenza.AGO && (Utility.IsRicostituzione(datiPensione.Gruppo) || isRiapertura))
                    {
                        ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                        if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiMaggiorazioniBenefici != null && prelievoAgo.Risposta.DatiMaggiorazioniBenefici.TipoSettimaneBeneficio != null &&
                            (prelievoAgo.Risposta.DatiMaggiorazioniBenefici.TipoSettimaneBeneficio.Trim() == "16" || prelievoAgo.Risposta.DatiMaggiorazioniBenefici.TipoSettimaneBeneficio.Trim() == "17"))
                        {
                            GestioneControlliDinamici.ControlloDinamico ctrlAbilitazioneRIC_TRFMemo16_2020 = null;
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo16_2020", out ctrlAbilitazioneRIC_TRFMemo16_2020);

                            if (ctrlAbilitazioneRIC_TRFMemo16_2020 != null && !String.IsNullOrEmpty(ctrlAbilitazioneRIC_TRFMemo16_2020.ValoreControllo) && !String.IsNullOrEmpty(ctrlAbilitazioneRIC_TRFMemo16_2020.ValoreControllo.Trim()) &&
                                ctrlAbilitazioneRIC_TRFMemo16_2020.ValoreControllo == "NO")
                            {
                                errori = "Prelievo al momento non disponibile";
                                return true;
                            }
                        }
                    }

                    //ENG - per le pensioni di reversibilità (Gruppo= 0003 prodotto= 0021) delle ENPALS (Categoria 203=SOSPETT; Categoria 206= SOSPORT)
                    //- Blocco prelievo se la categoria del DC è IOSPETT o IOSPORT e il codice natura al primo byte ha valore diverso da “3“, "4" o “5” e al secondo byte ha un valore diverso da “1” 
                    if (Utility.IsDomandaReversibilita(datiPensione) && (datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SOSPETT" || datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SOSPORT"))
                    {
                        if (datiDomanda != null && datiDomanda.Dati != null && datiDomanda.Dati.PensioneRiferimento != null && datiDomanda.Dati.PensioneRiferimento.Count > 0 && datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav != null &&
                            (datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav.ToUpperInvariant().Trim() == "IOSPETT" || datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav.ToUpperInvariant().Trim() == "IOSPORT"))
                        {
                            ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                            if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiPensione != null && prelievoAgo.Risposta.DatiPensione.NaturaPensione != null &&
                                !(prelievoAgo.Risposta.DatiPensione.NaturaPensione.Substring(0, 1) == "3" || prelievoAgo.Risposta.DatiPensione.NaturaPensione.Substring(0, 1) == "4" || prelievoAgo.Risposta.DatiPensione.NaturaPensione.Substring(0, 1) == "5") && prelievoAgo.Risposta.DatiPensione.NaturaPensione.Substring(1, 1) != "1")
                            {
                                errori = "Attenzione! La diretta del dante causa ha categoria IOSPETT o IOSPORT: è necessario verificare che il primo byte del codice natura sia 3 o 4 (inabilità) o 5 (pensione supplementare) oppure che il secondo byte sia uguale a 1 (invalidità specifica)";
                                return true;
                            }
                        }
                    }

                    //ENG - Memo 91_2025
                    if (tipoAppartenenza == Utility.TipoAppartenenza.AGO || tipoAppartenenza == Utility.TipoAppartenenza.CI)
                    {
                        GestioneControlliDinamici.ControlloDinamico ctrlAbilitazioneMemo91_2025 = null;
                        GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo91_2025", out ctrlAbilitazioneMemo91_2025);
                        if (ctrlAbilitazioneMemo91_2025 != null && ctrlAbilitazioneMemo91_2025.ValoreControllo == "SI")
                        {
                            if (((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0004") || (datiPensione.Gruppo == "0003" && datiPensione.Prodotto == "0022" && datiPensione.Tipo == "0004")) &&
                                datiPensione.DataPresentazioneDomanda != null && Utility.DataSuccessivaA(datiPensione.DataPresentazioneDomanda, new DateTime(2025, 01, 01)))
                            {
                                errori = "Attenzione la domanda non può essere liquidata a seguito dell’abrogazione dell’art 2 ter della legge n. 114/74 (circolare 53/2025)";
                                return true;
                            }
                        }
                    }

                    GestionePensione.DatiPatronato datiPatronato = null;
                    if (datiDomanda.Dati.Delega != null && datiDomanda.Dati.Delega.Rows.Count > 0)
                    {
                        for (int i = 0; i < datiDomanda.Dati.Delega.Rows.Count; i++)
                        {
                            DateTime? dataFine = Utility.DataFromString((datiDomanda.Dati.Delega[i]["DataFine"] == DBNull.Value ?
                                string.Empty : datiDomanda.Dati.Delega[i]["DataFine"].ToString()), Utility.FormatoData.AAAAmmGG);
                            if (!dataFine.HasValue)
                            {
                                datiPatronato = new GestionePensione.DatiPatronato(datiDomanda.Dati.Delega[i]["CodInpsPatronato"] == DBNull.Value ? null : datiDomanda.Dati.Delega[i]["CodInpsPatronato"].ToString().Trim(),
                                    datiDomanda.Dati.Delega[i]["CodUfficioPatronato"] == DBNull.Value ? null : datiDomanda.Dati.Delega[i]["CodUfficioPatronato"].ToString().Trim(),
                                    datiDomanda.Dati.Delega[i]["EstremiPratica"] == DBNull.Value ? null : datiDomanda.Dati.Delega[i]["EstremiPratica"].ToString().Trim(),
                                    datiDomanda.Dati.Delega[i]["CodTipoDelega"] == DBNull.Value ? null : datiDomanda.Dati.Delega[i]["CodTipoDelega"].ToString().Trim());
                                break;
                            }
                        }
                    }

                    tipoDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);

                    GestionePensione.DatiSindacato datiSindacato = null;
                    if (tipoDomanda != Utility.TipoDomanda.Ricostituzione && !isRiapertura)
                        if (datiDomanda.Dati.Sindacato != null && datiDomanda.Dati.Sindacato.Rows.Count > 0)
                        {
                            for (int i = 0; i < datiDomanda.Dati.Sindacato.Rows.Count; i++)
                            {
                                DateTime? dataFine = Utility.DataFromString((datiDomanda.Dati.Sindacato[i]["DataFine"] == DBNull.Value ?
                                    string.Empty : datiDomanda.Dati.Sindacato[i]["DataFine"].ToString()), Utility.FormatoData.AAAAmmGG);
                                var isPresenteCodSindacato = !(datiDomanda.Dati.Sindacato[i]["CodSindacato"] == DBNull.Value || string.IsNullOrEmpty(datiDomanda.Dati.Sindacato[i]["CodSindacato"].ToString()));
                                if (!dataFine.HasValue && isPresenteCodSindacato)
                                {
                                    datiSindacato = new GestionePensione.DatiSindacato(datiDomanda.Dati.Sindacato[i]["CodSindacato"] == DBNull.Value || string.IsNullOrEmpty(datiDomanda.Dati.Sindacato[i]["CodSindacato"].ToString()) ? null : datiDomanda.Dati.Sindacato[i]["CodSindacato"].ToString().Trim(),
                                        string.Empty,
                                        datiDomanda.Dati.Sindacato[i]["DataInizio"] == DBNull.Value ? null : Utility.DataFromString(datiDomanda.Dati.Sindacato[i]["DataInizio"].ToString().Trim(), Utility.FormatoData.AAAAmmGG),
                                        datiDomanda.Dati.Sindacato[i]["DataFine"] == DBNull.Value ? null : Utility.DataFromString(datiDomanda.Dati.Sindacato[i]["DataFine"].ToString().Trim(), Utility.FormatoData.AAAAmmGG), true);
                                    break;
                                }
                            }
                        }

                    GestionePagamento.DatiPagamento datiPagamento = null;

                    if (!((tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura || tipoDomanda == Utility.TipoDomanda.Ripristino || tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti) && (tipoAppartenenza == Utility.TipoAppartenenza.AGO || tipoAppartenenza == Utility.TipoAppartenenza.CI)))
                        RecuperaModPagamento(datiDomanda, tipoAppartenenza, tipoFondo, out datiPagamento);

                    if (Utility.IsDomandaINPDAP(datiPensione.Gestione))
                    {
                        if (datiDomanda != null && datiDomanda.DatiInternet != null && datiDomanda.DatiInternet.domandaInpdap != null && datiDomanda.DatiInternet.domandaInpdap.AdesioneFondoCredito != null)
                        {
                            if (datiPagamento == null)
                                datiPagamento = new GestionePagamento.DatiPagamento();

                            if (datiDomanda.DatiInternet.domandaInpdap.AdesioneFondoCredito == "S")
                                datiPagamento.TrattenutaInpdap = true;
                        }
                    }

                    //recupero familiari da WebDom
                    List<GestioneFamiliari.FamiliareRecuperato> CFfamiliari = null;
                    bool isConiugePresente = false;
                    bool isUnitoCivilePresente = false;

                    if (tipoDomanda != Utility.TipoDomanda.Ricostituzione && !isRiapertura)
                    {
                        if (datiDomanda.Dati.Soggetto != null && datiDomanda.Dati.Soggetto.Rows.Count > 0)
                        {
                            RecuperaFamiliari(datiDomanda, datiPensione, out CFfamiliari, out isConiugePresente, out isUnitoCivilePresente, isRiapertura, Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa));
                            if (CFfamiliari != null && CFfamiliari.Count > 0)
                            {
                                List<GestioneFamiliari.FamiliareRecuperato> listaFamiliariApp = Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) || Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) || (controlloDinamicoSpacchettate024 != null && controlloDinamicoSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, isRiapertura))
                                    || Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiapertura) ? CFfamiliari.FindAll(x => x.TipoComponente != 'T') : CFfamiliari;
                                if (listaFamiliariApp.Exists(x => x.SiglaFamiliare == 'R'))
                                {
                                    errori = "La domanda non è lavorabile in presenza di un familiare/contitolare con grado di parentela \"R - Ex Coniuge\".";
                                    return true;
                                }
                            }
                        }
                    }

                    List<GestioneAventiDiritto.AventeDirittoRecuperato> listaAventiDirittoWebDom = null;

                    if (Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa)
                        || (controlloDinamicoSpacchettate024 != null && controlloDinamicoSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, isRiapertura))
                        || Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiapertura))
                    {
                        if ((tipoDomanda != Utility.TipoDomanda.Ricostituzione && tipoDomanda != Utility.TipoDomanda.RipristinoSuperstiti))
                        {
                            if (!RecuperaAventiDirittoFromWebDom(datiDomanda, out listaAventiDirittoWebDom, out errori))
                                return true;
                            if (listaAventiDirittoWebDom == null || listaAventiDirittoWebDom.Count == 0)
                            {
                                errori = "Acquisire gli aventi diritto attraverso la funzionalità ‘Spacchettamento’ presente in Webdom";
                                return true;
                            }
                        }
                    }

                    bool isResidenteEstero = false;
                    string codiceFiscale = string.Empty;
                    //GestioneAnagrafica.DatiAnagrafici datiAnagraficiDB = null;
                    //GestioneAnagrafica.GetAnagraficaByNumeroDomanda(datiPensione.NDomus, out datiAnagraficiDB);

                    //if (datiAnagraficiDB != null)
                    //codiceFiscale = datiAnagraficiDB.CodiceFiscale;

                    GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                    //if (datiAnagraficiDB == null)
                    //{
                    if (!ValorizzaAnagraficaToDB(datiDomanda, out datiAnagrafici, out errori))
                        return false;
                    codiceFiscale = datiAnagrafici.CodiceFiscale;
                    //se conigue presente imposto stato civile pari a coniugato
                    if (isConiugePresente && (!datiAnagrafici.CodiceStatoCivile.HasValue || datiAnagrafici.CodiceStatoCivile.Value != '2'))
                        datiAnagrafici.CodiceStatoCivile = '2';
                    //se unito civile presente imposto stato civile pari a unito civilmente
                    else if (isUnitoCivilePresente && (!datiAnagrafici.CodiceStatoCivile.HasValue || datiAnagrafici.CodiceStatoCivile.Value != '7'))
                        datiAnagrafici.CodiceStatoCivile = '7';
                    if (tipoAppartenenza == Utility.TipoAppartenenza.AGO && prelievo != null)
                    {
                        ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = prelievo as ServiceReferences.LiquidazioneAgo.AreaPrelievo;
                        if (prelievoAgo != null && prelievoAgo.Risposta != null)
                            datiAnagrafici.Cittadinanza = prelievoAgo.Risposta.Cittadinanza;
                    }

                    if (tipoAppartenenza == Utility.TipoAppartenenza.CI && prelievo != null)
                    {
                        ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoCi = prelievo as ServiceReferences.LiquidazioneCi.AreaPrelievo;
                        if (prelievoCi != null && prelievoCi.Risposta != null)
                            datiAnagrafici.Cittadinanza = prelievoCi.Risposta.Cittadinanza;
                    }
                    //}

                    //#region Domanda LIPE

                    //if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO)
                    //    if (IsDomandaLIPE(datiPensione, isDiretta, out errori))
                    //        return true;

                    //#endregion Domanda LIPE

                    #region GestioneAttivitaWebDom
                    bool IsGestioneAttivita = true;
                    if (ConfigurationManager.AppSettings["BypassAttivitaWebDom"] != null &&
                            ConfigurationManager.AppSettings["BypassAttivitaWebDom"] == "SI")
                    {
                        IsGestioneAttivita = false;
                    }
                    #endregion GestioneAttivitaWebDom

                    #region ControlloAttivitaWebDom
                    bool isControlloAttivitaWebDomAttivo = false;
                    controlloDinamico = null;
                    nomeControlloDinamico = "ControlloAttivitaWebDom";
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo(nomeControlloDinamico, out controlloDinamico);
                    if (controlloDinamico != null && controlloDinamico.ValoreControllo == "SI")
                        isControlloAttivitaWebDomAttivo = true;
                    #endregion ControlloAttivitaWebDom
                    if (IsGestioneAttivita)
                    {
                        if (isControlloAttivitaWebDomAttivo)
                        {
                            if (!GestioneWebDom.ControlloAttivitaWebDom(datiDomanda, datiPensione, matricolaOperatore, sedeOperatore, out errori))
                                return true;
                        }
                    }

                    if (Utility.IsDomandaBancari(datiPensione.SiglaCategoria) && datiPensione != null && datiPensione.SiglaCategoria != null && datiPensione.DecorrenzaOriginaria.HasValue)
                    {
                        bool isRipristino = (bool)Utility.IsDomandaRipristino(datiPensione);
                        if ((ConfigurationManager.AppSettings["BypassDecorrenzaRipristinoBanc"] == null || ConfigurationManager.AppSettings["BypassDecorrenzaRipristinoBanc"] != "SI") &&
                            isRipristino && (Utility.IsDomandaVOBANC(datiPensione.SiglaCategoria) || Utility.IsDomandaIOBANC(datiPensione.SiglaCategoria)) && Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2010, 12, 31)))
                        {
                            errori = "La pensione deve essere riliquidata nell'assicurazione generale obbligatoria";
                            return true;
                        }
                    }
                    if (Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) && Utility.IsResidenteEstero(datiAnagrafici.CodiceComuneResidenza))
                    {
                        errori = "La domanda non è acquisibile in quanto il titolare è residente all'estero.";
                        return true;
                    }

                    if ((Utility.IsDomandaAUT(datiPensione) || Utility.IsDomandaAGOTipoContributivoFiltroERI(datiPensione)) && !Utility.IsResidenteEstero(datiAnagrafici.CodiceComuneResidenza) && datiPensione.GetFiltro() == "ERI")
                    {
                        errori = "Il titolare è residente in Italia, la domanda non è liquidabile.";
                        return true;
                    }

                    bool isDomandaConNuovaGestioneDatiFondoFSPT = false;
                    controlloDinamico = null;
                    nomeControlloDinamico = "NuovaGestioneDatiFondoFSPT";
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo(nomeControlloDinamico, out controlloDinamico);
                    if (controlloDinamico != null && controlloDinamico.ValoreControllo == "SI")
                    {
                        if (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT)
                            isDomandaConNuovaGestioneDatiFondoFSPT = true;
                    }

                    List<GestioneDecodifica.DecPersonaleViaggiante> elencoDecPersonaleViaggiante = null;
                    if (tipoFondo == Utility.TipoFondo.ET)
                        GestioneDecodifica.GetDecPersonaleViaggiante(out elencoDecPersonaleViaggiante);

                    if (!(new List<string> { "INDCOM", "APE", "VOCRED", "CRED27", "VOCOOP", "COOP28", "VOESO", "VESO33", "VESO92", "INVCIV", "AS" }.Contains(datiPensione.SiglaCategoria.Trim())) &&
                        Utility.IsDomandaAPEPrecoci(datiPensione) && tipoAppartenenza != Utility.TipoAppartenenza.FS &&
                        datiDomanda.Dati.ModalitaPagamento != null && datiDomanda.Dati.ModalitaPagamento.Count > 0 &&
                            datiDomanda.Dati.ModalitaPagamento[0].Abi == "01000" && datiDomanda.Dati.ModalitaPagamento[0].Cab == "03203")
                    {
                        short codiceSede = Utility.GetCodiceSedeLavorazione(datiPensione, isRiapertura);
                        byte? centroOperativo = Utility.GetCentroOperativoLavorazione(datiPensione, isRiapertura);


                        if (codiceSede != 7000 || centroOperativo != 0)
                        {
                            errori = "Le domande con metodo di pagamento Banca d'Italia devono essere lavorate su sede 700000 - ROMA.";
                            return true;
                        }
                    }

                    controlloDinamico = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneServizioVerificaTitolarita", out controlloDinamico);
                    if (controlloDinamico != null && controlloDinamico.ValoreControllo == "SI" && datiPagamento != null && (datiPagamento.TipoPagamento == 'B' || datiPagamento.TipoPagamento == 'P') &&
                        (datiPagamento.ModalitaPagamento == 'C' || datiPagamento.ModalitaPagamento == 'K' || datiPagamento.ModalitaPagamento == 'L') && !string.IsNullOrEmpty(datiPagamento.IBAN) && datiAnagrafici.DataMorte == null)
                    {
                        GestioneVerTitolIBAN.AreaTitolarita areaTitolarita = new GestioneVerTitolIBAN.AreaTitolarita();
                        areaTitolarita.CodiceIban = datiPagamento.IBAN;
                        areaTitolarita.CodiceFiscale = datiAnagrafici.CodiceFiscale;
                        areaTitolarita.NumDomanda = datiPensione.NDomus.ToString();
                        if (!GestioneVerTitolIBAN.GetStatoTitolarita(ref areaTitolarita, matricolaOperatore, sedeOperatore.ToString().PadLeft(4, '0'), out errori))
                            return false;
                        if (areaTitolarita.Status == "2" || areaTitolarita.Status == "5" || areaTitolarita.Status == "51" || areaTitolarita.Status == "54")
                        {
                            errori = "L'iban indicato sulla domanda non è associato al titolare, non è possibile proseguire con la liquidazione. Modificare le modalità di pagamento su Webdom prima di liquidare la prestazione.";
                            return true;
                        }
                        if (areaTitolarita.Status == "3")
                        {
                            errori = "Attendere l'esito della verifica di titolarità dell'Iban.";
                            return true;
                        }
                    }

                    //codUnitaProcesso va salvato in NuoveLiquidate
                    string codUnitaProcesso = datiDomanda.Dati.Domanda[0].CodUnitaProcesso;

                    string codUnitaProcessoDestinazione = null;
                    bool isPolarizzazionePerGestioneENPALSAttiva = Utility.IsPolarizzazionePerGestioneENPALSAttiva(datiPensione);

                    if (Utility.IsDomandaENPALS(datiPensione.Gestione) && !Utility.IsPoloPALS(datiPensione))
                    {
                        if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                        {
                            if (!isPolarizzazionePerGestioneENPALSAttiva || (!Utility.IsDomandaReversibilita(datiPensione) &&
                                (!Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsRicostituzione_MotiviContributivi(datiPensione) || Utility.IsRicostituzione_Supplemento(datiPensione))))
                            {
                                errori = "Non è possibile acquisire la domanda su una sede diversa dal polo PALS.";
                                return true;
                            }
                        }
                        else
                        {
                            if (!isPolarizzazionePerGestioneENPALSAttiva || (!Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsRicostituzione_MotiviContributivi(datiPensione) || Utility.IsRicostituzione_Supplemento(datiPensione)))
                            {
                                errori = "Non è possibile acquisire la domanda su una sede diversa dal polo PALS.";
                                return true;
                            }
                        }
                    }

                    string sedeDestinazione = string.Empty;
                    if ((Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) || Utility.IsDomandaAPEPrecoci(datiPensione) || Utility.IsGestioneENPALSConSedeDestinazione(datiPensione)) &&
                        !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) && tipoAppartenenza != Utility.TipoAppartenenza.FS)
                    {
                        if (!(!(new List<string> { "INDCOM", "APE", "VOCRED", "CRED27", "VOCOOP", "COOP28", "VOESO", "VESO33", "VESO92", "INVCIV", "AS" }.Contains(datiPensione.SiglaCategoria.Trim())) &&
                            Utility.IsDomandaAPEPrecoci(datiPensione) && datiDomanda.Dati.ModalitaPagamento != null && datiDomanda.Dati.ModalitaPagamento.Count > 0 &&
                            datiDomanda.Dati.ModalitaPagamento[0].Abi == "01000" && datiDomanda.Dati.ModalitaPagamento[0].Cab == "03203"))
                        {
                            if (datiAnagrafici.CodiceComuneResidenza == "H501" && new List<string> { "00135", "00155", "00166" }.Contains(datiAnagrafici.CAP))
                            {
                                switch (datiAnagrafici.CAP)
                                {
                                    case "00135":
                                        sedeDestinazione = "701400";
                                        break;
                                    case "00155":
                                        sedeDestinazione = "700900";
                                        break;
                                    case "00166":
                                        sedeDestinazione = "701200";
                                        break;
                                }
                            }
                            else if (Utility.IsDomandaENPALS(datiPensione.Gestione) && isPolarizzazionePerGestioneENPALSAttiva && Utility.IsResidenteEstero(datiAnagrafici.CodiceComuneResidenza))
                            {
                                GestioneControlliDinamici.ControlloDinamico ctrl = null;
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("SedePoloENPALS", out ctrl);

                                sedeDestinazione = (ctrl != null && !String.IsNullOrEmpty(ctrl.ValoreControllo)) ? ctrl.ValoreControllo.PadRight(6, '0') : string.Empty;
                                codUnitaProcessoDestinazione = "026";
                            }
                            else
                                GestioneWebDom.GetSedeDestinazione(datiPensione.NDomus, datiAnagrafici.CodiceComuneResidenza, datiAnagrafici.CAP, out sedeDestinazione, out errori);

                            if (!string.IsNullOrEmpty(sedeDestinazione) && sedeDestinazione.Length == 6)
                            {
                                short codiceSedeDestinazione = 0;
                                byte centroOperativoDestinazione = 0;
                                short.TryParse(sedeDestinazione.Substring(0, 4), out codiceSedeDestinazione);
                                byte.TryParse(sedeDestinazione.Substring(4, 2), out centroOperativoDestinazione);

                                if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) && Utility.IsDomandaENPALS(datiPensione.Gestione))
                                {
                                    List<GestioneCtrlSedePolarizzata_ENPALS.SedePolarizzata_ENPALS> listaSediDaPolarizzare = null;
                                    GestioneCtrlSedePolarizzata_ENPALS.GetCtrlSedePolarizzata_ENPALS(out listaSediDaPolarizzare);
                                    if (listaSediDaPolarizzare.Exists(x => x.CodiceSede == codiceSedeDestinazione && (x.CentroOperativo == null || x.CentroOperativo == centroOperativoDestinazione)))
                                    {
                                        datiPensione.CodiceSedeDestinazione = codiceSedeDestinazione;
                                        datiPensione.CentroOperativoDestinazione = centroOperativoDestinazione;
                                    }
                                }
                                else
                                {
                                    datiPensione.CodiceSedeDestinazione = codiceSedeDestinazione;
                                    datiPensione.CentroOperativoDestinazione = centroOperativoDestinazione;
                                }
                            }
                        }
                        else
                        {
                            if (Utility.IsDomandaENPALS(datiPensione.Gestione) && isPolarizzazionePerGestioneENPALSAttiva && Utility.IsResidenteEstero(datiAnagrafici.CodiceComuneResidenza))
                                codUnitaProcessoDestinazione = "026";
                            datiPensione.CodiceSedeDestinazione = datiPensione.CodiceSede;
                            datiPensione.CentroOperativoDestinazione = datiPensione.CentroOperativo;
                        }
                    }
                    //Gestione valida solo per PL (gruppi 0001, 0002, 0003)
                    if (Utility.IsDomandaINPDAP(datiPensione.Gestione) && datiPensione.CodiceSedeDestinazione.GetValueOrDefault() == 0 &&
                        !(tipoDomanda == Utility.TipoDomanda.Ricostituzione || tipoDomanda == Utility.TipoDomanda.Ripristino || tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti || isRiapertura))
                    {
                        if (Utility.IsRegimeSediINPDAP())
                        {
                            GestioneWebDom.GetSedeDestinazione(datiPensione.NDomus, datiAnagrafici.CodiceComuneResidenza, datiAnagrafici.CAP, out sedeDestinazione, out errori);
                            if (!string.IsNullOrEmpty(sedeDestinazione) && sedeDestinazione.Length == 6)
                            {
                                short tmpSede = 0;
                                short.TryParse(sedeDestinazione.Substring(0, 4), out tmpSede);
                                datiPensione.CodiceSedeDestinazione = tmpSede;
                            }
                        }
                        else if (Utility.IsSperimentazioneSediINPDAP())
                            datiPensione.CodiceSedeDestinazione = datiPensione.CodiceSede;
                    }


                    //memo 187
                    if (Utility.IsDomandaINPDAP(datiPensione.Gestione) && prelievo != null)
                    {
                        ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFs = (ServiceReferences.LiquidazioneFs.AreaPrelievo)prelievo;

                        if (Utility.isDomandaReverisibilitaMemo187(datiPensione, prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiPensione != null ? prelievoFs.Risposta.DatiPensione.GP1AV91B : "",
                            prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiPensioneFondoDatiGenerici != null ? prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.CodiceSpecificoGP : ""))
                        {
                            errori = "Domanda momentaneamente non lavorabile";
                            return true;
                        }
                    }
                    if (tipoAppartenenza == Utility.TipoAppartenenza.FS)
                    {
                        ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFs = (ServiceReferences.LiquidazioneFs.AreaPrelievo)prelievo;

                        if (Utility.IsRicPerMotiviContributiviDaIndiretteFsPt(datiPensione.SiglaCategoria, datiPensione.Gruppo, datiPensione.Prodotto, datiPensione.Tipo, prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiPensioneFondoDatiGenerici != null ? prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.CodiceSpecifico : null))
                        {
                            if (!GestioneCtrlSediRicMotContribFsPtIndirette.IsDomandaLavorabileRicMotContribFsPtIndirette(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.CodiceSede, datiPensione.SiglaCategoria))
                            {
                                errori = "Trattasi di ricostituzione per motivi contributivi da pensione indiretta non liquidabile su tale sede.";
                                return true;
                            }
                        }
                    }

                    if ((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0171") &&
                        !((Utility.IsDomandaVO(datiPensione.SiglaCategoria) || Utility.IsDomandaVDAI(datiPensione.SiglaCategoria)) && (Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Not)))
                    {
                        errori = string.Format("Tipologia di domanda 'Pensione Anticipata Prepensionamento Editoria art.1 comma 154 legge 205/2017' incongruente con la categoria {0}", datiPensione.SiglaCategoria);
                        return true;
                    }

                    //Rotabili
                    List<string> categorieAmmesse = new List<string> { "VO", "VDAI", "VOCOM", "VR", "VOART", "VOS", "VRS", "VOARTS", "VOCOMS" };
                    if ((Utility.IsDomandaAnzianitaMaggiorazioneAmiantoLegge208_2015(datiPensione) || Utility.IsDomandaVecchiaiaMaggiorazioneAmiantoLegge208_2015(datiPensione)) &&
                        !categorieAmmesse.Contains(datiPensione.SiglaCategoria.Trim()))
                    {
                        errori = string.Format("Tipologia di domanda 'Pensione con Maggiorazione Amianto legge 208/2015' incongruente con la categoria {0}", datiPensione.SiglaCategoria.Trim());
                        return true;
                    }

                    if (Utility.IsDomandaAnzianitaMaggiorazioneAmiantoLegge208_2015(datiPensione) || Utility.IsDomandaVecchiaiaMaggiorazioneAmiantoLegge208_2015(datiPensione))
                    {
                        if (datiPensione.Tipo == "0170" && Utility.DataStrettamenteSuccessivaA(datiPensione.DataPresentazioneDomanda, new DateTime(2021, 11, 30)))
                        {
                            errori = "Non è possibile acquisire la domanda con tipo 0170 se la data presentazione è successiva al 30/11/2021";
                            return true;
                        }
                        else if (datiPensione.Tipo == "0161" && !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPresentazioneDomanda, new DateTime(2021, 11, 30)))
                        {
                            errori = "Non è possibile acquisire la domanda con tipo 0161 se la data presentazione è minore o uguale al 30/11/2021";
                            return true;
                        }
                    }

                    if (Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true)
                        || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true))
                    {
                        if (datiAnagrafici != null && datiAnagrafici.Sesso != 'F')
                        {
                            errori = "Non è possibile acquisire la domanda di tipo Opzione Donna se il sesso del titolare è 'M'";
                            return true;
                        }
                    }

                    bool isTabRedditiOpzionale = false;
                    if (tipoAppartenenza == Utility.TipoAppartenenza.FS && Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) &&
                        (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT))
                        isTabRedditiOpzionale = true;
                    else if (Utility.IsDomandaQuota100(datiPensione))//(datiPensione.Gruppo == "0001")
                    {
                        isTabRedditiOpzionale = !GestioneRedditi.VerificaPresenzaRedditi(datiPensione, out errori);
                        errori = string.Empty;
                    }

                    List<GestioneDatiContributiviCi.PensioniCiPrestazioniEE> listaPrestazioniEE = null;
                    using (TransactionScope transactionScope = TransactionScopeFactory.Create(TransactionScopeOption.Required,
                        new TransactionOptions { IsolationLevel = System.Transactions.IsolationLevel.ReadCommitted }))
                    {
                        if (isDomandaCalcolataProvvisoria && isRiapertura)
                            BLCommon.GestionePensione.UpdateProgStorico(datiPensione.NDomus);

                        //Se il gruppo è diverso da 0031 (ricostituzioni) inserisco nei dati pensione il numero certificato calcolato incrementando la tabella NumCertificato
                        if (tipoDomanda != Utility.TipoDomanda.Ricostituzione && !isRiapertura && !Utility.IsDomandaPSO(datiPensione.SiglaCategoria.Trim()) && !Utility.IsDomandaPMO(datiPensione.SiglaCategoria.Trim()))
                        {
                            if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO && !Utility.IsDomandaENPALS(datiPensione.Gestione) && !Utility.IsDomandaINPDAP(datiPensione.Gestione)
                                && !Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) && !Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiapertura) && !Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiapertura)
                                && !Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiapertura) && !Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiapertura))
                            {
                                bool doGetCertificato = false;
                                GestioneControlliDinamici.ControlloDinamico ctrl = null;
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitaGeneraCertificato" + tipoAppartenenza.GetValueOrDefault().ToString(), out ctrl);
                                if (ctrl != null && ctrl.ValoreControllo == "SI")
                                {
                                    ServiceReferences.GeneraCertificati.CertificatoInput rich = new ServiceReferences.GeneraCertificati.CertificatoInput();
                                    rich.SiglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();
                                    if (datiPensione.CodiceSedeDestinazione.HasValue)
                                        rich.CodiceSede = datiPensione.CodiceSedeDestinazione.Value.ToString().PadLeft(4, '0');
                                    else
                                        rich.CodiceSede = datiPensione.CodiceSede.ToString().PadLeft(4, '0');

                                    ServiceReferences.GeneraCertificati.CertificatoOutput areaRisposta = null;
                                    if (!GestioneGeneraCertificati.GeneraCertificato(datiPensione.NDomus.ToString(), rich, out areaRisposta, out errori))
                                    {
                                        if (Utility.BetweenStrings(errori, ":", "-").Trim() == ((short)Utility.ErroreGeneraCertificato.CodiciSedeCategoriaNonValidi).ToString()
                                            || Utility.BetweenStrings(errori, ":", "-").Trim() == ((short)Utility.ErroreGeneraCertificato.IntervalloDateNonValido).ToString())
                                            doGetCertificato = true;
                                        else return false;

                                    }
                                    else
                                    {
                                        if (areaRisposta != null && !string.IsNullOrEmpty(areaRisposta.Certificato))
                                        {
                                            int res = 0;
                                            int.TryParse(areaRisposta.Certificato, out res);
                                            datiPensione.NCertificato = res;
                                        }
                                        else
                                        {
                                            errori = string.Format("Errore nell'assegnazione del certificato per la categoria {0} su sede {1}", rich.SiglaCategoria, rich.CodiceSede);
                                            return false;
                                        }
                                    }

                                }
                                if (ctrl == null || ctrl.ValoreControllo == "NO" || doGetCertificato)
                                {
                                    errori = string.Empty;
                                    GestioneAssegnazioneCertificato.RichiestaCertificato richiesta = new GestioneAssegnazioneCertificato.RichiestaCertificato();
                                    if (datiPensione.CodiceSedeDestinazione.HasValue)
                                        richiesta.CodiceSede = datiPensione.CodiceSedeDestinazione.Value;
                                    else
                                        richiesta.CodiceSede = datiPensione.CodiceSede;
                                    richiesta.SiglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();
                                    int certificato = 0;

                                    if (!GestioneAssegnazioneCertificato.GetCertificato(datiPensione.NDomus, richiesta, out certificato, out errori))
                                        return false;
                                    datiPensione.NCertificato = certificato;
                                }
                            }
                            else if (Utility.IsDomandaENPALS(datiPensione.Gestione) || Utility.IsDomandaINPDAP(datiPensione.Gestione) ||
                                    (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.CI)
                                    || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) || Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiapertura)
                                || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiapertura)) //ENG - Spacchettate SOPGI
                            {
                                ServiceReferences.GeneraCertificati.CertificatoInput rich = new ServiceReferences.GeneraCertificati.CertificatoInput();
                                rich.SiglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();
                                if (datiPensione.CodiceSedeDestinazione.HasValue && !(tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.CI && Utility.IsDomandaAPEPrecoci(datiPensione)))
                                    rich.CodiceSede = datiPensione.CodiceSedeDestinazione.Value.ToString().PadLeft(4, '0');
                                else
                                    rich.CodiceSede = datiPensione.CodiceSede.ToString().PadLeft(4, '0');

                                ServiceReferences.GeneraCertificati.CertificatoOutput areaRisposta = null;
                                if (!GestioneGeneraCertificati.GeneraCertificato(datiPensione.NDomus.ToString(), rich, out areaRisposta, out errori))
                                    return false;
                                if (areaRisposta != null && !string.IsNullOrEmpty(areaRisposta.Certificato))
                                {
                                    int res = 0;
                                    int.TryParse(areaRisposta.Certificato, out res);
                                    datiPensione.NCertificato = res;
                                }
                                else
                                {
                                    errori = string.Format("Errore nell'assegnazione del certificato per la categoria {0} su sede {1}", rich.SiglaCategoria, rich.CodiceSede);
                                    return false;
                                }
                            }
                            else
                            {
                                string numCertificato = string.Empty;
                                GestioneCertificato.GetCertificato(datiPensione.CodiceSede.ToString().PadLeft(4, '0'), datiPensione.SiglaCategoria, datiPensione.Gestione, datiPensione.Gruppo, out numCertificato);
                                if (numCertificato != null)
                                    datiPensione.NCertificato = Utility.StringToNullableInt(numCertificato);
                            }
                        }
                        else if (tipoAppartenenza == Utility.TipoAppartenenza.AGO)
                        {
                            ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = prelievo as ServiceReferences.LiquidazioneAgo.AreaPrelievo;
                            if (prelievoAgo != null && prelievoAgo.Risposta != null)
                                datiPensione.NCertificato = prelievoAgo.Risposta.CertificatoPensione;
                        }
                        else
                        {
                            if (isRiapertura)
                                datiPensione.NCertificato = Utility.StringToNullableInt(datiDomanda.Dati.PensioneGenerata.FirstOrDefault(x => x.IndAnnullata == "0").NumCertificatoGenAttuale);
                            else
                                datiPensione.NCertificato = Utility.StringToNullableInt(datiDomanda.Dati.PensioneRiferimento[0].NumCertificatoRifAttuale);
                        }

                        datiPensione.MatricolaUtenteAcquisizione = matricolaOperatore;
                        //prevalorizzo FlagVerify a true
                        datiPensione.FlagVerify = true;

                        //Settiamo il primo codice natura a '5' per le supplementari AGO
                        if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO)
                        {
                            if ((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && (datiPensione.Tipo == "0009" || datiPensione.Tipo == "0192")) ||
                                (datiPensione.Gruppo == "0002" && datiPensione.Prodotto == "0013" && datiPensione.Tipo == "0009") ||
                                (datiPensione.Gruppo == "0003" && datiPensione.Prodotto == "0022" && datiPensione.Tipo == "0009"))
                            {
                                datiPensione.NaturaPensione = "5  ";
                            }
                        }

                        //Settiamo il prico codice natura a '5' per le supplementari CI
                        if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.CI)
                        {
                            if (datiPensione.Gruppo == "0003" && datiPensione.Prodotto == "0022" && datiPensione.Tipo == "0009")
                            {
                                datiPensione.NaturaPensione = "5  ";
                            }
                        }

                        //setto il terzo byte del codice natura a "V" per le pl inpdai con lavoro estero valorizzato
                        if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.FS && Utility.IsDomandaINPDAP(datiPensione.Gestione) &&
                            !(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) || Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione)) && !Utility.IsDomandaReversibilita(datiPensione)
                            && datiDomanda.Dati != null && datiDomanda.Dati.Istanza[0] != null && !string.IsNullOrEmpty(datiDomanda.Dati.Istanza[0].LavoroEstero) && datiDomanda.Dati.Istanza[0].LavoroEstero != "0")
                        {
                            datiPensione.NaturaPensione = "  V";
                        }

                        GestionePensione.DatiTitolare datiTitolare = new GestionePensione.DatiTitolare();

                        //salvo anagrafica solo se non ancora presente sul DB
                        //if (datiAnagraficiDB == null)
                        //{
                        //GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                        //if (!ValorizzaAnagraficaToDB(datiDomanda, out datiAnagrafici, out errori))
                        //    throw new INPS.DNA.DnaApplicationException(errori);
                        GestioneAnagrafica.SalvaAnagrafica(datiAnagrafici);

                        datiTitolare.IdAnagrafica = datiAnagrafici.Id;

                        if (Utility.IsResidenteEstero(datiAnagrafici.CodiceComuneResidenza))
                            isResidenteEstero = true;
                        else
                            isResidenteEstero = false;

                        //}
                        //else
                        //{
                        //    datiTitolare.IdAnagrafica = datiAnagraficiDB.Id;
                        //    isResidenteEstero = datiAnagraficiDB.ResidenzaEstero.HasValue ? datiAnagraficiDB.ResidenzaEstero.Value : false;
                        //}

                        //calcolo codice ricorso
                        // Per RIC/TRF viene recuperato il valore dal prelievo e quindi non va ricalcolato dalla fase
                        byte? codRicorso = !(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) && tipoAppartenenza == Utility.TipoAppartenenza.AGO) ?
                            GetRicorsoByFasi_New(datiDomanda.Dati.Fase, tipoAppartenenza) : null;

                        //salvataggio dati precedente pensione per Trasformazione da AOI
                        GestioneIstruttoria.DatiIstruttoria datiIstruttoria = null;
                        if ((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0002") ||
                            Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione) || Utility.IsDomandaPSO(datiPensione.SiglaCategoria))
                        {
                            if (datiDomanda != null && datiDomanda.Dati != null && datiDomanda.Dati.PensioneRiferimento != null &&
                                datiDomanda.Dati.PensioneRiferimento.Count > 0)
                            {
                                datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();
                                short resShort = 0;

                                if (datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav != null)
                                {
                                    if (Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione))
                                    {
                                        if (datiPensione.DecorrenzaOriginaria != null)
                                            datiIstruttoria.DecorrenzaOriginariaAltraPensione = datiPensione.DecorrenzaOriginaria;
                                        else
                                        {
                                            if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO)
                                            {
                                                ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = prelievo as ServiceReferences.LiquidazioneAgo.AreaPrelievo;
                                                if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiPensione != null)
                                                    datiIstruttoria.DecorrenzaOriginariaAltraPensione = prelievoAgo.Risposta.DatiPensione.DecorrenzaOriginaria;
                                            }
                                        }
                                        if (Utility.IsDomandaRiliquidazione(datiPensione).GetValueOrDefault() && tipoAppartenenza == Utility.TipoAppartenenza.AGO)
                                        {
                                            if (!(new List<string> { "VO", "IO", "SO", "VDAI", "IDAI", "SDAI", "VOBANC", "IOBANC", "SOBANC", "VOS", "IOS", "SOS", "VOP", "IOP", "SOP", "VOMIN", "SOMIN", "VR", "IR", "SR", "VOART", "IOART", "SOART", "VOCOM", "IOCOM", "SOCOM", "VRS", "IRS", "SRS", "VOARTS", "IOARTS", "SOARTS", "VOCOMS", "IOCOMS", "SOCOMS", "IOAUT", "VOAUT", "SOAUT" }.Contains(datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav.Trim())))
                                            {
                                                errori = string.Format("Le pensioni con categoria {0} non possono essere riliquidate", datiPensione.SiglaCategoria);
                                                return true;
                                            }
                                            if (!Utility.IsSameTipoPensione(datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav, datiPensione.SiglaCategoria.Trim()))
                                            {
                                                errori = string.Format("Le pensioni da riliquidare devono essere della stessa tipologia della pensione di provenienza");
                                                return true;
                                            }
                                        }
                                        if (Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault() && tipoAppartenenza == Utility.TipoAppartenenza.AGO)
                                        {
                                            if (datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav.Trim() != datiPensione.SiglaCategoria.Trim())
                                            {
                                                errori = string.Format("La categoria della pensione di riferimento {0} è incongruente con la categoria {1}", datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav, datiPensione.SiglaCategoria);
                                                return true;
                                            }
                                            if (!(new List<string> { "VO", "IO", "SO", "VDAI", "IDAI", "SDAI", "VOBANC", "IOBANC", "SOBANC", "VOP", "IOP", "SOP", "VOMIN", "SOMIN", "VR", "IR", "SR", "VOART", "IOART", "SOART", "VOCOM", "IOCOM", "SOCOM", "PMO", "IOAUT", "VOAUT", "SOAUT", "VOPGI", "IOPGI", "SOPGI" }.Contains(datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav.Trim())))
                                            {
                                                errori = string.Format("Le pensioni con categoria  {0} non possono essere ripristinate", datiPensione.SiglaCategoria);
                                                return true;
                                            }

                                        }
                                    }

                                }

                                if (!Utility.IsDomandaPSO(datiPensione.SiglaCategoria) || (Utility.IsDomandaPSO(datiPensione.SiglaCategoria) && (datiPensione.Gruppo == "0005" && datiPensione.Prodotto == "0043" && datiPensione.Tipo == "0014")))
                                {
                                    if (datiDomanda.Dati.PensioneRiferimento[0].CodCatPensioneRif != null)
                                    {
                                        short.TryParse(datiDomanda.Dati.PensioneRiferimento[0].CodCatPensioneRif, out resShort);
                                        datiIstruttoria.CodiceP18PrecedentePensione = resShort;
                                    }
                                    if (datiDomanda.Dati.PensioneRiferimento[0].CodProvinciaRif != null && datiDomanda.Dati.PensioneRiferimento[0].CodProvinciaRif.Length > 1 &&
                                        datiDomanda.Dati.PensioneRiferimento[0].CodZonaRif != null && datiDomanda.Dati.PensioneRiferimento[0].CodZonaRif.Length > 1)
                                    {
                                        short.TryParse(datiDomanda.Dati.PensioneRiferimento[0].CodProvinciaRif.Substring(1) +
                                            datiDomanda.Dati.PensioneRiferimento[0].CodZonaRif.Substring(1), out resShort);
                                        datiIstruttoria.SedePrecedentePensione = resShort;
                                    }
                                    int resInt = 0;
                                    if (datiDomanda.Dati.PensioneRiferimento[0].NumCertificatoRif != null)
                                    {
                                        int.TryParse(datiDomanda.Dati.PensioneRiferimento[0].NumCertificatoRif, out resInt);
                                        datiIstruttoria.CertificatoPrecedentePensione = resInt;
                                    }
                                }

                                if (Utility.IsDomandaAUT(datiPensione) || Utility.IsDomandaVecchiaiaTrasformazioneAOI(datiPensione).GetValueOrDefault())
                                {
                                    string gp1aj10 = string.Empty;
                                    string gp1af02 = string.Empty;
                                    string gp1af03 = string.Empty;
                                    string key = datiIstruttoria.CodiceP18PrecedentePensione.ToString().PadLeft(3, '0') +
                                        datiIstruttoria.SedePrecedentePensione.ToString().PadLeft(4, '0') +
                                        datiIstruttoria.CertificatoPrecedentePensione.ToString().PadLeft(8, '0');
                                    if (!GestioneDatiPensioni.GetDatiTGP1ByChiavePensione_AOI_AUT(datiPensione.NDomus, key, out gp1aj10, out gp1af02, out gp1af03, out errori))
                                        throw new Exception(errori);

                                    //In caso di TrasformazioneAOI il primo codice natura della pensione da trasformare in pensione di vecchiaia non può essere uguale a 3 o 4
                                    if (Utility.IsDomandaVecchiaiaTrasformazioneAOI(datiPensione).GetValueOrDefault())
                                    {
                                        if (!string.IsNullOrEmpty(gp1af02) && (gp1af02.StartsWith("3") || gp1af02.StartsWith("4")))
                                        {
                                            errori = string.Format("La pensione di inabilità non può essere trasformata in pensione di vecchiaia");
                                            return true;
                                        }


                                        //ENG - Memo 166 - Vecchiaia Trasformazione AOI e filtro blank
                                        if (String.IsNullOrEmpty(datiPensione.GetFiltro()))
                                        {
                                            if (!String.IsNullOrEmpty(gp1af03) && gp1af03.Trim() == "8" &&
                                                (String.IsNullOrEmpty(gp1aj10) || gp1aj10.Trim().ToUpperInvariant() != "F") &&
                                                (String.IsNullOrEmpty(gp1af02) || gp1af02.Substring(1, 1).Trim().ToUpperInvariant() != "J"))
                                            {
                                                errori = string.Format("L'AOI di provenienza ha tipo calcolo contributivo. Occorre procedere alla modifica della tipologia di domanda di trasformazione in Webdom.");
                                                return true;
                                            }
                                        }

                                        //ENG - Memo 166 - Trasformazione AOI Filtro ODM
                                        if (Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensione))
                                        {
                                            if (String.IsNullOrEmpty(gp1af03) || gp1af03.Trim() != "8") //gp1af03 diverso da 8
                                            {
                                                errori = string.Format("L'AOI di provenienza non ha tipo calcolo contributivo. Occorre procedere alla modifica della tipologia di domanda di trasformazione in Webdom.");
                                                return true;
                                            }

                                            if (!String.IsNullOrEmpty(gp1af03) && gp1af03.Trim() == "8" &&
                                                ((!String.IsNullOrEmpty(gp1aj10) && gp1aj10.Trim().ToUpperInvariant() == "F") || (!String.IsNullOrEmpty(gp1af02) && gp1af02.Substring(1, 1).Trim().ToUpperInvariant() == "J")))
                                            {
                                                errori = string.Format("Per procedere alla liquidazione occorre modificare la tipologia di domanda di trasformazione in Webdom, scegliendo 'Nessuna'.");
                                                return true;
                                            }
                                        }

                                    }

