                                    {
                                        datiIstruttoria.CodiceNaturaPrecedentePensione = gp1af02;
                                        char cRes;
                                        char.TryParse(gp1aj10, out cRes);
                                        datiIstruttoria.FacoltaComputoPrecedentePensione = cRes == char.MinValue ? (char?)null : cRes;
                                        if (!string.IsNullOrEmpty(datiIstruttoria.CodiceNaturaPrecedentePensione) &&
                                            (datiIstruttoria.CodiceNaturaPrecedentePensione.StartsWith("3") ||
                                            datiIstruttoria.CodiceNaturaPrecedentePensione.StartsWith("4")) && !Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione))
