                        {
                            if (Utility.IsDomandaINPDAP(datiPensione.Gestione) && datiPensione.SiglaCategoria.Trim().EndsWith("CTPS") &&
                                !Utility.IsDomandaAutomatica(datiPensione) && Utility.IsRicostituzione_MotiviContributivi(datiPensione) && !Utility.isRicostituzioneOrReversibileINPDAP(datiPensione, danteCausa))
                            {
                                errori = "La tipologia di domanda selezionata non è abilitata alla liquidazione";
                                return true;
                            }
                        }

                        if (Utility.IsDomandaENPALS(datiPensione.Gestione))
                        {
                            if (datiDomanda != null && datiDomanda.Dati != null && datiDomanda.Dati.Istanza != null && datiDomanda.Dati.Istanza.Count > 0)
                            {
                                datiDomanda.Dati.Istanza[0].SiglaCatLav = datiPensione.SiglaCategoria;
                                datiDomanda.Dati.Istanza[0].CodFondo = datiPensione.Fondo;
                            }
                        }

                        datiTitolare.IdPensione = datiPensione.Id;
                        DateTime? dataMorteTitolare = null;
                        GetDataMorteTitolareFromWebdom(datiDomanda, out dataMorteTitolare);
                        if (dataMorteTitolare != null)
                            datiTitolare.DataMorte = dataMorteTitolare;
                        GestionePensione.SalvaTitolare(datiTitolare);

                        bool tabEliminazioneGialloAutomazione = false;
                        if (tipoAutomazione == Utility.TipoAutomazione.Vecchiaia && datiTitolare != null && datiTitolare.DataMorte.HasValue)
                        {
                            GestionePensione.DatiEliminazione datiEliminazione = new GestionePensione.DatiEliminazione();
                            datiEliminazione.DataEvento = datiTitolare.DataMorte;
                            datiEliminazione.DecorrenzaEliminazione = datiTitolare.DataMorte.Value.AddMonths(1);
                            datiEliminazione.CodiceMotivo = 1;
                            GestionePensione.SalvaEliminazione(datiPensione.Id, datiEliminazione);
                            tabEliminazioneGialloAutomazione = true;
                        }

                        if (Utility.IsDomandaINPDAP(datiPensione.Gestione))
                        {
                            GestioneControlliDinamici.ControlloDinamico ctrlAbilitazionePensioniGDPMigrate = null;
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitaPensioniGDPMigrate", out ctrlAbilitazionePensioniGDPMigrate);
                            if (ctrlAbilitazionePensioniGDPMigrate != null && ctrlAbilitazionePensioniGDPMigrate.ValoreControllo == "NO")
                            {
                                if (Utility.IsDomandaReversibilita(datiPensione))
                                {
                                    if (danteCausa != null && danteCausa.Certificato < 20000000)
                                    {
                                        errori = "La domanda deve essere acquisita dalla stessa procedura utilizzata per il calcolo della pensione originaria.";
                                        return true;
                                    }
                                }
                                else if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura))
                                {
                                    if (datiPensione.NCertificato < 20000000)
                                    {
                                        errori = "La domanda deve essere acquisita dalla stessa procedura utilizzata per il calcolo della pensione originaria.";
