                                datiAnagraficiDA.CodiceFiscale = datiAnagraficiDA.CodiceFiscale + datiPensione.Id;
                            GestioneAnagrafica.SalvaAnagrafica(datiAnagraficiDA);
                            danteCausa.IdAnagrafica = datiAnagraficiDA.Id;
                            danteCausa.IdPensione = datiPensione.Id;
                            if (!string.IsNullOrEmpty(datiAnagraficiDA.CodiceComuneResidenza) && datiAnagraficiDA.CodiceComuneResidenza.StartsWith("Z"))
                            {
                                danteCausa.StatoEEResidenza = anagraficaDA.CodiceComuneResidenza;
                                danteCausa.StatoEEResidenzaByArca = true;
