                            else
                                danteCausa.StatoEEResidenzaByArca = false;
                            if (!string.IsNullOrEmpty(datiAnagraficiDA.Cittadinanza) && !string.IsNullOrEmpty(datiAnagraficiDA.Cittadinanza.Trim()))
                                danteCausa.CittadinanzaByArca = true;
                            else
                                danteCausa.CittadinanzaByArca = false;

                            //ENG - Implementata la gestione mancante per le Reversibilità CI
                            if (tipoAppartenenza == Utility.TipoAppartenenza.CI)
                            {
                                ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoDatiCI = (ServiceReferences.LiquidazioneCi.AreaPrelievo)prelievo;
                                if (prelievoDatiCI != null && prelievoDatiCI.Risposta != null && prelievoDatiCI.Risposta.DatiDanteCausa != null && prelievoDatiCI.Risposta.DatiDanteCausa.NaturaPensione != null)
                                    danteCausa.NaturaPensione = prelievoDatiCI.Risposta.DatiDanteCausa.NaturaPensione;
                            }

                            bool IsDomandaRiliquidazioneIndiretta = datiPensione.Gruppo == "0051" && datiPensione.Prodotto == "0422" && datiPensione.Tipo == "0026";
                            if (IsDomandaRiliquidazioneIndiretta)
                            {
                                danteCausa.Sede = null;
                                danteCausa.SiglaCategoria = null;
                                danteCausa.Certificato = null;
                                danteCausa.DecorrenzaPensione = null;
                                danteCausa.CodiceBeneficiLegge = null;
                                danteCausa.Maggiorazione781Contributi = null;
                                danteCausa.ImportoPensione311284 = null;
                                danteCausa.ImportoPensione1185 = null;
                                danteCausa.ImportoPensione1190 = null;
                                danteCausa.NContributiDiretta = null;
                                danteCausa.ProvenienzaPensione = 0;
                                danteCausa.CodiceTipoPensione = null;

                            }


                            BLCommon.GestioneDanteCausa.SalvaDanteCausa(danteCausa);
                        }

                        string fase = string.Empty;
                        if (datiDomanda != null && datiDomanda.Dati != null && datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Count > 0)
                            fase = datiDomanda.Dati.Fase[datiDomanda.Dati.Fase.Count - 1].CodFase;

                        if (datiLavorazione == null)
                            datiLavorazione = new GestioneLavorazione.DatiLavorazione();

                        if (tipoAppartenenza == Utility.TipoAppartenenza.AGO)
                        {
                            char? tipo = null;
                            if (datiPensione != null && datiDomanda != null && datiDomanda.Dati != null &&
                                datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Count > 0)
                            {
                                string canale = datiDomanda.Dati.Fase[datiDomanda.Dati.Fase.Count - 1].CodCanale;
                                string fonte = datiDomanda.Dati.Fase[datiDomanda.Dati.Fase.Count - 1].CodFonte;
                                //string fase = datiDomanda.Dati.Fase[datiDomanda.Dati.Fase.Count - 1].CodFase;
                                GestioneDecodifica.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto, datiPensione.Tipo, datiPensione.Gestione,
                                    datiPensione.Fondo, datiPensione.Ente, datiPensione.IndConvInt, datiPensione.IndConvInt, canale, fonte, fase, out tipo);
