                            GestionePensione.SalvaPatronato(datiPensione.Id, datiPatronato);


                        //salvataggio StatiEsteri + CodiceConvenzione
                        if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.CI)
                        {
                            if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) && !Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault())
                            {
                                SalvaStatiEsteri(datiPensione, datiAnagrafici, istituzioniEsterePECO, matricolaOperatore, sedeOperatore, centroOperativoOperatore, prelievo, out listaPrestazioniEE, out errori);
                                if (!string.IsNullOrEmpty(errori))
                                    return true;
                            }
                            else
                            {
                                //ENG - RIC/TRF: aggiunta la gestione per il recupero degli stati(se presenti e diversi da quelli provenienti da prelievo) dal servizio Naci o AllegatiConvenzioni
                                SalvaStatiEsteriRicTrf(datiPensione, datiAnagrafici, istituzioniEsterePECO, matricolaOperatore, sedeOperatore, centroOperativoOperatore, prelievo, out listaPrestazioniEE, out errori);
                                if (!string.IsNullOrEmpty(errori))
                                    return true;
