                        //ENG - MEMO 74_2023
                        //ENG - Memo 116/2025
                        List<GestioneDatiEsteriCumulo.PensioneEsteraCumulo> listaPrestazioniEECumulo = null;
                        //salvataggio StatiEsteri 
                        //chiamata al servizio Naci, AllegatiConvenzioni e Cumulo
                        if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO)
                        {
                            if (ctrlMemo74_2023 != null && ctrlMemo74_2023.NomeControllo == "SI" && Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) &&
                                !string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "V")
                            {
