                                    {
                                        SalvaStatiEsteriCumulo(datiPensione, datiAnagrafici, matricolaOperatore, sedeOperatore, centroOperativoOperatore, prelievo, out listaPrestazioniEECumulo, out errori);
                                        if (!string.IsNullOrEmpty(errori))
                                            return true;
                                    }
                                }
                            }

                            if (Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione) || Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione) ||
                                Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione))
                            {
                                GestioneControlliDinamici.ControlloDinamico ctrlAbilitaChiamata_Naci_AllegatiConv_Memo116_2025 = null;
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitaChiamata_Naci_AllegatiConv_Memo116_2025", out ctrlAbilitaChiamata_Naci_AllegatiConv_Memo116_2025);

                                if (ctrlAbilitaChiamata_Naci_AllegatiConv_Memo116_2025 != null && ctrlAbilitaChiamata_Naci_AllegatiConv_Memo116_2025.ValoreControllo == "SI")
                                {
                                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura))
                                    {
                                        SalvaStatiEsteriCumulo(datiPensione, datiAnagrafici, matricolaOperatore, sedeOperatore, centroOperativoOperatore, prelievo, out listaPrestazioniEECumulo, out errori);
                                        if (!string.IsNullOrEmpty(errori))
