                            }
                        }

                        //Gestione per la visibilità della voce di menù MaggiorazioneBenefici e della tab Benefici.
                        bool? isTabBeneficiVisible = IsVisibleTabBenefici(tipoAppartenenza.Value, datiPensione, isRiapertura);
                        bool? isTabPrivilegiateVisible = null;
                        bool? isTabExCombattenteVisible = null;
                        bool? isTabMaggiorazioniVisible = null;
                        bool? isTabDl407Visibile = null;

                        bool? isTabPrepensinamentoVisible = null;

                        bool? isTabIstruttoriaRequired = null;
                        bool? isTabInailVisibleForAGO = null;
                        bool? isTabInailForAGORequired = null;
                        bool? isTabPrecedentePensioneAGO_FS = null;
                        bool isTabDatiPostDecOriginariaVisibleCI = false;

