                        bool isSpacchettamentoPerRicostituzione = false;

                        bool? isTabBititolaritaVisible = false;
                        bool? isTabSentenzeVisible = null;
                        bool? isDatiFondoOpzionale = null;
                        bool? isDecorrenzaMaggiorazioneFromPrelievo = null;
