                                Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) || Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione) || Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(datiPensione) ||
                                Utility.IsPrepensionamentoEditoriaArt1c500L160_2019(datiPensione) || Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) ||
