                                Utility.IsDomandaManualeInvaliditaOver80_L80(datiPensione) || (Utility.IsDomandaBancari(datiPensione.SiglaCategoria) && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura)))
