                                        || Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiapertura))
                                        isSpacchettamentoPerRicostituzione = true;

                                    if (prelievoAGO.Risposta.ListaDatiRedditiSentenza495_93 != null && prelievoAGO.Risposta.ListaDatiRedditiSentenza495_93.Count() > 0 && !Utility.IsDomandaBancRicAnte1991(datiPensione, danteCausa))
                                        isTabSentenza495_93AGORequired = true;

