                                        isSupplementiPerRic = true;

                                    if ((prelievoAGO.Risposta.ListaInail != null && prelievoAGO.Risposta.ListaInail.Count(x => !x.IsNull()) > 0) || (prelievoAGO.Risposta.DatiInabilita != null && !prelievoAGO.Risposta.DatiInabilita.IsNull()))
                                        isTabInailForAGORequired = true;

                                    // Caso di ricostituzione di domanda di prepensionamento editoria
                                    if (prelievoAGO.Risposta.DatiPensione != null && !string.IsNullOrEmpty(prelievoAGO.Risposta.DatiPensione.NaturaPensione) && prelievoAGO.Risposta.DatiPensione.NaturaPensione.Substring(2, 1) == "O")
                                    {
