                                    if (prelievoAGO.Risposta.ListaBititolarita != null && prelievoAGO.Risposta.ListaBititolarita.Count() > 0)
                                        isTabBititolaritaVisible = true;
                                    if ((prelievoAGO.Risposta.DatiPensioniDatiGenerici != null && prelievoAGO.Risposta.DatiPensioniDatiGenerici.CodRicalcoloSentenza.HasValue) ||
                                       (prelievoAGO.Risposta.ListaDatiSentenze != null && prelievoAGO.Risposta.ListaDatiSentenze.Count() > 0))
                                        isTabSentenzeVisible = true;
                                    if (prelievoAGO.Risposta.ListaQuotaFondoIntegrativo != null && prelievoAGO.Risposta.ListaQuotaFondoIntegrativo.Count() > 0)
                                        isQuotaFondoIntegrativoVisible = true;

                                    if (tipoDomanda == Utility.TipoDomanda.Ricostituzione && (Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) || Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione)) && (prelievoAGO.Risposta.ListaDatiOneri == null || prelievoAGO.Risposta.ListaDatiOneri.Count() == 0) &&
                                        prelievoAGO.Risposta.DatiPensione != null && !string.IsNullOrEmpty(prelievoAGO.Risposta.DatiPensione.NaturaPensione) && prelievoAGO.Risposta.DatiPensione.NaturaPensione.Substring(2, 1) == "O" &&
                                        datiPensione.DecorrenzaOriginaria.HasValue && !Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2017, 01, 01)))
                                        isOneriRicPrepensionamentoTipo0162NotVisible = true;

                                    //ENG - RIC REVERSIBILITA
                                    if (tipoDomanda == Utility.TipoDomanda.Ricostituzione && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, danteCausa)
                                        && !Utility.IsDomandaCumulo(datiPensione.SiglaCategoria))
                                    {
