                    //ENG - Implementata la gestione mancante per le Reversibilità CI

                    if (tipoAppartenenza == Utility.TipoAppartenenza.CI && (Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, danteCausa) || Utility.IsDomandaPensioneReversibilitaOrRicostituzione(datiPensione, danteCausa)))
                    {
                        BLCommon.GestioneDanteCausa.DatiDanteCausa datiDC = null;
                        BLCommon.GestioneDanteCausa.GetDanteCausabyIdPensione(datiPensione.Id, out datiDC);
                        ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoDatiCi = (ServiceReferences.LiquidazioneCi.AreaPrelievo)prelievo;

                        if (prelievoDatiCi.Risposta.DatiPensioniEstereDc != null)
                        {
                            // SALVATAGGIO DEL PRIMO RECORD CON: CODICE 10 E IMPORTO SE ARRIVA DAL PRELIEVO DAL CAMPO DEL TRACCIATO ICI2SUP
                            GestioneAreaPrelievo.ArchiviaDatiPensioniEstereDcImportoTotaleSupplementi(prelievoDatiCi.Risposta.ImportoTotaleSupplementi, datiDC.Id);
                            // SALVATAGGIO DEL SECONDO RECORD CON: CODICE 6 E IMPORTO SE ARRIVA DAL PRELIEVO DAL CAMPO DEL TRACCIATO IABMMEX6
                            GestioneAreaPrelievo.ArchiviaDatiPensioniEstereDcImportoArt6(prelievoDatiCi.Risposta.ImportoArt6, datiDC.Id);
                            // SALVATAGGIO DEL TERZO RECORD, SE PRESENTI I VALORI DAL PRELIEVO, CON: IL CODICE VALORIZZATO CON IL CAMPO DEL TRACCIATO IW1CM345 E IMPORTO VALORIZZATO CON IL CAMPO DEL TRACCIATO IABMM345
                            GestioneAreaPrelievo.ArchiviaDatiPensioniEstereDc(prelievoDatiCi.Risposta.DatiPensioniEstereDc, datiDC.Id);
                        }
                    }

                    // recupero Matricola Istituzione Estera da NACI/CIWEB 
                    try
                    {
                        if (tipoAppartenenza != null && tipoAppartenenza == Utility.TipoAppartenenza.CI)
                        {
                            ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoDatiCi = (ServiceReferences.LiquidazioneCi.AreaPrelievo)prelievo;

                            if (prelievoDatiCi != null && prelievoDatiCi.Risposta != null && prelievoDatiCi.Risposta.ListaStatiEsteri != null && listaPrestazioniEE != null && listaPrestazioniEE.Count() > 0)
                            {
                                foreach (GestioneDatiContributiviCi.PensioniCiPrestazioniEE statoEstero in listaPrestazioniEE)
                                {
                                    if (statoEstero != null)
                                    {
                                        var prestazioneCorrispondente = prelievoDatiCi.Risposta.ListaStatiEsteri.FirstOrDefault(x => x != null && x.PrestazioneEstera != null && x.PrestazioneEstera.CodiceStatoEE != null && x.PrestazioneEstera.CodiceStatoEE == statoEstero.CodiceStatoEE && x.PrestazioneEstera.CodiceIstituzione == statoEstero.CodiceIstituzione);

                                        if (prestazioneCorrispondente != null && prestazioneCorrispondente.PrestazioneEstera != null && statoEstero.MatricolaIstituzioneEE != null)
                                        {
                                            prestazioneCorrispondente.PrestazioneEstera.MatricolaIstituzioneEE = statoEstero.MatricolaIstituzioneEE;
                                            GestioneDatiContributiviCi.SalvaPrestazioneEstera(prestazioneCorrispondente.PrestazioneEstera);
                                        }
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception Ex)
                    {
                        string messaggioErrore = Utility.GetMessageFromException(Ex);
                        long numeroDomanda = 0;
                        if (datiDomanda != null && datiDomanda.Dati != null && datiDomanda.Dati.Domanda != null &&
                            datiDomanda.Dati.Domanda.Rows.Count > 0)
                            long.TryParse(datiDomanda.Dati.Domanda[0].NumDomanda, out numeroDomanda);
                        GestioneLogGenerico.SalvaLogGenerico(numeroDomanda, MethodBase.GetCurrentMethod().Name, Utility.TipoLogGenerico.ErroreApplicativo, messaggioErrore, null, Ex.StackTrace);
                    }
                }
            }
            catch (INPS.DNA.DnaValidationException Ex)
            {
                errori = Ex.Message;
                return true;
            }
            catch (Exception Ex)
            {
                errori = "Errore tecnico durante l'acquisizione della domanda";
                string messaggio = Utility.GetMessageFromException(Ex);
                long numeroDomanda = 0;
                if (datiDomanda != null && datiDomanda.Dati != null && datiDomanda.Dati.Domanda != null &&
                    datiDomanda.Dati.Domanda.Rows.Count > 0)
                    long.TryParse(datiDomanda.Dati.Domanda[0].NumDomanda, out numeroDomanda);
                GestioneLogGenerico.SalvaLogGenerico(numeroDomanda, MethodBase.GetCurrentMethod().Name, Utility.TipoLogGenerico.ErroreApplicativo, messaggio, null, Ex.StackTrace);
                Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        //ENG - Memo 06_2024_part_2
        private static bool ValorizzaLavorazioneManualeAutomatica(string gruppo, string prodotto, string tipo, long nDomus, out string errori)
        {
            errori = string.Empty;
            List<GestioneLavorazioneManualeAutomatiche.DatiLavorazioneManualeAutomatiche> lstDatiLavorazioneManualeAutomatiche = new List<GestioneLavorazioneManualeAutomatiche.DatiLavorazioneManualeAutomatiche>();
            try
            {
                GestioneAreaLavorazioneManualeAutomatiche.GetAllPensioniLavorazioneManualeAutomaticheByNDomus(gruppo, prodotto, tipo, nDomus, out lstDatiLavorazioneManualeAutomatiche);
                if (lstDatiLavorazioneManualeAutomatiche != null && lstDatiLavorazioneManualeAutomatiche.Count > 0)
                {
                    foreach (GestioneLavorazioneManualeAutomatiche.DatiLavorazioneManualeAutomatiche lst in lstDatiLavorazioneManualeAutomatiche)
                    {
                        if (lst.AutorizzazioneManuale == null)
                        {
                            errori = "Domanda in attesa di conferma lavorazione manuale";
                            return false;
                        }
                        else if (lst.AutorizzazioneManuale == false)
                        {
                            errori = "Lavorazione manuale negata";
                            return false;
                        }
                    }
                }
                else
                {
                    errori = "La domanda non risulta lavorata in Unicarpe, è necessario richiedere autorizzazione lavorazione manuale utilizzando il tasto “Richiesta Lavorazione Manuale”";
                    return false;
                }
            }
            catch (Exception Ex)
            {
                errori = "Errore tecnico durante l'acquisizione della domanda";
                string messaggio = Utility.GetMessageFromException(Ex);
                GestioneLogGenerico.SalvaLogGenerico(nDomus, MethodBase.GetCurrentMethod().Name, Utility.TipoLogGenerico.ErroreApplicativo, messaggio, null, Ex.StackTrace);
                Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        private static bool generaIndirizzoEmailPerSede(string sede, long nDomus, out string mailTo, out string errori)
        {
            mailTo = string.Empty;
            errori = string.Empty;
            try
            {
                List<GestioneDecodifica.DecSede> elencoDecSede = null;
                GestioneDecodifica.GetElencoDecSede(out elencoDecSede);
                foreach (GestioneDecodifica.DecSede lst in elencoDecSede)
                {
                    if (lst.CodiceSedeMeta == sede)
                    {
                        if (lst.CodTipoSede != "04")
                        {
                            mailTo = string.Concat("assicuratopensionatogestioneprivata.", lst.DescSede.Trim().Replace(" ", "").Replace("-", "").Replace("/", "").Replace("'", "").Replace(",", "").Replace("à", "a").Replace("è", "e").Replace("é", "e").Replace("ì", "i").Replace("ò", "o").Replace("ù", "u"), "@inps.it");
                        }
                        else
                        {
                            mailTo = string.Concat("agenzia.", lst.DescSede.Trim().Replace(" ", "").Replace("-", "").Replace("/", "").Replace("'", "").Replace(",", "").Replace("à", "a").Replace("è", "e").Replace("é", "e").Replace("ì", "i").Replace("ò", "o").Replace("ù", "u"), "@inps.it");
                        }
                        break;
                    }
                }
            }
            catch (Exception Ex)
            {
                errori = "Errore tecnico nella costruzione dell' indirizzo del destinatario";
                string messaggio = Utility.GetMessageFromException(Ex);
                GestioneLogGenerico.SalvaLogGenerico(nDomus, MethodBase.GetCurrentMethod().Name, Utility.TipoLogGenerico.ErroreApplicativo, messaggio, null, Ex.StackTrace);
                Logger.LogException(Ex);
                return false;
            }
            return true;
        }

