                                Utility.ValorizzaOggetti(prelievoFs.Risposta.DatiPensione, datiStoricoGP);
                                Utility.ValorizzaOggetti(prelievoFs.Risposta.DatiPensioneFondoDatiGenerici, datiStoricoGP);
