            //controlla se rientra nel perimetro delle automatizzabili senza tener conto della 168 aperta, condizione che viene valutata successivamente
            if (Utility.IsDomandaDaAutomatizzare(datiPensione, isTrasformazioneDaAutomatizzare, out tipoAutomazione, out scartoAutomazione) == false)
            {
