            //se è stato attribuito un tipoAutomazione ma la 168 è chiusa, si controlla se sulla stessa fase è stata in passato aperta una 168
            if (!isAttivita168Aperta && tipoAutomazione != null && tipoAutomazione != Utility.TipoAutomazione.Trasformazioni)
