                                (string.IsNullOrEmpty(datiPensione.NaturaPensione) || (datiPensione.NaturaPensione.Substring(0, 1) != "3" && datiPensione.NaturaPensione.Substring(0, 1) != "4" && (datiDanteCausa.SiglaCategoria == "IOSPORT" || datiPensione.NaturaPensione.Substring(1, 1) != "1"))))
                            {
                                errori = string.Format("Attenzione! La diretta del dante causa ha categoria {0}: è necessario verificare che il primo byte del codice natura sia 3 o 4 (inabilità) oppure che il secondo byte sia uguale a 1 (invalidità specifica)", datiDanteCausa.SiglaCategoria.Trim().ToUpperInvariant());
                                throw new INPS.DNA.DnaValidationException(errori);
                            }
                        }

                        if (!GestioneDatiPensioni.GetDatiTGP2ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, datiPensione, out datiCalcoloContributivoSOPGI, out datiCalcoloRetributivoSOPGI, out datiCalcoloContributivoQuotaFondoSOPGI, out datiCalcoloRetributivoQuotaFondoSOPGI, out datiSupplementiSOPGI, out coefficienteTrasformazione, out errori))
                            throw new DNA.DnaValidationException(errori);

                        if (!GestioneDatiPensioni.GetDatiTGP2ByChiavePensione(chiavePensione, ref datiPensione, out errori))
                            throw new DNA.DnaValidationException(errori);

                        if (!datiPensione.TipoCalcolo.HasValue)
                        {
                            if (!string.IsNullOrEmpty(gp1af03))
                            {
                                switch (gp1af03)
                                {
                                    case "8":
                                        datiPensione.TipoCalcolo = (byte)Utility.TipoCalcolo.Contributivo;
                                        break;
                                    case "2":
                                        datiPensione.TipoCalcolo = (byte)Utility.TipoCalcolo.Retributivo;
                                        break;
                                }
                            }
                        }

                        if (!datiPensione.TipoCalcolo.HasValue)
                        {
                            List<string> codiciGP1AF03Ammessi = new List<string> { "8", "2" };
                            if (!codiciGP1AF03Ammessi.Contains(gp1af03))
                            {
                                errori = "Attenzione tipo calcolo non determinabile (GP1AF03 = '" + (gp1af03 != null ? gp1af03 : string.Empty) + "')";
                                throw new INPS.DNA.DnaValidationException(errori);
                            }
                        }

                        if (datiStoricoGP == null)
                            datiStoricoGP = new GestioneDatiStoricoGP.DatiStoricoGP();
                        datiStoricoGP.InizioAssicurazione = datiPensione.InizioAssicurazione;
                        datiStoricoGP.FineAssicurazione = datiPensione.FineAssicurazione;
                        datiStoricoGP.TipoCalcolo = datiPensione.TipoCalcolo;

                    }

                    if (Utility.IsDomandaPensioneIndiretta(datiPensione) && !isRiapertura)
                    {
                        string gp1af03 = string.Empty;
                        if (!GestioneDatiPensioni.GetDatiTGP1ByChiavePensione(ref datiPensione, chiavePensione, ref datiENPALS, out gp1af03, out errori))
                            throw new DNA.DnaValidationException(errori);

                        if (!GestioneDatiPensioni.GetDatiTGP2ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, datiPensione, out datiCalcoloContributivoSOPGI, out datiCalcoloRetributivoSOPGI, out datiCalcoloContributivoQuotaFondoSOPGI, out datiCalcoloRetributivoQuotaFondoSOPGI, out datiSupplementiSOPGI, out coefficienteTrasformazione, out errori))
                            throw new DNA.DnaValidationException(errori);

                        if (!GestioneDatiPensioni.GetDatiTGP2ByChiavePensione(chiavePensione, ref datiPensione, out errori))
                            throw new DNA.DnaValidationException(errori);

                        if (!datiPensione.TipoCalcolo.HasValue)
                        {
                            if (!string.IsNullOrEmpty(gp1af03))
                            {
                                switch (gp1af03)
                                {
                                    case "8":
                                        datiPensione.TipoCalcolo = (byte)Utility.TipoCalcolo.Contributivo;
                                        break;
                                    case "2":
                                        datiPensione.TipoCalcolo = (byte)Utility.TipoCalcolo.Retributivo;
                                        break;
                                }
                            }
                        }

                        if (!datiPensione.TipoCalcolo.HasValue)
                        {
                            List<string> codiciGP1AF03Ammessi = new List<string> { "8", "2" };
                            if (!codiciGP1AF03Ammessi.Contains(gp1af03))
                            {
                                errori = "Attenzione tipo calcolo non determinabile (GP1AF03 = '" + (gp1af03 != null ? gp1af03 : string.Empty) + "')";
                                throw new INPS.DNA.DnaValidationException(errori);
                            }
                        }

                        datiStoricoGP = new GestioneDatiStoricoGP.DatiStoricoGP();
                        datiStoricoGP.InizioAssicurazione = datiPensione.InizioAssicurazione;
                        datiStoricoGP.FineAssicurazione = datiPensione.FineAssicurazione;
                        datiStoricoGP.TipoCalcolo = datiPensione.TipoCalcolo;

                    }

                    if (tipoDomanda == Utility.TipoDomanda.Ricostituzione && !Utility.IsRicostituzione_MotiviContributivi(datiPensione))
                    {
                        if (!GestioneDatiPensioni.GetDatiTGP2ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, datiPensione, out datiCalcoloContributivoSOPGI, out datiCalcoloRetributivoSOPGI, out datiCalcoloContributivoQuotaFondoSOPGI, out datiCalcoloRetributivoQuotaFondoSOPGI, out datiSupplementiSOPGI, out coefficienteTrasformazione, out errori))
                            throw new DNA.DnaValidationException(errori);
                    }

                    List<GestioneAnagrafica.DatiAnagrafici> listaAnagraficaAventiDiritto = null;
                    if (!GestioneDatiPensioni.GetDatiTGP4ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, anagraficaTitolare.CodiceFiscale, parametriArca, out listaAventiDirittoGP,
                        out listaAnagraficaAventiDiritto, out errori))
                        throw new DNA.DnaValidationException(errori);

                    if (listaAventiDirittoGP == null || listaAventiDirittoGP.Count == 0)
                        throw new DNA.DnaValidationException("Non sono stati trovati Aventi Diritto nel GP4");

                    if (!GestioneDatiPensioni.GetDatiTGP7ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, datiPensione, isRiapertura, out listaDatiRedditoSentenza495_93, out datiDanteCausaGP7, out errori))
                        throw new DNA.DnaValidationException(errori);

                    if (listaDatiRedditoSentenza495_93 != null && listaDatiRedditoSentenza495_93.Count > 0)
                    {
                        isTabSentenza495_93AGORequired = true;
                        ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAGO = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                        if (prelievo != null && prelievoAGO != null)
                            prelievoAGO.Risposta.ListaDatiRedditiSentenza495_93 = listaDatiRedditoSentenza495_93.ToArray();
                    }
                }
            }
            //ENG - SOPGI pensioni di reversibilità il campo GP1AV08 prelevato dalla GAIN deve essere visibile sul pannello dati assicurativi (campo “Numero Settimane”) non editabile
            if (Utility.IsDomandaSOPGI(datiPensione.SiglaCategoria) && Utility.IsDomandaReversibilita(datiPensione))
            {
                if (datiStoricoGP != null && datiStoricoGP.NSettimaneOBG.HasValue)
                {
                    if (datiIstruttoria == null)
                        datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                    datiIstruttoria.NSettimaneOBG = datiStoricoGP.NSettimaneOBG;
                }
            }
            #endregion SOPGI

            #region ENPALS
            if (Utility.IsDomandaENPALS(datiPensione.Gestione))
            {
                // Per le domande di reversibilità o le domande indirette con chiave fascicolo non generata non deve essere richiamato il SAI
                if (!Utility.IsDomandaReversibilita(datiPensione) && !(Utility.IsDomandaPensioneIndiretta(datiPensione) && !isRiapertura && !isChiaveFascicoloGenerata.GetValueOrDefault()) &&
                    !Utility.IsRicostituzioneContributivaPerEsecuzioneSentenza(datiPensione))
                {
                    Entity.SAI datiSAI = null;
                    Entity.SAI datiSAS = null;

                    TipoRichiesta.GET? tipoRicGET = TipoRichiesta.GET.GETSAI;
                    if (isRiapertura)
                        tipoRicGET = TipoRichiesta.GET.GETSAY;
                    else if (Utility.IsRicostituzione_Supplemento(datiPensione))
                        tipoRicGET = TipoRichiesta.GET.GETSAS;
                    else if (Utility.IsRicostituzione_MotiviContributivi(datiPensione))
                        tipoRicGET = TipoRichiesta.GET.GETSAR;

                    if (tipoRicGET.HasValue)
                    {
                        if (!GestioneSAI.GetDatiSAI(datiPensione.NDomus, codiceFiscale, tipoRicGET.Value, ref datiSAI, out errori))
                        {
                            // Caso di domanda di ricostituzione non proveniente dal SAI
                            if (!(Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione &&
                                    !Utility.IsRicostituzione_MotiviContributivi(datiPensione) && !Utility.IsRicostituzione_Supplemento(datiPensione)) &&
                                !Utility.IsRicostituzioneContributivaPerEsecuzioneSentenza(datiPensione) &&
                                !(tipoRicGET == TipoRichiesta.GET.GETSAI && GestioneControlliDinamici.IsEnpalsManualeAbilitata()))
                                throw new INPS.DNA.DnaValidationException(errori);
                            else if (!string.IsNullOrEmpty(errori) && errori.Equals("Domanda non trovata sul SAI.")) // Domanda non presente sul SAI
                                errori = string.Empty;
                        }

                        if (tipoRicGET == TipoRichiesta.GET.GETSAS && datiSAI != null)
                        {
                            datiSAS = new Entity.SAI();
                            Utility.ValorizzaOggetti(datiSAI, datiSAS);
                            if (datiSAI.GETSAI_CTB_RETRIB != null && datiSAI.GETSAI_CTB_RETRIB.Count > 0)
                            {
                                datiSAS.GETSAI_CTB_RETRIB = new List<Entity.SAI.DatiRetributiviSAI>();
                                foreach (Entity.SAI.DatiRetributiviSAI retr in datiSAI.GETSAI_CTB_RETRIB)
                                {
                                    Entity.SAI.DatiRetributiviSAI app = new Entity.SAI.DatiRetributiviSAI();
                                    Utility.ValorizzaOggetti(retr, app);
                                    datiSAS.GETSAI_CTB_RETRIB.Add(app);
                                }
                            }
                            if (datiSAI.GETSAI_CTB_CONTRIB != null && datiSAI.GETSAI_CTB_CONTRIB.Count > 0)
                            {
                                datiSAS.GETSAI_CTB_CONTRIB = new List<Entity.SAI.DatiContributiviSAI>();
                                foreach (Entity.SAI.DatiContributiviSAI contr in datiSAI.GETSAI_CTB_CONTRIB)
                                {
                                    Entity.SAI.DatiContributiviSAI app = new Entity.SAI.DatiContributiviSAI();
                                    Utility.ValorizzaOggetti(contr, app);
                                    datiSAS.GETSAI_CTB_CONTRIB.Add(app);
                                }
                            }
                            datiSAI = new Entity.SAI();
                        }

                        if (datiSAI == null)
                        {
                            datiPensione.IsDatiENPALSRecuperati = false;

                            if (!(Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione && !Utility.IsRicostituzione_MotiviContributivi(datiPensione) && !Utility.IsRicostituzione_Supplemento(datiPensione)) &&
                                !Utility.IsRicostituzioneContributivaPerEsecuzioneSentenza(datiPensione) && !(tipoRicGET == TipoRichiesta.GET.GETSAI && GestioneControlliDinamici.IsEnpalsManualeAbilitata()) &&
                                !(Utility.IsDomandaPensioneIndiretta(datiPensione) && isRiapertura))
                            {
                                errori = "Domanda non proveniente da SAI. Non è possibile lavorarla.";
                                return;
                            }
                        }
                        else
                        {
                            datiPensione.IsDatiENPALSRecuperati = true;

                            if (datiSAI.GETSAI_ESITO == '7')
                            {
                                if (!GestioneSAI.GetDatiSAI(datiPensione.NDomus, codiceFiscale, TipoRichiesta.GET.GETSAS, ref datiSAS, out errori))
                                    throw new INPS.DNA.DnaValidationException(errori);
                            }

                            datiENPALS = new GestioneEnpals.DatiEnpals();
                            if (datiIstruttoria == null)
                                datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();
                            listaDatiSupplementiENPALS = new List<BLCommon.Entity.DatiSupplementiENPALS>();
                            datiContribuzioneENPALSSupp = new BLCommon.Entity.DatiContribuzioneEnpals();
                            datiContribuzioneENPALSLiq = new BLCommon.Entity.DatiContribuzioneEnpals();

                            #region Pensione

                            if (!(tipoRicGET == TipoRichiesta.GET.GETSAR && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa)))
                            {
                                if (!String.IsNullOrEmpty(datiSAI.GETSAI_DT_DECORRENZA) && datiSAI.GETSAI_DT_DECORRENZA.Trim().Length == 8)
                                    datiPensione.DecorrenzaOriginaria = Utility.DataFromString(datiSAI.GETSAI_DT_DECORRENZA, Utility.FormatoData.AAAAmmGG);
                                else if (!String.IsNullOrEmpty(datiSAI.GETSAI_DT_DECORRENZA) && !String.IsNullOrEmpty(datiSAI.GETSAI_DT_DECORRENZA.Trim()))
                                    datiPensione.DecorrenzaOriginaria = Utility.DataFromInt(short.Parse(datiSAI.GETSAI_DT_DECORRENZA.Substring(0, 4)),
                                                                                     short.Parse(datiSAI.GETSAI_DT_DECORRENZA.Substring(4, 2)), 1);
                            }

                            if (!String.IsNullOrEmpty(datiSAI.GETSAI_DT_RAG_REQ) && datiSAI.GETSAI_DT_RAG_REQ.Trim().Length == 8)
                                datiPensione.DataPerfezionamentoRequisiti = Utility.DataFromString(datiSAI.GETSAI_DT_RAG_REQ, Utility.FormatoData.AAAAmmGG);
                            else if (!String.IsNullOrEmpty(datiSAI.GETSAI_DT_RAG_REQ) && !String.IsNullOrEmpty(datiSAI.GETSAI_DT_RAG_REQ.Trim()))
                                datiPensione.DataPerfezionamentoRequisiti = Utility.DataFromInt(short.Parse(datiSAI.GETSAI_DT_RAG_REQ.Substring(0, 4)),
                                                                                 short.Parse(datiSAI.GETSAI_DT_RAG_REQ.Substring(4, 2)), 1);

                            if (tipoRicGET == TipoRichiesta.GET.GETSAR && Utility.IsRicostituzione_MotiviContributivi(datiPensione) && datiSAI.GETSAI_IMP_PRT > 0M)
                            {
                                if (String.IsNullOrEmpty(datiPensione.NaturaPensione))
                                    datiPensione.NaturaPensione = "  V";
                                else if (datiPensione.NaturaPensione.Length == 3)
                                    datiPensione.NaturaPensione = datiPensione.NaturaPensione.Substring(0, 2) + "V";
                            }

                            #endregion Pensione

                            #region Dati Calcolo

                            datiCalcoloRetributivoENPALS = new GestioneCalcolo.DatiCalcoloRetributivoENPAL();
                            datiCalcoloContributivoENPALS = new GestioneCalcolo.DatiCalcoloContributivoENPAL();

                            if (datiSAI.GETSAI_IMP_CONTR != 0M)
                            {
                                datiCalcoloContributivoENPALS.ImportoContributivoTotale = datiSAI.GETSAI_IMP_CONTR;
                                if (datiSAI.GETSAI_COEFF_TRASF != 0M)
                                    datiCalcoloContributivoENPALS.CoefficienteTrasformazione = datiSAI.GETSAI_COEFF_TRASF;
                                if (datiSAI.GETSAI_MONT_CMP != 0M)
                                    datiCalcoloContributivoENPALS.Montante = datiSAI.GETSAI_MONT_CMP;
                                if (datiCalcoloContributivoENPALS.CoefficienteTrasformazione.HasValue || datiCalcoloContributivoENPALS.ImportoContributivoTotale.HasValue || datiCalcoloContributivoENPALS.Montante.HasValue)
                                {
                                    if (datiSAI.GETSAI_SISTEMA_CALCOLO == 'Z' || datiSAI.GETSAI_SISTEMA_CALCOLO == 'H' || datiSAI.GETSAI_SISTEMA_CALCOLO == 'K' || datiSAI.GETSAI_SISTEMA_CALCOLO == 'J')
                                        datiCalcoloContributivoENPALS.Quota = 'D';
                                    else
                                        datiCalcoloContributivoENPALS.Quota = 'C';
                                }

                                if (datiSAI.GETSAI_NUM_CTB_ENP_CONT != 0 || datiSAI.GETSAI_NUM_CTB_FIG_CONT != 0 || datiSAI.GETSAI_NUM_CTB_UFF_CONT != 0 || datiSAI.GETSAI_NUM_CTB_INPS_CONT != 0 ||
                                    datiSAI.GETSAI_NUM_CTB_VV_CONT != 0 || datiSAI.GETSAI_NUM_CTB_EST_CONT != 0)
                                {
                                    datiCalcoloContributivoENPALS.NumeroContributiTotale = datiSAI.GETSAI_NUM_CTB_ENP_CONT;
                                    datiCalcoloContributivoENPALS.NumeroContributiTotale += datiSAI.GETSAI_NUM_CTB_FIG_CONT;
                                    datiCalcoloContributivoENPALS.NumeroContributiTotale += datiSAI.GETSAI_NUM_CTB_UFF_CONT;
                                    datiCalcoloContributivoENPALS.NumeroContributiTotale += datiSAI.GETSAI_NUM_CTB_INPS_CONT;
                                    datiCalcoloContributivoENPALS.NumeroContributiTotale += datiSAI.GETSAI_NUM_CTB_VV_CONT;
                                    datiCalcoloContributivoENPALS.NumeroContributiTotale += datiSAI.GETSAI_NUM_CTB_EST_CONT;
                                }
                            }
                            else if (tipoRicGET == TipoRichiesta.GET.GETSAR || tipoRicGET == TipoRichiesta.GET.GETSAY)
                            {
                                datiCalcoloContributivoENPALS.ImportoContributivoTotale = null;
                                datiCalcoloContributivoENPALS.CoefficienteTrasformazione = null;
                                datiCalcoloContributivoENPALS.Montante = null;
                                datiCalcoloContributivoENPALS.Quota = null;
                            }

                            if (datiSAI.GETSAI_IMP_QUA != 0M && !Utility.IsDomandaSperimentaleDonna(datiPensione) && !Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione))
                            {
                                datiCalcoloRetributivoENPALS.ImportoQuotaA = datiSAI.GETSAI_IMP_QUA;
                                if (datiSAI.GETSAI_IMP_QUA_707 != 0M)
                                    datiCalcoloRetributivoENPALS.ImportoQuotaA707 = datiSAI.GETSAI_IMP_QUA_707;
                                if (datiSAI.GETSAI_NR_CTB_ANTE != 0)
                                {
                                    datiCalcoloRetributivoENPALS.PeriodiQuotaA = datiSAI.GETSAI_NR_CTB_ANTE;
                                    if (datiSAI.GETSAI_SISTEMA_CALCOLO == 'Z' || datiSAI.GETSAI_SISTEMA_CALCOLO == 'H' || datiSAI.GETSAI_SISTEMA_CALCOLO == 'K' || datiSAI.GETSAI_SISTEMA_CALCOLO == 'J')
                                        datiCalcoloRetributivoENPALS.GiorniQuotaA707 = datiSAI.GETSAI_NR_CTB_ANTE;
                                }
                                if (datiSAI.GETSAI_NR_CTB_QUOA != 0)
                                    datiCalcoloRetributivoENPALS.NTotaleContributiCalcoloQuotaA = datiSAI.GETSAI_NR_CTB_QUOA;
                                if (datiSAI.GETSAI_RTB_MED_540 != 0M)
                                    datiCalcoloRetributivoENPALS.RMQuotaA = datiSAI.GETSAI_RTB_MED_540;
                            }
                            else if (tipoRicGET == TipoRichiesta.GET.GETSAR || tipoRicGET == TipoRichiesta.GET.GETSAY)
                            {
                                datiCalcoloRetributivoENPALS.ImportoQuotaA = null;
                                datiCalcoloRetributivoENPALS.PeriodiQuotaA = null;
                                datiCalcoloRetributivoENPALS.NTotaleContributiCalcoloQuotaA = null;
                                datiCalcoloRetributivoENPALS.RMQuotaA = null;
                                datiCalcoloRetributivoENPALS.ImportoQuotaA707 = null;
                                datiCalcoloRetributivoENPALS.GiorniQuotaA707 = null;
                            }

                            if (datiSAI.GETSAI_IMP_QUB != 0M && !Utility.IsDomandaSperimentaleDonna(datiPensione) && !Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione))
                            {
                                datiCalcoloRetributivoENPALS.ImportoQuotaB = datiSAI.GETSAI_IMP_QUB;
                                if (datiSAI.GETSAI_IMP_QUB_707 != 0)
                                    datiCalcoloRetributivoENPALS.ImportoQuotaB707 = datiSAI.GETSAI_IMP_QUB_707;
                                if (datiSAI.GETSAI_NR_CTB_POST != 0)
                                    datiCalcoloRetributivoENPALS.PeriodiQuotaB = datiSAI.GETSAI_NR_CTB_POST;
                                if (datiSAI.GETSAI_NR_CTB_POST_707 != 0)
                                    datiCalcoloRetributivoENPALS.GiorniQuotaB707 = datiSAI.GETSAI_NR_CTB_POST_707;
                                if (datiSAI.GETSAI_NR_CTB_QUOB != 0)
                                    datiCalcoloRetributivoENPALS.NTotaleContributiCalcoloQuotaB = datiSAI.GETSAI_NR_CTB_QUOB;
                                if (datiSAI.GETSAI_RTB_MED_POST != 0M)
                                    datiCalcoloRetributivoENPALS.RMQuotaB = datiSAI.GETSAI_RTB_MED_POST;
                            }
                            else if (tipoRicGET == TipoRichiesta.GET.GETSAR || tipoRicGET == TipoRichiesta.GET.GETSAY)
                            {
                                datiCalcoloRetributivoENPALS.ImportoQuotaB = null;
                                datiCalcoloRetributivoENPALS.PeriodiQuotaB = null;
                                datiCalcoloRetributivoENPALS.NTotaleContributiCalcoloQuotaB = null;
                                datiCalcoloRetributivoENPALS.RMQuotaB = null;
                                datiCalcoloRetributivoENPALS.ImportoQuotaB707 = null;
                                datiCalcoloRetributivoENPALS.GiorniQuotaB707 = null;
                            }

                            if (datiSAI.GETSAI_IMP_PRT != 0M)
                                datiCalcoloRetributivoENPALS.ImportoProRataTemporis = datiSAI.GETSAI_IMP_PRT;

                            if (datiSAI.OBM_CM_IMP_RTV != 0M || tipoRicGET == TipoRichiesta.GET.GETSAR || tipoRicGET == TipoRichiesta.GET.GETSAY)
                                datiCalcoloRetributivoENPALS.ImportoQuotaRetributivaInMisto = datiSAI.OBM_CM_IMP_RTV;

                            if (datiSAI.GETSAI_IMP_PENS != 0M || tipoRicGET == TipoRichiesta.GET.GETSAR || tipoRicGET == TipoRichiesta.GET.GETSAY)
                                datiENPALS.ImportoPensione = datiSAI.GETSAI_IMP_PENS;

                            if (datiSAI.GETSAI_IMP_PENS_707 != 0M)
                                datiENPALS.ImportoPensione707 = datiSAI.GETSAI_IMP_PENS_707;

                            if (Utility.IsDomandaSperimentaleDonna(datiPensione) || Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione) ||
                                (!datiCalcoloContributivoENPALS.IsDatiCalcoloContributivoEnpalsNull() && datiCalcoloRetributivoENPALS.IsDatiCalcoloRetributivoEnpalsNull()))
                                datiPensione.TipoCalcolo = 1; // Tipo calcolo contributivo
                            else if (datiCalcoloContributivoENPALS.IsDatiCalcoloContributivoEnpalsNull() && !datiCalcoloRetributivoENPALS.IsDatiCalcoloRetributivoEnpalsNull())
                                datiPensione.TipoCalcolo = 2; // Tipo calcolo retributivo
                            else if (!datiCalcoloContributivoENPALS.IsDatiCalcoloContributivoEnpalsNull() && !datiCalcoloRetributivoENPALS.IsDatiCalcoloRetributivoEnpalsNull())
                            {
                                if (datiSAI.GETSAI_SISTEMA_CALCOLO == 'Z' || datiSAI.GETSAI_SISTEMA_CALCOLO == 'H')
