                            else
                                isContribuzioneENPALSPerLiq = true;

                            //Controlli in fase di prelievo della domanda dal SAI. Se mancano dati o ci sono errori, blocchiamo l'acquisizione della domanda
                            ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                            GestionePensione.DatiPensione datiPensioneDaPrelievo = null;
