                            {
                                datiENPALSDaPrelievo.ImportoIIS = null;
                                datiENPALSDaPrelievo.DecorrenzaImportoIIS = null;
                            }
                            if (Utility.IsRicostituzione_Supplemento(datiPensione))
                            {
                                GestionePensione.DatiPensione datiPensioneSAS = new GestionePensione.DatiPensione();
                                GestioneCalcolo.DatiCalcoloRetributivoENPAL datiCalcoloRetributivoSAS = new GestioneCalcolo.DatiCalcoloRetributivoENPAL();
                                GestioneCalcolo.DatiCalcoloContributivoENPAL datiCalcoloContributivoSAS = new GestioneCalcolo.DatiCalcoloContributivoENPAL();
                                GestioneEnpals.DatiEnpals datiENPALS_SAS = new GestioneEnpals.DatiEnpals();

                                #region Pensione

                                datiPensioneSAS.NDomus = datiPensione.NDomus;
