                                datiPensioneSAS.Gruppo = datiPensione.Gruppo;
                                datiPensioneSAS.Prodotto = datiPensione.Prodotto;
                                datiPensioneSAS.Tipo = datiPensione.Tipo;

                                if (!String.IsNullOrEmpty(datiSAS.GETSAI_DT_DECORRENZA) && datiSAS.GETSAI_DT_DECORRENZA.Trim().Length == 8)
                                    datiPensioneSAS.DecorrenzaOriginaria = Utility.DataFromString(datiSAS.GETSAI_DT_DECORRENZA, Utility.FormatoData.AAAAmmGG);
                                else if (!String.IsNullOrEmpty(datiSAS.GETSAI_DT_DECORRENZA) && !String.IsNullOrEmpty(datiSAS.GETSAI_DT_DECORRENZA.Trim()))
                                    datiPensioneSAS.DecorrenzaOriginaria = Utility.DataFromInt(short.Parse(datiSAS.GETSAI_DT_DECORRENZA.Substring(0, 4)),
                                                                                     short.Parse(datiSAS.GETSAI_DT_DECORRENZA.Substring(4, 2)), 1);

                                if (!String.IsNullOrEmpty(datiSAS.GETSAI_DT_PRI_CTB) && datiSAS.GETSAI_DT_PRI_CTB.Trim().Length == 8)
                                    datiPensioneSAS.InizioAssicurazione = Utility.DataFromString(datiSAS.GETSAI_DT_PRI_CTB, Utility.FormatoData.AAAAmmGG);
                                else if (!String.IsNullOrEmpty(datiSAS.GETSAI_DT_PRI_CTB) && !String.IsNullOrEmpty(datiSAS.GETSAI_DT_PRI_CTB.Trim()))
                                    datiPensioneSAS.InizioAssicurazione = Utility.DataFromInt(short.Parse(datiSAS.GETSAI_DT_PRI_CTB.Substring(0, 4)),
                                                                                     short.Parse(datiSAS.GETSAI_DT_PRI_CTB.Substring(4, 2)), 1);

                                if (!String.IsNullOrEmpty(datiSAS.GETSAI_DT_FIN_ASS) && datiSAS.GETSAI_DT_FIN_ASS.Trim().Length == 8)
                                    datiPensioneSAS.FineAssicurazione = Utility.DataFromString(datiSAS.GETSAI_DT_FIN_ASS, Utility.FormatoData.AAAAmmGG);
                                else if (!String.IsNullOrEmpty(datiSAS.GETSAI_DT_FIN_ASS) && !String.IsNullOrEmpty(datiSAS.GETSAI_DT_FIN_ASS.Trim()))
                                    datiPensioneSAS.FineAssicurazione = Utility.DataFromInt(short.Parse(datiSAS.GETSAI_DT_FIN_ASS.Substring(0, 4)),
                                                                                     short.Parse(datiSAS.GETSAI_DT_FIN_ASS.Substring(4, 2)), 1);

                                #endregion Pensione

                                #region Dati Calcolo

                                if (datiSAS.GETSAI_IMP_CONTR != 0M)
                                {
                                    datiCalcoloContributivoSAS.ImportoContributivoTotale = datiSAS.GETSAI_IMP_CONTR;
                                    if (datiSAS.GETSAI_COEFF_TRASF != 0M)
                                        datiCalcoloContributivoSAS.CoefficienteTrasformazione = datiSAS.GETSAI_COEFF_TRASF;
                                    if (datiSAS.GETSAI_MONT_CMP != 0M)
                                        datiCalcoloContributivoSAS.Montante = datiSAS.GETSAI_MONT_CMP;
                                    if (datiCalcoloContributivoSAS.CoefficienteTrasformazione.HasValue || datiCalcoloContributivoSAS.ImportoContributivoTotale.HasValue || datiCalcoloContributivoSAS.Montante.HasValue)
                                    {
                                        if (datiSAS.GETSAI_SISTEMA_CALCOLO == 'Z' || datiSAS.GETSAI_SISTEMA_CALCOLO == 'H' || datiSAS.GETSAI_SISTEMA_CALCOLO == 'K' || datiSAS.GETSAI_SISTEMA_CALCOLO == 'J')
