                                    if (datiSAS.GETSAI_IMP_QUA_707 != 0M)
                                        datiCalcoloRetributivoSAS.ImportoQuotaA707 = datiSAS.GETSAI_IMP_QUA_707;
                                    if (datiSAS.GETSAI_NR_CTB_ANTE != 0)
                                    {
                                        datiCalcoloRetributivoSAS.PeriodiQuotaA = datiSAS.GETSAI_NR_CTB_ANTE;
