                                {
                                    datiCalcoloRetributivoSAS.ImportoQuotaB = datiSAS.GETSAI_IMP_QUB;
                                    if (datiSAS.GETSAI_IMP_QUB_707 != 0)
                                        datiCalcoloRetributivoSAS.ImportoQuotaB707 = datiSAS.GETSAI_IMP_QUB_707;
                                    if (datiSAS.GETSAI_NR_CTB_POST != 0)
                                        datiCalcoloRetributivoSAS.PeriodiQuotaB = datiSAS.GETSAI_NR_CTB_POST;
                                    if (datiSAS.GETSAI_NR_CTB_POST_707 != 0)
                                        datiCalcoloRetributivoSAS.GiorniQuotaB707 = datiSAS.GETSAI_NR_CTB_POST_707;
                                    if (datiSAS.GETSAI_NR_CTB_QUOB != 0)
                                        datiCalcoloRetributivoSAS.NTotaleContributiCalcoloQuotaB = datiSAS.GETSAI_NR_CTB_QUOB;
                                    if (datiSAS.GETSAI_RTB_MED_POST != 0M)
                                        datiCalcoloRetributivoSAS.RMQuotaB = datiSAS.GETSAI_RTB_MED_POST;
                                }
                                else if (tipoRicGET == TipoRichiesta.GET.GETSAR || tipoRicGET == TipoRichiesta.GET.GETSAY)
                                {
                                    datiCalcoloRetributivoSAS.ImportoQuotaB = null;
                                    datiCalcoloRetributivoSAS.PeriodiQuotaB = null;
                                    datiCalcoloRetributivoSAS.NTotaleContributiCalcoloQuotaB = null;
