                                    datiCalcoloRetributivoSAS.ImportoQuotaRetributivaInMisto = datiSAS.OBM_CM_IMP_RTV;

                                if (datiSAS.GETSAI_IMP_PENS != 0M || tipoRicGET == TipoRichiesta.GET.GETSAR || tipoRicGET == TipoRichiesta.GET.GETSAY)
                                    datiENPALS_SAS.ImportoPensione = datiSAS.GETSAI_IMP_PENS;

