                                    datiENPALS_SAS.ImportoPensione707 = datiSAS.GETSAI_IMP_PENS_707;

                                if (Utility.IsDomandaSperimentaleDonna(datiPensione) || Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione) ||
                                    (!datiCalcoloContributivoSAS.IsDatiCalcoloContributivoEnpalsNull() && datiCalcoloRetributivoSAS.IsDatiCalcoloRetributivoEnpalsNull()))
                                    datiPensioneSAS.TipoCalcolo = 1; // Tipo calcolo contributivo
                                else if (datiCalcoloContributivoSAS.IsDatiCalcoloContributivoEnpalsNull() && !datiCalcoloRetributivoSAS.IsDatiCalcoloRetributivoEnpalsNull())
                                    datiPensioneSAS.TipoCalcolo = 2; // Tipo calcolo retributivo
                                else if (!datiCalcoloContributivoSAS.IsDatiCalcoloContributivoEnpalsNull() && !datiCalcoloRetributivoSAS.IsDatiCalcoloRetributivoEnpalsNull())
