                                    if (datiSAS.GETSAI_SISTEMA_CALCOLO == 'Z' || datiSAS.GETSAI_SISTEMA_CALCOLO == 'H')
                                        datiPensioneSAS.TipoCalcolo = 26; // Tipo calcolo Misto L.214
                                    else if (datiSAS.GETSAI_SISTEMA_CALCOLO == 'K' || datiSAS.GETSAI_SISTEMA_CALCOLO == 'J')
                                        datiPensioneSAS.TipoCalcolo = 27; // Tipo calcolo Retributivo Comma 707
                                    else
                                        datiPensioneSAS.TipoCalcolo = 21; // Tipo Calcolo Misto
                                }

                                #endregion DatiCalcolo

                                datiENPALS_SAS.CodiceTipoDomanda = datiSAS.GETSAI_COD_TIP_DOM;

                                if (!GestioneSAI.ControlsDatiSAI(datiPensioneSAS, datiPensioneDaPrelievo, datiCalcoloContributivoSAS, datiCalcoloRetributivoSAS, datiENPALS_SAS, datiENPALSDaPrelievo,
                                    datiContribuzioneENPALSLiq, datiSAS.GETSAI_SISTEMA_CALCOLO, matricolaOperatore, sedeOperatore, datiDanteCausa, isChiaveFascicoloGenerata, codiceFiscaleDanteCausa, out isNuovoCertificatoGeneratoEnpals, out errori))
                                    throw new INPS.DNA.DnaValidationException(errori);

                                datiPensione.SiglaCategoria = datiPensioneSAS.SiglaCategoria;
                                datiPensione.Fondo = datiPensioneSAS.Fondo;
                            }
                            else
                            {
                                if (!GestioneSAI.ControlsDatiSAI(datiPensione, datiPensioneDaPrelievo, datiCalcoloContributivoENPALS, datiCalcoloRetributivoENPALS, datiENPALS, datiENPALSDaPrelievo,
                                    datiContribuzioneENPALSLiq, datiSAI.GETSAI_SISTEMA_CALCOLO, matricolaOperatore, sedeOperatore, datiDanteCausa, isChiaveFascicoloGenerata, codiceFiscaleDanteCausa, out isNuovoCertificatoGeneratoEnpals, out errori))
                                    throw new INPS.DNA.DnaValidationException(errori);
                            }
