                }

                if (Utility.IsDomandaSpacchettamentoENPALS(datiPensione))
                {
                    // Caso per le domande successive alla prima, quindi con Chiave Fascicolo non generata
                    if (isChiaveFascicoloGenerata.HasValue && !isChiaveFascicoloGenerata.Value)
                    {
                        if (Utility.IsDomandaReversibilita(datiPensione) && !isRiapertura)
                        {
                            ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                            string gp1af03 = string.Empty;
                            //Non dovranno essere recuperati i dati ENPALS in quanto relativi ad un'altra pensione
                            GestioneEnpals.DatiEnpals datiENPALSApp = null;
                            if (!GestioneDatiPensioni.GetDatiTGP1ByChiavePensione(ref datiPensione, chiavePensione, ref datiENPALSApp, out gp1af03, out errori))
                                throw new DNA.DnaValidationException(errori);

                            if (datiDanteCausa != null && Utility.IsPensioneInvaliditaInabilitaENPALSOrCasellario(datiDanteCausa))
                            {
                                if (datiDanteCausa.DecorrenzaPensione.HasValue && Utility.DataSuccessivaA(datiDanteCausa.DecorrenzaPensione.Value, new DateTime(1984, 8, 1)) &&
                                    (string.IsNullOrEmpty(datiPensione.NaturaPensione) || (datiPensione.NaturaPensione.Substring(0, 1) != "3" && datiPensione.NaturaPensione.Substring(0, 1) != "4" && datiPensione.NaturaPensione.Substring(0, 1) != "5" && (datiDanteCausa.SiglaCategoria == "IOSPORT" || datiPensione.NaturaPensione.Substring(1, 1) != "1"))))
                                {
                                    errori = string.Format("Attenzione! La diretta del dante causa ha categoria {0}: è necessario verificare che il primo byte del codice natura sia 3 o 4 (inabilità) o 5 (pensione supplementare) oppure che il secondo byte sia uguale a 1 (invalidità specifica)", datiDanteCausa.SiglaCategoria.Trim().ToUpperInvariant());
                                    throw new INPS.DNA.DnaValidationException(errori);
                                }
                            }

                            GestioneDatiPensioni.GetDatiTGP2ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, datiPensione, out datiCalcoloRetributivoENPALS, out datiCalcoloContributivoENPALS, out listaDatiSupplementiENPALS, ref datiENPALS,
                                out listaDatiSuppRecordENPALS, out errori);

                            if (!GestioneDatiPensioni.GetDatiTGP2ByChiavePensione(chiavePensione, ref datiPensione, out errori))
                                throw new DNA.DnaValidationException(errori);

                            //RECUPERO IL TIPO CALCOLO DAI DATI CHE RITORNA TGP2
                            Utility.GetTipoCalcoloFromDatiHost(ref datiPensione, null, null, datiCalcoloRetributivoENPALS, datiCalcoloContributivoENPALS, datiENPALS);

                            // Se non sono riuscito a calcolare il tipo calcolo, perchè mancano effettivamente i dati calcolo allora lo recupero da GP1AF03
                            if (!datiPensione.TipoCalcolo.HasValue)
                            {
                                if (!string.IsNullOrEmpty(gp1af03))
                                {
                                    switch (gp1af03)
                                    {
                                        case "1":
                                        case "8":
                                            datiPensione.TipoCalcolo = (byte)Utility.TipoCalcolo.Contributivo;
                                            break;
                                        case "2":
                                        case "3":
                                        case "4":
                                            datiPensione.TipoCalcolo = (byte)Utility.TipoCalcolo.Retributivo;
                                            break;
                                    }
                                }
                            }

                            if (!datiPensione.TipoCalcolo.HasValue)
                            {
                                List<string> codiciGP1AF03Ammessi = new List<string> { "1", "2", "3", "4", "8" };
                                if (!codiciGP1AF03Ammessi.Contains(gp1af03))
                                {
                                    errori = "Attenzione tipo calcolo non determinabile (GP1AF03 = '" + (gp1af03 != null ? gp1af03 : string.Empty) + "')";
                                    throw new INPS.DNA.DnaValidationException(errori);
                                }
                            }

                            #region Storico
                            if (datiStoricoGP == null)
                                datiStoricoGP = new GestioneDatiStoricoGP.DatiStoricoGP();
                            datiStoricoGP.InizioAssicurazione = datiPensione.InizioAssicurazione;
                            datiStoricoGP.FineAssicurazione = datiPensione.FineAssicurazione;
                            datiStoricoGP.TipoCalcolo = datiPensione.TipoCalcolo;
                            #endregion Storico
                        }

                        if (Utility.IsDomandaPensioneIndiretta(datiPensione) && !isRiapertura)
                        {
                            string gp1af03 = string.Empty;
                            if (!GestioneDatiPensioni.GetDatiTGP1ByChiavePensione(ref datiPensione, chiavePensione, ref datiENPALS, out gp1af03, out errori))
                                throw new DNA.DnaValidationException(errori);

                            if (!GestioneDatiPensioni.GetDatiTGP2ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, datiPensione, out datiCalcoloRetributivoENPALS, out datiCalcoloContributivoENPALS, out listaDatiSupplementiENPALS, ref datiENPALS,
                                out listaDatiSuppRecordENPALS, out errori))
                                throw new DNA.DnaValidationException(errori);

                            //Non dovranno essere recuperati i dati dei supplementi (GP2BEXXX) in quanto non pertinenti nel caso di indirette
                            listaDatiSupplementiENPALS = null;
                            listaDatiSuppRecordENPALS = null;

                            if (!GestioneDatiPensioni.GetDatiTGP2ByChiavePensione(chiavePensione, ref datiPensione, out errori))
                                throw new DNA.DnaValidationException(errori);

                            //RECUPERO IL TIPO CALCOLO DAI DATI CHE RITORNA TGP2
                            Utility.GetTipoCalcoloFromDatiHost(ref datiPensione, null, null, datiCalcoloRetributivoENPALS, datiCalcoloContributivoENPALS, datiENPALS);

                            // Se non sono riuscito a calcolare il tipo calcolo, perchè mancano effettivamente i dati calcolo allora lo recupero da GP1AF03
                            if (!datiPensione.TipoCalcolo.HasValue)
                            {
                                if (!string.IsNullOrEmpty(gp1af03))
                                {
                                    switch (gp1af03)
                                    {
                                        case "1":
                                        case "8":
                                            datiPensione.TipoCalcolo = (byte)Utility.TipoCalcolo.Contributivo;
                                            break;
                                        case "2":
                                        case "3":
                                        case "4":
                                            datiPensione.TipoCalcolo = (byte)Utility.TipoCalcolo.Retributivo;
                                            break;
                                    }
                                }
                            }

                            if (!datiPensione.TipoCalcolo.HasValue)
                            {
                                List<string> codiciGP1AF03Ammessi = new List<string> { "1", "2", "3", "4", "8" };
                                if (!codiciGP1AF03Ammessi.Contains(gp1af03))
                                {
                                    errori = "Attenzione tipo calcolo non determinabile (GP1AF03 = '" + (gp1af03 != null ? gp1af03 : string.Empty) + "')";
                                    throw new INPS.DNA.DnaValidationException(errori);
                                }
                            }

                            #region Storico
                            datiStoricoGP = new GestioneDatiStoricoGP.DatiStoricoGP();
                            datiStoricoGP.InizioAssicurazione = datiPensione.InizioAssicurazione;
                            datiStoricoGP.FineAssicurazione = datiPensione.FineAssicurazione;
                            datiStoricoGP.TipoCalcolo = datiPensione.TipoCalcolo;
                            #endregion Storico
                        }

                        //ENG - Per le Ric Supplemento ENPALS P=0402 i supplementi vanno presi dal GETSAS
                        List<BLCommon.Entity.DatiSuppRecordENPALS> listaDatiSuppRecordGETSAS = listaDatiSuppRecordENPALS;
                        List<BLCommon.Entity.DatiSupplementiENPALS> listaDatiSupplementiGETSAS = listaDatiSupplementiENPALS;

                        if (tipoDomanda == Utility.TipoDomanda.Ricostituzione && !Utility.IsRicostituzione_MotiviContributivi(datiPensione))
                        {
                            if (!GestioneDatiPensioni.GetDatiTGP2ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, datiPensione, out datiCalcoloRetributivoENPALS, out datiCalcoloContributivoENPALS, out listaDatiSupplementiENPALS, ref datiENPALS,
                                out listaDatiSuppRecordENPALS, out errori))
                                throw new DNA.DnaValidationException(errori);
                        }

                        //ENG - Per le Ric Supplemento ENPALS P=0402 i supplementi vanno presi dal GETSAS
                        if (datiPensione.Gruppo == "0031" && datiPensione.Prodotto == "0402" && datiPensione.Tipo == "0001")
                        {
                            if (listaDatiSuppRecordGETSAS != null)
                                listaDatiSuppRecordENPALS = listaDatiSuppRecordGETSAS;

                            if (listaDatiSupplementiGETSAS != null)
                                listaDatiSupplementiENPALS = listaDatiSupplementiGETSAS;
                        }

                        List<GestioneAnagrafica.DatiAnagrafici> listaAnagraficaAventiDiritto = null;
                        if (!GestioneDatiPensioni.GetDatiTGP4ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, anagraficaTitolare.CodiceFiscale, parametriArca, out listaAventiDirittoGP,
                            out listaAnagraficaAventiDiritto, out errori))
                            throw new DNA.DnaValidationException(errori);

                        if (listaAventiDirittoGP == null || listaAventiDirittoGP.Count == 0)
                            throw new DNA.DnaValidationException("Non sono stati trovati Aventi Diritto nel GP4");

                        if (!GestioneDatiPensioni.GetDatiTGP7ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, datiPensione, isRiapertura, out listaDatiRedditoSentenza495_93, out datiDanteCausaGP7, out errori))
                            throw new DNA.DnaValidationException(errori);

                        if (listaDatiRedditoSentenza495_93 != null && listaDatiRedditoSentenza495_93.Count > 0)
                        {
                            isTabSentenza495_93AGORequired = true;
                            ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAGO = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                            if (prelievo != null && prelievoAGO != null)
                                prelievoAGO.Risposta.ListaDatiRedditiSentenza495_93 = listaDatiRedditoSentenza495_93.ToArray();
                        }

                        if (datiENPALS == null || datiENPALS.IsDatiEnpalsNull())
                            datiENPALS = null;

                        if (listaDatiSuppRecordENPALS == null || listaDatiSuppRecordENPALS.Count == 0)
                            listaDatiSuppRecordENPALS = null;
                        else
                            isSupplementiPerENPALS = true;

                        if (listaDatiSupplementiENPALS == null || listaDatiSupplementiENPALS.Count == 0)
                            listaDatiSupplementiENPALS = null;
                        else
                            isSupplementiPerENPALS = true;
                    }
                }

                if (TipoSalvaguardia != Utility.TipoSalvaguardia.Nessuna)
                {
                    ServiceReferences.AggPec.csAggiornamentoPECO_AGO dati = null;
                    if (!GestioneAggiornamentoPECO.GetCertificazione_AGO(tipoAppartenenza, codiceFiscale, datiPensione.NDomus.ToString(), ref dati, ref errori))
                        throw new INPS.DNA.DnaValidationException(errori);

                    if (dati != null)
                    {
                        datiPensione.FlagUnicarpe = true;
                        datiPensione.TipoLetturaUnicarpe = !String.IsNullOrEmpty(dati.PL_Funzione) ? Convert.ToChar(dati.PL_Funzione) : (char?)null;

                        //ENG - Memo 06_2024
                        if (controlloDinamicoAbilitazioneMemo06_2024 != null && !String.IsNullOrEmpty(controlloDinamicoAbilitazioneMemo06_2024.ValoreControllo) &&
                            controlloDinamicoAbilitazioneMemo06_2024.ValoreControllo.ToUpperInvariant() == "SI")
                        {
                            datiPensione.CodProPE = dati.PL_CodProPE;
                        }

                        #region Istruttoria

                        if (datiIstruttoria == null)
                            datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                        if (!string.IsNullOrEmpty(dati.PL_Deroga))
                        {
                            string categoriaNumerica = datiPensione.GetCodCategoria();

                            List<GestioneDecodifica.CodiceParticolare> listaCodiciParticolari = null;
                            GestioneDecodifica.GetCodiciParticolari(out listaCodiciParticolari);
                            if (listaCodiciParticolari != null && listaCodiciParticolari.Count > 0)
                            {
                                char derogaOutput;
                                char? deroga;
                                char.TryParse(dati.PL_Deroga, out derogaOutput);
                                if (derogaOutput == ' ' || derogaOutput == '\0' || derogaOutput == '0')
                                    deroga = null;
                                else
                                    deroga = derogaOutput;
                                GestioneDecodifica.CodiceParticolare codiceParticolare = listaCodiciParticolari.Find(x => x.TraduzioneSuGp == deroga && x.CodCategoria == categoriaNumerica);
                                if (codiceParticolare != null)
                                {
                                    datiIstruttoria.CodiceParticolareSoggettoDerogato = codiceParticolare.Id;
                                    bSaveIstruttoria = true;
                                }
                            }
                        }

                        if (!bSaveIstruttoria)
                            datiIstruttoria = null;

                        #endregion Istruttoria

                        #region MaggiorazioneBenefici

                        if (dati.aONERI != null && dati.aONERI.Length > 0)
                        {
                            foreach (ServiceReferences.AggPec.ONERI oneri in dati.aONERI)
                            {
                                if (oneri.PL_CodBenef == "10")
                                {
                                    if (datiMaggiorazioniBenefici == null)
                                        datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                    datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.PL_CodBenef;
                                    datiMaggiorazioniBenefici.IsBeneficioArt24Comma15BisFromFELPE = true;

                                    datiPensione.Benefici = true;
                                }
                                else if (oneri.PL_CodBenef == "11")
                                {
                                    if (datiMaggiorazioniBenefici == null)
                                        datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                    datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.PL_CodBenef;
                                    datiMaggiorazioniBenefici.IsBeneficioApePrecociFromFELPE = true;

                                    datiPensione.Benefici = true;
                                }
                            }
                        }

                        if ((Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione || Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ripristino ||
                            Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.RipristinoSuperstiti || isRiapertura) &&
                            datiMaggiorazioniBenefici != null && !string.IsNullOrEmpty(datiMaggiorazioniBenefici.TipoSettimaneBeneficio) && datiMaggiorazioniBenefici.TipoSettimaneBeneficio == "11")
                            datiPensione.IdTipoPLPerRIC = (byte?)Utility.TipoPLPerRIC.APEPrecoci.GetHashCode();

                        #endregion MaggiorazioneBenefici
                    }

                    datiAGGPECO = dati;
                }
            }
            #endregion ENPALS
            #region INPDAP
            else if (Utility.IsDomandaINPDAP(datiPensione.Gestione))
            {
                int categoriaWebDom = 0;
                string categoriaWebDomString = datiPensione.GetCodCategoria();
                int categoriaFelpe = 0;
                int.TryParse(categoriaWebDomString, out categoriaWebDom);

                var IsFlussoFelpePerINPDAP = GestioneCtrlFelpePerINPDAP.IsFlussoFelpePerINPDAP(datiPensione.SiglaCategoria, datiPensione.Gruppo, datiPensione.Prodotto);
                ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_AMG_INPDAP dati_AMG_INPDAP = null;
                ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_AMG dati_AMG = null;

                bool isFlussoAmg = false;
                Utility.TipoFelpe? isFlussoAmgSin = null;
                CheckAttivitaForINPDAP(datiDomanda.Dati.Attivita, out isFlussoAmg, out isFlussoAmgSin);

                // la chiamata a Felpe va fatta solo per domande non di ricostituzione e per  ricostituzioni per motivi contributivi
                if ((Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) != Utility.TipoDomanda.Ricostituzione && !Utility.IsDomandaReversibilita(datiPensione)) || Utility.IsRicostituzione_MotiviContributivi(datiPensione))
                {
                    if (IsFlussoFelpePerINPDAP)
                    {
                        //caso SIN
                        if (isFlussoAmgSin == Utility.TipoFelpe.SIN || isFlussoAmgSin == Utility.TipoFelpe.SPI)
                        {
                            if (!GestioneAggiornamentoPECO.GetDatiPECO_AMG_INPDAP(datiPensione, codiceFiscale, TipoSalvaguardia, isRiapertura, ref dati_AMG_INPDAP, out errori))
                                throw new INPS.DNA.DnaValidationException(errori);
                        }
                        //caso AMG
                        else if (isFlussoAmg)
                        {
                            if (!GestioneAggiornamentoPECO.GetDatiPECO_AMG(datiPensione, codiceFiscale, TipoSalvaguardia, isRiapertura, ref dati_AMG, out errori))
                                throw new INPS.DNA.DnaValidationException(errori);
                        }
                        //l'else è caso manuale
                    }
                    else
                    {
                        if (!GestioneAggiornamentoPECO.GetDatiPECO_AMG_INPDAP(datiPensione, codiceFiscale, TipoSalvaguardia, isRiapertura, ref dati_AMG_INPDAP, out errori))
                            throw new INPS.DNA.DnaValidationException(errori);
                    }
                }

                #region Benefici Contrattuali

                if (dati_AMG != null || dati_AMG_INPDAP != null)
                {
                    var datiContributivi = dati_AMG != null && dati_AMG.aCONTRIBUTIVE_AMG != null ? dati_AMG.aCONTRIBUTIVE_AMG :
                        dati_AMG_INPDAP != null && dati_AMG_INPDAP.aCONTRIBUTIVE_AMG != null ? dati_AMG_INPDAP.aCONTRIBUTIVE_AMG : null;

                    List<string> idR = new List<string> { "R1", "R2", "R3" };
                    datiContributivi = datiContributivi.Where(x => idR.Contains(x.A_CodGest_Contr)).ToArray();
                    if (datiContributivi != null)
                    {
                        listaDatiQuoteMiglioramentiContrattuali = new List<GestioneMiglioramentiContrattuali.DatiQuoteMiglioramentiContrattuali>();
                        foreach (var quota in datiContributivi)
                        {
                            GestioneMiglioramentiContrattuali.DatiQuoteMiglioramentiContrattuali nuovaQuota = new GestioneMiglioramentiContrattuali.DatiQuoteMiglioramentiContrattuali
                            {
                                IdPensione = datiPensione.Id,
                                Codice = quota.A_CodGest_Contr,
                                DataDecorrenza = quota.A_Decorrec,
                                Quota = quota.A_Quotac.ToString()
                            };
                            listaDatiQuoteMiglioramentiContrattuali.Add(nuovaQuota);
                        }
                    }

                }
                #endregion

                if (dati_AMG_INPDAP != null)
                {
                    int.TryParse(dati_AMG_INPDAP.A_Categoria, out categoriaFelpe);

                    Utility.TipoUnicarpe ctrlUnicarpe = Utility.IsDomandaUnicarpe(true, Utility.StringToNullableChar(dati_AMG_INPDAP.A_Funzione), true);
                    if (categoriaFelpe != categoriaWebDom && ctrlUnicarpe == Utility.TipoUnicarpe.Automatica)
                    {
                        throw new INPS.DNA.DnaValidationException("Categoria incongruente tra Procedura Diritto/Misura (" + categoriaFelpe + ") e WebDom ( " + categoriaWebDom + ").");
                    }

                    // Per le ricostituzioni e le trasformazioni da provvisoria il valore di CODPROV deve essere spazio
                    if (Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione || isRiapertura)
                        if (!string.IsNullOrEmpty(dati_AMG_INPDAP.A_Codprov) && !string.IsNullOrEmpty(dati_AMG_INPDAP.A_Codprov.Trim()))
                        {

                            if (Utility.IsDomandaINPDAP(datiPensione.Gestione))
                            {
                                throw new INPS.DNA.DnaValidationException("Domanda proveniente da procedura diritto/misura non acquisibile per codice provvisorietà impostato.");
                            }
                            else
                                throw new INPS.DNA.DnaValidationException("Domanda proveniente da Unicarpe non acquisibile per codice provvisorietà impostato.");
                        }
                    datiPensione.FlagUnicarpe = true;
                    datiPensione.TipoLetturaUnicarpe = !String.IsNullOrEmpty(dati_AMG_INPDAP.A_Funzione) ? Convert.ToChar(dati_AMG_INPDAP.A_Funzione) : (char?)null;
                    datiPensione.TipoFelpe = isFlussoAmgSin == Utility.TipoFelpe.SIN ? (byte)Utility.TipoFelpe.SIN : (byte)Utility.TipoFelpe.SPI;
                    ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFs = (ServiceReferences.LiquidazioneFs.AreaPrelievo)prelievo;

                    if (datiPensione.TipoFelpe == (byte)Utility.TipoFelpe.SPI)
                    {
                        datiPensione.IdNota = Utility.StringToNullableInt(dati_AMG_INPDAP.A_IdNota);
                    }

                    #region Pensione

                    // solo per funzione di lettura = "L", "H" o "G"
                    if (!String.IsNullOrEmpty(dati_AMG_INPDAP.A_Funzione) && (dati_AMG_INPDAP.A_Funzione == "L" || dati_AMG_INPDAP.A_Funzione == "H" || dati_AMG_INPDAP.A_Funzione == "G"))
                    {
                        if (!String.IsNullOrEmpty(dati_AMG_INPDAP.A_Decorre) && dati_AMG_INPDAP.A_Decorre.Trim().Length == 8)
                            datiPensione.DecorrenzaOriginaria = Utility.DataFromString(dati_AMG_INPDAP.A_Decorre, Utility.FormatoData.AAAAmmGG);
                        else if (!String.IsNullOrEmpty(dati_AMG_INPDAP.A_Decorre.Trim()))
                            datiPensione.DecorrenzaOriginaria = Utility.DataFromInt(short.Parse(dati_AMG_INPDAP.A_Decorre.Substring(0, 4)),
                                                                             short.Parse(dati_AMG_INPDAP.A_Decorre.Substring(4, 2)), 1);

                        if (dati_AMG_INPDAP.A_Iniass.ToString().Length == 8)
                            datiPensione.InizioAssicurazione = Utility.DataFromString(dati_AMG_INPDAP.A_Iniass.ToString(), Utility.FormatoData.AAAAmmGG);
                        else
                            datiPensione.InizioAssicurazione = dati_AMG_INPDAP.A_Iniass != 0 ? Utility.DataFromInt(short.Parse(dati_AMG_INPDAP.A_Iniass.ToString().Substring(0, 4)),
                                                                                                    short.Parse(dati_AMG_INPDAP.A_Iniass.ToString().Substring(4, 2)), 1) : null;

                        if (dati_AMG_INPDAP.A_Finass.ToString().Length == 8)
                            datiPensione.FineAssicurazione = Utility.DataFromString(dati_AMG_INPDAP.A_Finass.ToString(), Utility.FormatoData.AAAAmmGG);
                        else
                            datiPensione.FineAssicurazione = dati_AMG_INPDAP.A_Finass != 0 ? Utility.DataFromInt(short.Parse(dati_AMG_INPDAP.A_Finass.ToString().Substring(0, 4)),
                                                                                                    short.Parse(dati_AMG_INPDAP.A_Finass.ToString().Substring(4, 2)), 1) : null;

                        if (!String.IsNullOrEmpty(dati_AMG_INPDAP.A_Datreq) && dati_AMG_INPDAP.A_Datreq.Trim() != string.Empty)
                        {
                            if (dati_AMG_INPDAP.A_Datreq.Trim().Length == 8)
                                datiPensione.DataPerfezionamentoRequisiti = datiPensione.DataPerfezionamentoRequisitiUnicarpe = Utility.DataFromString(dati_AMG_INPDAP.A_Datreq, Utility.FormatoData.AAAAmmGG);
                            else
                                datiPensione.DataPerfezionamentoRequisiti = datiPensione.DataPerfezionamentoRequisitiUnicarpe = Utility.DataFromInt(short.Parse(dati_AMG_INPDAP.A_Datreq.Substring(0, 4)), short.Parse(dati_AMG_INPDAP.A_Datreq.Substring(4, 2)), 1);
                        }

                        //if (!String.IsNullOrEmpty(dati_AMG_INPDAP.A_Att_Econ))
                        //    datiPensione.AttivitaEconomica = datiPensione.AttivitaEconomicaFELPE = Utility.StringToNullableInt(dati_AMG_INPDAP.A_Att_Econ);

                        //if (!String.IsNullOrEmpty(dati_AMG_INPDAP.A_ProF_Indiv))
                        //    datiPensione.ProfessioneIndividuale = datiPensione.ProfessioneIndividualeFELPE = Utility.StringToNullableInt(dati_AMG_INPDAP.A_ProF_Indiv);

                        if (datiPensione.TipoFelpe == (byte)Utility.TipoFelpe.SPI)
                        {
                            if (Utility.IsGestioneLavoratriciMadri(datiPensione))
                            {
                                datiPensione.NumeroFigli = dati_AMG_INPDAP.A_NumFigli == 0 ? (byte?)null : byte.Parse(dati_AMG_INPDAP.A_NumFigli.ToString());
                                datiPensione.SceltaLavMadri = string.IsNullOrEmpty(dati_AMG_INPDAP.A_SceltaLM) ? (byte?)null : byte.Parse(dati_AMG_INPDAP.A_SceltaLM.ToString());
                            }
                            else
                                numeroFigliOpzioneDonna = dati_AMG_INPDAP.A_NumFigli == 0 ? (byte?)null : byte.Parse(dati_AMG_INPDAP.A_NumFigli.ToString());
                        }
                    }

                    if (dati_AMG_INPDAP.aCONTRIBUTIVE_AMG == null || dati_AMG_INPDAP.aRETRIBUTIVE_AMG == null)
                        throw new DNA.DnaValidationException("Non sono presenti i dati di calcolo tra le informazioni provenienti da FELPE.");

                    //Modificata la valorizzazione dei dati sull'array
                    ArrayList datiArrayFS = new ArrayList();
                    datiArrayFS.Add(dati_AMG_INPDAP.aCONTRIBUTIVE_AMG[0].A_Contrib);   // 0
                    datiArrayFS.Add(dati_AMG_INPDAP.aCONTRIBUTIVE_AMG[0].A_Montante);  // 1
                    datiArrayFS.Add(dati_AMG_INPDAP.aCONTRIBUTIVE_AMG[0].A_Anzconc);   // 2
                    datiArrayFS.Add(dati_AMG_INPDAP.aCONTRIBUTIVE_AMG[0].A_Quotac);     // 3
                    datiArrayFS.Add(0.0);//dati_AMG.aCONTRIBUTIVE_AMG[0].A_AnzGG);     // 4
                    datiArrayFS.Add(0.0);//dati_AMG.aCONTRIBUTIVE_AMG[0].A_AnzMM);     // 5
                    datiArrayFS.Add(0.0);//dati_AMG.aCONTRIBUTIVE_AMG[0].A_MonteSCL);  // 6
                    datiArrayFS.Add(dati_AMG_INPDAP.aRETRIBUTIVE_AMG[0].A_CodQuota);  // 7 
                    datiArrayFS.Add(dati_AMG_INPDAP.aRETRIBUTIVE_AMG[0].A_Anzconr);        // 8
                    datiArrayFS.Add(dati_AMG_INPDAP.aRETRIBUTIVE_AMG[0].A_Rms);    // 9
                    datiArrayFS.Add(dati_AMG_INPDAP.aRETRIBUTIVE_AMG[0].A_Quotar);   // 10

                    datiArrayFS.Add(datiPensione.DecorrenzaOriginaria);      // 11
                    datiArrayFS.Add(dati_AMG_INPDAP.A_Sistcal);                       // 12

                    datiPensione.TipoCalcolo = GetTipoCalcoloFromData(tipoAppartenenza, datiArrayFS, datiPensione);

                    if (dati_AMG_INPDAP.aONERI_AMG != null)
                    {
                        if (dati_AMG_INPDAP.aONERI_AMG.Any(x => (x.A_CodGrup == "5300" && x.A_CodSGrup == "5302") || (x.A_CodGrup == "5800" && x.A_CodSGrup == "5802") || (x.A_CodGrup == "6000" && x.A_CodSGrup == "6002") || (x.A_CodGrup == "6100" && x.A_CodSGrup == "6102")))
                            datiPensione.LavoratorePubblico = true;
                        else if (dati_AMG_INPDAP.aONERI_AMG.Any(x => (x.A_CodGrup == "5300" && x.A_CodSGrup == "5301") || (x.A_CodGrup == "5800" && x.A_CodSGrup == "5801") || (x.A_CodGrup == "6000" && x.A_CodSGrup == "6001") || (x.A_CodGrup == "6100" && x.A_CodSGrup == "6101")))
                            datiPensione.LavoratorePubblico = false;
                    }

                    if (dati_AMG_INPDAP.A_SceltaLM != null && !string.IsNullOrEmpty(dati_AMG_INPDAP.A_SceltaLM.Trim()) && dati_AMG_INPDAP.A_SceltaLM.Trim() != "0")
                    {
                        datiPensione.Benefici = true;
                    }

                    GestioneControlliDinamici.ControlloDinamico AbilitazioneMemo_74_88_2025_GDP = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo_74_88_2025_GDP", out AbilitazioneMemo_74_88_2025_GDP);
                    if (AbilitazioneMemo_74_88_2025_GDP != null && !String.IsNullOrEmpty(AbilitazioneMemo_74_88_2025_GDP.ValoreControllo) && AbilitazioneMemo_74_88_2025_GDP.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                    {
                        if (dati_AMG_INPDAP.A_TipCert.Trim() == "POS")
                        {
                            string CaratterizzazioneToInsert = Utility.InserisciValoreCaratterizzazione(datiPensione.Caratterizzazione, '1', 3);
                            datiPensione.Caratterizzazione = CaratterizzazioneToInsert;
                        }
                    }

                    #endregion Pensione

                    #region FondoSpecifico
                    if (dati_AMG_INPDAP.A_Vvdir != 0)
                    {
                        strApp = dati_AMG_INPDAP.A_Vvdir.ToString().PadLeft(6, '0');
                        if (datiPensioneINPDAP == null)
                            datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();
                        datiPensioneINPDAP.VVUtiliDirittoAA = Utility.StringToNullableShort(strApp.Substring(0, 2));
                        datiPensioneINPDAP.VVUtiliDirittoMM = Utility.StringToNullableByte(strApp.Substring(2, 2));
                        datiPensioneINPDAP.VVUtiliDirittoGG = Utility.StringToNullableByte(strApp.Substring(4, 2));
                    }

                    if (dati_AMG_INPDAP.A_Vvmis != 0)
                    {
                        strApp = dati_AMG_INPDAP.A_Vvmis.ToString().PadLeft(6, '0');
                        if (datiPensioneINPDAP == null)
                            datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();
                        datiPensioneINPDAP.VVUtiliMisuraAA = Utility.StringToNullableShort(strApp.Substring(0, 2));
                        datiPensioneINPDAP.VVUtiliMisuraMM = Utility.StringToNullableByte(strApp.Substring(2, 2));
                        datiPensioneINPDAP.VVUtiliMisuraGG = Utility.StringToNullableByte(strApp.Substring(4, 2));
                    }

                    if (isFlussoAmgSin != Utility.TipoFelpe.SPI && !string.IsNullOrEmpty(dati_AMG_INPDAP.A_Microqual))
                    {
                        GestioneDecodifica.DecMicroqualificaINPDAP decMicroqualifica;
                        GestioneDecodifica.GetMicroqualificaByTraduzioneSuGP(dati_AMG_INPDAP.A_Microqual, out decMicroqualifica);
                        if (decMicroqualifica != null)
                        {
                            if (datiPensioneINPDAP == null)
                                datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();
                            datiPensioneINPDAP.Microqualifica = decMicroqualifica.Id;
                        }
                        else
                            throw new INPS.DNA.DnaValidationException(string.Format("La microqualifica ({0}) non è presente in decodifica.", dati_AMG_INPDAP.A_Microqual));
                    }

                    if (!string.IsNullOrEmpty(dati_AMG_INPDAP.A_Annimax))
                    {
                        if (datiPensioneINPDAP == null)
                            datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();
                        datiPensioneINPDAP.AnniMax = Utility.StringToNullableByte(dati_AMG_INPDAP.A_Annimax);
                    }

                    if (!string.IsNullOrEmpty(dati_AMG_INPDAP.A_Anniutili))
                    {
                        if (datiPensioneINPDAP == null)
                            datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();
                        datiPensioneINPDAP.AnniUtili = Utility.StringToNullableByte(dati_AMG_INPDAP.A_Anniutili);
                    }

                    if (!string.IsNullOrEmpty(dati_AMG_INPDAP.Comparto))
                    {
                        if (datiPensioneINPDAP == null)
                            datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();
                        datiPensioneINPDAP.Comparto = Utility.StringToNullableInt(dati_AMG_INPDAP.Comparto);
                    }

                    if (!string.IsNullOrEmpty(dati_AMG_INPDAP.Settore))
                    {
                        if (datiPensioneINPDAP == null)
                            datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();
                        datiPensioneINPDAP.Settore = Utility.StringToNullableInt(dati_AMG_INPDAP.Settore);
                    }

                    if (!string.IsNullOrEmpty(dati_AMG_INPDAP.Ruolo))
                    {
                        if (datiPensioneINPDAP == null)
                            datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();
                        datiPensioneINPDAP.Ruolo = Utility.StringToNullableInt(dati_AMG_INPDAP.Ruolo);
                    }

                    if (datiPensione.TipoFelpe == (byte)Utility.TipoFelpe.SPI)
                    {
                        List<GestioneDecodifica.DecodificaCausaCessazione> ListaCausaCess = null;
                        GestioneDecodifica.GetElencoCodiciCausaCessazione(out ListaCausaCess);
                        GetListaCausaCessazione(datiPensione, ref ListaCausaCess);
                        GestioneDecodifica.DecodificaCausaCessazione causaCess = null;

                        if (!string.IsNullOrEmpty(dati_AMG_INPDAP.A_CFEntePatr) && !string.IsNullOrEmpty(dati_AMG_INPDAP.A_CFEntePatr.Trim()))
                        {
                            if (datiPensioneINPDAP == null)
                                datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();

                            datiPensioneINPDAP.CfAmministrazione = dati_AMG_INPDAP.A_CFEntePatr;
                        }

                        if (!string.IsNullOrEmpty(dati_AMG_INPDAP.A_PrgEntePatr) && !string.IsNullOrEmpty(dati_AMG_INPDAP.A_PrgEntePatr.Trim()))
                        {
                            if (datiPensioneINPDAP == null)
                                datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();

                            datiPensioneINPDAP.ProgAmministrazione = dati_AMG_INPDAP.A_PrgEntePatr;
                        }

                        if (!string.IsNullOrEmpty(dati_AMG_INPDAP.Motivocess) && !string.IsNullOrEmpty(dati_AMG_INPDAP.Motivocess.Trim()))
                        {
                            if (datiPensioneINPDAP == null)
                                datiPensioneINPDAP = new GestionePensioneINPDAP.DatiPensioneINPDAP();

                            if (ListaCausaCess != null && ListaCausaCess.Count > 0)
                            {
                                short resShort = 0;
                                if (short.TryParse(dati_AMG_INPDAP.Motivocess, out resShort))
                                    causaCess = ListaCausaCess.Find(x => x.TraduzioneSuGP.Trim().ToUpperInvariant() == resShort.ToString().Trim().ToUpperInvariant() && x.Fondo == "DAP");
                            }

                            datiPensioneINPDAP.CausaCessazione = causaCess != null ? causaCess.Id : (long?)null;
                        }
                    }
                    #endregion FondoSpecifico

                    #region DatiFondo
                    if (!string.IsNullOrEmpty(dati_AMG_INPDAP.A_Iisconglobata))
                    {
                        if (recordDatiFondoINPDAP == null)
                            recordDatiFondoINPDAP = new GestioneRecordDatiFondoINPDAP.RecordDatiFondoINPDAP();
                        recordDatiFondoINPDAP.IndennitaIntegrativaSpecialeConglobata = dati_AMG_INPDAP.A_Iisconglobata.Trim() == "S" ? true : (dati_AMG_INPDAP.A_Iisconglobata.Trim() == "N" ? false : (bool?)null);
                    }

                    if (prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.ListaRecordDatiFondoINPDAP != null && (Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione || isRiapertura))
                    {
                        if (recordDatiFondoINPDAP == null)
                            recordDatiFondoINPDAP = new GestioneRecordDatiFondoINPDAP.RecordDatiFondoINPDAP();
                        recordDatiFondoINPDAP.Capitolo = prelievoFs.Risposta.ListaRecordDatiFondoINPDAP.FirstOrDefault().Capitolo;
                    }

                    //solo per G/P/T = 2/12/52
                    if (datiPensione.TipoFelpe == (byte)Utility.TipoFelpe.SPI && Utility.IsDomandaInabilitaLegge335(datiPensione))
                    {
                        if (!string.IsNullOrEmpty(dati_AMG_INPDAP.A_ScadRS) && !string.IsNullOrEmpty(dati_AMG_INPDAP.A_ScadRS.Trim()))
                        {
                            if (recordDatiFondoINPDAP == null)
                                recordDatiFondoINPDAP = new GestioneRecordDatiFondoINPDAP.RecordDatiFondoINPDAP();

                            if (dati_AMG_INPDAP.A_ScadRS.Trim() == "99999999")
                                recordDatiFondoINPDAP.ScadenzaIllimitata = true;
                            else
                                recordDatiFondoINPDAP.ScadenzaBenefici = Utility.DataFromString(dati_AMG_INPDAP.A_ScadRS.Trim(), Utility.FormatoData.AAAAmmGG);
                        }
                    }
                    if (recordDatiFondoINPDAP == null)
                        recordDatiFondoINPDAP = new GestioneRecordDatiFondoINPDAP.RecordDatiFondoINPDAP();
                    decimal valueRata;
                    if (Decimal.TryParse(dati_AMG_INPDAP.A_ImportoSingolaRata, out valueRata))
                        recordDatiFondoINPDAP.ImportoSingolaRata = Decimal.Parse(dati_AMG_INPDAP.A_ImportoSingolaRata);

                    int parsedValue;
                    if (int.TryParse(dati_AMG_INPDAP.A_NumeroRate, out parsedValue))
                        recordDatiFondoINPDAP.NumeroRate = int.Parse(dati_AMG_INPDAP.A_NumeroRate);


                    //Memo 282/2024 e Memo 145/2025
                    if (dati_AMG_INPDAP.aTBPECO_13 != null && dati_AMG_INPDAP.aTBPECO_13.Length > 0)
                    {
                        foreach (ServiceReferences.AggPec.iTBPECO13_INPDAP TBPECO_13 in dati_AMG_INPDAP.aTBPECO_13)
                        {
                            //var TBPECO_13 = dati_AMG_INPDAP.aTBPECO_13[0];
                            if (!string.IsNullOrEmpty(TBPECO_13.A_EnteEquoInd))
                                recordDatiFondoINPDAP.EnteEquoInd = TBPECO_13.A_EnteEquoInd;

                            decimal valueImpEq;
                            if (Decimal.TryParse(TBPECO_13.A_ImpEquoInd, out valueImpEq))
                                recordDatiFondoINPDAP.ImpEquoInd = Decimal.Parse(TBPECO_13.A_ImpEquoInd);

                            if (!string.IsNullOrEmpty(TBPECO_13.A_CodInd))
                                recordDatiFondoINPDAP.CodInd = TBPECO_13.A_CodInd;

                            if (!String.IsNullOrEmpty(TBPECO_13.A_DataInizioInd) && TBPECO_13.A_DataInizioInd.Trim().Length == 8)
                                recordDatiFondoINPDAP.DataInizioInd = Utility.DataFromString(TBPECO_13.A_DataInizioInd, Utility.FormatoData.AAAAmmGG);

                            decimal valueImp;
                            if (Decimal.TryParse(TBPECO_13.A_ImpInd, out valueImp))
                                recordDatiFondoINPDAP.ImpInd = Decimal.Parse(TBPECO_13.A_ImpInd);

                            if (!String.IsNullOrEmpty(TBPECO_13.A_DataCessInd) && TBPECO_13.A_DataCessInd.Trim().Length == 8)
                                recordDatiFondoINPDAP.DataCessInd = Utility.DataFromString(TBPECO_13.A_DataCessInd, Utility.FormatoData.AAAAmmGG);

                            decimal valueImpRataIniz;
                            if (Decimal.TryParse(TBPECO_13.A_ImpRataIniz, out valueImpRataIniz))
                                recordDatiFondoINPDAP.ImpRataIniz = Decimal.Parse(TBPECO_13.A_ImpRataIniz);

                            decimal valueImpRataOrd;
                            if (Decimal.TryParse(TBPECO_13.A_ImpRataOrd, out valueImpRataOrd))
                                recordDatiFondoINPDAP.ImpRataOrd = Decimal.Parse(TBPECO_13.A_ImpRataOrd);

                            decimal valueImpRataFin;
                            if (Decimal.TryParse(TBPECO_13.A_ImpRataFin, out valueImpRataFin))
                                recordDatiFondoINPDAP.ImpRataFin = Decimal.Parse(TBPECO_13.A_ImpRataFin);

                            int ValueNumRate;
                            if (int.TryParse(TBPECO_13.A_NumRate, out ValueNumRate))
                                recordDatiFondoINPDAP.NumRate = int.Parse(TBPECO_13.A_NumRate);
                        }

                        //foreach (ServiceReferences.AggPec.iTBPECO13_INPDAP elem in dati_AMG_INPDAP.aTBPECO_13) { }
                    }
                    #endregion

                    #region PensioneFondoDatiGenerici

                    bool bFondo = false;
                    datiPensioneFondoDatiGenerici = new GestioneFondo.DatiFondo();

                    // solo per funzione di lettura = "L", "H" o "G"
                    if (!String.IsNullOrEmpty(dati_AMG_INPDAP.A_Funzione) && (dati_AMG_INPDAP.A_Funzione == "L" || dati_AMG_INPDAP.A_Funzione == "H" || dati_AMG_INPDAP.A_Funzione == "G"))
                    {
                        if (!String.IsNullOrEmpty(datiPensione.Gruppo) && datiPensione.Gruppo.Trim() == "0001" && !String.IsNullOrEmpty(datiPensione.Prodotto) && datiPensione.Prodotto.Trim() == "0001")
                        {
                            datiPensioneFondoDatiGenerici.RiduzioneRetributiva = !String.IsNullOrEmpty(dati_AMG_INPDAP.A_Flagriduz) && !String.IsNullOrEmpty(dati_AMG_INPDAP.A_Flagriduz.Trim()) && dati_AMG_INPDAP.A_Flagriduz.Trim().ToUpperInvariant() == "S" ? true : false;
                            datiPensioneFondoDatiGenerici.RiduzioneRetributivaPercentuale = !Utility.IsDoubleEquals(dati_AMG_INPDAP.A_Percriduz, 0.0) ? Convert.ToDecimal(dati_AMG_INPDAP.A_Percriduz) : (decimal?)null;
                        }
                    }

                    if (datiPensioneFondoDatiGenerici.RiduzioneRetributiva || datiPensioneFondoDatiGenerici.RiduzioneRetributivaPercentuale.HasValue)
                        bFondo = true;

                    if (!bFondo)
                        datiPensioneFondoDatiGenerici = null;

                    #endregion PensioneFondoDatiGenerici

                    #region Istruttoria
                    if (datiIstruttoria == null)
                        datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                    //if (dati_AMG_INPDAP.A_Tipocalc != null && !string.IsNullOrEmpty(dati_AMG_INPDAP.A_Tipocalc.Trim()))
                    //{
                    //    char tipCalc;
                    //    if (char.TryParse(dati_AMG_INPDAP.A_Tipocalc, out tipCalc))
                    //    {
                    //        datiIstruttoria.TipoCalcoloVincenteUnicarpe = tipCalc;
                    //        bSaveIstruttoria = true;
                    //    }
                    //}

                    if (!string.IsNullOrEmpty(dati_AMG_INPDAP.A_Deroga))
                    {
                        if (datiIstruttoria == null)
                            datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                        string categoriaNumerica = datiPensione.GetCodCategoria();

                        List<GestioneDecodifica.CodiceParticolare> listaCodiciParticolari = null;
                        GestioneDecodifica.GetCodiciParticolari(out listaCodiciParticolari);
                        if (listaCodiciParticolari != null && listaCodiciParticolari.Count > 0)
                        {
                            char derogaOutput;
                            char? deroga;
                            char.TryParse(dati_AMG_INPDAP.A_Deroga, out derogaOutput);
                            if (derogaOutput == ' ' || derogaOutput == '\0' || derogaOutput == '0')
                                deroga = null;
                            else
                                deroga = derogaOutput;
                            GestioneDecodifica.CodiceParticolare codiceParticolare = listaCodiciParticolari.Find(x => x.TraduzioneSuGp == deroga && x.CodCategoria == categoriaNumerica);
                            if (codiceParticolare != null)
                            {
                                datiIstruttoria.CodiceParticolareSoggettoDerogato = codiceParticolare.Id;
                                bSaveIstruttoria = true;
                            }
                        }
                    }

                    if (!bSaveIstruttoria)
                        datiIstruttoria = null;

                    #endregion Istruttoria

                    #region Maggiorazioni/Benefici
                    if (dati_AMG_INPDAP.aONERI_AMG != null && dati_AMG_INPDAP.aONERI_AMG.Length > 0)
                    {
                        foreach (ServiceReferences.AggPec.A_TABONERI oneri in dati_AMG_INPDAP.aONERI_AMG)
                        {
                            if (oneri.A_CodBenef == "10")
                            {
                                if (datiMaggiorazioniBenefici == null)
                                    datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                datiMaggiorazioniBenefici.TipoSettimaneBeneficio = "05";
                                datiMaggiorazioniBenefici.IsBeneficioArt24Comma15BisFromFELPE = true;

                                datiPensione.Benefici = true;
                            }
                            else if (oneri.A_CodBenef == "11")
                            {
                                if (datiMaggiorazioniBenefici == null)
                                    datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.A_CodBenef;
                                datiMaggiorazioniBenefici.IsBeneficioApePrecociFromFELPE = true;

                                datiPensione.Benefici = true;
                            }
                            else if (oneri.A_CodBenef == "14" || oneri.A_CodBenef == "18" || oneri.A_CodBenef == "19" || oneri.A_CodBenef == "24")
                            {
                                if (datiMaggiorazioniBenefici == null)
                                    datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.A_CodBenef;
                                datiPensione.Benefici = true;
                            }
                            else if (oneri.A_CodBenef == "01")
                            {
                                if (datiMaggiorazioniBenefici == null)
                                    datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.A_CodBenef;
                                datiMaggiorazioniBenefici.NSettimaneBeneficio = oneri.A_AnzCon;
                                datiMaggiorazioniBenefici.SettAnzContribPost311295 = Convert.ToInt16(oneri.A_AnzBenef);
                                datiMaggiorazioniBenefici.DataNonVedenteDal = Utility.DataFromString(dati_AMG.A_DatNonV.ToString(), Utility.FormatoData.AAAAmmGG);

                                datiPensione.Benefici = true;
                            }
                        }
                    }

                    if (dati_AMG_INPDAP.A_Amianto != 0)
                    {
                        if (datiMaggiorazioniBenefici == null)
                            datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                        datiMaggiorazioniBenefici.MaggiorazioneAmianto = dati_AMG_INPDAP.A_Amianto;
                    }

                    if (dati_AMG_INPDAP.A_Inv74 != 0)
                    {
                        if (datiMaggiorazioniBenefici == null)
                            datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                        datiMaggiorazioniBenefici.MaggiorazioneInv74 = dati_AMG_INPDAP.A_Inv74;
                    }

                    #endregion Maggiorazioni/Benefici

                    controlloFelpe = new GestioneDatiControlloFelpe.ControlloFelpe();

                    //Pulisco il campo CodiceComunicazioneCampo3 del prelievo
                    if (prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiIstruttoria != null)
                    {
                        prelievoFs.Risposta.DatiIstruttoria.CodiceComunicazioneCampo3 = null;
                    }

                    if (!string.IsNullOrEmpty(dati_AMG_INPDAP.A_Codprov) && !string.IsNullOrEmpty(dati_AMG_INPDAP.A_Codprov.Trim()))
                    {

                        if (elencoDecodificaComunicazioneCampo3 != null && elencoDecodificaComunicazioneCampo3.Count() > 0 &&
                            elencoDecodificaComunicazioneCampo3.Exists(x => x.Id.Trim().ToUpperInvariant() == dati_AMG_INPDAP.A_Codprov.Trim().ToUpperInvariant()))
