                            GestioneEnpals.DatiEnpals datiENPALSApp = null;
                            if (!GestioneDatiPensioni.GetDatiTGP1ByChiavePensione(ref datiPensione, chiavePensione, ref datiENPALSApp, out gp1af03, out errori))
