                        if (tipoFondo == Utility.TipoFondo.FS)
                        {
                            if (datiFondoSpecificoFELPE == null)
                                datiFondoSpecificoFELPE = new Entity.DatiFondoSpecificoFELPE();
                            if (datiFondoSpecificoFELPE.DatiFondoFST == null)
                                datiFondoSpecificoFELPE.DatiFondoFST = new GestioneFondo.DatiFondoFST();
                            datiFondoSpecificoFELPE.DatiFondoFST.VVUtiliMisura = _VVUtiliMisura;
                        }
                        else if (tipoFondo == Utility.TipoFondo.PT)
                        {
                            if (datiFondoSpecificoFELPE == null)
                                datiFondoSpecificoFELPE = new Entity.DatiFondoSpecificoFELPE();
                            if (datiFondoSpecificoFELPE.DatiFondoPT == null)
                                datiFondoSpecificoFELPE.DatiFondoPT = new GestioneFondo.DatiFondoPT();
                            datiFondoSpecificoFELPE.DatiFondoPT.VVUtiliMisura = _VVUtiliMisura;
                        }
                    }

                    if (dati_AMG.A_Beneficio336 != 0)
                    {
                        if (tipoFondo == Utility.TipoFondo.FS)
                        {
                            if (datiFondoSpecificoFELPE == null)
                                datiFondoSpecificoFELPE = new Entity.DatiFondoSpecificoFELPE();
                            if (datiFondoSpecificoFELPE.DatiFondoFST == null)
                                datiFondoSpecificoFELPE.DatiFondoFST = new GestioneFondo.DatiFondoFST();
                            datiFondoSpecificoFELPE.DatiFondoFST.RMSSenzaLegge33670QA = !Utility.IsDoubleEquals(dati_AMG.A_Beneficio336, 0.0) ? Convert.ToDecimal(dati_AMG.A_Beneficio336) : (decimal?)null;
                        }
                        else if (tipoFondo == Utility.TipoFondo.PT)
                        {
                            if (datiFondoSpecificoFELPE == null)
                                datiFondoSpecificoFELPE = new Entity.DatiFondoSpecificoFELPE();
                            if (datiFondoSpecificoFELPE.DatiFondoPT == null)
                                datiFondoSpecificoFELPE.DatiFondoPT = new GestioneFondo.DatiFondoPT();
                            datiFondoSpecificoFELPE.DatiFondoPT.RMSSenzaLegge33670QA = !Utility.IsDoubleEquals(dati_AMG.A_Beneficio336, 0.0) ? Convert.ToDecimal(dati_AMG.A_Beneficio336) : (decimal?)null;
                        }
                    }
                    #endregion FondoSpecifico

                    #region PensioneFondoDatiGenerici

                    bool bFondo = false;
                    datiPensioneFondoDatiGenerici = new GestioneFondo.DatiFondo();

                    // solo per funzione di lettura = "L", "H" o "G"
                    if (!String.IsNullOrEmpty(dati_AMG.A_Funzione) && (dati_AMG.A_Funzione == "L" || dati_AMG.A_Funzione == "H" || dati_AMG.A_Funzione == "G"))
                    {
                        if (!String.IsNullOrEmpty(datiPensione.Gruppo) && datiPensione.Gruppo.Trim() == "0001" && !String.IsNullOrEmpty(datiPensione.Prodotto) && datiPensione.Prodotto.Trim() == "0001")
                        {
                            datiPensioneFondoDatiGenerici.RiduzioneRetributiva = !String.IsNullOrEmpty(dati_AMG.A_Flagriduz) && !String.IsNullOrEmpty(dati_AMG.A_Flagriduz.Trim()) && dati_AMG.A_Flagriduz.Trim().ToUpperInvariant() == "S" ? true : false;
                            datiPensioneFondoDatiGenerici.RiduzioneRetributivaPercentuale = !Utility.IsDoubleEquals(dati_AMG.A_Percriduz, 0.0) ? Convert.ToDecimal(dati_AMG.A_Percriduz) : (decimal?)null;
                        }
                    }

                    if (datiPensioneFondoDatiGenerici.RiduzioneRetributiva || datiPensioneFondoDatiGenerici.RiduzioneRetributivaPercentuale.HasValue)
                        bFondo = true;

                    if (!bFondo)
                        datiPensioneFondoDatiGenerici = null;

                    #endregion PensioneFondoDatiGenerici

                    #region Istruttoria
                    if (datiIstruttoria == null)
                        datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                    if (dati_AMG.A_Tipocalc != null && !string.IsNullOrEmpty(dati_AMG.A_Tipocalc.Trim()))
                    {
                        char tipCalc;
                        if (char.TryParse(dati_AMG.A_Tipocalc, out tipCalc))
                        {
                            datiIstruttoria.TipoCalcoloVincenteUnicarpe = tipCalc;
                            bSaveIstruttoria = true;
                        }
                    }

                    if (!string.IsNullOrEmpty(dati_AMG.A_Deroga))
                    {
                        if (datiIstruttoria == null)
                            datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                        string categoriaNumerica = datiPensione.GetCodCategoria();

                        List<GestioneDecodifica.CodiceParticolare> listaCodiciParticolari = null;
                        GestioneDecodifica.GetCodiciParticolari(out listaCodiciParticolari);
                        if (listaCodiciParticolari != null && listaCodiciParticolari.Count > 0)
                        {
                            char derogaOutput;
                            char? deroga;
                            char.TryParse(dati_AMG.A_Deroga, out derogaOutput);
                            if (derogaOutput == ' ' || derogaOutput == '\0' || derogaOutput == '0')
                                deroga = null;
                            else
                                deroga = derogaOutput;
                            GestioneDecodifica.CodiceParticolare codiceParticolare = listaCodiciParticolari.Find(x => x.TraduzioneSuGp == deroga && x.CodCategoria == categoriaNumerica);
                            if (codiceParticolare != null)
                            {
                                datiIstruttoria.CodiceParticolareSoggettoDerogato = codiceParticolare.Id;
                                bSaveIstruttoria = true;
                            }
                        }
                    }

                    if (!bSaveIstruttoria)
                        datiIstruttoria = null;

                    #endregion Istruttoria

                    #region Maggiorazioni/Benefici
                    if (dati_AMG.aONERI_AMG != null && dati_AMG.aONERI_AMG.Length > 0)
                    {
                        foreach (ServiceReferences.AggPec.A_TABONERI oneri in dati_AMG.aONERI_AMG)
                        {
                            if (oneri.A_CodBenef == "10")
                            {
                                if (datiMaggiorazioniBenefici == null)
                                    datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                datiMaggiorazioniBenefici.TipoSettimaneBeneficio = "05";
                                datiMaggiorazioniBenefici.IsBeneficioArt24Comma15BisFromFELPE = true;

                                datiPensione.Benefici = true;
                                break;
                            }
                            else if (oneri.A_CodBenef == "11")
                            {
                                if (datiMaggiorazioniBenefici == null)
                                    datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.A_CodBenef;
                                datiMaggiorazioniBenefici.IsBeneficioApePrecociFromFELPE = true;

                                datiPensione.Benefici = true;
                            }
                            else if (oneri.A_CodBenef == "01")
                            {
                                if (datiMaggiorazioniBenefici == null)
                                    datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.A_CodBenef;
                                datiMaggiorazioniBenefici.NSettimaneBeneficio = oneri.A_AnzCon;
                                datiMaggiorazioniBenefici.SettAnzContribPost311295 = Convert.ToInt16(oneri.A_AnzBenef);
                                datiMaggiorazioniBenefici.DataNonVedenteDal = Utility.DataFromString(dati_AMG.A_DatNonV.ToString(), Utility.FormatoData.AAAAmmGG);

                                datiPensione.Benefici = true;
                            }
                        }
                    }

                    if (dati_AMG.A_Amianto != 0)
                    {
                        if (datiMaggiorazioniBenefici == null)
                            datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                        datiMaggiorazioniBenefici.MaggiorazioneAmianto = dati_AMG.A_Amianto;
                    }

                    if (dati_AMG.A_Inv74 != 0)
                    {
                        if (datiMaggiorazioniBenefici == null)
                            datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                        datiMaggiorazioniBenefici.MaggiorazioneInv74 = dati_AMG.A_Inv74;
                    }

                    #endregion Maggiorazioni/Benefici

                    controlloFelpe = new GestioneDatiControlloFelpe.ControlloFelpe();
                    if (!string.IsNullOrEmpty(dati_AMG.A_Codprov) && !string.IsNullOrEmpty(dati_AMG.A_Codprov.Trim()))
                    {

                        if (elencoDecodificaComunicazioneCampo3 != null && elencoDecodificaComunicazioneCampo3.Count() > 0 &&
                            elencoDecodificaComunicazioneCampo3.Exists(x => x.Id.Trim().ToUpperInvariant() == dati_AMG.A_Codprov.Trim().ToUpperInvariant()))
                        {
                            if (datiIstruttoria == null)
                                datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                            datiIstruttoria.CodiceComunicazioneCampo3 = Utility.StringToNullableChar(dati_AMG.A_Codprov.Trim().ToUpperInvariant());
                        }

                        controlloFelpe.IsProvvisoria = true;

                    }
                    else
                        controlloFelpe.IsProvvisoria = false;

                    datiAGGPECO = dati_AMG;
                }
                else
                {
                    datiPensione.FlagUnicarpe = false;
                    datiPensione.TipoLetturaUnicarpe = null;
                    errori = string.Empty;
                }

                if (controlloDinamicoSpacchettate024 != null && controlloDinamicoSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, isRiapertura))
                {
                    // Caso per le domande successive alla prima, quindi con Chiave Fascicolo non generata
                    if (isChiaveFascicoloGenerata.HasValue && !isChiaveFascicoloGenerata.Value)
                    {
                        if ((Utility.IsDomandaReversibilita(datiPensione) || Utility.IsDomandaPensioneIndiretta(datiPensione)) && !isRiapertura)
                        {
                            string gp1af03 = string.Empty;
                            //I dati relativi alle ENPALS non sono inerenti al fondo PT. La chiamata al servizio serve per recuperare la Natura Pensione
                            GestioneEnpals.DatiEnpals datiENPALSApp = null;
                            if (!GestioneDatiPensioni.GetDatiTGP1ByChiavePensione(ref datiPensione, chiavePensione, ref datiENPALSApp, out gp1af03, out errori))
                                throw new DNA.DnaValidationException(errori);

                            if (!GestioneDatiPensioni.GetDatiTGP2ByChiavePensione(chiavePensione, ref datiPensione, out errori))
                                throw new DNA.DnaValidationException(errori);

                            #region Storico
                            if (datiStoricoGP == null)
                                datiStoricoGP = new GestioneDatiStoricoGP.DatiStoricoGP();
                            datiStoricoGP.InizioAssicurazione = datiPensione.InizioAssicurazione;
                            datiStoricoGP.FineAssicurazione = datiPensione.FineAssicurazione;
                            datiStoricoGP.TipoCalcolo = datiPensione.TipoCalcolo;
                            #endregion Storico
                        }

                        List<GestioneAnagrafica.DatiAnagrafici> listaAnagraficaAventiDiritto = null;
                        if (!GestioneDatiPensioni.GetDatiTGP4ByCodiceFascicolo(datiPensione.NDomus, codiceFascicolo, anagraficaTitolare.CodiceFiscale, parametriArca, out listaAventiDirittoGP,
                            out listaAnagraficaAventiDiritto, out errori))
                            throw new DNA.DnaValidationException(errori);

                        if (listaAventiDirittoGP == null || listaAventiDirittoGP.Count == 0)
                            throw new DNA.DnaValidationException("Non sono stati trovati Aventi Diritto nel GP4");
                    }
                }
            }
            #endregion Fondi AMG
            #region Cumulo
            else if (Utility.IsDomandaCumulo(datiPensione.SiglaCategoria))
            {
                //ENG - Memo 32_a/2018
                if ((Utility.IsRicostituzione(datiPensione.Gruppo) && (datiPensione.Prodotto == "0102" || datiPensione.Prodotto == "0107" || Utility.IsRicostituzioneMotiviContributiviVariazioneDatiSupplementiCumulo(datiPensione)) &&
                     GestioneCtrlControlliApplicativi.CheckControlloApplicativoAttivoByData(GestioneCtrlControlliApplicativi.EnumNomeControllo.AGO.BLOCCO_RIC_CUMULO_AUTOMATICHE, dataSistema)) ||
                     (isRiapertura && GestioneCtrlControlliApplicativi.CheckControlloApplicativoAttivoByData(GestioneCtrlControlliApplicativi.EnumNomeControllo.AGO.BLOCCO_TRF_CUMULO_AUTOMATICHE, dataSistema)) ||
                     !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) ||
                    Utility.IsDomandaAPEPrecoci(datiPensione))
                {
                    ServiceReferences.TotalIvs.clsDatiCumulo risposta = null;
                    if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura))
                    {
                        //ENG - TRF VOCUM PRECOCI con tipo richiesta diversa da S1
                        if (isRiapertura && Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && Utility.IsDomandaAPEPrecoci(datiPensione)
                            && !String.IsNullOrEmpty(datiPensione.CodiceTipoRichiesta) && datiPensione.CodiceTipoRichiesta.Trim().ToUpperInvariant() != "S1")
                        {
                            //chiamo il servizio del cumulo per le PL
                            if (!GestioneTotalIvs.GetDatiCumulIVS(datiPensione.NDomus, out risposta, out errori))
                                throw new INPS.DNA.DnaValidationException(errori);

                            if (risposta == null)
                                mostraPopupMemo312023 = true;
                        }
                        else
                        {
                            if (!GestioneTotalIvs.GetDatiCumulRicostituzioneIVS(datiPensione.NDomus, out risposta, out errori))
                                throw new INPS.DNA.DnaValidationException(errori);

                            //ENG - Memo 32_a/2018
                            if (Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && risposta == null && (isRiapertura || (datiPensione.Prodotto == "0102" || datiPensione.Prodotto == "0107") || Utility.IsRicostituzioneMotiviContributiviVariazioneDatiSupplementiCumulo(datiPensione)) &&
                                GestioneCtrlControlliApplicativi.CheckControlloApplicativoAttivoByData(GestioneCtrlControlliApplicativi.EnumNomeControllo.AGO.BLOCCO_RIC_VOCUM, dataSistema))
                            {
                                GestioneControlliDinamici.ControlloDinamico sediDaControllare = null;
                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("SediRICCumuloAutomatiche", out sediDaControllare);
                                if (sediDaControllare != null && (string.IsNullOrEmpty(sediDaControllare.ValoreControllo) ||
                                    sediDaControllare.ValoreControllo.Split(';').ToList().Exists(x => x.PadLeft(4, '0') == sedeOperatore.ToString().PadLeft(4, '0')))
                                    && !(isRiapertura && Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && Utility.IsDomandaAPEPrecoci(datiPensione) && !String.IsNullOrEmpty(datiPensione.CodiceTipoRichiesta) && datiPensione.CodiceTipoRichiesta.Trim().ToUpperInvariant() == "S1"))
                                {
                                    errori = "Non è possibile acquisire la domanda VOCUM. E' necessario lavorare la domanda su procedura CUMUL";
                                    throw new INPS.DNA.DnaValidationException(errori);
                                }
                            }
                        }
                    }
                    else
                    {
                        bool isDomandaAutomatica = datiPensione.CodiceTipoRichiesta == "S1";

                        if (!(isDomandaAutomatica == false && Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && Utility.IsDomandaAPEPrecoci(datiPensione)))
                        {
                            if (!GestioneTotalIvs.GetDatiCumulIVS(datiPensione.NDomus, out risposta, out errori))
                                throw new INPS.DNA.DnaValidationException(errori);
                        }

                        if (isDomandaAutomatica && Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && Utility.IsDomandaAPEPrecoci(datiPensione) && risposta == null)
                        {
                            errori = "Per la domanda di precoci automatica che si sta tentando di acquisire mancano le informazioni provenienti da Cumul. E’ necessario definire la domanda in  procedura CUMUL";
                            throw new INPS.DNA.DnaValidationException(errori);
                        }
                    }

                    if (risposta != null)
                    {
                        datiPensione.IsCumuloAutomatica = true;
                        if (Utility.IsRicostituzione(datiPensione.Gruppo))
                            isStoricoVisible = true;

                        if (risposta.objDomanda != null)
                        {
                            if (!(Utility.IsDomandaSupplementoCumulo(datiPensione) || Utility.IsDomandaRicostituzioneAdeguamentoProQuotaCasse(datiPensione)))
                            {
                                #region Pensione

                                if (risposta.objDomanda.Decorrenza != DateTime.MinValue)
                                    datiPensione.DecorrenzaOriginaria = risposta.objDomanda.Decorrenza;

                                if (risposta.objDomanda.DataPerfReq != DateTime.MinValue)
                                    datiPensione.DataPerfezionamentoRequisiti = risposta.objDomanda.DataPerfReq;

                                if (risposta.objDomanda.SistemaCalcolo == "1")
                                    datiPensione.Contributivo = '8';
                                else if (risposta.objDomanda.SistemaCalcolo == "2")
                                    datiPensione.Contributivo = '2';

                                if (risposta.objDomanda.DataIniAss != DateTime.MinValue)
                                    datiPensione.InizioAssicurazione = risposta.objDomanda.DataIniAss;

                                if (risposta.objDomanda.DataFineAss != DateTime.MinValue)
                                    datiPensione.FineAssicurazione = risposta.objDomanda.DataFineAss;

                                if (risposta.objDomanda.CodiceNatura == "S" || risposta.objDomanda.CodiceNatura == "Z")
                                {
                                    if (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Length == 3)
                                        datiPensione.NaturaPensione = datiPensione.NaturaPensione.Substring(0, 2) + "S";
                                    else
                                        datiPensione.NaturaPensione = "  S";
                                }
                                //ENG - Domanda VOCUM recupero codice natura 3zo byte V
                                if (risposta.objDomanda.CodiceNatura == "V")
                                {
                                    if (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Length == 3)
                                        datiPensione.NaturaPensione = datiPensione.NaturaPensione.Substring(0, 2) + "V";
                                    else
                                        datiPensione.NaturaPensione = "  V";
                                }

                                if (risposta.objDomanda.TipoDipendente == "1")
                                    datiPensione.LavoratorePubblico = false;
                                else if (risposta.objDomanda.TipoDipendente == "2")
                                    datiPensione.LavoratorePubblico = true;


                                if ((Utility.IsGestioneLavoratriciMadri(datiPensione) && Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria)) ||
                                    Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true))
                                {
                                    datiPensione.NumeroFigli = string.IsNullOrEmpty(risposta.objDomanda.NumeroFigli) || risposta.objDomanda.NumeroFigli == "0" ? (byte?)null : byte.Parse(risposta.objDomanda.NumeroFigli);
                                    if (!Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) && !Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true))
                                        datiPensione.SceltaLavMadri = string.IsNullOrEmpty(risposta.objDomanda.TipoBeneficioLavoratriciMadri) || risposta.objDomanda.TipoBeneficioLavoratriciMadri == "0" ? (byte?)null : byte.Parse(risposta.objDomanda.TipoBeneficioLavoratriciMadri);
                                    //if (Utility.IsDomandaTipoContributivo(datiPensione, null, null))
                                    //{
                                    //    if (!String.IsNullOrEmpty(dati.PL_DatOPZ) && dati.PL_DatOPZ.Trim() != string.Empty)
                                    //    {
                                    //        if (dati.PL_DatOPZ.Trim().Length == 8)
                                    //            datiPensione.DataOpzione = Utility.DataFromString(dati.PL_DatOPZ, Utility.FormatoData.AAAAmmGG);
                                    //        else
                                    //            datiPensione.DataOpzione = Utility.DataFromInt(short.Parse(dati.PL_DatOPZ.Substring(0, 4)), short.Parse(dati.PL_DatOPZ.Substring(4, 2)), 1);
                                    //    }
                                    //}
                                }

                                //ENG  - Memo 108_2024
                                if (Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria))
                                {
                                    //ENG  - Memo 108_2024 (per la gestione del campo "CaratterizzazioneLegge" non serve la chiave "AbilitazioneMemo108_2024")
                                    if (!String.IsNullOrEmpty(risposta.objDomanda.CaratterizzazioneLegge) && !String.IsNullOrEmpty(risposta.objDomanda.CaratterizzazioneLegge.Trim()))
                                    {
                                        if (risposta.objDomanda.CaratterizzazioneLegge.Trim() == "1")
                                            datiPensione.Caratterizzazione = "1";
                                    }
                                }

                                #endregion Pensione

                                #region Sindacato

                                if (!string.IsNullOrEmpty(risposta.objDomanda.Sindacato))
                                {
                                    datiSindacato = new GestionePensione.DatiSindacato();
                                    datiSindacato.CodiceSindacato = risposta.objDomanda.Sindacato;
                                    //TODO: Verificare se è necessario recuperare in qualche modo la decorrenza sindacato e/o la cessazione sindacato
                                }

                                #endregion Sindacato

                                #region StatoCivile

                                if (!string.IsNullOrEmpty(risposta.objDomanda.StatoCivile) && risposta.objDomanda.Decorrenza != DateTime.MinValue)
                                {
                                    // Considero solo gli stati civili censiti su IVS
                                    if (new List<string> { "1", "2", "3", "4", "5", "7", "8", "C" }.Contains(risposta.objDomanda.StatoCivile))
                                    {
                                        if (listaDatiStatoCivile == null)
                                            listaDatiStatoCivile = new List<GestioneAnagrafica.DatiStatoCivile>();

                                        GestioneAnagrafica.DatiStatoCivile statoCivile = new GestioneAnagrafica.DatiStatoCivile();
                                        statoCivile.Decorrenza = risposta.objDomanda.Decorrenza;
                                        statoCivile.Codice = risposta.objDomanda.StatoCivile[0];

                                        listaDatiStatoCivile.Add(statoCivile);
                                    }
                                }

                                #endregion StatoCivile

                                #region PensioniDatiGenerici

                                if (datiPensioniDatiGenerici == null)
                                    datiPensioniDatiGenerici = new GestioneDatiGenericiAgoCi.PensioniDatiGenerici();

                                if (!string.IsNullOrEmpty(risposta.objDomanda.EnteIstruttoria) && !string.IsNullOrEmpty(risposta.objDomanda.EnteIstruttoria.Trim()))
                                {
                                    List<GestioneDecodifica.DecodificaEnteCassaProfessionale> elencoDecodificaEnteCassaProfessionale = null;
                                    GestioneDecodifica.GetDecodificaEnteCassaProfessionale(out elencoDecodificaEnteCassaProfessionale);
                                    if (elencoDecodificaEnteCassaProfessionale != null && elencoDecodificaEnteCassaProfessionale.Count > 0)
                                    {
                                        GestioneDecodifica.DecodificaEnteCassaProfessionale decodifica = elencoDecodificaEnteCassaProfessionale.Find(x => x.TraduzioneSuGP == risposta.objDomanda.EnteIstruttoria.PadLeft(4, '0'));
                                        if (decodifica != null)
                                            datiPensioniDatiGenerici.EnteCassa = decodifica.Id;
                                    }
                                }

                                datiPensioniDatiGenerici.TipoCumulo = risposta.objDomanda.Interna;
                                if (!string.IsNullOrEmpty(risposta.objDomanda.StatoCompletamento) && !string.IsNullOrEmpty(risposta.objDomanda.StatoCompletamento.Trim()) &&
                                    new List<string> { "E", "M" }.Contains(risposta.objDomanda.StatoCompletamento))
                                    datiPensioniDatiGenerici.CumuloEsterno = risposta.objDomanda.StatoCompletamento[0];
                                //if (!datiPensioniDatiGenerici.TipoCumulo.GetValueOrDefault())
                                //    datiPensioniDatiGenerici.CumuloEsterno = 'E';

                                #endregion PensioniDatiGenerici

                                #region Istruttoria
                                if (risposta.objDomanda.TotSettDiritto != 0)
                                {
                                    if (datiIstruttoria == null)
                                        datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                                    datiIstruttoria.NSettimaneOBG = risposta.objDomanda.TotSettDiritto;
                                    bSaveIstruttoria = true;
                                }
                                #endregion Istruttoria

                                #region Oneri
                                if (datiPensione.LavoratorePubblico.HasValue || Utility.IsDomandaAnzianitaPerLeggeBilancio2019OrRicostituzione(datiPensione) || Utility.IsDomandaRiliquidazioneAnzianitaAnticipataConFinestraDecorrenza(datiPensione) || Utility.IsDomandaAnticipataConOpzionePL(datiPensione))
                                {
                                    List<GestioneDecodifica.GruppoOneri> listaDecGruppoOneri = null;
                                    List<GestioneDecodifica.SottoGruppoOneri> listaDecSottogruppoOneri = null;
                                    GestioneDecodifica.GetGruppoOneri(out listaDecGruppoOneri);
                                    GestioneDecodifica.GetSottoGruppoOneri(out listaDecSottogruppoOneri);

                                    if (listaOneri == null)
                                        listaOneri = new List<GestioneOneri.DatiOneri>();
                                    GestioneOneri.DatiOneri onere = null;

                                    if (datiPensione.LavoratorePubblico.HasValue)
                                    {
                                        if (Utility.IsDomandaAnticipataFlessibile(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione))
                                        {
                                            onere = new GestioneOneri.DatiOneri
                                            {
                                                IdCodeGruppo = listaDecGruppoOneri.FirstOrDefault(x => x.Code == "6000").Id,
                                                IdCodeSottoGruppo = datiPensione.LavoratorePubblico.Value ? listaDecSottogruppoOneri.FirstOrDefault(x => x.Code == "6002").Id : listaDecSottogruppoOneri.FirstOrDefault(x => x.Code == "6001").Id,
                                                Scadenza = risposta.objDomanda.DataFineOneri != DateTime.MinValue ? risposta.objDomanda.DataFineOneri : (DateTime?)null,
                                                ScadenzaBeneficio = risposta.objDomanda.DataFineIncumulabilita != DateTime.MinValue ? risposta.objDomanda.DataFineIncumulabilita : (DateTime?)null
                                            };

                                        }
                                        else if (Utility.IsDomandaQuota102(datiPensione))
                                        {
                                            onere = new GestioneOneri.DatiOneri
                                            {
                                                IdCodeGruppo = listaDecGruppoOneri.FirstOrDefault(x => x.Code == "5800").Id,
                                                IdCodeSottoGruppo = datiPensione.LavoratorePubblico.Value ? listaDecSottogruppoOneri.FirstOrDefault(x => x.Code == "5802").Id : listaDecSottogruppoOneri.FirstOrDefault(x => x.Code == "5801").Id,
                                                Scadenza = risposta.objDomanda.DataFineOneri != DateTime.MinValue ? risposta.objDomanda.DataFineOneri : (DateTime?)null,
                                                ScadenzaBeneficio = risposta.objDomanda.DataFineIncumulabilita != DateTime.MinValue ? risposta.objDomanda.DataFineIncumulabilita : (DateTime?)null
                                            };

                                        }
                                        else if (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))
                                        {
                                            onere = new GestioneOneri.DatiOneri
                                            {
                                                IdCodeGruppo = listaDecGruppoOneri.FirstOrDefault(x => x.Code == "6100").Id,
                                                IdCodeSottoGruppo = datiPensione.LavoratorePubblico.Value ? listaDecSottogruppoOneri.FirstOrDefault(x => x.Code == "6102").Id : listaDecSottogruppoOneri.FirstOrDefault(x => x.Code == "6101").Id,
                                                Scadenza = risposta.objDomanda.DataFineOneri != DateTime.MinValue ? risposta.objDomanda.DataFineOneri : (DateTime?)null,
                                                ScadenzaBeneficio = risposta.objDomanda.DataFineIncumulabilita != DateTime.MinValue ? risposta.objDomanda.DataFineIncumulabilita : (DateTime?)null
                                            };

                                        }
                                        else
                                        {
                                            onere = new GestioneOneri.DatiOneri
                                            {
                                                IdCodeGruppo = listaDecGruppoOneri.FirstOrDefault(x => x.Code == "5300").Id,
                                                IdCodeSottoGruppo = datiPensione.LavoratorePubblico.Value ? listaDecSottogruppoOneri.FirstOrDefault(x => x.Code == "5302").Id : listaDecSottogruppoOneri.FirstOrDefault(x => x.Code == "5301").Id,
                                                Scadenza = risposta.objDomanda.DataFineOneri != DateTime.MinValue ? risposta.objDomanda.DataFineOneri : (DateTime?)null,
                                                ScadenzaBeneficio = risposta.objDomanda.DataFineIncumulabilita != DateTime.MinValue ? risposta.objDomanda.DataFineIncumulabilita : (DateTime?)null
                                            };
                                        }
                                    }
                                    else if (Utility.IsDomandaAnzianitaPerLeggeBilancio2019OrRicostituzione(datiPensione) || Utility.IsDomandaRiliquidazioneAnzianitaAnticipataConFinestraDecorrenza(datiPensione) || Utility.IsDomandaAnticipataConOpzionePL(datiPensione))
                                    {
                                        onere = new GestioneOneri.DatiOneri
                                        {
                                            IdCodeGruppo = listaDecGruppoOneri.FirstOrDefault(x => x.Code == "5400").Id,
                                            IdCodeSottoGruppo = Utility.IsDomandaINPDAP(datiPensione.Gestione) ? listaDecSottogruppoOneri.FirstOrDefault(x => x.Code == "5402").Id : listaDecSottogruppoOneri.FirstOrDefault(x => x.Code == "5401").Id,
                                            Scadenza = risposta.objDomanda.DataFineOneri != DateTime.MinValue ? risposta.objDomanda.DataFineOneri : (DateTime?)null,
                                        };
                                    }

                                    if (Utility.IsDomandaAnticipataConOpzionePL(datiPensione))
                                    {
                                        if (risposta.objDomanda.DataFineOneri != DateTime.MinValue)
                                        {
                                            isTabOneriVisible = true;
                                            listaOneri.Add(onere);
                                        }
                                    }
                                    else
                                        listaOneri.Add(onere);
                                }
                                #endregion Oneri

                                #region NuoveLiquidate

                                //ENG - Memo 108_2024                             
                                if (Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria))
                                {
                                    //ENG  - Memo 108_2024 (per la gestione del campo "CodiceProvvisorio" serve la chiave "AbilitazioneMemo108_2024")
                                    GestioneControlliDinamici.ControlloDinamico abilitazioneMemo108_2024 = null;
                                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo108_2024", out abilitazioneMemo108_2024);

                                    if (abilitazioneMemo108_2024 != null && !String.IsNullOrEmpty(abilitazioneMemo108_2024.ValoreControllo)
                                        && abilitazioneMemo108_2024.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                                    {
                                        if (!String.IsNullOrEmpty(risposta.objDomanda.CodiceProvvisorio) && !String.IsNullOrEmpty(risposta.objDomanda.CodiceProvvisorio.Trim()))
                                        {
                                            if (risposta.objDomanda.CodiceProvvisorio.Trim() == "8")
                                            {
                                                if (datiNuoveLiquidate == null)
                                                    datiNuoveLiquidate = new GestioneNuoveLiquidate.NuoveLiquidate();

                                                datiNuoveLiquidate.FlagProvvisoria = true;
                                                datiNuoveLiquidate.IsFlagProvvisoriaFromCumulo = true;

                                            }
                                            else if (risposta.objDomanda.CodiceProvvisorio.Trim() == "0")
                                            {
                                                if (datiNuoveLiquidate == null)
                                                    datiNuoveLiquidate = new GestioneNuoveLiquidate.NuoveLiquidate();

                                                datiNuoveLiquidate.FlagProvvisoria = false;
                                            }
                                        }
                                    }
                                }

                                #endregion NuoveLiquidate
                            }
                        }

                        if (risposta.objPagamento != null)
                        {
                            if (!(Utility.IsDomandaSupplementoCumulo(datiPensione) || Utility.IsDomandaRicostituzioneAdeguamentoProQuotaCasse(datiPensione)))
                            {
                                #region Pagamento
                                GestionePagamento.DatiPagamento datiPagamentoApp = null;
                                RecuperaModPagamentoFromTotalIVS(risposta.objPagamento, out datiPagamentoApp);

                                if (datiPagamentoApp != null)
                                    datiPagamento = datiPagamentoApp;
                                #endregion Pagamento
                            }
                        }

                        if (risposta.objDatiContributivi != null && risposta.objDatiContributivi.Length > 0)
                        {
                            List<GestioneDecodifica.DecEnteGestioneFondo> listaDecEnteGestioneFondo = null;
                            GestioneDecodifica.GetDecEnteGestioneFondo(out listaDecEnteGestioneFondo);

                            if (Utility.IsDomandaSupplementoCumulo(datiPensione) || Utility.IsDomandaRicostituzioneAdeguamentoProQuotaCasse(datiPensione))
                            {
                                #region Supplementi
                                listaDatiSupplementiCumuloTotalIVS = new List<BLCommon.Entity.DatiSupplementiCumulo>();
                                foreach (ServiceReferences.TotalIvs.datiContributiviCumulo datiContributivi in risposta.objDatiContributivi)
                                {
                                    // Verifico che siano presenti i dati nel record
                                    if (datiContributivi != new ServiceReferences.TotalIvs.datiContributiviCumulo())
                                    {
                                        BLCommon.Entity.DatiSupplementiCumulo supplemento = new BLCommon.Entity.DatiSupplementiCumulo();
                                        GestioneDecodifica.DecEnteGestioneFondo decEnteGestioneFondo = listaDecEnteGestioneFondo.Find(x => x.Codice == datiContributivi.Codice && x.CodiceFondo.ToString() == datiContributivi.CodiceFondo);
                                        if (decEnteGestioneFondo != null)
                                            supplemento.EnteGestioneFondo = decEnteGestioneFondo.Id;
                                        else
                                            throw new INPS.DNA.DnaValidationException(string.Format("La coppia codice {0} e codice fondo {1} non è censita nell'applicazione.", datiContributivi.Codice, datiContributivi.CodiceFondo));

                                        supplemento.Settimane = datiContributivi.SettimaneMisura;

                                        if (!string.IsNullOrEmpty(datiContributivi.ImpQuotaEnte))
                                            supplemento.Importo = Utility.StringToNullableDecimal(datiContributivi.ImpQuotaEnte);

                                        if (!string.IsNullOrEmpty(datiContributivi.DataDecorrenzaQuota))
                                            supplemento.Decorrenza = Utility.DataFromString(datiContributivi.DataDecorrenzaQuota, Utility.FormatoData.GGmmAAAA);

                                        if (Utility.IsDomandaRicostituzioneAdeguamentoProQuotaCasse(datiPensione))
                                            supplemento.AdeguamentoProQuotaCasse = true;

                                        listaDatiSupplementiCumuloTotalIVS.Add(supplemento);
                                    }
                                }
                                if (listaDatiSupplementiCumuloTotalIVS != null && listaDatiSupplementiCumuloTotalIVS.Count > 0)
                                    isSupplementiPerTotalIVS = true;
                                #endregion Supplementi
                            }
                            else
                            {
                                #region Quote Pensione
                                listaDatiQuotePensioneTotalIVS = new List<GestioneCalcolo.QuotePensione>();
                                foreach (ServiceReferences.TotalIvs.datiContributiviCumulo datiContributivi in risposta.objDatiContributivi)
                                {
                                    // Verifico che siano presenti i dati nel record
                                    if (datiContributivi != new ServiceReferences.TotalIvs.datiContributiviCumulo())
                                    {
                                        GestioneCalcolo.QuotePensione quotePensione = new GestioneCalcolo.QuotePensione();

                                        GestioneDecodifica.DecEnteGestioneFondo decEnteGestioneFondo = listaDecEnteGestioneFondo.Find(x => x.Codice == datiContributivi.Codice && x.CodiceFondo.ToString() == datiContributivi.CodiceFondo);
                                        if (decEnteGestioneFondo != null)
                                            quotePensione.EnteGestioneFondo = decEnteGestioneFondo.Id;
                                        else
                                            throw new INPS.DNA.DnaValidationException(string.Format("La coppia codice {0} e codice fondo {1} non è censita nell'applicazione.", datiContributivi.Codice, datiContributivi.CodiceFondo));

                                        if (datiContributivi.SettimaneMisura != 0)
                                            quotePensione.Settimane = datiContributivi.SettimaneMisura;

                                        if (!string.IsNullOrEmpty(datiContributivi.ImpQuotaEnte))
                                            quotePensione.Importo = Utility.StringToNullableDecimal(datiContributivi.ImpQuotaEnte);

                                        if (!string.IsNullOrEmpty(datiContributivi.DataDecorrenzaQuota))
                                            quotePensione.Decorrenza = Utility.DataFromString(datiContributivi.DataDecorrenzaQuota, Utility.FormatoData.GGmmAAAA);

                                        if (GestioneCtrlControlliApplicativi.CheckControlloApplicativoAttivoByData(GestioneCtrlControlliApplicativi.EnumNomeControllo.AGO.SCARICO_TRATTENUTE_CUMULO, dataSistema) &&
                                            datiContributivi.objDatiTrattenute != null && datiContributivi.objDatiTrattenute.Count() > 0)
                                        {
                                            if (listaDatiTrattenuteQuotePensioneTotalIVS == null)
                                                listaDatiTrattenuteQuotePensioneTotalIVS = new List<GestioneCalcolo.TrattenuteQuotePensione>();
                                            foreach (ServiceReferences.TotalIvs.clsDatiTrattenute datiTrattenute in datiContributivi.objDatiTrattenute)
                                            {
                                                if (datiTrattenute != new ServiceReferences.TotalIvs.clsDatiTrattenute())
                                                {
                                                    GestioneCalcolo.TrattenuteQuotePensione trattenute = new GestioneCalcolo.TrattenuteQuotePensione();
                                                    trattenute.EnteGestioneFondoQuote = decEnteGestioneFondo.Id;
                                                    short? annoCompetenza = Utility.StringToNullableShort(datiTrattenute.AnnoCompetenza);
                                                    trattenute.AnnoCompetenza = annoCompetenza.GetValueOrDefault();
                                                    trattenute.CodiceTrattenute = datiTrattenute.CodTrattenuta;
                                                    if (!string.IsNullOrEmpty(datiTrattenute.ImpTrattEnte))
                                                    {
                                                        decimal? importo = Utility.StringToNullableDecimal(datiTrattenute.ImpTrattEnte);
                                                        trattenute.ImportoTrattenute = importo.GetValueOrDefault();
                                                    }
                                                    listaDatiTrattenuteQuotePensioneTotalIVS.Add(trattenute);
                                                }
                                            }
                                        }
                                        listaDatiQuotePensioneTotalIVS.Add(quotePensione);
                                    }
                                }
                                #endregion Quote Pensione
                            }
                        }

                        //ENG - Memo32_a/2018
                        if (Utility.IsRicostituzioneMotiviContributiviVariazioneDatiSupplementiCumulo(datiPensione))
                        {
                            if (risposta != null && risposta.objListaVarSup != null && risposta.objListaVarSup.Length > 0)
                            {
                                List<GestioneDecodifica.DecEnteGestioneFondo> listaDecEnteGestioneFondo = null;
                                GestioneDecodifica.GetDecEnteGestioneFondo(out listaDecEnteGestioneFondo);

                                listaDatiSupplementiCumuloTotalIVS = new List<BLCommon.Entity.DatiSupplementiCumulo>();
                                foreach (ServiceReferences.TotalIvs.clsVarSup datiSupplemento in risposta.objListaVarSup)
                                {
                                    if (datiSupplemento != new ServiceReferences.TotalIvs.clsVarSup())
                                    {
                                        BLCommon.Entity.DatiSupplementiCumulo supplemento = new BLCommon.Entity.DatiSupplementiCumulo();
                                        GestioneDecodifica.DecEnteGestioneFondo decEnteGestioneFondo = listaDecEnteGestioneFondo.Find(x => x.CodiceFondo.ToString() == datiSupplemento.CodiceFondo);
                                        if (decEnteGestioneFondo != null)
                                            supplemento.EnteGestioneFondo = decEnteGestioneFondo.Id;
                                        else
                                            throw new INPS.DNA.DnaValidationException(string.Format("Il codice fondo {1} non è censito nell'applicazione.", datiSupplemento.CodiceFondo));

                                        if (!string.IsNullOrEmpty(datiSupplemento.Prorata))
                                            supplemento.Importo = Utility.StringToNullableDecimal(datiSupplemento.Prorata);

                                        if (!string.IsNullOrEmpty(datiSupplemento.DataDecSupplemento))
                                            supplemento.Decorrenza = Utility.DataFromString(datiSupplemento.DataDecSupplemento, Utility.FormatoData.GGmmAAAA);

                                        supplemento.Settimane = datiSupplemento.TotSettDiritto;
                                        supplemento.TipoVariazione = datiSupplemento.TipoVariazione;

                                        listaDatiSupplementiCumuloTotalIVS.Add(supplemento);
                                    }
                                }
                            }
                        }

                        if (risposta.objDatiMiglioramenti != null)
                        {
                            datiMiglioramentiContrattuali = new GestioneMiglioramentiContrattuali.DatiMiglioramentiContrattuali();
                            datiMiglioramentiContrattuali.CodiceCessazione = risposta.objDatiMiglioramenti.CodiceCessazione;
                            datiMiglioramentiContrattuali.MotivoCessazione = risposta.objDatiMiglioramenti.MotivoCessazione;
                            datiMiglioramentiContrattuali.CodiceEnte = risposta.objDatiMiglioramenti.CodiceEnte;

                            if (risposta.objDatiMiglioramenti.objQuoteMiglioramenti != null)
                            {
                                listaDatiQuoteMiglioramentiContrattuali = new List<GestioneMiglioramentiContrattuali.DatiQuoteMiglioramentiContrattuali>();
                                isQuoteMiglioramentiContrattualiVisible = true;
                                foreach (var quota in risposta.objDatiMiglioramenti.objQuoteMiglioramenti)
                                {
                                    GestioneMiglioramentiContrattuali.DatiQuoteMiglioramentiContrattuali datiQuoteMiglioramentiContrattuali = new GestioneMiglioramentiContrattuali.DatiQuoteMiglioramentiContrattuali();
                                    datiQuoteMiglioramentiContrattuali.Codice = quota.Codice;
                                    datiQuoteMiglioramentiContrattuali.DataDecorrenza = quota.DataDecorrenza;
                                    datiQuoteMiglioramentiContrattuali.Quota = quota.Quota;
                                    listaDatiQuoteMiglioramentiContrattuali.Add(datiQuoteMiglioramentiContrattuali);
                                }
                            }
                        }
                    }

                    if (!Utility.IsRicostituzione(datiPensione.Gruppo) && TipoSalvaguardia != Utility.TipoSalvaguardia.Nessuna)
                    {
                        int categoriaWebDom = 0;
                        string categoriaWebDomString = datiPensione.GetCodCategoria();
                        int.TryParse(categoriaWebDomString, out categoriaWebDom);

                        ServiceReferences.AggPec.csAggiornamentoPECO_AGO dati = null;
                        if (!GestioneAggiornamentoPECO.GetCertificazione_AGO(tipoAppartenenza, codiceFiscale, datiPensione.NDomus.ToString(), ref dati, ref errori))
                            throw new INPS.DNA.DnaValidationException(errori);

                        if (dati == null)
                        {
                            if (Utility.IsDomandaAPEPrecoci(datiPensione))
                            {
                                errori = "Nessuna Certificazione Presente o Certificazione non valida per la domanda che si sta tentando di acquisire";
                                throw new INPS.DNA.DnaValidationException(errori);
                            }
                        }
                        else
                        {
                            datiPensione.FlagUnicarpe = true;
                            datiPensione.TipoLetturaUnicarpe = !String.IsNullOrEmpty(dati.PL_Funzione) ? Convert.ToChar(dati.PL_Funzione) : (char?)null;

                            //ENG - Memo 06_2024
                            if (controlloDinamicoAbilitazioneMemo06_2024 != null && !String.IsNullOrEmpty(controlloDinamicoAbilitazioneMemo06_2024.ValoreControllo) &&
                                controlloDinamicoAbilitazioneMemo06_2024.ValoreControllo.ToUpperInvariant() == "SI")
                            {
                                datiPensione.CodProPE = dati.PL_CodProPE;
                            }

                            #region Istruttoria

                            if (datiIstruttoria == null)
                                datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                            if (!string.IsNullOrEmpty(dati.PL_Deroga))
                            {
                                string categoriaNumerica = datiPensione.GetCodCategoria();

                                List<GestioneDecodifica.CodiceParticolare> listaCodiciParticolari = null;
                                GestioneDecodifica.GetCodiciParticolari(out listaCodiciParticolari);
                                if (listaCodiciParticolari != null && listaCodiciParticolari.Count > 0)
                                {
                                    char derogaOutput;
                                    char? deroga;
                                    char.TryParse(dati.PL_Deroga, out derogaOutput);
                                    if (derogaOutput == ' ' || derogaOutput == '\0' || derogaOutput == '0')
                                        deroga = null;
                                    else
                                        deroga = derogaOutput;
                                    GestioneDecodifica.CodiceParticolare codiceParticolare = listaCodiciParticolari.Find(x => x.TraduzioneSuGp == deroga && x.CodCategoria == categoriaNumerica);
                                    if (codiceParticolare != null)
                                    {
                                        datiIstruttoria.CodiceParticolareSoggettoDerogato = codiceParticolare.Id;
                                        bSaveIstruttoria = true;
                                    }
                                }
                            }

                            if (!bSaveIstruttoria)
                                datiIstruttoria = null;

                            #endregion Istruttoria

                            #region MaggiorazioneBenefici

                            if (datiPensione.Amianto181Unicarpe.GetValueOrDefault())
                            {
                                if (dati.aONERI != null && dati.aONERI.Length > 0)
                                {
                                    for (int i = 0; i < dati.aONERI.Length; i++)
                                    {
                                        // Beneficio Amianto 181
                                        if (dati.aONERI[i].PL_CodGrup == "2000" && dati.aONERI[i].PL_CodSGrup == "2010")
                                        {
                                            if (datiMaggiorazioniBenefici == null)
                                            {
                                                datiMaggiorazioniBenefici = new BLCommon.GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();
                                                datiMaggiorazioniBenefici.IdPensione = datiPensione.Id;
                                            }

                                            datiMaggiorazioniBenefici.NSettimaneBeneficio = dati.aONERI[i].PL_AnzCon;
                                            isBeneficioAmianto181Present = true;
                                            break;
                                        }
                                    }
                                }

                                if (!isBeneficioAmianto181Present)
                                {
                                    errori = "Oneri Amianto cod.181 non provenienti da Unicarpe.";
                                    return;
                                }
                            }
                            else
                            {
                                if (dati.aONERI != null && dati.aONERI.Length > 0 && dati.aONERI.ToList().Exists(x => x.PL_CodGrup == "2000" && x.PL_CodSGrup == "2010"))
                                {
                                    errori = "Oneri Amianto cod.181 incompatibili con attività economica e professione individuale provenienti da Unicarpe.";
                                    return;
                                }
                            }

                            if (dati.aONERI != null && dati.aONERI.Length > 0)
                            {
                                foreach (ServiceReferences.AggPec.ONERI oneri in dati.aONERI)
                                {
                                    if (oneri.PL_CodBenef == "10")
                                    {
                                        if (datiMaggiorazioniBenefici == null)
                                            datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                        datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.PL_CodBenef;
                                        datiMaggiorazioniBenefici.IsBeneficioArt24Comma15BisFromFELPE = true;

                                        datiPensione.Benefici = true;
                                    }
                                    else if (oneri.PL_CodBenef == "11")
                                    {
                                        if (datiMaggiorazioniBenefici == null)
                                            datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                        datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.PL_CodBenef;
                                        datiMaggiorazioniBenefici.IsBeneficioApePrecociFromFELPE = true;

                                        datiPensione.Benefici = true;
                                    }
                                }
                            }

                            #endregion MaggiorazioneBenefici
                        }

                        datiAGGPECO = dati;
                    }

                    bool ByPassCumuloManuale = false;
                    if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
                    {
                        GestioneControlliDinamici.ControlloDinamico Abilita_MANUALE_CUMUL_MEMO_79_2025 = null;
                        GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("Abilita_MANUALE_CUMUL_MEMO_79_2025", out Abilita_MANUALE_CUMUL_MEMO_79_2025);
                        if (Abilita_MANUALE_CUMUL_MEMO_79_2025 != null && !String.IsNullOrEmpty(Abilita_MANUALE_CUMUL_MEMO_79_2025.ValoreControllo) && Abilita_MANUALE_CUMUL_MEMO_79_2025.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                        {
                            ByPassCumuloManuale = true;
                        }
                    }

                    if (!ByPassCumuloManuale)
                    {
                        if ((ConfigurationManager.AppSettings["BypassControlliSviluppo"] == null ||
                                ConfigurationManager.AppSettings["BypassControlliSviluppo"] != "SI") &&
                                !datiPensione.IsCumuloAutomatica.GetValueOrDefault() && !datiPensione.FlagUnicarpe.GetValueOrDefault() &&
                                Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && !Utility.IsRicostituzione(datiPensione.Gruppo))
                        {
                            throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda manuale in Cumulo");
                        }
                    }

                    if (datiPensione.IsCumuloAutomatica.GetValueOrDefault())
                    {
                        if ((Utility.IsDomandaQuota100(datiPensione) || Utility.IsDomandaQuota102(datiPensione) || Utility.IsDomandaAnticipataFlessibile(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)) &&
                            !Utility.IsDomandaSupplementoCumulo(datiPensione) && (datiPensioniDatiGenerici == null || !datiPensioniDatiGenerici.TipoCumulo.HasValue || !datiPensioniDatiGenerici.TipoCumulo.GetValueOrDefault()))
                        {
                            if (Utility.IsDomandaQuota102(datiPensione))
                                throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda automatica di Quota 102 con tipo cumulo diverso da INTERNO");
                            else if (Utility.IsDomandaAnticipataFlessibile(datiPensione))
                                throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda automatica Anticipata Flessibile con tipo cumulo diverso da INTERNO");
                            else if (Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione))
                                throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda automatica Anticipata Flessibile Opzione Contributivo con tipo cumulo diverso da INTERNO");
                            else if (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione))
                                throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda automatica Anticipata Flessibile legge di bilancio 2024 con tipo cumulo diverso da INTERNO");
                            else if (Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))
                                throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda automatica Anticipata Flessibile Opzione Contributivo legge di bilancio 2024 con tipo cumulo diverso da INTERNO");
                            else
                                throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda automatica di Quota 100 con tipo cumulo diverso da INTERNO");
                        }

                        if (datiPensioniDatiGenerici != null && datiPensioniDatiGenerici.TipoCumulo.HasValue)
                        {
                            if (ctrlAbilitazioneMemo93 != null && !String.IsNullOrEmpty(ctrlAbilitazioneMemo93.ValoreControllo) && ctrlAbilitazioneMemo93.ValoreControllo.ToUpperInvariant().Trim() == "SI")
                            {
                                if (datiPensioniDatiGenerici.TipoCumulo.Value && risposta.objDatiContributivi.Select(x => { short ret = 0; short.TryParse(x.CodiceFondo, out ret); return ret; }).ToList().Exists(x => x > 718 && x <= 737 || x == 988))
                                    throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda automatica con tipo cumulo INTERNO se sono presenti casse esterne.");
                                else if (!datiPensioniDatiGenerici.TipoCumulo.Value && !risposta.objDatiContributivi.Select(x => { short ret = 0; short.TryParse(x.CodiceFondo, out ret); return ret; }).ToList().Exists(x => x > 718 && x <= 737 || x == 988 || x == 971))
                                    throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda automatica con tipo cumulo ESTERNO se non sono presenti casse esterne.");
                            }
                            else
                            {
                                if (datiPensioniDatiGenerici.TipoCumulo.Value && risposta.objDatiContributivi.Select(x => { short ret = 0; short.TryParse(x.CodiceFondo, out ret); return ret; }).ToList().Exists(x => x >= 718 && x <= 737 || x == 988))
                                    throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda automatica con tipo cumulo INTERNO se sono presenti casse esterne.");
                                else if (!datiPensioniDatiGenerici.TipoCumulo.Value && !risposta.objDatiContributivi.Select(x => { short ret = 0; short.TryParse(x.CodiceFondo, out ret); return ret; }).ToList().Exists(x => x >= 718 && x <= 737 || x == 988 || x == 971))
                                    throw new INPS.DNA.DnaValidationException("Non è possibile acquisire una domanda automatica con tipo cumulo ESTERNO se non sono presenti casse esterne.");
                            }
                        }
                    }
                }

                ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiPensioniDatiGenerici != null && prelievoAgo.Risposta.DatiPensioniDatiGenerici.TipologiaCumulo != null)
                {
                    if (datiPensioniDatiGenerici == null)
                        datiPensioniDatiGenerici = new GestioneDatiGenericiAgoCi.PensioniDatiGenerici();
                    datiPensioniDatiGenerici.TipologiaCumulo = prelievoAgo.Risposta.DatiPensioniDatiGenerici.TipologiaCumulo;
                }
                else
                {
                    if (datiPensioniDatiGenerici == null)
                        datiPensioniDatiGenerici = new GestioneDatiGenericiAgoCi.PensioniDatiGenerici();

                    if (datiPensione.Gestione == "202")
                        datiPensioniDatiGenerici.TipologiaCumulo = 'A';
                    else if (datiPensione.Gestione == "203")
                        datiPensioniDatiGenerici.TipologiaCumulo = 'B';
                }
            }
            #endregion Cumulo

            else if (Utility.IsDomandaTotalizzazione(datiPensione.SiglaCategoria))
            {
                ServiceReferences.TotalIvs.clsDati risposta = null;
                if (!GestioneTotalIvs.GetDatiTotalIVS(datiPensione.NDomus, out risposta, out errori))
                    throw new INPS.DNA.DnaValidationException(errori);

                if (risposta != null)
                {
                    datiPensione.IsTotAutomatica = true;
                    if (Utility.IsRicostituzione(datiPensione.Gruppo))
                        isStoricoVisible = true;

                    if (risposta.objDomanda != null)
                    {
                        #region Pensione
                        if (!string.IsNullOrEmpty(risposta.objDomanda.Decorrenza))
                            datiPensione.DecorrenzaOriginaria = Utility.DataFromString(risposta.objDomanda.Decorrenza, Utility.FormatoData.AAAAmm);

                        if (!string.IsNullOrEmpty(risposta.objDomanda.DataPerfReq))
                            datiPensione.DataPerfezionamentoRequisiti = Utility.DataFromString(risposta.objDomanda.DataPerfReq, Utility.FormatoData.GGmmAAAA);

                        if (risposta.objDomanda.SistemaCalcolo == "1")
                            datiPensione.Contributivo = '8';
                        else if (risposta.objDomanda.SistemaCalcolo == "2")
                            datiPensione.Contributivo = '2';

                        if (!string.IsNullOrEmpty(risposta.objDomanda.DataIniAss))
                            datiPensione.InizioAssicurazione = Utility.DataFromString(risposta.objDomanda.DataIniAss, Utility.FormatoData.GGmmAAAA);

                        if (!string.IsNullOrEmpty(risposta.objDomanda.DataFineAss))
                            datiPensione.FineAssicurazione = Utility.DataFromString(risposta.objDomanda.DataFineAss, Utility.FormatoData.GGmmAAAA);

                        if (risposta.objDomanda.CodiceNatura == "S" || risposta.objDomanda.CodiceNatura == "Z")
                        {
                            if (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Length == 3)
                                datiPensione.NaturaPensione = datiPensione.NaturaPensione.Substring(0, 2) + "S";
                            else
                                datiPensione.NaturaPensione = "  S";
                        }
                        #endregion Pensione

                        #region Sindacato

                        if (!string.IsNullOrEmpty(risposta.objDomanda.Sindacato))
                        {
                            datiSindacato = new GestionePensione.DatiSindacato();
                            datiSindacato.CodiceSindacato = risposta.objDomanda.Sindacato;
                            //TODO: Verificare se è necessario recuperare in qualche modo la decorrenza sindacato e/o la cessazione sindacato
                        }

                        #endregion Sindacato

                        #region StatoCivile

                        if (!string.IsNullOrEmpty(risposta.objDomanda.StatoCivile) && !string.IsNullOrEmpty(risposta.objDomanda.Decorrenza))
                        {
                            // Considero solo gli stati civili censiti su IVS
                            if (new List<string> { "1", "2", "3", "4", "5", "7", "8", "C" }.Contains(risposta.objDomanda.StatoCivile))
                            {
                                if (listaDatiStatoCivile == null)
                                    listaDatiStatoCivile = new List<GestioneAnagrafica.DatiStatoCivile>();

                                GestioneAnagrafica.DatiStatoCivile statoCivile = new GestioneAnagrafica.DatiStatoCivile();
                                statoCivile.Decorrenza = Utility.DataFromString(risposta.objDomanda.Decorrenza, Utility.FormatoData.AAAAmm);
                                statoCivile.Codice = risposta.objDomanda.StatoCivile[0];

                                listaDatiStatoCivile.Add(statoCivile);
                            }
                        }

                        #endregion StatoCivile

                        #region PensioniDatiGenerici

                        if (datiPensioniDatiGenerici == null)
                            datiPensioniDatiGenerici = new GestioneDatiGenericiAgoCi.PensioniDatiGenerici();

                        if (!string.IsNullOrEmpty(risposta.objDomanda.EnteIstruttoria) && !string.IsNullOrEmpty(risposta.objDomanda.EnteIstruttoria.Trim()))
                        {
                            List<GestioneDecodifica.DecodificaEnteCassaProfessionale> elencoDecodificaEnteCassaProfessionale = null;
                            GestioneDecodifica.GetDecodificaEnteCassaProfessionale(out elencoDecodificaEnteCassaProfessionale);
                            if (elencoDecodificaEnteCassaProfessionale != null && elencoDecodificaEnteCassaProfessionale.Count > 0)
                            {
                                GestioneDecodifica.DecodificaEnteCassaProfessionale decodifica = elencoDecodificaEnteCassaProfessionale.Find(x => x.TraduzioneSuGP == risposta.objDomanda.EnteIstruttoria.PadLeft(4, '0'));
                                if (decodifica != null)
                                    datiPensioniDatiGenerici.EnteCassa = decodifica.Id;
                            }
                        }

                        #endregion PensioniDatiGenerici

                        #region Istruttoria
                        if (!string.IsNullOrEmpty(risposta.objDomanda.TotSettDiritto))
                        {
                            if (datiIstruttoria == null)
                                datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                            datiIstruttoria.NSettimaneOBG = Utility.StringToNullableInt(risposta.objDomanda.TotSettDiritto);
                        }
                        #endregion Istruttoria

                    }

                    if (risposta.objPagamento != null)
                    {
                        #region Pagamento
                        GestionePagamento.DatiPagamento datiPagamentoApp = null;
                        RecuperaModPagamentoFromTotalPerTotIVS(risposta.objPagamento, out datiPagamentoApp);

                        if (datiPagamentoApp != null)
                            datiPagamento = datiPagamentoApp;
                        #endregion Pagamento
                    }

                    if (risposta.objDatiContributivi != null && risposta.objDatiContributivi.Length > 0)
                    {
                        List<GestioneDecodifica.DecEnteGestioneFondo> listaDecEnteGestioneFondo = null;
                        GestioneDecodifica.GetDecEnteGestioneFondo(out listaDecEnteGestioneFondo);

                        #region Quote Pensione
                        listaDatiQuotePensioneTotalIVS = new List<GestioneCalcolo.QuotePensione>();
                        foreach (ServiceReferences.TotalIvs.clsDatiContributivi datiContributivi in risposta.objDatiContributivi)
                        {
                            // Verifico che siano presenti i dati nel record
                            if (datiContributivi != new ServiceReferences.TotalIvs.clsDatiContributivi())
                            {
                                GestioneCalcolo.QuotePensione quotePensione = new GestioneCalcolo.QuotePensione();

                                GestioneDecodifica.DecEnteGestioneFondo decEnteGestioneFondo = listaDecEnteGestioneFondo.Find(x => x.Codice == datiContributivi.EnteFondo);
                                if (decEnteGestioneFondo != null)
                                    quotePensione.EnteGestioneFondo = decEnteGestioneFondo.Id;
                                else
                                    throw new INPS.DNA.DnaValidationException(string.Format("Il codice {0} non è censito nell'applicazione.", datiContributivi.EnteFondo));

                                if (!string.IsNullOrEmpty(datiContributivi.SettimaneMisura))
                                    quotePensione.Settimane = Utility.StringToNullableInt(datiContributivi.SettimaneMisura);

                                if (!string.IsNullOrEmpty(datiContributivi.ImpQuotaEnte))
                                    quotePensione.Importo = Utility.StringToNullableDecimal(datiContributivi.ImpQuotaEnte);

                                if (GestioneCtrlControlliApplicativi.CheckControlloApplicativoAttivoByData(GestioneCtrlControlliApplicativi.EnumNomeControllo.AGO.SCARICO_TRATTENUTE_CUMULO, dataSistema) &&
                                        datiContributivi.objDatiTrattenute != null && datiContributivi.objDatiTrattenute.Count() > 0)
                                {
                                    if (listaDatiTrattenuteQuotePensioneTotalIVS == null)
                                        listaDatiTrattenuteQuotePensioneTotalIVS = new List<GestioneCalcolo.TrattenuteQuotePensione>();
                                    foreach (ServiceReferences.TotalIvs.clsDatiTrattenute datiTrattenute in datiContributivi.objDatiTrattenute)
                                    {
                                        if (datiTrattenute != new ServiceReferences.TotalIvs.clsDatiTrattenute())
                                        {
                                            GestioneCalcolo.TrattenuteQuotePensione trattenute = new GestioneCalcolo.TrattenuteQuotePensione();
                                            trattenute.EnteGestioneFondoQuote = decEnteGestioneFondo.Id;
                                            short? annoCompetenza = Utility.StringToNullableShort(datiTrattenute.AnnoCompetenza);
                                            trattenute.AnnoCompetenza = annoCompetenza.GetValueOrDefault();
                                            trattenute.CodiceTrattenute = datiTrattenute.CodTrattenuta;
                                            if (!string.IsNullOrEmpty(datiTrattenute.ImpTrattEnte))
                                            {
                                                decimal? importo = Utility.StringToNullableDecimal(datiTrattenute.ImpTrattEnte);
                                                trattenute.ImportoTrattenute = importo.GetValueOrDefault();
                                            }
                                            listaDatiTrattenuteQuotePensioneTotalIVS.Add(trattenute);
                                        }
                                    }
                                }
                                listaDatiQuotePensioneTotalIVS.Add(quotePensione);
                            }

                        #endregion Quote Pensione
                        }

                    }
                }
                else if (risposta == null && (ConfigurationManager.AppSettings["BypassControlliSviluppo"] == null ||
                         ConfigurationManager.AppSettings["BypassControlliSviluppo"] != "SI") && Utility.IsDomandaVOTOT(datiPensione.SiglaCategoria) && !(Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione || isRiapertura))
                {
                    throw new INPS.DNA.DnaValidationException("Lavorare la domanda su procedura TOTAL.");
                }
            }
            else
            {
                int categoriaWebDom = 0;
                string categoriaWebDomString = datiPensione.GetCodCategoria();
                int categoriaFelpe = 0;
                int.TryParse(categoriaWebDomString, out categoriaWebDom);
                switch (tipoAppartenenza)
                {
                    #region  PECO_FS
                    case Utility.TipoAppartenenza.FS:

                        errori = string.Empty;
                        ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_Speciali datiFS = null;

                        // la chiamata a Felpe va fatta solo per domande non di ricostituzione e per  ricostituzioni per motivi contributivi
                        if (Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) != Utility.TipoDomanda.Ricostituzione || (Utility.IsRicostituzione_MotiviContributivi(datiPensione) && !Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione)))
                            if (!GestioneAggiornamentoPECO.GetDatiPECO_FS(datiPensione, codiceFiscale, TipoSalvaguardia, isRiapertura, ref datiFS, out errori))
                                throw new INPS.DNA.DnaValidationException(errori);

                        if (datiFS != null)
                        {
                            if (tipoFondo.HasValue && listaTipoFondo_PECO_Fondi_AMG.Contains(tipoFondo.Value) && (datiFS.F_Funzione == "L" || datiFS.F_Funzione == "H" || datiFS.F_Funzione == "G"))
                                throw new INPS.DNA.DnaValidationException(string.Format("Non è possibile acquisire domande automatiche della categoria {0}", datiPensione.SiglaCategoria));

                            int.TryParse(datiFS.F_Categoria, out categoriaFelpe);

                            Utility.TipoUnicarpe ctrlUnicarpe = Utility.IsDomandaUnicarpe(true, Utility.StringToNullableChar(datiFS.F_Funzione), true);
                            if (categoriaFelpe != categoriaWebDom && ctrlUnicarpe == Utility.TipoUnicarpe.Automatica)
                            {
                                throw new INPS.DNA.DnaValidationException("Categoria incongruente tra Unicarpe (" + categoriaFelpe + ") e WebDom ( " + categoriaWebDom + ").");
                            }

                            // Per le ricostituzioni e le trasformazioni da provvisoria il valore di CODPROV deve essere spazio
                            if (Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione || isRiapertura)
                                if (!string.IsNullOrEmpty(datiFS.F_Codprov) && !string.IsNullOrEmpty(datiFS.F_Codprov.Trim()))
                                    throw new INPS.DNA.DnaValidationException("Domanda proveniente da Unicarpe non acquisibile per codice provvisorietà impostato.");

                            #region Storico
                            switch (tipoFondo)
                            {
                                case Utility.TipoFondo.TT:
                                case Utility.TipoFondo.EL:
                                case Utility.TipoFondo.ET:
                                case Utility.TipoFondo.VL:
                                    if ((Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione || isRiapertura) && prelievo != null)
                                    {
                                        isStoricoVisible = true;
                                    }
                                    break;
                            }


                            #endregion Storico

                            datiPensione.FlagUnicarpe = true;
                            datiPensione.TipoLetturaUnicarpe = !String.IsNullOrEmpty(datiFS.F_Funzione) ? Convert.ToChar(datiFS.F_Funzione) : (char?)null;

                            //ENG - Memo 06_2024
                            if (controlloDinamicoAbilitazioneMemo06_2024 != null && !String.IsNullOrEmpty(controlloDinamicoAbilitazioneMemo06_2024.ValoreControllo) &&
                                controlloDinamicoAbilitazioneMemo06_2024.ValoreControllo.ToUpperInvariant() == "SI")
                            {
                                datiPensione.CodProPE = datiFS.F_CodProPE;
                            }

                            #region Pensione

                            // solo per funzione di lettura = "L", "H" o "G"
                            if (!String.IsNullOrEmpty(datiFS.F_Funzione) && (datiFS.F_Funzione == "L" || datiFS.F_Funzione == "H" || datiFS.F_Funzione == "G"))
                            {
                                if (!String.IsNullOrEmpty(datiFS.F_Decorre) && datiFS.F_Decorre.Trim().Length == 8)
                                    datiPensione.DecorrenzaOriginaria = Utility.DataFromString(datiFS.F_Decorre, Utility.FormatoData.AAAAmmGG);
                                else if (!String.IsNullOrEmpty(datiFS.F_Decorre.Trim()))
                                    datiPensione.DecorrenzaOriginaria = Utility.DataFromInt(short.Parse(datiFS.F_Decorre.Substring(0, 4)),
                                                                                     short.Parse(datiFS.F_Decorre.Substring(4, 2)), 1);

                                if (datiFS.F_Iniass.ToString().Length == 8)
                                    datiPensione.InizioAssicurazione = Utility.DataFromString(datiFS.F_Iniass.ToString(), Utility.FormatoData.AAAAmmGG);
                                else
                                    datiPensione.InizioAssicurazione = datiFS.F_Iniass != 0 ? Utility.DataFromInt(short.Parse(datiFS.F_Iniass.ToString().Substring(0, 4)),
                                                                                                            short.Parse(datiFS.F_Iniass.ToString().Substring(4, 2)), 1) : null;

                                if (datiFS.F_Finass.ToString().Length == 8)
                                    datiPensione.FineAssicurazione = Utility.DataFromString(datiFS.F_Finass.ToString(), Utility.FormatoData.AAAAmmGG);
                                else
                                    datiPensione.FineAssicurazione = datiFS.F_Finass != 0 ? Utility.DataFromInt(short.Parse(datiFS.F_Finass.ToString().Substring(0, 4)),
                                                                                                            short.Parse(datiFS.F_Finass.ToString().Substring(4, 2)), 1) : null;

                                if (!String.IsNullOrEmpty(datiFS.F_Datreq) && datiFS.F_Datreq.Trim() != string.Empty)
                                {
                                    if (datiFS.F_Datreq.Trim().Length == 8)
                                        datiPensione.DataPerfezionamentoRequisiti = datiPensione.DataPerfezionamentoRequisitiUnicarpe = Utility.DataFromString(datiFS.F_Datreq, Utility.FormatoData.AAAAmmGG);
                                    else
                                        datiPensione.DataPerfezionamentoRequisiti = datiPensione.DataPerfezionamentoRequisitiUnicarpe = Utility.DataFromInt(short.Parse(datiFS.F_Datreq.Substring(0, 4)), short.Parse(datiFS.F_Datreq.Substring(4, 2)), 1);
                                }

                                if (Utility.IsGestioneLavoratriciMadri(datiPensione))
                                {
                                    datiPensione.NumeroFigli = datiFS.F_NumFigli == 0 ? (byte?)null : byte.Parse(datiFS.F_NumFigli.ToString());
                                    datiPensione.SceltaLavMadri = datiFS.F_SceltaLM == 0 ? (byte?)null : byte.Parse(datiFS.F_SceltaLM.ToString());
                                    if (Utility.IsDomandaTipoContributivo(datiPensione, null, null))
                                    {
                                        if (!String.IsNullOrEmpty(datiFS.F_DatOPZ) && datiFS.F_DatOPZ.Trim() != string.Empty)
                                        {
                                            if (datiFS.F_DatOPZ.Trim().Length == 8)
                                                datiPensione.DataOpzione = Utility.DataFromString(datiFS.F_DatOPZ, Utility.FormatoData.AAAAmmGG);
                                            else
                                                datiPensione.DataOpzione = Utility.DataFromInt(short.Parse(datiFS.F_DatOPZ.Substring(0, 4)), short.Parse(datiFS.F_DatOPZ.Substring(4, 2)), 1);
                                        }
                                    }
                                }
                                else
                                    numeroFigliOpzioneDonna = datiFS.F_NumFigli == 0 ? (byte?)null : byte.Parse(datiFS.F_NumFigli.ToString());
                            }
                            else if (!String.IsNullOrEmpty(datiFS.F_Funzione) && datiFS.F_Funzione == "C" && Utility.IsDomandaTipoContributivo(datiPensione, null, null))
                            {
                                if (!String.IsNullOrEmpty(datiFS.F_Datreq) && datiFS.F_Datreq.Trim() != string.Empty)
                                {
                                    if (datiFS.F_Datreq.Trim().Length == 8)
                                        datiPensione.DataRaggiungimentoOpzione = Utility.DataFromString(datiFS.F_Datreq, Utility.FormatoData.AAAAmmGG);
                                    else
                                        datiPensione.DataRaggiungimentoOpzione = Utility.DataFromInt(short.Parse(datiFS.F_Datreq.Substring(0, 4)), short.Parse(datiFS.F_Datreq.Substring(4, 2)), 1);
                                }
                                if (!String.IsNullOrEmpty(datiFS.F_DatOPZ) && datiFS.F_DatOPZ.Trim() != string.Empty)
                                {
                                    if (datiFS.F_DatOPZ.Trim().Length == 8)
                                        datiPensione.DataOpzione = Utility.DataFromString(datiFS.F_DatOPZ, Utility.FormatoData.AAAAmmGG);
                                    else
                                        datiPensione.DataOpzione = Utility.DataFromInt(short.Parse(datiFS.F_DatOPZ.Substring(0, 4)), short.Parse(datiFS.F_DatOPZ.Substring(4, 2)), 1);
                                }
                            }

                            ArrayList datiArrayFS = new ArrayList();
                            datiArrayFS.Add(datiFS.aCONTRIBUTIVE_FS[0].F_Contrib);   // 0
                            datiArrayFS.Add(datiFS.aCONTRIBUTIVE_FS[0].F_Montante);  // 1
                            datiArrayFS.Add(datiFS.aCONTRIBUTIVE_FS[0].F_Anzconc);   // 2
                            datiArrayFS.Add(datiFS.aCONTRIBUTIVE_FS[0].F_AnzAA);     // 3
                            datiArrayFS.Add(datiFS.aCONTRIBUTIVE_FS[0].F_AnzGG);     // 4
                            datiArrayFS.Add(datiFS.aCONTRIBUTIVE_FS[0].F_AnzMM);     // 5
                            datiArrayFS.Add(datiFS.aCONTRIBUTIVE_FS[0].F_MonteSCL);  // 6
                            datiArrayFS.Add(datiFS.aCONTRIBUTIVE_FS[0].F_SetteSCL);  // 7 

                            datiArrayFS.Add(datiFS.aRETRIBUTIVE_FS[0].F_Rms);        // 8
                            datiArrayFS.Add(datiFS.aRETRIBUTIVE_FS[0].F_Anzconr);    // 9
                            datiArrayFS.Add(datiFS.aRETRIBUTIVE_FS[0].F_CodQuota);   // 10
                            datiArrayFS.Add(datiPensione.DecorrenzaOriginaria);      // 11
                            datiArrayFS.Add(datiFS.F_Sistcal);                       // 12

                            datiPensione.TipoCalcolo = GetTipoCalcoloFromData(tipoAppartenenza, datiArrayFS, datiPensione);

                            if (datiPensione.FlagUnicarpe.HasValue && datiPensione.FlagUnicarpe.Value && datiPensione.TipoCalcolo == 18 &&
                                datiPensione.DecorrenzaOriginaria.HasValue && Utility.DataSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2012, 02, 01)) &&
                                datiPensione.Gruppo.Equals("0002") && datiPensione.Prodotto.Equals("0012"))
                            {
                                switch (tipoFondo)
                                {
                                    case Utility.TipoFondo.EL:
                                    case Utility.TipoFondo.TT:
                                    case Utility.TipoFondo.ET:
                                    case Utility.TipoFondo.VL:
                                        datiPensione.TipoCalcolo = 25;
                                        break;
                                }
                            }

                            if (datiFS.aONERI_FS != null)
                            {
                                if (datiFS.aONERI_FS.Any(x => (x.F_CodGrup == "5300" && x.F_CodSGrup == "5302") || (x.F_CodGrup == "5800" && x.F_CodSGrup == "5802") || (x.F_CodGrup == "6000" && x.F_CodSGrup == "6002") || (x.F_CodGrup == "6100" && x.F_CodSGrup == "6102")))
                                    datiPensione.LavoratorePubblico = true;
                                else if (datiFS.aONERI_FS.Any(x => (x.F_CodGrup == "5300" && x.F_CodSGrup == "5301") || (x.F_CodGrup == "5800" && x.F_CodSGrup == "5801") || (x.F_CodGrup == "6000" && x.F_CodSGrup == "6001") || (x.F_CodGrup == "6100" && x.F_CodSGrup == "6101")))
                                    datiPensione.LavoratorePubblico = false;
                            }

                            if (datiFS.F_SceltaLM != 0)
                            {
                                datiPensione.Benefici = true;
                            }

                            GestioneControlliDinamici.ControlloDinamico AbilitazioneMemo_74_88_2025_FS = null;
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo_74_88_2025_FS", out AbilitazioneMemo_74_88_2025_FS);
                            if (AbilitazioneMemo_74_88_2025_FS != null && !String.IsNullOrEmpty(AbilitazioneMemo_74_88_2025_FS.ValoreControllo) && AbilitazioneMemo_74_88_2025_FS.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                            {
                                if (datiFS.F_TipCert.Trim() == "POS" || (datiFS.F_TipoSpec.Trim() == "C" || datiFS.F_TipoSpec.Trim() == "D"))
                                {
                                    string CaratterizzazioneToInsert = Utility.InserisciValoreCaratterizzazione(datiPensione.Caratterizzazione, '1', 3);
                                    datiPensione.Caratterizzazione = CaratterizzazioneToInsert;
                                }
                            }


                            #endregion Pensione

                            #region PensioneFondoDatiGenerici

                            bool bFondo = false;
                            datiPensioneFondoDatiGenerici = new GestioneFondo.DatiFondo();

                            // solo per funzione di lettura = "L", "H" o "G"
                            if (!String.IsNullOrEmpty(datiFS.F_Funzione) && (datiFS.F_Funzione == "L" || datiFS.F_Funzione == "H" || datiFS.F_Funzione == "G"))
                            {
                                if (!String.IsNullOrEmpty(datiPensione.Gruppo) && datiPensione.Gruppo.Trim() == "0001" && !String.IsNullOrEmpty(datiPensione.Prodotto) && datiPensione.Prodotto.Trim() == "0001")
                                {
                                    datiPensioneFondoDatiGenerici.RiduzioneRetributiva = !String.IsNullOrEmpty(datiFS.F_FLAGRIDUZ) && !String.IsNullOrEmpty(datiFS.F_FLAGRIDUZ.Trim()) && datiFS.F_FLAGRIDUZ.Trim().ToUpperInvariant() == "S" ? true : false;
                                    datiPensioneFondoDatiGenerici.RiduzioneRetributivaPercentuale = !Utility.IsDoubleEquals(datiFS.F_PERCRIDUZ, 0.0) ? Convert.ToDecimal(datiFS.F_PERCRIDUZ) : (decimal?)null;
                                }
                            }

                            if (datiFS.F_Anzcont != 0)
                            {
                                switch (tipoFondo)
                                {
                                    case Utility.TipoFondo.EL:
                                    case Utility.TipoFondo.TT:
                                    case Utility.TipoFondo.ET:
                                    case Utility.TipoFondo.VL:
                                        datiPensioneFondoDatiGenerici.SettimaneUtiliDiritto = datiFS.F_Anzcont;
                                        break;
                                }
                            }

                            if (datiPensioneFondoDatiGenerici.RiduzioneRetributiva || datiPensioneFondoDatiGenerici.RiduzioneRetributivaPercentuale.HasValue ||
                                datiPensioneFondoDatiGenerici.SettimaneUtiliDiritto.HasValue)
                                bFondo = true;

                            if (!bFondo)
                                datiPensioneFondoDatiGenerici = null;

                            #endregion PensioneFondoDatiGenerici

                            #region Fondo Specifico

                            switch (tipoFondo)
                            {
                                #region Fondo TT
                                case Utility.TipoFondo.TT:
                                    bool bFondoTT = false;
                                    // solo per funzione di lettura = "L", "H" o "G"
                                    if (!String.IsNullOrEmpty(datiFS.F_Funzione) && (datiFS.F_Funzione == "L" || datiFS.F_Funzione == "H" || datiFS.F_Funzione == "G"))
                                    {
                                        datiFondoSpecificoFELPE = new Entity.DatiFondoSpecificoFELPE();
                                        datiFondoSpecificoFELPE.DatiFondoTT = new GestioneFondo.DatiFondoTT();
                                        if (!Utility.IsDoubleEquals(datiFS.F_Retrultanno, 0.0))
                                        {
                                            datiFondoSpecificoFELPE.DatiFondoTT.RetribuzioneUltimoAnnoQuotaA = Convert.ToDecimal(datiFS.F_Retrultanno);
                                            bFondoTT = true;
                                        }

                                        if (!Utility.IsDoubleEquals(datiFS.F_Retrbiennio, 0.0))
                                        {
                                            datiFondoSpecificoFELPE.DatiFondoTT.RetribuzioneBiennio = Convert.ToDecimal(datiFS.F_Retrbiennio);
                                            bFondoTT = true;
                                        }

                                        if (!bFondoTT)
                                            datiFondoSpecificoFELPE = null;
                                    }
                                    break;
                                #endregion Fondo TT

                                #region Fondo VL
                                case Utility.TipoFondo.VL:
                                    if (datiFS != null && (datiFS.F_Funzione == "L" || datiFS.F_Funzione == "H" || datiFS.F_Funzione == "G") && datiFS.aRETRIBUTIVE_FS != null && datiFS.aRETRIBUTIVE_FS.Length > 0)
                                    {
                                        ServiceReferences.AggPec.F_RETRIBUTIVE datiRetribuzioneSettimanaleAgoQuotaA = datiFS.aRETRIBUTIVE_FS.Where(elem => elem.F_CodQuota == "AA").FirstOrDefault();
                                        if (datiRetribuzioneSettimanaleAgoQuotaA != null)
                                        {
                                            if (datiFondoSpecificoFELPE == null)
                                                datiFondoSpecificoFELPE = new Entity.DatiFondoSpecificoFELPE();
                                            if (datiFondoSpecificoFELPE.DatiFondoVL == null)
                                                datiFondoSpecificoFELPE.DatiFondoVL = new GestioneFondo.DatiFondoVL();
                                            datiFondoSpecificoFELPE.DatiFondoVL.RetribuzioneSettimanaleAgoQuotaA = Convert.ToDecimal(datiRetribuzioneSettimanaleAgoQuotaA.F_Rms);
                                        }
                                        ServiceReferences.AggPec.F_RETRIBUTIVE datiRetribuzioneSettimanaleAgoQuotaB = datiFS.aRETRIBUTIVE_FS.Where(elem => elem.F_CodQuota == "BA").FirstOrDefault();
                                        if (datiRetribuzioneSettimanaleAgoQuotaB != null)
                                        {
                                            if (datiFondoSpecificoFELPE == null)
                                                datiFondoSpecificoFELPE = new Entity.DatiFondoSpecificoFELPE();
                                            if (datiFondoSpecificoFELPE.DatiFondoVL == null)
                                                datiFondoSpecificoFELPE.DatiFondoVL = new GestioneFondo.DatiFondoVL();
                                            datiFondoSpecificoFELPE.DatiFondoVL.RetribuzioneSettimanaleAgoQuotaB = Convert.ToDecimal(datiRetribuzioneSettimanaleAgoQuotaB.F_Rms);
                                        }
                                    }

                                    break;
                                #endregion Fondo VL

                                #region Fondo ET
                                case Utility.TipoFondo.ET:
                                    if (ConfigurationManager.AppSettings["DPRArmonizzazione"] != null && ConfigurationManager.AppSettings["DPRArmonizzazione"] == "SI")
                                    {
                                        // DPR Armonizzazione
                                        if (datiFS != null && datiFS.F_Persviag != 0)
                                        {
                                            if (datiFondoSpecificoFELPE == null)
                                                datiFondoSpecificoFELPE = new Entity.DatiFondoSpecificoFELPE();
                                            if (datiFondoSpecificoFELPE.DatiFondoET == null)
                                                datiFondoSpecificoFELPE.DatiFondoET = new GestioneFondo.DatiFondoET();

                                            if (elencoDecPersonaleViaggiante != null && elencoDecPersonaleViaggiante.Count > 0)
                                            {
                                                GestioneDecodifica.DecPersonaleViaggiante decPersonaleViaggiante = elencoDecPersonaleViaggiante.Find(x => x.TraduzioneSuGP == (byte)datiFS.F_Persviag);
                                                if (decPersonaleViaggiante != null)
                                                    datiFondoSpecificoFELPE.DatiFondoET.PersonaleViaggiante = decPersonaleViaggiante.Id;
                                            }
                                        }
                                    }
                                    break;
                                #endregion Fondo ET
                            }
                            #endregion Fondo Specifico

                            #region Istruttoria
                            if (datiIstruttoria == null)
                                datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                            if (datiFS.F_Tipocalc != null && !string.IsNullOrEmpty(datiFS.F_Tipocalc.Trim()))
                            {
                                char tipCalc;
                                if (char.TryParse(datiFS.F_Tipocalc, out tipCalc))
                                {
                                    datiIstruttoria.TipoCalcoloVincenteUnicarpe = tipCalc;
                                    bSaveIstruttoria = true;
                                }
                            }

                            if (!string.IsNullOrEmpty(datiFS.F_Deroga))
                            {
                                if (datiIstruttoria == null)
                                    datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                                string categoriaNumerica = datiPensione.GetCodCategoria();
                                List<GestioneDecodifica.CodiceParticolare> listaCodiciParticolari = null;
                                GestioneDecodifica.GetCodiciParticolari(out listaCodiciParticolari);
                                if (listaCodiciParticolari != null && listaCodiciParticolari.Count > 0)
                                {
                                    char derogaOutput;
                                    char? deroga;
                                    char.TryParse(datiFS.F_Deroga, out derogaOutput);
                                    if (derogaOutput == ' ' || derogaOutput == '\0' || derogaOutput == '0')
                                        deroga = null;
                                    else
                                        deroga = derogaOutput;
                                    GestioneDecodifica.CodiceParticolare codiceParticolare = listaCodiciParticolari.Find(x => x.TraduzioneSuGp == deroga && x.CodCategoria == categoriaNumerica);
                                    if (codiceParticolare != null)
                                    {
                                        datiIstruttoria.CodiceParticolareSoggettoDerogato = codiceParticolare.Id;
                                        bSaveIstruttoria = true;
                                    }
                                }
                            }

                            if (!bSaveIstruttoria)
                                datiIstruttoria = null;

                            #endregion Istruttoria

                            #region Maggiorazioni/Benefici
                            if (datiFS.aONERI_FS != null && datiFS.aONERI_FS.Length > 0)
                            {
                                foreach (ServiceReferences.AggPec.F_TABONERI oneri in datiFS.aONERI_FS)
                                {
                                    if (oneri.F_CodBenef == "10")
                                    {
                                        if (datiMaggiorazioniBenefici == null)
                                            datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                        datiMaggiorazioniBenefici.TipoSettimaneBeneficio = "05";
                                        datiMaggiorazioniBenefici.IsBeneficioArt24Comma15BisFromFELPE = true;

                                        datiPensione.Benefici = true;
                                        break;
                                    }
                                    else if (oneri.F_CodBenef == "11")
                                    {
                                        if (datiMaggiorazioniBenefici == null)
                                            datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                        datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.F_CodBenef;
                                        datiMaggiorazioniBenefici.IsBeneficioApePrecociFromFELPE = true;

                                        datiPensione.Benefici = true;
                                    }
                                    else if (oneri.F_CodBenef == "01")
                                    {
                                        if (datiMaggiorazioniBenefici == null)
                                            datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                        datiMaggiorazioniBenefici.TipoSettimaneBeneficio = oneri.F_CodBenef;
                                        datiMaggiorazioniBenefici.NSettimaneBeneficio = oneri.F_AnzCon;
                                        datiMaggiorazioniBenefici.SettAnzContribPost311295 = Convert.ToInt16(oneri.F_AnzBenef);
                                        datiMaggiorazioniBenefici.DataNonVedenteDal = Utility.DataFromString(datiFS.F_DatNonV.ToString(), Utility.FormatoData.AAAAmmGG);


                                        datiPensione.Benefici = true;
                                    }
                                }
                            }

                            if (datiFS.F_Amianto != 0)
                            {
                                if (datiMaggiorazioniBenefici == null)
                                    datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                datiMaggiorazioniBenefici.MaggiorazioneAmianto = datiFS.F_Amianto;
                            }

                            if (datiFS.F_Inv74 != 0)
                            {
                                if (datiMaggiorazioniBenefici == null)
                                    datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();

                                datiMaggiorazioniBenefici.MaggiorazioneInv74 = datiFS.F_Inv74;
                            }

                            if ((Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione || Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ripristino ||
                            Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.RipristinoSuperstiti || isRiapertura) &&
                                datiMaggiorazioniBenefici != null && !string.IsNullOrEmpty(datiMaggiorazioniBenefici.TipoSettimaneBeneficio) && datiMaggiorazioniBenefici.TipoSettimaneBeneficio == "11")
                                datiPensione.IdTipoPLPerRIC = (byte?)Utility.TipoPLPerRIC.APEPrecoci.GetHashCode();

                            #endregion Maggiorazioni/Benefici

                            controlloFelpe = new GestioneDatiControlloFelpe.ControlloFelpe();
                            if (!string.IsNullOrEmpty(datiFS.F_Codprov) && !string.IsNullOrEmpty(datiFS.F_Codprov.Trim()))
                            {
                                if (elencoDecodificaComunicazioneCampo3 != null && elencoDecodificaComunicazioneCampo3.Count() > 0 &&
                                    elencoDecodificaComunicazioneCampo3.Exists(x => x.Id.Trim().ToUpperInvariant() == datiFS.F_Codprov.Trim().ToUpperInvariant()))
                                {
                                    if (datiIstruttoria == null)
                                        datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();

                                    datiIstruttoria.CodiceComunicazioneCampo3 = Utility.StringToNullableChar(datiFS.F_Codprov.Trim().ToUpperInvariant());
                                }

                                controlloFelpe.IsProvvisoria = true;
                            }
                            else
                                controlloFelpe.IsProvvisoria = false;

                            if (((Utility.IsRicostituzione_MotiviContributivi(datiPensione) && !Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione)) || isRiapertura) && datiFS.F_Return_Code != 0)
                            {
                                errori = string.Format("Errore tecnico durante il recupero delle informazioni relative alla misura e al diritto. Codice: {0}", datiFS.F_Return_Code.ToString());
                                return;
                            }

                            datiAGGPECO = datiFS;
                        }
                        else
                        {
                            datiPensione.FlagUnicarpe = false;
                            datiPensione.TipoLetturaUnicarpe = null;
                            errori = string.Empty;
                        }
                        break;
                    #endregion  PECO_FS

                    #region PECO_AGO
                    case Utility.TipoAppartenenza.AGO:

                        errori = string.Empty;
                        bSavePensioniCiDatiGenerici = false;
                        datiNuoveLiquidate = null;
                        datiMaggiorazioniBenefici = null;
                        datiPensioniDatiGenerici = null;

                        ServiceReferences.AggPec.csAggiornamentoPECO_AGO dati = null;

                        if (codRicorso.HasValue)
                        {
                            if (datiIstruttoria == null)
                                datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();
                            datiIstruttoria.CodiceDomandaRicorso = codRicorso;
                            bSaveIstruttoria = true;
                        }

                        GestioneControlliDinamici.ControlloDinamico bloccoEsattorialiAutomatiche = null;
                        GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("BloccoAutomaticheEsattoriali", out bloccoEsattorialiAutomatiche);

                        // la chiamata a Felpe va fatta solo per domande non di ricostituzione e per  ricostituzioni per motivi contributivi                      
                        if ((Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) != Utility.TipoDomanda.Ricostituzione ||
                            (Utility.IsRicostituzione_MotiviContributivi(datiPensione) && !Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione))) &&
                            !(Utility.IsDomandaAnticipataEsattoriali(datiPensione) && bloccoEsattorialiAutomatiche != null && bloccoEsattorialiAutomatiche.ValoreControllo == "SI") &&
                            !Utility.IsDomandaPSO(datiPensione.SiglaCategoria) &&
                            !Utility.IsDomandaPMO(datiPensione.SiglaCategoria))
                        {
                            if (!GestioneAggiornamentoPECO.GetDatiPECO_AGO(datiPensione, codiceFiscale, TipoSalvaguardia, isRiapertura, ref dati, out errori))
                                throw new INPS.DNA.DnaValidationException(errori);
                        }
                        // Se sono una RIC per motivi non contributi e se sono una idTipoPlPerRic = 27 oppure 31
                        else if (Utility.IsRicostituzione_MotiviContributivi(datiPensione) == false && Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione) == false &&
                            (datiPensione.IdTipoPLPerRIC == Utility.TipoPLPerRIC.RicAnticipateFlessibileOpzioneContributivo.GetHashCode() || datiPensione.IdTipoPLPerRIC == Utility.TipoPLPerRIC.RicAnticipataFlessibileOpzioneContributivoLeggeBilancio2024.GetHashCode()) &&
                            Utility.IsDomandaPSO(datiPensione.SiglaCategoria) == false && Utility.IsDomandaPMO(datiPensione.SiglaCategoria) == false)
                        {
                            if (!GestioneAggiornamentoPECO.GetDatiPECO_AGO_FunzioneC(datiPensione, codiceFiscale, ref dati, out errori))
                                throw new INPS.DNA.DnaValidationException(errori);
                        }
                        if (dati != null)
                        {
                            int.TryParse(dati.PL_Categoria, out categoriaFelpe);

                            Utility.TipoUnicarpe ctrlUnicarpe = Utility.IsDomandaUnicarpe(true, Utility.StringToNullableChar(dati.PL_Funzione), true);
                            if (categoriaFelpe != categoriaWebDom && ctrlUnicarpe == Utility.TipoUnicarpe.Automatica)
                                throw new INPS.DNA.DnaValidationException("Categoria incongruente tra Unicarpe (" + categoriaFelpe + ") e WebDom ( " + categoriaWebDom + ").");

                            RecuperaDatiFromFELPE_AGO(dati, tipoAppartenenza, categoriaWebDom, ref datiPensione, prelievo, ref datiIstruttoria, isRiapertura, ref isRidRetrPresent, ref isStoricoVisible,
                                ref bSaveIstruttoria, ref isBeneficioAmianto181Present, ref datiNuoveLiquidate, ref datiMaggiorazioniBenefici, ref datiPensioniDatiGenerici, ref controlloFelpe,
                                datiStoricoGP, out datiAGGPECO, out numeroFigliOpzioneDonna, out errori);

                            if (!string.IsNullOrEmpty(errori))
                                return;

                            if (((Utility.IsRicostituzione_MotiviContributivi(datiPensione) && !Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione)) || isRiapertura) && dati.PL_Return_Code != 0)
                            {
                                errori = string.Format("Errore tecnico durante il recupero delle informazioni relative alla misura e al diritto. Codice: {0}", dati.PL_Return_Code.ToString());
                                return;
                            }
                        }
                        else
                        {
                            if (Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) && !Utility.IsRicostituzione(datiPensione.Gruppo))
                            {
                                errori = "Non è possibile acquisire la domanda di APE Sociale. E' necessario lavorare la domanda su Unicarpe";
                                return;
                            }
                            datiPensione.FlagUnicarpe = false;
                            datiPensione.TipoLetturaUnicarpe = null;
                            errori = string.Empty;
                        }

                        break;
                    #endregion PECO_AGO

                    #region PECO_CI
                    case Utility.TipoAppartenenza.CI:
                        errori = string.Empty;
                        bSavePensioniCiDatiGenerici = false;
                        datiNuoveLiquidate = null;
                        datiMaggiorazioniBenefici = null;
                        datiPensioniDatiGenerici = null;

                        ServiceReferences.AggPec.csAggiornamentoPECO_Convenzioni_Internazionali dati_CI = null;

                        if (codRicorso.HasValue)
                        {
                            if (datiIstruttoria == null)
                                datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();
                            datiIstruttoria.CodiceDomandaRicorso = codRicorso;
                            bSaveIstruttoria = true;
                        }

