                                if (dati_CI.CI_Anzcont != 0 && !(new List<string> { "VOS", "IOS", "SOS" }).Contains(datiPensione.SiglaCategoria.Trim()))
                                {
                                    datiPensioniDatiGenerici.SettimaneItalianeDiritto = dati_CI.CI_Anzcont;
                                    bSavePensioniCiDatiGenerici = true;
                                }

                                if (!Utility.IsDoubleEquals(dati_CI.CI_Impivs, 0))
                                {
                                    datiPensioniDatiGenerici.ImportoIVS = Convert.ToDecimal(dati_CI.CI_Impivs);
                                    bSavePensioniCiDatiGenerici = true;
                                }

                                if (!Utility.IsDoubleEquals(dati_CI.CI_Mmedset, 0.0))
                                {
                                    datiPensioniDatiGenerici.CMSM = Convert.ToDecimal(dati_CI.CI_Mmedset);
                                    bSavePensioniCiDatiGenerici = true;
                                }

                                if (!String.IsNullOrEmpty(datiPensione.Gruppo) && datiPensione.Gruppo.Trim() == "0001" && !String.IsNullOrEmpty(datiPensione.Prodotto) && datiPensione.Prodotto.Trim() == "0001")
                                {
                                    datiPensioniDatiGenerici.RiduzioneRetributiva = !String.IsNullOrEmpty(dati_CI.CI_FLAGRIDUZ) && !String.IsNullOrEmpty(dati_CI.CI_FLAGRIDUZ.Trim()) && dati_CI.CI_FLAGRIDUZ.Trim().ToUpperInvariant() == "S" ? true : false;
                                    datiPensioniDatiGenerici.RiduzioneRetributivaPercentuale = !Utility.IsDoubleEquals(dati_CI.CI_PERCRIDUZ, 0.0) ? Convert.ToDecimal(dati_CI.CI_PERCRIDUZ) : (decimal?)null;
                                    if (datiPensioniDatiGenerici.RiduzioneRetributiva)
                                        isRidRetrPresent = true;

                                    if (datiPensioniDatiGenerici.RiduzioneRetributiva || datiPensioniDatiGenerici.RiduzioneRetributivaPercentuale.HasValue)
                                        bSavePensioniCiDatiGenerici = true;
                                }
                            }

                            if (!bSavePensioniCiDatiGenerici)
                                datiPensioniDatiGenerici = null;

                            #endregion DatiGenericiCi

                            #region Istituzioni Estere
                            if (dati_CI.aISTITUZIONI_CI != null && dati_CI.aISTITUZIONI_CI.Count() > 0)
                            {
                                istituzioniEsterePECO = new List<ServiceReferences.AggPec.CI_ISTITUZIONI>();
                                foreach (ServiceReferences.AggPec.CI_ISTITUZIONI istituzione in dati_CI.aISTITUZIONI_CI)
                                {
                                    if (!string.IsNullOrEmpty(istituzione.CI_Stato) && !string.IsNullOrEmpty(istituzione.CI_Stato.Trim()) &&
                                        !string.IsNullOrEmpty(istituzione.CI_Istit) && !string.IsNullOrEmpty(istituzione.CI_Istit.Trim()) ||
                                        (isRiapertura && !Utility.IsDoubleEquals(istituzione.CI_Direst, 0.0) && !Utility.IsDoubleEquals(istituzione.CI_Misest, 0.0)))
                                        istituzioniEsterePECO.Add(istituzione);
                                }
                            }
                            #endregion Istituzioni Estere
                            #endregion Dati Statici

                            if ((Utility.IsRicostituzione_MotiviContributivi(datiPensione) || isRiapertura) && dati_CI.CI_Return_Code != 0)
                            {
                                errori = string.Format("Errore tecnico durante il recupero delle informazioni relative alla misura e al diritto. Codice: {0}", dati_CI.CI_Return_Code.ToString());
                                return;
                            }

                            datiAGGPECO = dati_CI;
                        }
                        else
                        {
                            datiPensione.FlagUnicarpe = false;
                            datiPensione.TipoLetturaUnicarpe = null;
                            errori = string.Empty;
                        }

                        break;
                    #endregion PECO_CI

                    case null:
                        throw new INPS.DNA.DnaValidationException("Impossibile determinare il Web Service da invocare.");
                }

                // Controllo che verifica se in caso di tipoLettura = 'L', la decorrenza è valorizzata.
                // Inserito per segnalazione 05-06-2015 (Oggetto Mail: produzione sede di Pistoia  SRFGNN53E43D617X) 
                if (!IsDecorrenzaPresenteForLetturaL(datiPensione.TipoLetturaUnicarpe, datiPensione.DecorrenzaOriginaria, out errori))
                    return;

                //Flusso Automazione Supplementi
                if (tipoAutomazione == Utility.TipoAutomazione.Supplementi)
                {
                    ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;

                    char codNatura1 = ' ';
                    char codNatura2 = ' ';
                    char codNatura3 = ' ';
                    if (prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiPensione != null) Utility.GetCodiciNatura(prelievoAgo.Risposta.DatiPensione.NaturaPensione, out codNatura1, out codNatura2, out codNatura3);
                    if ((codNatura1 == '3' || codNatura1 == '4') && datiPensione.Gruppo == "0031" && datiPensione.Prodotto == "0302" && datiPensione.Tipo == "0001")
                    {
                        //Chiudere 168
                        GestioneWebDom.ChiusuraAttivita(datiPensione, matricolaOperatore, sedeOperatore, GestioneWebDom.CodiceAttivita.InAttesaDiCalcoloAutomatico, out errori);
                        errori = "Supplemento su pensione di inabilità che non può essere processata. " + errori;
                        return;
                    }
                    if (Utility.IsRequisitiCalcoloQuote(datiPensione, prelievoAgo.Risposta.ListaCalcoloContributivo, prelievoAgo.Risposta.ListaSupplementi))
                    {
                        BLCommon.Entity.DatiSupplementi[] listaSupplementiOut;
                        bool erroreTemporaneo = false;
                        if (!GestioneCalcoloQuote.Calcola(prelievoAgo.Risposta.CodiceFiscale, datiPensione, prelievoAgo.Risposta.ListaSupplementi, prelievoAgo.Risposta.DatiPensione.InizioAssicurazione, out listaSupplementiOut, isRiapertura, out errori, out erroreTemporaneo))
                        {
                            if (erroreTemporaneo)
                                errori = "Chiamata dati supplementi con esito negativo (" + errori + "), sarà effettuata una verifica tecnica. La domanda sarà riprocessata.";
                            else
                            {
                                //Chiudere 168
                                string erroreWebdom = string.Empty;
                                GestioneWebDom.ChiusuraAttivita(datiPensione, matricolaOperatore, sedeOperatore, GestioneWebDom.CodiceAttivita.InAttesaDiCalcoloAutomatico, out erroreWebdom);
                                errori = "Chiamata dati supplementi con esito negativo (" + errori + "), la domanda deve essere lavorata manualmente dalla sede. " + erroreWebdom;
                            }
                            return;
                        }
                        else
                        {
                            prelievoAgo.Risposta.ListaSupplementi = listaSupplementiOut;
                            //Chiudere 168
                            GestioneWebDom.ChiusuraAttivita(datiPensione, matricolaOperatore, sedeOperatore, GestioneWebDom.CodiceAttivita.InAttesaDiCalcoloAutomatico, out errori);
                            datiPensione.TipoAutomazione = (byte)Utility.TipoAutomazione.Supplementi;
                        }
                    }
                    else
                    {
                        //Chiudere 168
                        GestioneWebDom.ChiusuraAttivita(datiPensione, matricolaOperatore, sedeOperatore, GestioneWebDom.CodiceAttivita.InAttesaDiCalcoloAutomatico, out errori);
                        errori = "Dati del prelievo pensione non rientranti fra quelli oggetto di automazione. " + errori;
                        return;
                    }


                }
            }

            if (Utility.IsDomandaInabilitaAmianto(datiPensione) && Utility.IsDomandaPL(datiPensione) && tipoAppartenenza != null && Utility.IsDomandaUnicarpe(datiPensione, true) != Utility.TipoUnicarpe.Automatica)
            {
                switch (tipoAppartenenza)
                {

                    case Utility.TipoAppartenenza.AGO:
                        ServiceReferences.AggPec.csAggiornamentoPECO_AGO dati = null;
                        if (!GestioneAggiornamentoPECO.GetCertificazione_AGO(tipoAppartenenza, codiceFiscale, datiPensione.NDomus.ToString(), ref dati, ref errori))
                            throw new INPS.DNA.DnaValidationException(errori);

                        if (dati == null)
                        {
                            errori = "Lavorazione non consentita, certificazione non presente su FELPE, si prega di scrivere alla casella helpcertificazioni@inps.it";
                            throw new INPS.DNA.DnaValidationException(errori);
                        }
                        else if (dati != null && dati.PL_Deroga == "4")
                        {
                            errori = "ATTENZIONE: certificazione presente su FELPE in attesa dell’esito del monitoraggio";
                            throw new INPS.DNA.DnaValidationException(errori);
                        }

                        break;
                    case Utility.TipoAppartenenza.FS:
                        ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_AMG datiFS = null;
                        if (!GestioneAggiornamentoPECO.GetCertificazione_AMG(tipoAppartenenza, codiceFiscale, datiPensione.NDomus.ToString(), ref datiFS, ref errori))
                            throw new INPS.DNA.DnaValidationException(errori);

                        if (datiFS == null)
                        {
                            errori = "Lavorazione non consentita, certificazione non presente su FELPE, si prega di scrivere alla casella helpcertificazioni@inps.it";
                            throw new INPS.DNA.DnaValidationException(errori);
                        }


                        else if (datiFS != null && datiFS.A_Deroga == "4")
                        {
                            errori = "ATTENZIONE: certificazione presente su FELPE in attesa dell’esito del monitoraggio";
                            throw new INPS.DNA.DnaValidationException(errori);
                        }
                        break;

                    case Utility.TipoAppartenenza.CI:

                        ServiceReferences.AggPec.csAggiornamentoPECO_Convenzioni_Internazionali datiCI = null;
                        if (!GestioneAggiornamentoPECO.GetCertificazione_CI(tipoAppartenenza, codiceFiscale, datiPensione.NDomus.ToString(), ref datiCI, ref errori))
                            throw new INPS.DNA.DnaValidationException(errori);

                        if (datiCI == null)
                        {
                            errori = "Lavorazione non consentita, certificazione non presente su FELPE, si prega di scrivere alla casella helpcertificazioni@inps.it";
                            throw new INPS.DNA.DnaValidationException(errori);
                        }


                        else if (datiCI != null && datiCI.CI_Deroga == "4")
                        {
                            errori = "ATTENZIONE: certificazione presente su FELPE in attesa dell’esito del monitoraggio";
                            throw new INPS.DNA.DnaValidationException(errori);
                        }
                        break;

                }
            }

            //TFR/RIC
            if (tipoAppartenenza == Utility.TipoAppartenenza.CI && Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) && !Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione))
            {
                char codNatura1 = ' ';
                char codNatura2 = ' ';
                char codNatura3 = ' ';
                GestioneControlliDinamici.ControlloDinamico controlloDinamicoOpzContr = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("Abilita_TRF_RIC_OpzContributivo", out controlloDinamicoOpzContr);
                if (prelievo != null)
                {
                    ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoCi = (ServiceReferences.LiquidazioneCi.AreaPrelievo)prelievo;
                    if (prelievoCi.Risposta != null && prelievoCi.Risposta.DatiPensione != null) Utility.GetCodiciNatura(prelievoCi.Risposta.DatiPensione.NaturaPensione, out codNatura1, out codNatura2, out codNatura3);
                    if (controlloDinamicoOpzContr != null && !String.IsNullOrEmpty(controlloDinamicoOpzContr.ValoreControllo) && controlloDinamicoOpzContr.ValoreControllo.Trim().ToUpperInvariant() != "SI"
                        && codNatura2 == 'J')
                    {
                        errori = "Prodotto di opzione al contributivo al momento non lavorabile";
                        return;
                    }
                }
            }

            //ENG - Memo 06_2024_part_2
            if (controlloDinamicoAbilitazioneMemo06_2024_part_2 != null && !String.IsNullOrEmpty(controlloDinamicoAbilitazioneMemo06_2024_part_2.ValoreControllo) &&
                controlloDinamicoAbilitazioneMemo06_2024_part_2.ValoreControllo.ToUpperInvariant() == "SI" && !Utility.IsDomandaAPEPrecoci(datiPensione) &&
                !(Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) && tipoAppartenenza == Utility.TipoAppartenenza.AGO) && !Utility.IsDomandaINPDAP(datiPensione.Gestione)
                && !Utility.IsRicostituzione_PerVariazioneDatiSupplementoAll(datiPensione))
            {
                bool isRicPlAutomaticaUnicarpe = false;
                bool isPlAutomaticaUnicarpe = false;
                string mailTo = string.Empty;

                if (datiPensione.TipoLetturaUnicarpe == null && (datiPensione.FlagUnicarpe == null || datiPensione.FlagUnicarpe == false))
                {
                    List<GestioneLavorazioneManualeAutomatiche.TipologiaAutomaticaUnicarpe> elencoTipologiaAutomaticaUnicarpe = new List<GestioneLavorazioneManualeAutomatiche.TipologiaAutomaticaUnicarpe>();
                    GestioneAreaLavorazioneManualeAutomatiche.GetAllTipologieAutomaticheUnicarpe(out elencoTipologiaAutomaticaUnicarpe);

                    if (tipoDomanda == Utility.TipoDomanda.Ricostituzione && datiPensione.DecorrenzaOriginaria.HasValue)
                    {
                        if (Utility.IsRicostituzione_MotiviContributivi(datiPensione))
                        {
                            if (!GestioneDatiPensioni.GetDatiTGP1ByChiavePensioneForLavorazioneManuale(datiPensione, prelievo, tipoAppartenenza, datiPensione.NDomus, sedeChiavePensione, datiPensione.DecorrenzaOriginaria, datiPensione.GetFiltro(), elencoTipologiaAutomaticaUnicarpe, out isRicPlAutomaticaUnicarpe, out errori))
                            {
                                return;
                            }
                            else
                            {
                                if (isRicPlAutomaticaUnicarpe)
                                {
                                    if (!ValorizzaLavorazioneManualeAutomatica(datiPensione.Gruppo, datiPensione.Prodotto, datiPensione.Tipo, datiPensione.NDomus, out errori))
                                        throw new INPS.DNA.DnaValidationException(errori);
                                    else
                                    {
                                        if (abilitaInvioUnicarpeIconaMemo06_2024 != null && !String.IsNullOrEmpty(abilitaInvioUnicarpeIconaMemo06_2024.ValoreControllo) &&
                                            abilitaInvioUnicarpeIconaMemo06_2024.ValoreControllo.ToUpperInvariant() == "SI")
                                        {
                                            if (generaIndirizzoEmailPerSede(datiPensione.CodiceSede.ToString().PadLeft(4, '0'), datiPensione.NDomus, out mailTo, out errori))
                                                if (!GestioneMail.NotificaSbloccoDomandaUnicarpe(matricolaOperatore, datiPensione.NDomus, codiceFiscale, datiPensione.CodiceSede, "Posizione sbloccata per lavorazione manuale", mailTo, out errori))
                                                    if (invioUnicarpeIconaBloccanteMemo06_2024 != null && !String.IsNullOrEmpty(invioUnicarpeIconaBloccanteMemo06_2024.ValoreControllo) &&
                                                        invioUnicarpeIconaBloccanteMemo06_2024.ValoreControllo.ToUpperInvariant() == "SI")
                                                        throw new INPS.DNA.DnaValidationException(errori);
                                        }
                                    }
                                }
                            }
                        }
                    }
                    else
                    {
                        if (datiPensione.DecorrenzaOriginaria.HasValue)
                        {
                            string strFiltro = datiPensione.GetFiltro().ToString().ToUpperInvariant();
                            foreach (GestioneLavorazioneManualeAutomatiche.TipologiaAutomaticaUnicarpe lst in elencoTipologiaAutomaticaUnicarpe)
                            {
                                if (lst.SiglaCategoria.Trim().ToUpperInvariant() == datiPensione.SiglaCategoria.Trim().ToUpperInvariant() &&
                                    lst.Gruppo == datiPensione.Gruppo && lst.Prodotto == datiPensione.Prodotto &&
                                    lst.Tipo == datiPensione.Tipo &&
                                    lst.CodiceTipoRichiesta.Trim().ToUpperInvariant() == datiPensione.GetFiltro().Trim().ToUpperInvariant() &&
                                    Utility.DataStrettamenteSuccessivaA((DateTime)datiPensione.DecorrenzaOriginaria, (DateTime)lst.DecorrenzaMinima))
                                {
                                    isPlAutomaticaUnicarpe = true;
                                    break;
                                }
                            }
                        }
                        else
                        {
                            foreach (GestioneLavorazioneManualeAutomatiche.TipologiaAutomaticaUnicarpe lst in elencoTipologiaAutomaticaUnicarpe)
                            {
                                if (lst.SiglaCategoria.Trim().ToUpperInvariant() == datiPensione.SiglaCategoria.Trim().ToUpperInvariant() && lst.Gruppo == datiPensione.Gruppo && lst.Prodotto == datiPensione.Prodotto &&
                                    lst.Tipo == datiPensione.Tipo && lst.CodiceTipoRichiesta.Trim().ToUpperInvariant() == datiPensione.GetFiltro().Trim().ToUpperInvariant())
                                {
                                    isPlAutomaticaUnicarpe = true;
                                    break;
                                }
                            }
                        }

                        if (isPlAutomaticaUnicarpe)
                        {
                            if (!ValorizzaLavorazioneManualeAutomatica(datiPensione.Gruppo, datiPensione.Prodotto, datiPensione.Tipo, datiPensione.NDomus, out errori))
                                throw new INPS.DNA.DnaValidationException(errori);
                            else
                            {
                                if (abilitaInvioUnicarpeIconaMemo06_2024 != null && !String.IsNullOrEmpty(abilitaInvioUnicarpeIconaMemo06_2024.ValoreControllo) &&
                                            abilitaInvioUnicarpeIconaMemo06_2024.ValoreControllo.ToUpperInvariant() == "SI")
                                {
                                    if (generaIndirizzoEmailPerSede(datiPensione.CodiceSede.ToString().PadLeft(4, '0'), datiPensione.NDomus, out mailTo, out errori))
                                        if (!GestioneMail.NotificaSbloccoDomandaUnicarpe(matricolaOperatore, datiPensione.NDomus, codiceFiscale, datiPensione.CodiceSede, "Posizione sbloccata per lavorazione manuale", mailTo, out errori))
                                            if (invioUnicarpeIconaBloccanteMemo06_2024 != null && !String.IsNullOrEmpty(invioUnicarpeIconaBloccanteMemo06_2024.ValoreControllo) &&
                                               invioUnicarpeIconaBloccanteMemo06_2024.ValoreControllo.ToUpperInvariant() == "SI")
                                                throw new INPS.DNA.DnaValidationException(errori);
                                }
                            }
                        }
                    }
                }
            }

            if (Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) && !Utility.IsDomandaAutomatica(datiPensione))
            {
                GestioneControlliDinamici.ControlloDinamico ctrlManualiAnticipateFlessibiliOpzioneContr = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("ManualiAnticipateFlessibiliOpzioneContr", out ctrlManualiAnticipateFlessibiliOpzioneContr);
                if (ctrlManualiAnticipateFlessibiliOpzioneContr != null && !String.IsNullOrEmpty(ctrlManualiAnticipateFlessibiliOpzioneContr.ValoreControllo)
                    && ctrlManualiAnticipateFlessibiliOpzioneContr.ValoreControllo.Trim().ToUpperInvariant() == "NO")
                {
                    errori = "Prelievo al momento non disponibile";
                    return;
                }
            }

            //Automazione vecchiaia
            if (tipoAutomazione == Utility.TipoAutomazione.Vecchiaia)
            {
                if (datiPensione.TipoLetturaUnicarpe == null)
                {
                    //Chiudere 168
                    GestioneWebDom.ChiusuraAttivita(datiPensione, matricolaOperatore, sedeOperatore, GestioneWebDom.CodiceAttivita.InAttesaDiCalcoloAutomatico, out errori);
                    errori = "Domanda automatizzata per la quale occorre elaborare i dati di diritto/misura" + errori;
                    return;
                }
                if (anagraficaTitolare.ResidenzaEstero == true)
                {
                    //Chiudere 168
                    GestioneWebDom.ChiusuraAttivita(datiPensione, matricolaOperatore, sedeOperatore, GestioneWebDom.CodiceAttivita.InAttesaDiCalcoloAutomatico, out errori);
                    errori = "Domanda automatizzata per la quale il titolare non risiede in Italia." + errori;
                    return;
                }

                //momentaneamente sospeso
                //if (anagraficaTitolare.Cittadinanza != "Z000")
                //{
                //    //Chiudere 168
                //    GestioneWebDom.ChiusuraAttivita(datiPensione, matricolaOperatore, sedeOperatore, GestioneWebDom.CodiceAttivita.InAttesaDiCalcoloAutomatico, out errori);
                //    errori = "Domanda automatizzata per la quale il titolare non ha la cittadinanza italiana." + errori;
                //    return;
                //}

                if (CFfamiliari != null && CFfamiliari.Exists(x => x.SiglaFamiliare != 'C' && x.SiglaFamiliare != 'U'))
                {
                    //Chiudere 168
                    GestioneWebDom.ChiusuraAttivita(datiPensione, matricolaOperatore, sedeOperatore, GestioneWebDom.CodiceAttivita.InAttesaDiCalcoloAutomatico, out errori);
                    errori = "Domanda automatizzata per la quale sono presenti familiari diversi dal coniuge / unito civile." + errori;
                    return;
                }

                //--- controllo bititolarita
                int countElementi = 0;
                if (!GestioneDatiPensioni.GetDatiECodiciVari(datiPensione, anagraficaTitolare.CodiceFiscale, isRiapertura, out countElementi, out errori))
                    return;
                else if (countElementi > 0)
                {
                    //Chiudere 168
                    GestioneWebDom.ChiusuraAttivita(datiPensione, matricolaOperatore, sedeOperatore, GestioneWebDom.CodiceAttivita.InAttesaDiCalcoloAutomatico, out errori);
                    errori = "Domanda automatizzata per la quale il titolare risulta bititolare." + errori;
                    return;
                }


                datiPensione.TipoAutomazione = (byte)Utility.TipoAutomazione.Vecchiaia;
                datiPensione.AttivitaEconomica = 11;
                datiPensione.ProfessioneIndividuale = 111;
            }

            //Flusso Automazione Trasformazioni
            if (tipoAutomazione == Utility.TipoAutomazione.Trasformazioni)
            {
                if (isAttivita168Aperta)
                {
                    errori = "Domanda di trasformazione al momento non acquisibile, è in corso la lavorazione dal processo automatizzato" + errori;
                    tipoAutomazione = null;
                    return;
                }

                if (datiPensione.TipoLetturaUnicarpe == null)
                {
                    if (isMatricolaForAutomazione && isAttivita168Aperta)
                    {
                        //Chiudere 168
                        GestioneWebDom.ChiusuraAttivita(datiPensione, matricolaOperatore, sedeOperatore, GestioneWebDom.CodiceAttivita.InAttesaDiCalcoloAutomatico, out errori);
                    }
                    errori = "Domanda automatizzata per la quale occorre elaborare i dati di diritto/misura" + errori;
                    return;
                }

                datiPensione.TipoAutomazione = (byte)Utility.TipoAutomazione.Trasformazioni;

                if (datiPensione.DecorrenzaOriginaria.HasValue && DateTime.UtcNow.Year - datiPensione.DecorrenzaOriginaria.Value.Year <= 5)
                    datiPensione.DecorrenzaCalcoloArretrati = datiPensione.DecorrenzaOriginaria;
                else
                    datiPensione.DecorrenzaCalcoloArretrati = DateTime.UtcNow.AddYears(-5);
            }

            //Gestione per la visibilità della voce di menù MaggiorazioneBenefici.
            if (IsVisibleTabBenefici(tipoAppartenenza.Value, datiPensione, isRiapertura))
                datiPensione.Benefici = true;
            ////////////////////////////////////////////////////////////////////

            //Per le ENPALS con GPT 0001-0002-0172 non deve essere richiesta la lavorazione in Unicarpe
            if (!((Utility.IsDomandaENPALS(datiPensione.Gestione) && Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1(datiPensione))
                || Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) || Utility.IsDomandaVOTOT(datiPensione.SiglaCategoria) || datiPensione.SiglaCategoria.Trim() == "VOSPETT" || datiPensione.SiglaCategoria.Trim() == "VOSPORT"))
            {
                if (!CheckDomandaAutomaticaObbligatoria(datiPensione, out errori))
                    return;
            }

            DateTime? scadenzaBeneficioUnicarpe = null;
            #region Deroga
            if ((listaOneri == null || listaOneri.Count == 0) && !IsDomandaConDerogaCorretta(tipoAppartenenza, datiPensione, datiAGGPECO, isRiapertura,
