                 Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) || Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1(datiPensione) ||
                 Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1OpzioneContributivo(datiPensione) || Utility.IsDomandaQuota100(datiPensione) || Utility.IsDomandaQuota102(datiPensione) || Utility.IsDomandaAnticipataFlessibile(datiPensione)
                 || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione) || Utility.IsDomandaAnzianitaPerLeggeBilancio2019OrRicostituzione(datiPensione) ||
                 Utility.IsDomandaVecchiaiaMaggiorazioneAmiantoLegge208_2015(datiPensione) || Utility.IsDomandaAnzianitaMaggiorazioneAmiantoLegge208_2015(datiPensione) ||
                 Utility.IsDomandaRiliquidazioneAnzianitaAnticipataConFinestraDecorrenza(datiPensione) || Utility.IsDomandaAnticipataConOpzionePL(datiPensione) || (datiMaggiorazioniBenefici != null && datiMaggiorazioniBenefici.TipoSettimaneBeneficio == "01")
                 || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true) ||
                 (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
