                                if (Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica && datiAMG_INPDAP != null && !string.IsNullOrEmpty(datiAMG_INPDAP.A_Decinc) && datiAMG_INPDAP.A_Decinc != "0" && datiAMG_INPDAP.A_Decinc.ToString().Length == 8)
                                {
