                        else if ((isGestioneAMG_Fondi_FSPT && tipoFondo.HasValue && listaTipoFondo_PECO_Fondi_AMG.Contains(tipoFondo.Value)) || datiPensione.TipoFelpe == (byte)Utility.TipoFelpe.AMG)
                        {
                            if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0017")
                            {
                                ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_AMG datiAMG = (ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_AMG)datiAGGPECO;
                                if (Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica && datiAMG != null && datiAMG.A_Decinc != 0 && datiAMG.A_Decinc.ToString().Length == 8)
                                {
