            }
            #endregion CodUnitaProcessoDestinazione

            #region Perdita Titolo
            if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.FS && Utility.IsDomandaVecchPerditaTitolo(datiPensione))
