            UnisciFamiliariPrelievoWebdom(CFfamiliari, tipoAppartenenza.Value, ref prelievo);

            string gp1Af03 = string.Empty;
            string gp1Tipo = string.Empty;
            string gp1Prodotto = string.Empty;
            string gp1Gruppo = string.Empty;
            bool isPLAnticipata0017 = false;
            bool isPLAnticipata0045PAV = false;

            if (!RecuperaPLUnicarpe(ref datiPensione, prelievo, tipoAppartenenza, isPLUnicarpeFromDB, isPLPrepensionamentoEditoriaTipo0162FiltroEAA, isPLPrepensionamentoEditoriaTipo0162FiltroEBA, isPLESPAFiltroL26, isPLVESO33FiltroDAP, datiDomanda, sedeChiavePensione, isRiapertura, numeroFigliOpzioneDonna, codTipoRichiesta, out gp1Af03, out gp1Tipo, out gp1Prodotto, out gp1Gruppo, out isPLAnticipata0017, out isPLAnticipata0045PAV, out errori))
                return;

            //ENG - Memo 28 inserimento blocco RIC/TRF vecchiaia     
            if (!string.IsNullOrEmpty(gp1Gruppo) && gp1Gruppo == "0001" && !string.IsNullOrEmpty(gp1Prodotto) && gp1Prodotto == "0002")
            {
                //ENG - Memo 28 inserite nuove chiavi per bloccare le RIC/TRF a secondo della linea di lavorazione
                bool bloccaRicTrfVecchiaiaMemo28 = false;
                if (tipoAppartenenza == Utility.TipoAppartenenza.AGO)
                {
                    GestioneControlliDinamici.ControlloDinamico ctrlVecchiaiaMemo28_AGO = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("Memo28_2024_blocco_RicTrf_vecchiaia_AGO", out ctrlVecchiaiaMemo28_AGO);
                    if (ctrlVecchiaiaMemo28_AGO != null && !String.IsNullOrEmpty(ctrlVecchiaiaMemo28_AGO.ValoreControllo) && ctrlVecchiaiaMemo28_AGO.ValoreControllo.Trim().ToUpperInvariant() == "SI")
