                }
                else if (tipoAppartenenza == Utility.TipoAppartenenza.CI)
                {
                    GestioneControlliDinamici.ControlloDinamico ctrlVecchiaiaMemo28_CI = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("Memo28_2024_blocco_RicTrf_vecchiaia_CI", out ctrlVecchiaiaMemo28_CI);
                    if (ctrlVecchiaiaMemo28_CI != null && !String.IsNullOrEmpty(ctrlVecchiaiaMemo28_CI.ValoreControllo) && ctrlVecchiaiaMemo28_CI.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                        bloccaRicTrfVecchiaiaMemo28 = true;
                }

                if (bloccaRicTrfVecchiaiaMemo28)
                {
                    string naturaPensioneDaPrelievo = string.Empty;
                    int? contributiItalianiEdEsteriAl1295 = null;
                    GestionePensione.DatiPensione datiPensioneTemp = new GestionePensione.DatiPensione();

                    if (tipoAppartenenza.HasValue)
                    {
                        if (tipoAppartenenza.Value == Utility.TipoAppartenenza.FS)
                        {
                            ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFs = (ServiceReferences.LiquidazioneFs.AreaPrelievo)prelievo;
                            if (prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiPensione != null && !String.IsNullOrEmpty(prelievoFs.Risposta.DatiPensione.NaturaPensione))
                            {
                                Utility.ValorizzaOggettiMaster(prelievoFs.Risposta.DatiPensione, datiPensioneTemp);
                            }
                        }
                        else if (tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO)
                        {
                            ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = (ServiceReferences.LiquidazioneAgo.AreaPrelievo)prelievo;
                            if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiPensione != null && !String.IsNullOrEmpty(prelievoAgo.Risposta.DatiPensione.NaturaPensione))
                            {
                                naturaPensioneDaPrelievo = prelievoAgo.Risposta.DatiPensione.NaturaPensione;
                                Utility.ValorizzaOggettiMaster(prelievoAgo.Risposta.DatiPensione, datiPensioneTemp);
                            }
                        }
                        else if (tipoAppartenenza.Value == Utility.TipoAppartenenza.CI)
                        {
                            ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoCi = (ServiceReferences.LiquidazioneCi.AreaPrelievo)prelievo;
                            if (prelievoCi != null && prelievoCi.Risposta != null && prelievoCi.Risposta.DatiPensione != null && !String.IsNullOrEmpty(prelievoCi.Risposta.DatiPensione.NaturaPensione))
                            {
                                contributiItalianiEdEsteriAl1295 = prelievoCi.Risposta.DatiPensioniCiDatiGenerici != null ? prelievoCi.Risposta.DatiPensioniCiDatiGenerici.ContributiItalianiEdEsteriAl1295 : null;
                                naturaPensioneDaPrelievo = prelievoCi.Risposta.DatiPensione.NaturaPensione;
                                Utility.ValorizzaOggettiMaster(prelievoCi.Risposta.DatiPensione, datiPensioneTemp);
                            }
                        }
                    }
                    Utility.ValorizzaOggettiMaster(datiPensione, datiPensioneTemp);
                    if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) &&
                    datiPensioneTemp.DataPerfezionamentoRequisiti.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensioneTemp.DataPerfezionamentoRequisiti.Value, new DateTime(2023, 12, 31)))
                    {
                        if ((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0017") ||
                            ((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0001") && !string.IsNullOrEmpty(gp1Af03) && gp1Af03 == "8") ||
                            (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0045"))
