                throw new INPS.DNA.DnaValidationException(errori);
        }

        private static bool CheckDomandaAutomaticaObbligatoria(GestionePensione.DatiPensione datiPensione, out string errori)
        {
            errori = string.Empty;
            //ENG - Aggiunto filtro "FCA"
            if (Utility.IsDomandaUnicarpe(datiPensione, true) != Utility.TipoUnicarpe.Automatica && new List<string> { "XAA", "XCA", "ACA", "VCA", "FCA" }.Contains(datiPensione.GetFiltro()))
            {
                errori = "E' necessario lavorare la domanda su Unicarpe";
                return false;
            }
            return true;
        }

        private static void SalvaStatiEsteri(GestionePensione.DatiPensione datiPensione, GestioneAnagrafica.DatiAnagrafici datiAnagrafici, List<ServiceReferences.AggPec.CI_ISTITUZIONI> istituzioniEsterePECO,
            string matricolaOperatore, short sedeOperatore, short centroOperativoOperatore, object prelievo, out List<GestioneDatiContributiviCi.PensioniCiPrestazioniEE> listaPrestazioniEE, out string errori)
        {
            listaPrestazioniEE = null;
            List<GestioneDatiContributiviCi.PensioniCiImportiEsteri> listaImportiEsteri = null;
            string cittadinanzaTitolare = string.Empty;
            if (!GestioneLiquidazioneCi.GetStatiEsteri(datiPensione, datiPensione.CodiceSede, datiPensione.CentroOperativo.HasValue ? datiPensione.CentroOperativo.Value : (byte)0, matricolaOperatore,
                sedeOperatore, centroOperativoOperatore, istituzioniEsterePECO, out listaPrestazioniEE, out listaImportiEsteri, out cittadinanzaTitolare, out errori))
                return;

            ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoCI = prelievo as ServiceReferences.LiquidazioneCi.AreaPrelievo;
            if (listaPrestazioniEE != null && listaPrestazioniEE.Count > 0)
            {
                //ENG - Implementata la gestione mancante per le Reversibilità
                if (Utility.IsDomandaReversibilita(datiPensione))
                {
                    if (prelievoCI != null && prelievoCI.Risposta != null && prelievoCI.Risposta.ListaStatiEsteri != null)
                        ArchiviaDatiStatiEsteriPerReversibilità(prelievoCI.Risposta.ListaStatiEsteri.ToList(), datiPensione.Id, listaPrestazioniEE);
                }
                else
                    GestioneDatiContributiviCi.SalvaListaPrestazioniEstere(datiPensione.Id, listaPrestazioniEE);
            }

            if (!string.IsNullOrEmpty(cittadinanzaTitolare))
            {
                datiAnagrafici.Cittadinanza = cittadinanzaTitolare;
                GestioneAnagrafica.SalvaAnagrafica(datiAnagrafici);
            }
        }

        //ENG - RIC/TRF: aggiunta la gestione per il recupero degli stati(se presenti e diversi da quelli provenienti da prelievo) dal servizio Naci o AllegatiConvenzioni
        private static void SalvaStatiEsteriRicTrf(GestionePensione.DatiPensione datiPensione, GestioneAnagrafica.DatiAnagrafici datiAnagrafici, List<ServiceReferences.AggPec.CI_ISTITUZIONI> istituzioniEsterePECO,
          string matricolaOperatore, short sedeOperatore, short centroOperativoOperatore, object prelievo, out List<GestioneDatiContributiviCi.PensioniCiPrestazioniEE> listaPrestazioniEE, out string errori)
        {
            listaPrestazioniEE = null;
            List<GestioneDatiContributiviCi.PensioniCiImportiEsteri> listaImportiEsteri = null;
            string cittadinanzaTitolare = string.Empty;

            if (!GestioneLiquidazioneCi.GetStatiEsteriRicTrf(datiPensione, datiPensione.CodiceSede, datiPensione.CentroOperativo.HasValue ? datiPensione.CentroOperativo.Value : (byte)0, matricolaOperatore,
                sedeOperatore, centroOperativoOperatore, istituzioniEsterePECO, out listaPrestazioniEE, out listaImportiEsteri, out cittadinanzaTitolare, out errori))
                return;

            ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoCI = prelievo as ServiceReferences.LiquidazioneCi.AreaPrelievo;
            if (listaPrestazioniEE != null && listaPrestazioniEE.Count > 0)
            {
                if (prelievoCI != null && prelievoCI.Risposta != null && prelievoCI.Risposta.ListaStatiEsteri != null)
                    ArchiviaDatiStatiEsteriPerRicTrf(prelievoCI.Risposta.ListaStatiEsteri.ToList(), listaPrestazioniEE);
            }

            if (!string.IsNullOrEmpty(cittadinanzaTitolare))
            {
                datiAnagrafici.Cittadinanza = cittadinanzaTitolare;
                GestioneAnagrafica.SalvaAnagrafica(datiAnagrafici);
            }
        }

        //ENG - Implementata la gestione mancante per le Reversibilità
        private static void ArchiviaDatiStatiEsteriPerReversibilità(List<ServiceReferences.LiquidazioneCi.GestioneContribStatoEstero> ListaStatiEsteriCi, long idPensione, List<GestioneDatiContributiviCi.PensioniCiPrestazioniEE> listaPrestazioniEE)
        {
            foreach (GestioneDatiContributiviCi.PensioniCiPrestazioniEE statoEstero in listaPrestazioniEE)
            {
                if (statoEstero != null)
                {
                    statoEstero.IdPensione = idPensione;
                    var prestazioneEstera = ListaStatiEsteriCi.Find(x => x.PrestazioneEstera.CodiceStatoEE == statoEstero.CodiceStatoEE && x.PrestazioneEstera.CodiceIstituzione == statoEstero.CodiceIstituzione) != null ? ListaStatiEsteriCi.Find(x => x.PrestazioneEstera.CodiceStatoEE == statoEstero.CodiceStatoEE && x.PrestazioneEstera.CodiceIstituzione == statoEstero.CodiceIstituzione).PrestazioneEstera : null;
                    if (prestazioneEstera != null)
                    {
                        int? contributiEEDecorrenzaOriginaria = prestazioneEstera.ContributiEEDecorrenzaOriginaria;
                        if (contributiEEDecorrenzaOriginaria.HasValue)
                            statoEstero.ContributiEEDecorrenzaOriginaria = contributiEEDecorrenzaOriginaria;

                        int? contributiEEDiritto = prestazioneEstera.ContributiEEDiritto;
                        if (contributiEEDiritto.HasValue)
                            statoEstero.ContributiEEDiritto = contributiEEDiritto;

                        int? contributiEERicalcolo = prestazioneEstera.ContributiEERicalcolo;
                        if (contributiEERicalcolo.HasValue)
                            statoEstero.ContributiEERicalcolo = contributiEERicalcolo;

                        DateTime? decorrenzaLiquidazioneStatoEE = prestazioneEstera.DecorrenzaLiquidazioneStatoEE;
                        if (decorrenzaLiquidazioneStatoEE.HasValue)
                            statoEstero.DecorrenzaLiquidazioneStatoEE = decorrenzaLiquidazioneStatoEE;

                        char? sospensioneCautelativaIntegrazione = prestazioneEstera.SospensioneCautelativaIntegrazione;
                        if (sospensioneCautelativaIntegrazione.HasValue)
                            statoEstero.SospensioneCautelativaIntegrazione = sospensioneCautelativaIntegrazione;

                        byte? etaSospensione = prestazioneEstera.EtaSospensione;
                        if (etaSospensione.HasValue)
                            statoEstero.EtaSospensione = etaSospensione;

                        char? codiceArt48 = prestazioneEstera.CodiceArt48;
                        if (codiceArt48.HasValue)
                            statoEstero.CodiceArt48 = codiceArt48;

                        DateTime? decorrenzaArt48 = prestazioneEstera.DecorrenzaArt48;
                        if (decorrenzaArt48.HasValue)
                            statoEstero.DecorrenzaArt48 = decorrenzaArt48;

                        decimal? quotaIntegrazioneEEeArgentinaResidentiItalia = prestazioneEstera.QuotaIntegrazioneEEeArgentinaResidentiItalia;
                        if (quotaIntegrazioneEEeArgentinaResidentiItalia.HasValue)
                            statoEstero.QuotaIntegrazioneEEeArgentinaResidentiItalia = quotaIntegrazioneEEeArgentinaResidentiItalia;

                        DateTime? decorrenzaIntegrazione = prestazioneEstera.DecorrenzaIntegrazione;
                        if (decorrenzaIntegrazione.HasValue)
                            statoEstero.DecorrenzaIntegrazione = decorrenzaIntegrazione;

                        DateTime? decorrenzaRicalcolo = prestazioneEstera.DecorrenzaRicalcolo;
                        if (decorrenzaRicalcolo.HasValue)
                            statoEstero.DecorrenzaRicalcolo = decorrenzaRicalcolo;

                        GestioneDatiContributiviCi.SalvaPrestazioneEstera(statoEstero);
                    }
                }
            }
        }

        //ENG - RIC/TRF: aggiunta la gestione per il recupero degli stati(se presenti e diversi da quelli provenienti da prelievo) dal servizio Naci o AllegatiConvenzioni
        private static void ArchiviaDatiStatiEsteriPerRicTrf(List<ServiceReferences.LiquidazioneCi.GestioneContribStatoEstero> ListaStatiEsteriCi, List<GestioneDatiContributiviCi.PensioniCiPrestazioniEE> listaPrestazioniEE)
        {
            foreach (GestioneDatiContributiviCi.PensioniCiPrestazioniEE statoEstero in listaPrestazioniEE)
            {
                if (statoEstero != null)
                {
                    if (!ListaStatiEsteriCi.Exists(x => x.PrestazioneEstera.CodiceStatoEE == statoEstero.CodiceStatoEE && x.PrestazioneEstera.CodiceIstituzione == statoEstero.CodiceIstituzione))
                        GestioneDatiContributiviCi.SalvaPrestazioneEstera(statoEstero);
                }
            }
        }

