        private static void SalvaStatiEsteriCumulo(GestionePensione.DatiPensione datiPensione, GestioneAnagrafica.DatiAnagrafici datiAnagrafici, string matricolaOperatore, short sedeOperatore, short centroOperativoOperatore, object prelievo, out List<GestioneDatiEsteriCumulo.PensioneEsteraCumulo> listaPrestazioniEE, out string errori)
        {
            listaPrestazioniEE = null;
            List<GestioneDatiEsteriCumulo.PensioneImportiEsteriCumulo> listaImportiEsteri = null;
