        private static byte? GetTipoCalcoloFromData(Utility.TipoAppartenenza? tipoAppartenenza, ArrayList data, GestionePensione.DatiPensione datiPensione)
        {
            byte? tipoCalcolo = null;
            bool bContrib = false;
            bool bRetrib = false;
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiPensione.SiglaCategoria);
            List<Utility.TipoFondo> listaTipoFondoPECO_AMG = Utility.GetListaTipoFondo_PECO_Fondi_AMG();
            bool isGestioneAMG_Fondi_FSPT = false;
            if (ConfigurationManager.AppSettings["GestioneAMG_Fondi_FSPT"] != null &&
                ConfigurationManager.AppSettings["GestioneAMG_Fondi_FSPT"] == "SI")
                isGestioneAMG_Fondi_FSPT = true;

            switch (tipoAppartenenza)
            {
                case Utility.TipoAppartenenza.FS:
                    if (Utility.IsDomandaINPDAP(datiPensione.Gestione) || (isGestioneAMG_Fondi_FSPT && tipoFondo.HasValue && listaTipoFondoPECO_AMG.Contains(tipoFondo.Value)))
                    {
                        //contrib
                        if (!Utility.IsDoubleEquals(Convert.ToDouble(data[0]), 0.0) || !Utility.IsDoubleEquals(Convert.ToDouble(data[1]), 0.0) ||
                            !Utility.IsDoubleEquals(Convert.ToDouble(data[2]), 0.0) || !Utility.IsDoubleEquals(Convert.ToDouble(data[3]), 0.0))
                            bContrib = true;
                        //retrib
                        if (!String.IsNullOrEmpty(data[7].ToString().Trim()) || Convert.ToInt32(data[8]) != 0 ||
                            !Utility.IsDoubleEquals(Convert.ToDouble(data[9]), 0.0) || !Utility.IsDoubleEquals(Convert.ToDouble(data[10]), 0.0))
                            bRetrib = true;
                    }
                    else
                    {
                        // contrib
                        if (!Utility.IsDoubleEquals(Convert.ToDouble(data[0]), 0.0) || !Utility.IsDoubleEquals(Convert.ToDouble(data[1]), 0.0) ||
                            Convert.ToInt32(data[2]) != 0 || Convert.ToInt32(data[3]) != 0 || Convert.ToInt32(data[4]) != 0 || Convert.ToInt32(data[5]) != 0 ||
                            !Utility.IsDoubleEquals(Convert.ToDouble(data[6]), 0.0) || !Utility.IsDoubleEquals(Convert.ToDouble(data[7]), 0.0))
                            bContrib = true;
                        //retrib
                        if (!Utility.IsDoubleEquals(Convert.ToDouble(data[8]), 0) || Convert.ToInt32(data[9]) != 0 || !String.IsNullOrEmpty(data[10].ToString().Trim()))
                            bRetrib = true;
                    }

                    if (bContrib && bRetrib)
                        tipoCalcolo = 20;
                    else if (bContrib)
                        tipoCalcolo = 19;
                    else if (bRetrib)
                        tipoCalcolo = 18;

                    if (tipoCalcolo == 20 && Convert.ToString(data[12]) == "1" &&
                        ((DateTime?)data[11]).HasValue && DateTime.Compare(((DateTime?)data[11]).Value.Date, new DateTime(2012, 01, 01).Date) >= 0)
                        tipoCalcolo = 25;
                    break;
                case Utility.TipoAppartenenza.AGO:

                    //////// contrib
                    //////if (Convert.ToInt32(data[0]) != 0 || !String.IsNullOrEmpty(data[1].ToString().Trim()) || !String.IsNullOrEmpty(data[2].ToString().Trim()) ||
                    //////    Convert.ToDouble(data[3]) != 0.0 || Convert.ToDouble(data[4]) != 0.0)
                    //////    bContrib = true;
                    ////////retrib
                    //////if (Convert.ToInt32(data[5]) != 0 || !String.IsNullOrEmpty(data[6].ToString().Trim()) || !String.IsNullOrEmpty(data[7].ToString().Trim()) || Convert.ToDouble(data[8]) != 0.0)
                    //////    bRetrib = true;


                    //////if (bContrib && bRetrib)
                    //////    tipoCalcolo = 21;
                    //////else if (bContrib && !bRetrib)
                    //////    tipoCalcolo = 1;
                    //////else if (!bContrib && bRetrib)
                    //////    tipoCalcolo = 2;

                    if (data[0] != null && !string.IsNullOrEmpty(data[0].ToString()) && data[0].ToString().Trim() != string.Empty)
                    {
                        byte tipocalcoloApp = Convert.ToByte(data[0].ToString());
                        if (tipocalcoloApp == 0)
                            tipoCalcolo = 2;
                        else if (tipocalcoloApp == 1 || tipocalcoloApp == 3)
                            tipoCalcolo = 1;
                        else if (tipocalcoloApp == 2)
                        {
                            if (Convert.ToBoolean(data[1]))
                                tipoCalcolo = 21;
                            else
                            {
                                // Se non è una categoria INPDAI, ENPALS o INPDAP
                                if (!Convert.ToBoolean(data[3]))
                                {
                                    // Se è presente la quota B
                                    if (Convert.ToBoolean(data[2]))
                                    {
                                        if (Convert.ToInt32(data[4]) < 780)
                                            tipoCalcolo = 21;
                                        else
                                            tipoCalcolo = 2;
                                    }
                                    else
                                    {
                                        if (Convert.ToInt32(data[4]) < 936)
                                            tipoCalcolo = 21;
                                        else
                                            tipoCalcolo = 2;
                                    }
                                }
                                else
                                    tipoCalcolo = 2;
                            }
                        }
                    }
                    break;

                case Utility.TipoAppartenenza.CI:
                    //// contrib
                    //if (Convert.ToInt32(data[0]) != 0 || !String.IsNullOrEmpty(data[1].ToString().Trim()) || !String.IsNullOrEmpty(data[2].ToString().Trim()) ||
                    //    Convert.ToDouble(data[3]) != 0.0 || Convert.ToDouble(data[4]) != 0.0)
                    //    bContrib = true;
                    ////retrib
                    //if (Convert.ToInt32(data[5]) != 0 || !String.IsNullOrEmpty(data[6].ToString().Trim()) || !String.IsNullOrEmpty(data[7].ToString().Trim()) || Convert.ToDouble(data[8]) != 0.0)
                    //    bRetrib = true;

                    //if (bContrib && bRetrib)
                    //    tipoCalcolo = 24;
                    //else if (bContrib && !bRetrib)
                    //    tipoCalcolo = 22;
                    //else if (!bContrib && bRetrib)
                    //    tipoCalcolo = 23;
                    //break;
                    if (data[0] != null && !string.IsNullOrEmpty(data[0].ToString()) && data[0].ToString().Trim() != string.Empty)
                    {
                        byte tipocalcoloApp = Convert.ToByte(data[0].ToString());
                        if (tipocalcoloApp == 0)
                            tipoCalcolo = 23;
                        else if (tipocalcoloApp == 1 || tipocalcoloApp == 3)
                            tipoCalcolo = 22;
                        else if (tipocalcoloApp == 2)
                        {
                            if (Convert.ToBoolean(data[1]))
                                tipoCalcolo = 24;
                            else
                                tipoCalcolo = 23;
                        }
                    }
                    break;
            }


            return tipoCalcolo;
        }

        #region Benefici

        private static bool IsVisibleTabBenefici(Utility.TipoAppartenenza? tipoAppartenenza, GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda)
        {
            if (tipoAppartenenza.HasValue)
            {
                Utility.TipoDomanda? tipoDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);

                switch (tipoAppartenenza.Value)
                {
                    case Utility.TipoAppartenenza.AGO:
                        if ((datiPensione.Gruppo == "0002" && datiPensione.Prodotto == "0012") || //Pensione di Inabilità
                            (datiPensione.AttivitaEconomica.GetValueOrDefault() == 14 && datiPensione.ProfessioneIndividuale.GetValueOrDefault() == 190)) // Beneficio Amianto 181
                            return true;
                        else if (tipoDomanda == Utility.TipoDomanda.Ricostituzione || tipoDomanda == Utility.TipoDomanda.Ripristino || tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti || isRiaperturaDomanda)//pensione di ricostituzione + ripristino
                            return datiPensione.Benefici.HasValue ? datiPensione.Benefici.Value : false;
                        else
                            return false;
                    case Utility.TipoAppartenenza.CI:
                        if (datiPensione.Gruppo == "0002" && datiPensione.Prodotto == "0012")   //Pensione di Inabilità
                            return true;
                        else if (tipoDomanda == Utility.TipoDomanda.Ricostituzione || tipoDomanda == Utility.TipoDomanda.Ripristino || tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti || isRiaperturaDomanda)//pensione di ricostituzione + ripristino
                            return datiPensione.Benefici.HasValue ? datiPensione.Benefici.Value : false;
                        else
                            return false;

                    case Utility.TipoAppartenenza.FS:
                        if (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiaperturaDomanda)  //pensione di ricostituzione
                            return datiPensione.Benefici.HasValue ? datiPensione.Benefici.Value : false;
                        else
                            return false;
                }
            }
            return false;
        }

        #endregion Benefici

        #region Deroga
        private static bool IsDomandaConDerogaCorretta(Utility.TipoAppartenenza? tipoAppartenenza, GestionePensione.DatiPensione datiPensione,
            object datiAGGPECO, bool isRiaperturaDomanda,
            out List<GestioneOneri.DatiOneri> listaOneri,
            out List<GestioneBeneficiParticolari.DatiBeneficiParticolari> listaBeneficiParticolari,
            out bool isTabOneriVisible,
            out string errori, out DateTime? scadenzaBeneficioUnicarpe, GestioneControlliDinamici.ControlloDinamico ctrlMemo121_2023, GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024, GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib)
        {
            errori = string.Empty;
            listaOneri = null;
            listaBeneficiParticolari = null;
            isTabOneriVisible = false;
            Utility.TipoSalvaguardia TipoSalvaguardia = Utility.GetTipoSalvaguardia(datiPensione);
            scadenzaBeneficioUnicarpe = null;

            if (TipoSalvaguardia != Utility.TipoSalvaguardia.Nessuna)
            {
                DateTime? decPensione = datiPensione.DecorrenzaOriginaria;
                bool IsAutomatica = Utility.IsDomandaSalvaguardiaAutomatica(datiPensione);
                bool ControllaOneri = true;
                if (TipoSalvaguardia == Utility.TipoSalvaguardia.L122 || TipoSalvaguardia == Utility.TipoSalvaguardia.Contributivo_Optante || TipoSalvaguardia == Utility.TipoSalvaguardia.Bancari_Bonus)
                    ControllaOneri = false;
                Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensione, true);
                if (IsDatiDerogaPresent(datiPensione, IsAutomatica, tipoUnicarpe, tipoAppartenenza, datiAGGPECO,
                    TipoSalvaguardia, ControllaOneri, isRiaperturaDomanda,
                    out listaOneri, out listaBeneficiParticolari, out isTabOneriVisible, out errori, out scadenzaBeneficioUnicarpe, ctrlMemo121_2023, ctrlMemo123_2024, ctrlMemo123_2024OpzioneContrib))
                {
                    datiPensione.DecorrenzaOriginaria = decPensione;
                    return true;
                }
                else
                    return false;
            }

            return true;
        }

        private static bool IsDatiDerogaPresent(GestionePensione.DatiPensione datiPensione, bool IsAutomatica, Utility.TipoUnicarpe tipoUnicarpe,
            Utility.TipoAppartenenza? tipoAppartenenza, object datiAGGPECO, Utility.TipoSalvaguardia TipoSalvaguardia,
            bool ControllaOneri, bool isRiaperturaDomanda,
            out List<GestioneOneri.DatiOneri> listaOneri,
            out List<GestioneBeneficiParticolari.DatiBeneficiParticolari> listaBeneficiParticolari,
            out bool isTabOneriVisible,
            out string messaggioVideo, out DateTime? scadenzaBeneficioUnicarpe, GestioneControlliDinamici.ControlloDinamico ctrlMemo121_2023, GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024, GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib)
        {
            messaggioVideo = string.Empty;
            listaOneri = null;
            listaBeneficiParticolari = null;
            isTabOneriVisible = false;
            string descrizioneDomanda = TipoSalvaguardia == Utility.TipoSalvaguardia.Usuranti ? "Usuranti" : TipoSalvaguardia == Utility.TipoSalvaguardia.EsuberiPA ? "Esuberi" :
                TipoSalvaguardia == Utility.TipoSalvaguardia.APE_Precoci ? "Precoci" : "Salvaguardia";
            char? deroga = null;

            GestioneControlliDinamici.ControlloDinamico ctrlEliminazioneScartoOneri0031_0105_0112 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("EliminazioneScartoOneri0031_0105_0112", out ctrlEliminazioneScartoOneri0031_0105_0112);

            scadenzaBeneficioUnicarpe = null;

            //Contributivo Optante - Bypass controlli in caso di domanda automatica
            if ((TipoSalvaguardia == Utility.TipoSalvaguardia.Contributivo_Optante || TipoSalvaguardia == Utility.TipoSalvaguardia.Bancari_Bonus) && tipoUnicarpe == Utility.TipoUnicarpe.Automatica)
                return true;

            //se la domanda è automatica deve per forza esserci lettura unicarpe ad L
            if (IsAutomatica && tipoUnicarpe != Utility.TipoUnicarpe.Automatica && !(Utility.IsDomandaAPEPrecoci(datiPensione) && Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria)))
            {
                messaggioVideo = "Per la domanda di " + descrizioneDomanda +
                    " automatica che si sta tentando di acquisire, mancano le informazioni provenienti da Unicarpe. " +
                    "E' necessario lavorare correttamente la domanda da Unicarpe";
                return false;
            }

            if (!GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Acquisizione.NO_CERT_FELPE) && !(isRiaperturaDomanda && Utility.IsDomandaTipoContributivo(datiPensione, null, true)) && !Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) && !Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione))
            {
                if (datiAGGPECO == null)
                {
                    messaggioVideo = "Nessuna Certificazione Presente o Certificazione non valida per la domanda che si sta tentando di acquisire";
                    return false;
                }

                if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.FS)
                {
                    Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiPensione.SiglaCategoria);
                    List<Utility.TipoFondo> listaTipoFondoPECO_AMG = Utility.GetListaTipoFondo_PECO_Fondi_AMG();
                    bool isGestioneAMG_Fondi_FSPT = false;
                    if (ConfigurationManager.AppSettings["GestioneAMG_Fondi_FSPT"] != null &&
                        ConfigurationManager.AppSettings["GestioneAMG_Fondi_FSPT"] == "SI")
                        isGestioneAMG_Fondi_FSPT = true;

                    if (Utility.IsDomandaINPDAP(datiPensione.Gestione) && datiPensione.TipoFelpe == (byte)Utility.TipoFelpe.SIN || datiPensione.TipoFelpe == (byte)Utility.TipoFelpe.SPI)
                    {
                        ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_AMG_INPDAP datiAMG_INPDAP = (ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_AMG_INPDAP)datiAGGPECO;

                        if (datiAMG_INPDAP == null)
                        {
                            messaggioVideo = "Nessuna Certificazione Presente o Certificazione non valida per la domanda che si sta tentando di acquisire";
                            return false;
                        }

                        if (!Utility.IsDomandaAPEPrecoci(datiPensione))
                        {
                            if (TipoSalvaguardia != Utility.TipoSalvaguardia.Contributivo_Optante && TipoSalvaguardia != Utility.TipoSalvaguardia.Bancari_Bonus)
                            {
                                if (!IsCertificazioneInviata(datiAMG_INPDAP.A_Deroga, out messaggioVideo))
                                {
                                    messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                                    return false;
                                }
                            }

                            if (!IsDerogaCorretta(TipoSalvaguardia, datiAMG_INPDAP.A_Deroga, datiAMG_INPDAP.A_TipCert, out messaggioVideo))
                            {
                                messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                                return false;
                            }

                            deroga = char.Parse(datiAMG_INPDAP.A_Deroga);
                        }

                        PrelievoOneriBeneficiAMG_INPDAP(datiAMG_INPDAP, out listaOneri, out listaBeneficiParticolari, out isTabOneriVisible, out scadenzaBeneficioUnicarpe, ctrlMemo121_2023, datiPensione, ctrlMemo123_2024, ctrlMemo123_2024OpzioneContrib);
                    }
                    else if ((isGestioneAMG_Fondi_FSPT && tipoFondo.HasValue && listaTipoFondoPECO_AMG.Contains(tipoFondo.Value)) || datiPensione.TipoFelpe == (byte)Utility.TipoFelpe.AMG)
                    {
                        ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_AMG datiAMG = datiAGGPECO as ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_AMG;

                        if (datiAMG == null)
                        {
                            messaggioVideo = "Nessuna Certificazione Presente o Certificazione non valida per la domanda che si sta tentando di acquisire";
                            return false;
                        }

                        if (!Utility.IsDomandaAPEPrecoci(datiPensione))
                        {
                            deroga = char.Parse(datiAMG.A_Deroga);

                            if (TipoSalvaguardia != Utility.TipoSalvaguardia.Contributivo_Optante && TipoSalvaguardia != Utility.TipoSalvaguardia.Bancari_Bonus)
                            {
                                if (!IsCertificazioneInviata(deroga.ToString(), out messaggioVideo))
                                {
                                    messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                                    return false;
                                }
                            }

                            if (!IsDerogaCorretta(TipoSalvaguardia, deroga.ToString(), datiAMG.A_TipCert, out messaggioVideo))
                            {
                                messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                                return false;
                            }
                        }

                        PrelievoOneriBeneficiAMG(datiAMG, out listaOneri, out listaBeneficiParticolari, out isTabOneriVisible, out scadenzaBeneficioUnicarpe, ctrlMemo121_2023, datiPensione, ctrlMemo123_2024, ctrlMemo123_2024OpzioneContrib);
                    }
                    else
                    {
                        ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_Speciali datiFS = (ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_Speciali)datiAGGPECO;

                        if (datiFS == null)
                        {
                            messaggioVideo = "Nessuna Certificazione Presente o Certificazione non valida per la domanda che si sta tentando di acquisire";
                            return false;
                        }

                        if (!Utility.IsDomandaAPEPrecoci(datiPensione))
                        {
                            if (TipoSalvaguardia != Utility.TipoSalvaguardia.Contributivo_Optante && TipoSalvaguardia != Utility.TipoSalvaguardia.Bancari_Bonus)
                            {
                                if (!IsCertificazioneInviata(datiFS.F_Deroga, out messaggioVideo))
                                {
                                    messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                                    return false;
                                }
                            }

                            if (!IsDerogaCorretta(TipoSalvaguardia, datiFS.F_Deroga, datiFS.F_TipCert, out messaggioVideo))
                            {
                                messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                                return false;
                            }

                            deroga = char.Parse(datiFS.F_Deroga);
                        }

                        PrelievoOneriBeneficiFS(datiFS, out listaOneri, out listaBeneficiParticolari, out isTabOneriVisible, out scadenzaBeneficioUnicarpe, ctrlMemo121_2023, datiPensione, ctrlMemo123_2024, ctrlMemo123_2024OpzioneContrib);
                    }
                }
                else if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO)
                {
                    ServiceReferences.AggPec.csAggiornamentoPECO_AGO datiAGO = (ServiceReferences.AggPec.csAggiornamentoPECO_AGO)datiAGGPECO;

                    if (datiAGO == null)
                    {
                        messaggioVideo = "Nessuna Certificazione Presente o Certificazione non valida per la domanda che si sta tentando di acquisire";
                        return false;
                    }

                    if (!Utility.IsDomandaAPEPrecoci(datiPensione))
                    {
                        if (TipoSalvaguardia != Utility.TipoSalvaguardia.Contributivo_Optante && TipoSalvaguardia != Utility.TipoSalvaguardia.Bancari_Bonus)
                        {
                            if (!IsCertificazioneInviata(datiAGO.PL_Deroga, out messaggioVideo))
                            {
                                messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                                return false;
                            }
                        }

                        if (!IsDerogaCorretta(TipoSalvaguardia, datiAGO.PL_Deroga, datiAGO.PL_TipCert, out messaggioVideo))
                        {
                            messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                            return false;
                        }

                        deroga = char.Parse(datiAGO.PL_Deroga);
                    }

                    PrelievoOneriBeneficiAGO(datiAGO, out listaOneri, out listaBeneficiParticolari, out isTabOneriVisible, out scadenzaBeneficioUnicarpe, ctrlMemo121_2023, datiPensione, ctrlMemo123_2024, ctrlMemo123_2024OpzioneContrib);
                }
                else if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.CI)
                {
                    ServiceReferences.AggPec.csAggiornamentoPECO_Convenzioni_Internazionali datiCI = (ServiceReferences.AggPec.csAggiornamentoPECO_Convenzioni_Internazionali)datiAGGPECO;

                    if (datiCI == null)
                    {
                        messaggioVideo = "Nessuna Certificazione Presente o Certificazione non valida per la domanda che si sta tentando di acquisire";
                        return false;
                    }

                    if (!Utility.IsDomandaAPEPrecoci(datiPensione))
                    {
                        if (TipoSalvaguardia != Utility.TipoSalvaguardia.Contributivo_Optante && TipoSalvaguardia != Utility.TipoSalvaguardia.Bancari_Bonus)
                        {
                            if (!IsCertificazioneInviata(datiCI.CI_Deroga, out messaggioVideo))
                            {
                                messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                                return false;
                            }
                        }

                        if (!IsDerogaCorretta(TipoSalvaguardia, datiCI.CI_Deroga, datiCI.CI_TipCert, out messaggioVideo))
                        {
                            messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                            return false;
                        }

                        deroga = char.Parse(datiCI.CI_Deroga);
                    }

                    PrelievoOneriBeneficiCI(datiCI, out listaOneri, out listaBeneficiParticolari, out isTabOneriVisible, out scadenzaBeneficioUnicarpe, ctrlMemo121_2023, datiPensione, ctrlMemo123_2024, ctrlMemo123_2024OpzioneContrib);
                }
                else
                    return false;
            }

            if (!IsDerogaCorretta(TipoSalvaguardia, listaBeneficiParticolari, out messaggioVideo))
            {
                messaggioVideo = "Domanda di " + descrizioneDomanda + ". " + messaggioVideo;
                return false;
            }

            if (Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && isRiaperturaDomanda && Utility.IsDomandaAPEPrecoci(datiPensione))
                listaBeneficiParticolari = new List<GestioneBeneficiParticolari.DatiBeneficiParticolari>();

            if (listaOneri != null && listaOneri.Count > 0)
            {
                // Commento dovuto ad anomal segnalata 05-06-2015: se da Unicarpe non ci arriva la decorrenzaPensione 
                // lanciamo un errore anzichè provare a valorizzarla con la decorrenzaOnere (Oggetto Mail: produzione sede di Pistoia  SRFGNN53E43D617X) 
                //if (listaOneri[0].Decorrenza.HasValue && !decPensione.HasValue)
                //    decPensione = listaOneri[0].Decorrenza;

                if (IsAutomatica)
                {
                    List<GestioneDecodifica.GruppoOneri> listaGruppoOneriDB = null;
                    GestioneDecodifica.GetGruppoOneri(out listaGruppoOneriDB);
                    DateTime? scadenzaOnerePrecedente = null;
                    GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare = null;
                    GestioneAnagrafica.GetAnagraficaByIdPensione(datiPensione.Id, out datiAnagraficiTitolare);

                    bool isDomandaAutomatica = datiPensione.CodiceTipoRichiesta == "S1";
                    if (isDomandaAutomatica && Utility.IsDomandaAPEPrecoci(datiPensione) && Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria))
                    {
                        string errori = string.Empty;
                        ServiceReferences.TotalIvs.clsDatiCumulo risposta = null;
                        if (!GestioneTotalIvs.GetDatiCumulIVS(datiPensione.NDomus, out risposta, out errori))
                            throw new INPS.DNA.DnaValidationException(errori);
                        if (!isRiaperturaDomanda)
                        {
                            if (risposta != null && risposta.objDomanda != null)
                            {
                                DateTime? fineIncumulabilita = risposta.objDomanda.DataFineIncumulabilita;
                                DateTime? fineOneri = risposta.objDomanda.DataFineOneri;

                                if (fineIncumulabilita == null || fineOneri == null)
                                {
                                    messaggioVideo = "Per la domanda di " + descrizioneDomanda +
                                    " che si sta tentando di acquisire, Scadenza Onere o Cess. Incumulabilità non valorizzati" +
                                    ". E' necessario lavorare correttamente la domanda dal Servizio del Cumulo.";
                                    return false;
                                }
                                else
                                {
                                    listaOneri.ForEach(x =>
                                    {
                                        x.ScadenzaBeneficio = fineIncumulabilita.Value;
                                        x.Scadenza = fineOneri.Value;
                                    });
                                }
                            }
                        }
                    }
                    else
                    {
                        foreach (GestioneOneri.DatiOneri onere in listaOneri)
                        {
                            string codGruppoOnere = listaGruppoOneriDB.Find(x => x.Id == onere.IdCodeGruppo).Code;

                            List<GestioneDecodifica.SottoGruppoOneri> elencoSottoGruppoOneri = null;
                            GestioneDecodifica.GetSottoGruppoOneri(out elencoSottoGruppoOneri);
                            GestioneDecodifica.SottoGruppoOneri SottoGruppoOnereDec = elencoSottoGruppoOneri.Find(x => x.Id == onere.IdCodeSottoGruppo);

                            if (!GestioneCrossControls.ALL_VerificaDecorrenzeOneri(datiPensione, codGruppoOnere, onere.Decorrenza, onere.Scadenza, onere.ScadenzaBeneficio, deroga, isRiaperturaDomanda, SottoGruppoOnereDec.Code, scadenzaOnerePrecedente, datiAnagraficiTitolare, tipoAppartenenza, ctrlEliminazioneScartoOneri0031_0105_0112, out messaggioVideo))
                            {
                                messaggioVideo = "Per la domanda di " + descrizioneDomanda +
                                " che si sta tentando di acquisire, " + messaggioVideo +
                                ". E' necessario lavorare correttamente la domanda da Unicarpe";
                                return false;
                            }
                            scadenzaOnerePrecedente = onere.Scadenza;
                        }
                    }
                }
                return true;
            }
            else if (ControllaOneri && !Utility.IsDomandaENPALS(datiPensione.Gestione) && datiPensione != null && datiPensione.IdTipoPLPerRIC != null && datiPensione.TipoLetturaUnicarpe.HasValue &&
                !(datiPensione.IdTipoPLPerRIC == 1 && datiPensione.TipoLetturaUnicarpe == 'G'))
            {
                messaggioVideo = "Oneri non presenti per la domanda di " + descrizioneDomanda +
                    " automatica che si sta tentando di acquisire. " +
                    "E' necessario lavorare correttamente la domanda da Unicarpe";
                return false;
            }

            return true;
        }

        private static bool IsDecorrenzaPresenteForLetturaL(char? tipoLettura, DateTime? decorrenzaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (tipoLettura == 'L' && !decorrenzaPensione.HasValue)
            {
                messaggioVideo = "Decorrenza pensione non proveniente da Unicarpe.";
                return false;
            }
            return true;
        }

        private static bool IsDerogaCorretta(Utility.TipoSalvaguardia TipoSalvaguardia, string deroga, string tipoCertificazione, out string messaggioVideo)
        {
            messaggioVideo = "Deroga '" + deroga + "' errata per " + Utility.GetDescription(TipoSalvaguardia);

            switch (TipoSalvaguardia)
            {
                case Utility.TipoSalvaguardia.L214:
                    if (deroga != "5" && deroga != "6" && deroga != "7" && deroga != "8")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.L124Art11Bis:
                    if (deroga != "E" && deroga != "F")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.L122:
                    if (deroga != "3" && deroga != "5")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.L124:
                    if (deroga != "C" && deroga != "D")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.L135:
                    if (deroga != "9" && deroga != "N")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.L228:
                    if (deroga != "A" && deroga != "B")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.L147:
                    if (deroga != "G" && deroga != "H")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.Usuranti:
                    if (deroga != "3")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.EsuberiPA:
                    if (deroga != "M")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.L147_2014:
                    if (deroga != "I" && deroga != "L")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.L208_2015:
                    if (deroga != "O" && deroga != "P")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.L232_2016:
                    if (deroga != "Q" && deroga != "R")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.APE_Precoci:
                    if (deroga != "S")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.Contributivo_Optante:
                    if (string.IsNullOrEmpty(tipoCertificazione) || tipoCertificazione.Trim().ToUpper() != "OPZ")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.L178_2020:
                    if (deroga != "S" && deroga != "T")
                        return false;
                    break;
                case Utility.TipoSalvaguardia.Bancari_Bonus:
                    if (string.IsNullOrEmpty(tipoCertificazione) || tipoCertificazione.Trim().ToUpper() != "BON")
                        return false;
                    break;
            }

            messaggioVideo = string.Empty;
            return true;
        }

        private static bool IsDerogaCorretta(Utility.TipoSalvaguardia TipoSalvaguardia, List<GestioneBeneficiParticolari.DatiBeneficiParticolari> listaBeneficiParticolari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            switch (TipoSalvaguardia)
            {
                case Utility.TipoSalvaguardia.APE_Precoci:
                    if (listaBeneficiParticolari == null || !listaBeneficiParticolari.Exists(x => x.CodiceBenefici == "11"))
                    {
                        messaggioVideo = "Beneficio non presente per la domanda di APE Precoci.";
                        return false;
                    }
                    break;
            }

            return true;
        }

        private static void PrelievoOneriBeneficiFS(ServiceReferences.AggPec.csAggiornamentoPECO_Fondi_Speciali dati, out List<GestioneOneri.DatiOneri> listaOneri,
            out List<GestioneBeneficiParticolari.DatiBeneficiParticolari> listaBeneficiParticolari, out bool isTabOneriVisible, out DateTime? scadenzaBeneficioUnicarpe, GestioneControlliDinamici.ControlloDinamico ctrlMemo121_2023, GestionePensione.DatiPensione datiPensione, GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024, GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib)
        {
            listaOneri = null;
            listaBeneficiParticolari = null;
            isTabOneriVisible = false;
            scadenzaBeneficioUnicarpe = null;

            if (dati != null && dati.aONERI_FS != null && dati.aONERI_FS.Count() > 0)
            {
                List<GestioneDecodifica.GruppoOneri> elencoGruppoOneri = null;
                GestioneDecodifica.GetGruppoOneri(out elencoGruppoOneri);

                List<GestioneDecodifica.SottoGruppoOneri> elencoSottoGruppoOneri = null;
                GestioneDecodifica.GetSottoGruppoOneri(out elencoSottoGruppoOneri);

                for (int i = 0; i < dati.aONERI_FS.Count(); i++)
                {
                    GestioneDecodifica.GruppoOneri GruppoOnereDec = elencoGruppoOneri.Find(x => x.Code == dati.aONERI_FS[i].F_CodGrup);
                    GestioneDecodifica.SottoGruppoOneri SottoGruppoOnereDec = elencoSottoGruppoOneri.Find(x => x.Code == dati.aONERI_FS[i].F_CodSGrup);

                    if (GruppoOnereDec != null && SottoGruppoOnereDec != null)
                    {
                        GestioneOneri.DatiOneri onere = new GestioneOneri.DatiOneri();

                        if (GruppoOnereDec != null)
                            onere.IdCodeGruppo = GruppoOnereDec.Id;

                        if (SottoGruppoOnereDec != null)
                            onere.IdCodeSottoGruppo = SottoGruppoOnereDec.Id;

                        if (!String.IsNullOrEmpty(dati.aONERI_FS[i].F_DecOnere) && dati.aONERI_FS[i].F_DecOnere.Trim() != string.Empty)
                        {
                            if (dati.aONERI_FS[i].F_DecOnere.Trim().Length == 8)
                                onere.Decorrenza = Utility.DataFromString(dati.aONERI_FS[i].F_DecOnere, Utility.FormatoData.AAAAmmGG);
                            else
                                onere.Decorrenza = Utility.DataFromInt(short.Parse(dati.aONERI_FS[i].F_DecOnere.Substring(0, 4)), short.Parse(dati.aONERI_FS[i].F_DecOnere.Substring(4, 2)), 1);
                        }

                        if (!Utility.IsDoubleEquals(dati.aONERI_FS[i].F_Onere, 0.0))
                            onere.Onere = Convert.ToDecimal(dati.aONERI_FS[i].F_Onere);

                        if (!String.IsNullOrEmpty(dati.aONERI_FS[i].F_Scadenza) && dati.aONERI_FS[i].F_Scadenza.Trim() != string.Empty)
                        {
                            if (dati.aONERI_FS[i].F_Scadenza.Trim().Length == 8)
                                onere.Scadenza = Utility.DataFromString(dati.aONERI_FS[i].F_Scadenza, Utility.FormatoData.AAAAmmGG);
                            else
                                onere.Scadenza = Utility.DataFromInt(short.Parse(dati.aONERI_FS[i].F_Scadenza.Substring(0, 4)), short.Parse(dati.aONERI_FS[i].F_Scadenza.Substring(4, 2)), 1);
                        }

                        if (dati.aONERI_FS[i].F_AnzCon != 0)
                            onere.Settimane = Convert.ToInt16(dati.aONERI_FS[i].F_AnzCon);

                        if (dati.F_Decinc != 0)
                        {
                            if (dati.F_Decinc.ToString().Length == 8)
                                onere.ScadenzaBeneficio = Utility.DataFromString(dati.F_Decinc.ToString(), Utility.FormatoData.AAAAmmGG);
                            else
                                onere.ScadenzaBeneficio = Utility.DataFromInt(short.Parse(dati.F_Decinc.ToString().Substring(0, 4)), short.Parse(dati.F_Decinc.ToString().Substring(4, 2)), 1);
                        }

                        if (listaOneri == null)
                            listaOneri = new List<GestioneOneri.DatiOneri>();
                        listaOneri.Add(onere);
                    }

                    if (dati.aONERI_FS[i].F_CodBenef != null && dati.aONERI_FS[i].F_CodBenef.Trim() != string.Empty)
                    {
                        GestioneBeneficiParticolari.DatiBeneficiParticolari datiBeneficiParticolari = new GestioneBeneficiParticolari.DatiBeneficiParticolari();
                        datiBeneficiParticolari.CodiceBenefici = dati.aONERI_FS[i].F_CodBenef;
                        if (dati.aONERI_FS[i].F_AnzBenef != 0)
                            datiBeneficiParticolari.Settimane = Convert.ToInt16(dati.aONERI_FS[i].F_AnzBenef);

                        if (listaBeneficiParticolari == null)
                            listaBeneficiParticolari = new List<GestioneBeneficiParticolari.DatiBeneficiParticolari>();
                        listaBeneficiParticolari.Add(datiBeneficiParticolari);
                    }
                }
            }

            if (dati != null && (listaOneri == null || listaOneri.Count == 0))
            {
                if ((ctrlMemo121_2023 != null && !String.IsNullOrEmpty(ctrlMemo121_2023.ValoreControllo) && ctrlMemo121_2023.ValoreControllo.Trim().ToUpperInvariant() == "SI"
                    && (Utility.IsDomandaQuota100(datiPensione) || Utility.IsDomandaQuota102(datiPensione) || Utility.IsDomandaAnticipataFlessibile(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione))
                    && Utility.IsDomandaAutomatica(datiPensione) && Utility.IsRicostituzione(datiPensione.Gruppo)) ||
                    (((ctrlMemo123_2024 != null && !String.IsNullOrEmpty(ctrlMemo123_2024.ValoreControllo) && ctrlMemo123_2024.ValoreControllo.Trim().ToUpperInvariant() == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) ||
                    (ctrlMemo123_2024OpzioneContrib != null && !String.IsNullOrEmpty(ctrlMemo123_2024OpzioneContrib.ValoreControllo) && ctrlMemo123_2024OpzioneContrib.ValoreControllo.Trim().ToUpperInvariant() == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))
                    && Utility.IsDomandaAutomatica(datiPensione) && Utility.IsRicostituzione(datiPensione.Gruppo)))
                {
                    if (dati.F_Decinc != 0)
                    {
