            out List<GestioneBeneficiParticolari.DatiBeneficiParticolari> listaBeneficiParticolari, out bool isTabOneriVisible, out DateTime? scadenzaBeneficioUnicarpe, GestioneControlliDinamici.ControlloDinamico ctrlMemo121_2023, GestionePensione.DatiPensione datiPensione, GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024, GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib)
        {
            listaOneri = null;
            listaBeneficiParticolari = null;
            isTabOneriVisible = false;
            scadenzaBeneficioUnicarpe = null;

            if (dati != null && dati.aONERI_CI != null && dati.aONERI_CI.Count() > 0)
            {
                List<GestioneDecodifica.GruppoOneri> elencoGruppoOneri = null;
                GestioneDecodifica.GetGruppoOneri(out elencoGruppoOneri);

                List<GestioneDecodifica.SottoGruppoOneri> elencoSottoGruppoOneri = null;
                GestioneDecodifica.GetSottoGruppoOneri(out elencoSottoGruppoOneri);

                for (int i = 0; i < dati.aONERI_CI.Count(); i++)
                {
                    GestioneDecodifica.GruppoOneri GruppoOnereDec = elencoGruppoOneri.Find(x => x.Code == dati.aONERI_CI[i].CI_CodGrup);
                    GestioneDecodifica.SottoGruppoOneri SottoGruppoOnereDec = elencoSottoGruppoOneri.Find(x => x.Code == dati.aONERI_CI[i].CI_CodSGrup);

                    if (GruppoOnereDec != null && SottoGruppoOnereDec != null)
                    {
                        GestioneOneri.DatiOneri onere = new GestioneOneri.DatiOneri();

                        if (GruppoOnereDec != null)
                            onere.IdCodeGruppo = GruppoOnereDec.Id;

                        if (SottoGruppoOnereDec != null)
                            onere.IdCodeSottoGruppo = SottoGruppoOnereDec.Id;

                        if (!String.IsNullOrEmpty(dati.aONERI_CI[i].CI_DecOnere) && dati.aONERI_CI[i].CI_DecOnere.Trim() != string.Empty)
                        {
                            if (dati.aONERI_CI[i].CI_DecOnere.Trim().Length == 8)
                                onere.Decorrenza = Utility.DataFromString(dati.aONERI_CI[i].CI_DecOnere, Utility.FormatoData.AAAAmmGG);
                            else
                                onere.Decorrenza = Utility.DataFromInt(short.Parse(dati.aONERI_CI[i].CI_DecOnere.Substring(0, 4)), short.Parse(dati.aONERI_CI[i].CI_DecOnere.Substring(4, 2)), 1);
                        }

                        if (!Utility.IsDoubleEquals(dati.aONERI_CI[i].CI_Onere, 0.0))
                            onere.Onere = Convert.ToDecimal(dati.aONERI_CI[i].CI_Onere);

                        if (!String.IsNullOrEmpty(dati.aONERI_CI[i].CI_ScadenzaA) && dati.aONERI_CI[i].CI_ScadenzaA.Trim() != string.Empty)
                        {
                            if (dati.aONERI_CI[i].CI_ScadenzaA.Trim().Length == 8)
                                onere.Scadenza = Utility.DataFromString(dati.aONERI_CI[i].CI_ScadenzaA, Utility.FormatoData.AAAAmmGG);
                            else
                                onere.Scadenza = Utility.DataFromInt(short.Parse(dati.aONERI_CI[i].CI_ScadenzaA.Substring(0, 4)), short.Parse(dati.aONERI_CI[i].CI_ScadenzaA.Substring(4, 2)), 1);
                        }

                        if (dati.aONERI_CI[i].CI_AnzCon != 0)
                            onere.Settimane = Convert.ToInt16(dati.aONERI_CI[i].CI_AnzCon);

                        if (dati.CI_Decinc != 0)
                        {
                            if (dati.CI_Decinc.ToString().Length == 8)
                                onere.ScadenzaBeneficio = Utility.DataFromString(dati.CI_Decinc.ToString(), Utility.FormatoData.AAAAmmGG);
                            else
                                onere.ScadenzaBeneficio = Utility.DataFromInt(short.Parse(dati.CI_Decinc.ToString().Substring(0, 4)), short.Parse(dati.CI_Decinc.ToString().Substring(4, 2)), 1);
                        }

                        if (listaOneri == null)
                            listaOneri = new List<GestioneOneri.DatiOneri>();
                        listaOneri.Add(onere);
                    }

                    if (dati.aONERI_CI[i].CI_CodBenef != null && dati.aONERI_CI[i].CI_CodBenef.Trim() != string.Empty)
                    {
                        GestioneBeneficiParticolari.DatiBeneficiParticolari datiBeneficiParticolari = new GestioneBeneficiParticolari.DatiBeneficiParticolari();
                        datiBeneficiParticolari.CodiceBenefici = dati.aONERI_CI[i].CI_CodBenef;
                        if (dati.aONERI_CI[i].CI_AnzBenef != 0)
                            datiBeneficiParticolari.Settimane = Convert.ToInt16(dati.aONERI_CI[i].CI_AnzBenef);

                        if (listaBeneficiParticolari == null)
                            listaBeneficiParticolari = new List<GestioneBeneficiParticolari.DatiBeneficiParticolari>();
                        listaBeneficiParticolari.Add(datiBeneficiParticolari);
                    }
                }
            }

            if (dati != null && (listaOneri == null || listaOneri.Count == 0))
            {
                if ((ctrlMemo121_2023 != null && !String.IsNullOrEmpty(ctrlMemo121_2023.ValoreControllo) && ctrlMemo121_2023.ValoreControllo.Trim().ToUpperInvariant() == "SI"
                    && (Utility.IsDomandaQuota100(datiPensione) || Utility.IsDomandaQuota102(datiPensione) || Utility.IsDomandaAnticipataFlessibile(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione))
                    && Utility.IsDomandaAutomatica(datiPensione) && Utility.IsRicostituzione(datiPensione.Gruppo)) ||
                    (((ctrlMemo123_2024 != null && !String.IsNullOrEmpty(ctrlMemo123_2024.ValoreControllo) && ctrlMemo123_2024.ValoreControllo.Trim().ToUpperInvariant() == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) ||
                    (ctrlMemo123_2024OpzioneContrib != null && !String.IsNullOrEmpty(ctrlMemo123_2024OpzioneContrib.ValoreControllo) && ctrlMemo123_2024OpzioneContrib.ValoreControllo.Trim().ToUpperInvariant() == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))
                    && Utility.IsDomandaAutomatica(datiPensione) && Utility.IsRicostituzione(datiPensione.Gruppo)))
                {
                    if (dati.CI_Decinc != 0)
                    {
                        if (dati.CI_Decinc.ToString().Length == 8)
                            scadenzaBeneficioUnicarpe = Utility.DataFromString(dati.CI_Decinc.ToString(), Utility.FormatoData.AAAAmmGG);
                        else
                            scadenzaBeneficioUnicarpe = Utility.DataFromInt(short.Parse(dati.CI_Decinc.ToString().Substring(0, 4)), short.Parse(dati.CI_Decinc.ToString().Substring(4, 2)), 1);
                    }
                }
            }


            if ((listaOneri != null && listaOneri.Count > 0) || (listaBeneficiParticolari != null && listaBeneficiParticolari.Count > 0))
                isTabOneriVisible = true;
        }
        #endregion Deroga

        #region Certificazione
        private static bool IsCertificazioneInviata(string deroga, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            switch (deroga)
            {
                case "4":
                    // if (deroga == 4)
                    messaggioVideo = "La certificazione non risulta inviata";
                    return false;
                case "3":
                case "5":
                case "6":
                case "7":
                case "8":
                case "9":
                case "A":
                case "B":
                case "C":
                case "D":
                case "E":
                case "F":
                case "G":
                case "H":
                case "I":
                case "L":
                case "M":
                case "N":
                case "O":
                case "P":
                case "Q":
                case "R":
                case "S":
                case "T":
                    return true;
                default:
                    messaggioVideo = "Tipologia domanda non compatibile con i dati presenti su Felpe";
                    return false;
            }
        }
        #endregion Certificazione

        private static bool IsDomandaLIPE(GestionePensione.DatiPensione datiPensione, bool isDiretta, out string errori)
        {
            errori = string.Empty;
            if (Utility.IsDomandaLIPE(datiPensione, isDiretta))
            {
                errori = "Domanda da lavorare con la procedura LIPE.";
                return true;
            }
            return false;
        }

        private static bool PrelevaFs(Entity.ParametriARCA parametriArca, ServiceReferences.WebDom.DatiDomanda datiDomanda, short sedeOperatore, short centroOperativoOperatore,
            Entity.ParametriARCA parametriARCA, Utility.TipoDomanda tipoDomanda, GestionePensione.DatiPensione datiPensione,
            ref GestioneLavorazione.DatiLavorazione datiLavorazione, ref string chiavePensione, out Entity.Anagrafica anagraficaDA,
            out BLCommon.GestioneDanteCausa.DatiDanteCausa danteCausa, out object prelievo, out bool isRicRev, out bool isDiretta,
            out bool isResEsteroPerRic, out bool isSupplementiPerRic, out string errori,
            out bool mostraPanelloMessBloccantePensioniOvunque, out string sedePensioneGP1ALZ6, out string codCategoriaPensione)
        {
            bool isRiapertura = false;
            anagraficaDA = null;
            danteCausa = null;
            isRicRev = false;
            isDiretta = false;
            isResEsteroPerRic = false;
            isSupplementiPerRic = false;
            errori = "";
            datiLavorazione = new GestioneLavorazione.DatiLavorazione();
            prelievo = null;
            long NDomus;
            ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFs = null;
            int? nCertificato = null;
            string numDomanda = datiDomanda.Dati.Domanda[0].NumDomanda;
            List<Entity.Pensione> elencoPensioniDA = null;

            GestioneControlliDinamici.ControlloDinamico ctrlSpacchettate024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneSpacchettate024", out ctrlSpacchettate024);

            //ENG - Pensioni Ovunque: gestione nuovo pannello
            mostraPanelloMessBloccantePensioniOvunque = false;
            sedePensioneGP1ALZ6 = string.Empty;
            codCategoriaPensione = string.Empty;

            if (datiDomanda.Dati != null && datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Count > 0)
                isRiapertura = Utility.IsRiaperturaDomanda(datiDomanda.Dati.Fase.LastOrDefault().CodFase);

            short sedePensione = 0;
            int numeroCertificato = 0;
            if (isRiapertura)
            {
                ServiceReferences.WebDom.DataSetDomanda.PensioneGenerataRow pensioneGenerata = datiDomanda.Dati.PensioneGenerata.FirstOrDefault(x => x.IndAnnullata == "0");
                sedePensione = short.Parse(pensioneGenerata.CodProvinciaGenAttuale.Substring(1) + pensioneGenerata.CodZonaGenAttuale.Substring(1));
                numeroCertificato = int.Parse(pensioneGenerata.NumCertificatoGenAttuale);
                if (!GestioneLiquidazioneFs.PrelevaDomanda(numDomanda, sedePensione, short.Parse(pensioneGenerata.CodCatPensioneGenAttuale),
                    int.Parse(pensioneGenerata.NumCertificatoGenAttuale), sedeOperatore, centroOperativoOperatore, datiDomanda.Dati.Istanza[0].CodGruppo,
                    datiDomanda.Dati.Istanza[0].CodProdotto, datiDomanda.Dati.Istanza[0].CodTipo, isRiapertura, datiDomanda.Dati.Istanza[0].SiglaCatLav, out prelievoFs, out errori))
                    return true;
                else
                    prelievo = prelievoFs;
                nCertificato = int.Parse(pensioneGenerata.NumCertificatoGenAttuale);
            }
            else
            {
                //caso reversibilità indiretta (no FSPR)
                if (!(tipoDomanda == Utility.TipoDomanda.Superstiti && (datiDomanda.Dati.PensioneRiferimento.Rows.Count == 0 || isPensioneRiferimentoNull(datiDomanda.Dati.PensioneRiferimento[0]))))
                {
                    sedePensione = short.Parse(datiDomanda.Dati.PensioneRiferimento[0].CodProvinciaRifAttuale.Substring(1) + datiDomanda.Dati.PensioneRiferimento[0].CodZonaRifAttuale.Substring(1));
                    numeroCertificato = int.Parse(datiDomanda.Dati.PensioneRiferimento[0].NumCertificatoRifAttuale);
                    if (!GestioneLiquidazioneFs.PrelevaDomanda(numDomanda, sedePensione, short.Parse(datiDomanda.Dati.PensioneRiferimento[0].CodCatPensioneRifAttuale),
                        int.Parse(datiDomanda.Dati.PensioneRiferimento[0].NumCertificatoRifAttuale), sedeOperatore, centroOperativoOperatore, datiDomanda.Dati.Istanza[0].CodGruppo,
                        datiDomanda.Dati.Istanza[0].CodProdotto, datiDomanda.Dati.Istanza[0].CodTipo, isRiapertura, datiDomanda.Dati.Istanza[0].SiglaCatLav, out prelievoFs, out errori))
                        return true;
                    else
                        prelievo = prelievoFs;
                    nCertificato = int.Parse(datiDomanda.Dati.PensioneRiferimento[0].NumCertificatoRifAttuale);
                }
            }

            if (tipoDomanda == Utility.TipoDomanda.Superstiti && !isRiapertura)
            {
                GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
                richiestaArca.Applicazione = parametriARCA.Applicazione;
                richiestaArca.Matricola = parametriARCA.Matricola;
                richiestaArca.Provenienza = parametriARCA.Provenienza;
                richiestaArca.Ruolo = parametriARCA.Ruolo;

                //per reversibilità indiretta recupero codice fiscale DC da WebDom altrimenti da FSPR
                if ((datiDomanda.Dati.PensioneRiferimento.Rows.Count == 0 || isPensioneRiferimentoNull(datiDomanda.Dati.PensioneRiferimento[0])))
                {
                    DataRow[] RelSoggDC = datiDomanda.Dati.RelazioneSoggetto.Select("CodRelazioneSoggetto = 'DA'");
                    DataRow[] SoggDC = datiDomanda.Dati.Soggetto.Select("IdSoggetto = '" + RelSoggDC[0]["IdSoggetto"] + "'");

                    richiestaArca.CodiceFiscaleRichiedente = SoggDC[0]["CodiceFiscale"].ToString();
                    richiestaArca.CodiceFiscale = SoggDC[0]["CodiceFiscale"].ToString();

                    danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                    danteCausa.DecorrenzaPensione = null;
                    danteCausa.Sede = null;
                    danteCausa.Certificato = null;
                    danteCausa.SiglaCategoria = null;
                }
                else
                {
                    isDiretta = true;
                    danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                    if (prelievoFs != null && prelievoFs.Risposta != null)
                    {
                        richiestaArca.CodiceFiscaleRichiedente = prelievoFs.Risposta.CodiceFiscale;
                        richiestaArca.CodiceFiscale = prelievoFs.Risposta.CodiceFiscale;

                        danteCausa.DecorrenzaPensione = prelievoFs.Risposta.DataDecorrenza;
                        danteCausa.Sede = prelievoFs.Richiesta._Sede.ToString().PadLeft(4, '0');
                        danteCausa.Certificato = prelievoFs.Richiesta._Certificato;
                        //nuova gestione di recupero Sigla categoria
                        danteCausa.SiglaCategoria = prelievoFs.Risposta.SiglaCategoriaPensioneReversibilita;// datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav.Trim().ToUpperInvariant();
                    }
                }

                if (!GestioneARCA.GetAreaArcaByCodiceFiscale(richiestaArca, datiPensione.NDomus.ToString(), out anagraficaDA, out elencoPensioniDA, out errori) || !string.IsNullOrEmpty(errori))
                    return false;

                danteCausa.DataMorte = anagraficaDA.DataMorte;
                danteCausa.DataMorteOrigine = anagraficaDA.DataMorte;

                if (prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiAnagDanteCausa != null)
                    anagraficaDA.DataMatrimonio = prelievoFs.Risposta.DatiAnagDanteCausa.DataMatrimonio;

                if (datiDomanda.Dati.Istanza[0].CodProdotto == "0021")
                {
                    datiLavorazione.TipoReversibilita = 'R';
                    datiLavorazione.TipoLiquidazione = "A2";
                }
                else if (datiDomanda.Dati.Istanza[0].CodProdotto == "0022")
                {
                    datiLavorazione.TipoReversibilita = 'I';
                    datiLavorazione.TipoLiquidazione = "A1";
                }

            }
            else if (tipoDomanda == Utility.TipoDomanda.Ricostituzione || tipoDomanda == Utility.TipoDomanda.Ripristino || tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti || isRiapertura)
            {
                Utility.TipoFondo? tipoFondo = null;
                //salvataggio DC per ricRev
                if (prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiDanteCausa != null && !prelievoFs.Risposta.DatiDanteCausa.IsNull())
                {
                    isRicRev = true;
                    List<Entity.Anagrafica> elencoAnagrafiche = null;

                    GetDatiParziali(parametriArca, prelievoFs.Risposta.DatiAnagDanteCausa.Nome, prelievoFs.Risposta.DatiAnagDanteCausa.Cognome,
                        prelievoFs.Risposta.DatiAnagDanteCausa.DataNascita, prelievoFs.Risposta.DatiAnagDanteCausa.Sesso.HasValue ? prelievoFs.Risposta.DatiAnagDanteCausa.Sesso.Value.ToString() : null,
                        numDomanda, out elencoAnagrafiche, out errori);
                    if (!string.IsNullOrEmpty(errori))
                        return true;
                    if (elencoAnagrafiche != null)
                    {
                        if (elencoAnagrafiche.Count == 1)
                        {
                            //singolo dante causa trovato
                            anagraficaDA = elencoAnagrafiche[0];
                        }
                        else
                        {
                            //trovati sinonimi
                            foreach (Entity.Anagrafica anag in elencoAnagrafiche)
                            {
                                if (Utility.IsNullOrWhiteSpace(anag.CodiceFiscale) || anag.CodiceFiscale.Trim().Length < 16)
                                    continue;
                                int codComuneInps = 0;
                                GestioneDBSComuni.GetCodInpsComuneByCodCatastale(anag.CodiceComuneNascita, Utility.TipoAppartenenza.FS.ToString(), prelievoFs.Risposta.DatiAnagDanteCausa.CodiceComuneInps, true, out codComuneInps);
                                if (codComuneInps == prelievoFs.Risposta.DatiAnagDanteCausa.CodiceComuneInps)
                                {
                                    GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
                                    richiestaArca.Applicazione = parametriARCA.Applicazione;
                                    richiestaArca.Matricola = parametriARCA.Matricola;
                                    richiestaArca.Provenienza = parametriARCA.Provenienza;
                                    richiestaArca.Ruolo = parametriARCA.Ruolo;
                                    richiestaArca.CodiceFiscaleRichiedente = anag.CodiceFiscale;
                                    richiestaArca.CodiceFiscale = anag.CodiceFiscale;

                                    if (!GestioneARCA.GetAreaArcaByCodiceFiscale(richiestaArca, datiPensione.NDomus.ToString(), out anagraficaDA, out elencoPensioniDA, out errori))
                                        return false;
                                    break;
                                }
                            }
                        }
                        if (anagraficaDA != null)
                        {
                            danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                            Utility.TipoFondo? fondo = Utility.GetTipoFondoByCategoria(Utility.TipoAppartenenza.FS, datiPensione.SiglaCategoria);
                            bool isChiamataGP7Effettuta = false;
                            //if (prelievo.Risposta.DatiDanteCausa.DecorrenzaPensione.HasValue && !String.IsNullOrEmpty(prelievo.Risposta.DatiDanteCausa.Sede) &&
                            if (!String.IsNullOrEmpty(prelievoFs.Risposta.DatiDanteCausa.Sede) &&
                                !String.IsNullOrEmpty(prelievoFs.Risposta.DatiDanteCausa.SiglaCategoria) && prelievoFs.Risposta.DatiDanteCausa.Certificato.HasValue)
                                isDiretta = true;
                            else if (prelievoFs.Risposta.DataDecorrenza.HasValue && prelievoFs.Risposta.ListaRecordFondo != null && prelievoFs.Risposta.ListaRecordFondo.Count() > 0 &&
                                Utility.DataStrettamenteSuccessivaA(prelievoFs.Risposta.DataDecorrenza.Value, prelievoFs.Risposta.ListaRecordFondo.OrderBy(x => x.DecorrenzaValiditaDati.GetValueOrDefault()).FirstOrDefault().DecorrenzaValiditaDati.Value))
                            {
                                string chiavePensioneDC = string.Format("{0:000}{1:0000}{2:00000000}", prelievoFs.Richiesta._Categoria, prelievoFs.Richiesta._Sede, prelievoFs.Richiesta._Certificato);
                                List<BLCommon.GestioneDanteCausa.DatiRedditoSentenza495_93> listaDatiRedditoSentenza495_93 = null;
                                BLCommon.GestioneDanteCausa.DatiDanteCausa datiDanteCausaGP7 = null;
                                if (!Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) && !(ctrlSpacchettate024 != null && ctrlSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, isRiapertura)))
                                {
                                    if (!GestioneDatiPensioni.GetDatiTGP7ByCodiceFascicolo(datiPensione.NDomus, chiavePensioneDC, datiPensione, isRiapertura, out listaDatiRedditoSentenza495_93, out datiDanteCausaGP7, out errori) || !string.IsNullOrEmpty(errori))
                                        return true;
                                    if (datiDanteCausaGP7 != null && !datiDanteCausaGP7.IsNull())
                                    {
                                        prelievoFs.Risposta.DatiDanteCausa.Sede = datiDanteCausaGP7.Sede;
                                        string siglaCategoriaDC = null;
                                        GestioneDecodifica.FS_GetFondoByCategoriaNumerica(datiDanteCausaGP7.SiglaCategoria.PadLeft(4, '0'), datiDanteCausaGP7.Certificato.GetValueOrDefault(), out tipoFondo);
                                        if (tipoFondo.HasValue)
                                        {
                                            string valueToControl = datiDanteCausaGP7.Certificato.GetValueOrDefault().ToString().PadLeft(8, '0').Substring(2, 1);
                                            if (valueToControl == "1" || valueToControl == "4")
                                                siglaCategoriaDC = string.Format("V{0}", tipoFondo);
                                            else if (valueToControl == "2" || valueToControl == "5")
                                                siglaCategoriaDC = string.Format("I{0}", tipoFondo);
                                        }
                                        prelievoFs.Risposta.DatiDanteCausa.SiglaCategoria = siglaCategoriaDC ?? (tipoFondo.HasValue ? tipoFondo.Value.ToString() : null);
                                        prelievoFs.Risposta.DatiDanteCausa.Certificato = datiDanteCausaGP7.Certificato;
                                        //ENG - RIC Reversibilita 024: la decorrenza della diretta deve essere letta dal prelievo e non dal GP7
                                        if (!(tipoDomanda == Utility.TipoDomanda.Ricostituzione &&
                                            Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, prelievoFs.Risposta.DatiDanteCausa, prelievoFs.Risposta.DatiLavorazione) &&
                                            (fondo == Utility.TipoFondo.PT || fondo == Utility.TipoFondo.FS)))
                                        {
                                            prelievoFs.Risposta.DatiDanteCausa.DecorrenzaPensione = datiDanteCausaGP7.DecorrenzaPensione;
                                        }
                                        isChiamataGP7Effettuta = true;
                                        if (!String.IsNullOrEmpty(prelievoFs.Risposta.DatiDanteCausa.Sede) &&
                                            !String.IsNullOrEmpty(prelievoFs.Risposta.DatiDanteCausa.SiglaCategoria) && prelievoFs.Risposta.DatiDanteCausa.Certificato.HasValue)
                                            isDiretta = true;

                                    }
                                }
                            }

                            danteCausa = prelievoFs.Risposta.DatiDanteCausa;
                            //ENG - RIC REVERSIBILITA 024: implementazione flusso per riconoscere le reversibilità "vecchie"                                      
                            if (isChiamataGP7Effettuta && tipoDomanda == Utility.TipoDomanda.Ricostituzione
                                && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, danteCausa, prelievoFs.Risposta.DatiLavorazione)
                                && (fondo == Utility.TipoFondo.PT || fondo == Utility.TipoFondo.FS))
                            {
                                isDiretta = true;
                            }

                            if (!danteCausa.DataMorte.HasValue)
                                danteCausa.DataMorte = anagraficaDA.DataMorte;
                            if (!danteCausa.DataMorteOrigine.HasValue)
                                danteCausa.DataMorteOrigine = anagraficaDA.DataMorte;

                            if (prelievoFs.Risposta.DatiAnagDanteCausa != null)
                                anagraficaDA.DataMatrimonio = prelievoFs.Risposta.DatiAnagDanteCausa.DataMatrimonio;
                        }
                    }
                    else
                    {
                        //ENG - RICOSTITUZIONI (NO Inpdap) bypassare il messaggio bloccante "Nessun Dante Causa individuato"
                        tipoFondo = Utility.GetTipoFondoByCategoria(Utility.TipoAppartenenza.FS, datiPensione.SiglaCategoria);
                        if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Dante_Causa_FS.NESSUN_DANTE_CAUSA) || !GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Dante_Causa_FS.NESSUN_DANTE_CAUSA_DINAMICO) || tipoDomanda != Utility.TipoDomanda.Ricostituzione || Utility.IsDomandaINPDAP(datiPensione.Gestione))
                        {
                            errori = "Nessun Dante Causa individuato";
                            return true;
                        }
                    }
                }

                //ENG - RICOSTITUZIONI (NO Inpdap) bypassare i messaggi bloccanti "Dati anagrafici del Dante Causa non presenti sull'archivio pensione" e
                //"Il Dante Causa recuperato dall'archivio pensione non è presente su ARCA."
                tipoFondo = Utility.GetTipoFondoByCategoria(Utility.TipoAppartenenza.FS, datiPensione.SiglaCategoria);
                bool checkAndLockBypass = GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Dante_Causa_FS.NESSUN_DANTE_CAUSA) || GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Dante_Causa_FS.NESSUN_DANTE_CAUSA_DINAMICO);
                if (!checkAndLockBypass || tipoDomanda != Utility.TipoDomanda.Ricostituzione || Utility.IsDomandaINPDAP(datiPensione.Gestione))
                {
                    if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) && danteCausa == null)
                    {
                        byte? codiceSpecifico = prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.CodiceSpecifico;
                        bool checkFsPtCodiceSpedifico = ((codiceSpecifico != null && tipoFondo != null) && (
                            (tipoFondo == Utility.TipoFondo.PT && codiceSpecifico == 188) || (tipoFondo == Utility.TipoFondo.FS && codiceSpecifico == 189)
                            || (tipoFondo == Utility.TipoFondo.PT && codiceSpecifico == 142) || (tipoFondo == Utility.TipoFondo.FS && codiceSpecifico == 187)
                            )) || (prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.BypassDinamicoCodiceSpecifico.HasValue ? prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.BypassDinamicoCodiceSpecifico.Value : false);

                        if (prelievoFs == null || prelievoFs.Risposta == null || prelievoFs.Risposta.DatiAnagDanteCausa == null)
                        {
                            errori = "Dati anagrafici del Dante Causa non presenti sull'archivio pensione.";
                            return true;
                        }
                        else if (prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiDanteCausa != null && !checkFsPtCodiceSpedifico)
                        {
                            errori = string.Format("Il Dante Causa recuperato dall'archivio pensione non è presente su ARCA.<br /><b>Nome:</b> {0}<br /><b>Cognome:</b> {1}<br /><b>Data Nascita:</b> {2:dd/MM/yyyy}<br /><b>Sesso:</b> {3}",
                                prelievoFs.Risposta.DatiAnagDanteCausa.Nome, prelievoFs.Risposta.DatiAnagDanteCausa.Cognome, prelievoFs.Risposta.DatiAnagDanteCausa.DataNascita,
                                prelievoFs.Risposta.DatiAnagDanteCausa.Sesso.HasValue ? prelievoFs.Risposta.DatiAnagDanteCausa.Sesso.Value.ToString() : string.Empty);
                            return true;
                        }
                        else if (prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiDanteCausa != null && checkFsPtCodiceSpedifico)
                        {
                            List<GestioneBypassControllo.DatiDecBypassControllo> decBypassControllo;
                            GestioneBypassControllo.GetDecBypassControlloDinamiciByTipoApp("FS", out decBypassControllo);
                            long idBypassDinamico = decBypassControllo.Find(x => x.Nome.Equals("NESSUN_DANTE_CAUSA_DINAMICO")).Id;
                            List<GestioneBypassControllo.DatiBypassControllo> bypassDomanda;
                            GestioneBypassControllo.GetBypassApplicatiPerNDomus(datiPensione.NDomus, out bypassDomanda);
                            bool checkEsistenzaFlag = bypassDomanda.Exists(b => b.IdDecBypassControllo == idBypassDinamico);

                            if (!checkEsistenzaFlag)
                            {
                                GestioneBypassControllo.DatiBypassControllo bypassTemporaneo = new GestioneBypassControllo.DatiBypassControllo()
                                {
                                    NCertificato = nCertificato,
                                    CodCategoria = datiPensione.GetCodCategoria(),
                                    CodiceSede = datiPensione.CodiceSede,
                                    NDomus = datiPensione.NDomus,
                                    Note = string.Empty,
                                    Matricola = parametriArca.Matricola,
                                    Lock = true,
                                    IdDecBypassControllo = idBypassDinamico
                                };
                                GestioneBypassControllo.SalvaBypassControllo(bypassTemporaneo);
                            }
                        }
                    }
                }

                tipoFondo = Utility.GetTipoFondoByCategoria(Utility.TipoAppartenenza.FS, datiPensione.SiglaCategoria);
                if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                {
                    if (prelievoFs != null && prelievoFs.Risposta != null &&
                        (string.IsNullOrEmpty(prelievoFs.Risposta.DatiLavorazione.TipoLiquidazione) || string.IsNullOrEmpty(prelievoFs.Risposta.DatiLavorazione.TipoLiquidazione.Trim())) &&
                         nCertificato.HasValue)
                    {
                        string certificato = nCertificato.Value.ToString().PadLeft(8, '0');
                        switch (certificato[2])
                        {
                            case '1':
                            case '2':
                            case '4':
                            case '5':
                                datiLavorazione.TipoLiquidazione = "B1";
                                break;
                            case '3':
                            case '6':
                                datiLavorazione.TipoLiquidazione = "B2";
                                break;
                        }
                    }

                    //ENG - Ric Superstiti 024: per prodotto "0413" e prodotto "0407" passare B1
                    if (tipoDomanda == Utility.TipoDomanda.Ricostituzione && (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) && (datiPensione.Prodotto == "0413" || datiPensione.Prodotto == "0407"))
                        datiLavorazione.TipoLiquidazione = "B1";
                }
                else if (tipoDomanda == Utility.TipoDomanda.Ripristino || tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti)
                {
                    datiLavorazione.TipoLiquidazione = "A1";
                }
                else if ((tipoFondo == Utility.TipoFondo.PT || tipoFondo == Utility.TipoFondo.FS) && Utility.IsRicostituzione_Reddituale(datiPensione))
                    datiLavorazione.TipoLiquidazione = "B3";
                else if ((tipoFondo == Utility.TipoFondo.PT || tipoFondo == Utility.TipoFondo.FS) && ((Utility.IsRicostituzione_Reddituale(datiPensione) && !new List<string> { "0101", "0103", "0178" }.Contains(datiPensione.Tipo)) ||
                    Utility.IsRicostituzione_TrattamentoDiFamiglia(datiPensione) || Utility.IsRicostituzione_MotiviDocumentali(datiPensione) || Utility.IsRicEsenzioneFiscaleVittimeDelDovere(datiPensione)))
                    datiLavorazione.TipoLiquidazione = "B2";
                else
                    datiLavorazione.TipoLiquidazione = "B1";
                if (prelievoFs != null && prelievoFs.Risposta != null)
                {
                    datiPensione.DecorrenzaOriginaria = prelievoFs.Risposta.DataDecorrenza;
                    datiLavorazione.TipoReversibilita = prelievoFs.Risposta.DatiLavorazione.TipoReversibilita;

                    if (prelievoFs.Risposta.ListaResidenzeEstere != null && prelievoFs.Risposta.ListaResidenzeEstere.Length > 0)
                        isResEsteroPerRic = true;

                    if ((Utility.IsRicostituzione_MotiviContributivi(datiPensione) || Utility.IsRicostituzione_Supplemento(datiPensione) || tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) &&
                        prelievoFs.Risposta.ListaSupplementi != null && prelievoFs.Risposta.ListaSupplementi.Length > 0)
                        isSupplementiPerRic = true;
                }
            }
            else if (tipoDomanda == Utility.TipoDomanda.Riliquidazione || tipoDomanda == Utility.TipoDomanda.RiliquidazioneSuperstiti)
            {
                datiLavorazione.TipoLiquidazione = "A1";
            }
            if (Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) || (datiPensione.Gestione == "007" && (datiPensione.Fondo == "014" || datiPensione.Fondo == "006") && datiPensione.SiglaCategoria.ToUpperInvariant().StartsWith("S")) || (Utility.IsDomandaINPGI(datiPensione) && datiPensione.SiglaCategoria.ToUpperInvariant().StartsWith("S")))
            {
                if (datiDomanda != null && datiDomanda.Dati != null && datiDomanda.Dati.RelazioneSoggetto != null && datiDomanda.Dati.RelazioneSoggetto.Any(row => row.CodRelazioneParentela == "18" || row.CodRelazioneParentela == "19"))
                {
                    var soggettoRelazione = datiDomanda.Dati.RelazioneSoggetto.FirstOrDefault(row => row.CodRelazioneSoggetto == "18" || row.CodRelazioneParentela == "18");
                    if (soggettoRelazione != null && datiDomanda.Dati.Soggetto != null)
                    {
                        var idSoggetto = soggettoRelazione.IdSoggetto;
                        var soggetto = datiDomanda.Dati.Soggetto.FirstOrDefault(s => s.IdSoggetto == idSoggetto);
                        if (soggetto != null)
                        {
                            var codiceFiscale = soggetto.CodiceFiscale;
                            errori = string.Format("Verificare la relazione di parentela con il dante causa del soggetto {0} (es. precisare se si tratta di minore, studente, universitario, inabile, etc...).", codiceFiscale);
                            return true;
                        }
                    }

                }
            }

            if (Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) || (ctrlSpacchettate024 != null && ctrlSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, isRiapertura)))
            {
                short codiceCategoriaSuperstite = 0;
                string codCategoriaSuperstite = datiPensione.GetCodCategoria();
                short.TryParse(codCategoriaSuperstite, out codiceCategoriaSuperstite);

                Entity.Pensione pensioneFascicolo = null;
                //ENG - PL Reversibilita/Indiretta eliminata più volte (NO RIC/TRF)
                bool chiamaTGP4pensioniEliminate = false;

                if (tipoDomanda != Utility.TipoDomanda.Ricostituzione && !isRiapertura)
                {
                    if (elencoPensioniDA != null && elencoPensioniDA.Count > 0)
                    {
                        pensioneFascicolo = elencoPensioniDA.Find(x => x.Categoria.Trim() == datiPensione.SiglaCategoria.Trim() && string.IsNullOrEmpty(x.Eliminazione) && x.TipoComponente.GetValueOrDefault() == 'P');
                        if (pensioneFascicolo == null)
                        {
                            pensioneFascicolo = elencoPensioniDA.Find(x => x.Categoria.Trim() == datiPensione.SiglaCategoria.Trim() && x.Eliminazione != "5" && x.TipoComponente.GetValueOrDefault() == 'P');
                            //ENG - Se ci sono più pensioni eliminate devo chiamare il TGP4 per ogni pensione eliminata
                            if (elencoPensioniDA.Count(x => x.Categoria.Trim() == datiPensione.SiglaCategoria.Trim() && x.Eliminazione != "5" && x.TipoComponente.GetValueOrDefault() == 'P') > 1)
                                chiamaTGP4pensioniEliminate = true;
                        }
                    }
                }

                if (anagraficaDA != null)
                {

                    if (BLCommon.GestioneDanteCausa.IsPresenteDomandaInLiquidazionePerControlloSpacENPALS(anagraficaDA.CodiceFiscale, null, null, null, false, out NDomus))
                    {
                        errori = string.Format("Non è possibile acquisire la domanda in presenza di altre domande in liquidazione sullo stesso dante causa. Numero domanda: {0}", NDomus);
                        return true;
                    }
                }

                if (pensioneFascicolo != null || tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura)
                {
                    short? categoriaFascicolo = null;
                    short? sedeFascicolo = null;
                    int? numeroFascicolo = null;

                    if (tipoDomanda != Utility.TipoDomanda.Ricostituzione && !isRiapertura)
                        chiavePensione = codiceCategoriaSuperstite.ToString().PadLeft(3, '0') + pensioneFascicolo.Sede.PadLeft(4, '0') + pensioneFascicolo.Certificato.PadLeft(8, '0');
                    else if (prelievoFs != null && prelievoFs.Risposta != null)
                        chiavePensione = codiceCategoriaSuperstite.ToString().PadLeft(3, '0') + prelievoFs.Richiesta._Sede.ToString().PadLeft(4, '0') + prelievoFs.Richiesta._Certificato.ToString().PadLeft(8, '0');


                    //ENG - PL Reversibilità/Indirette (la variabile chiamaTGP4pensioniEliminate rimane a false per le RIC/TRF che non devono essere coinvolte dal nuovo flusso)
                    if (chiamaTGP4pensioniEliminate == true)
                    {
                        if (elencoPensioniDA != null && elencoPensioniDA.Count() > 0)
                        {
                            List<Entity.Pensione> elencoPensioniEliminate = elencoPensioniDA.FindAll(x => x.Categoria.Trim() == datiPensione.SiglaCategoria.Trim() && x.Eliminazione != "5" && x.TipoComponente.GetValueOrDefault() == 'P');
                            if (elencoPensioniEliminate != null && elencoPensioniEliminate.Count > 0)
                            {
                                foreach (Entity.Pensione pensioneEliminataDC in elencoPensioniEliminate)
                                {
                                    chiavePensione = codiceCategoriaSuperstite.ToString().PadLeft(3, '0') + pensioneEliminataDC.Sede.PadLeft(4, '0') + pensioneEliminataDC.Certificato.PadLeft(8, '0');
                                    GestioneDatiPensioni.GetCodiceFascicoloByChiavePensione(datiPensione.NDomus, chiavePensione, out categoriaFascicolo, out sedeFascicolo, out numeroFascicolo, out errori);
                                    if (numeroFascicolo.HasValue) //interrompo la chiamata al TGP4 appena si trova una pensione per la quale viene restituito il numero fascicolo
                                        break;
                                }
                            }
                        }

                    }
                    else
                        GestioneDatiPensioni.GetCodiceFascicoloByChiavePensione(datiPensione.NDomus, chiavePensione, out categoriaFascicolo, out sedeFascicolo, out numeroFascicolo, out errori);

                    if (!string.IsNullOrEmpty(errori))
                        return true;

                    if ((danteCausa.CategoriaFascicolo.HasValue && danteCausa.CategoriaFascicolo.Value != categoriaFascicolo) ||
                        (danteCausa.SedeFascicolo.HasValue && danteCausa.SedeFascicolo.Value != sedeFascicolo) ||
                        (danteCausa.NumeroFascicolo.HasValue && danteCausa.NumeroFascicolo.Value != numeroFascicolo))
                    {
                        errori = "Il codice fascicolo presente sull'Archivio Pensione è diverso da quello presente su ARCA.";
                        return true;
                    }

                    if (BLCommon.GestioneDanteCausa.IsPresenteDomandaInLiquidazionePerControlloSpacENPALS(anagraficaDA.CodiceFiscale, categoriaFascicolo, sedeFascicolo, numeroFascicolo, true, out NDomus))
                    {
                        errori = string.Format("Non è possibile acquisire la domanda in presenza di altre domande in liquidazione sullo stesso dante causa. Numero domanda: {0}", NDomus);
                        return true;
                    }

                    danteCausa.CategoriaFascicolo = categoriaFascicolo;
                    danteCausa.SedeFascicolo = sedeFascicolo;
                    danteCausa.NumeroFascicolo = numeroFascicolo;
                    danteCausa.IsFascicoloGenerato = false;
                }
                else if (anagraficaDA != null)
                {
                    ServiceReferences.GeneraCertificati.FascicoloOutput fascicolo = null;
                    GestioneGeneraCertificati.GeneraFascicolo(numDomanda, codiceCategoriaSuperstite.ToString(), "9990", anagraficaDA.CodiceFiscale, out fascicolo, out errori);

                    if (!string.IsNullOrEmpty(errori))
                        return true;

                    danteCausa.CategoriaFascicolo = codiceCategoriaSuperstite;
                    danteCausa.SedeFascicolo = 9990;
                    danteCausa.NumeroFascicolo = (int)fascicolo.NumeroFascicolo;
                    danteCausa.IsFascicoloGenerato = true;
                }
            }

            //Se è una reversibile di una "invalidità" NON prelevare le informazione del comma 707 
            //(sulle nuove pensioni di invalidità non dovrebbe arrivare ma sulle vecchie è possibile).
            if (Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, danteCausa, prelievoFs != null ? prelievoFs.Risposta != null ? prelievoFs.Risposta.DatiLavorazione : null : null)
                && danteCausa != null && !string.IsNullOrEmpty(danteCausa.SiglaCategoria) &&
                danteCausa.SiglaCategoria.StartsWith("I") && prelievoFs != null && prelievoFs.Risposta != null && prelievoFs.Risposta.DatiPensioneFondoDatiGenerici != null)
            {
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaA707 = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaA2707 = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaB707 = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaC707 = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaC2707 = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaD707 = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaA707AA = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaA707MM = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaA707GG = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaB707AA = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaB707MM = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaB707GG = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaC707AA = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaC707MM = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaC707GG = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.RetribuzionePonderataAGO707 = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaAES707 = null;
                prelievoFs.Risposta.DatiPensioneFondoDatiGenerici.QuotaBES707 = null;
                prelievo = prelievoFs;
            }

            //ENG - Reversibilita 024
            Utility.TipoFondo? tipologiaFondo = Utility.GetTipoFondoByCategoria(Utility.TipoAppartenenza.FS, datiPensione.SiglaCategoria);
            if (Utility.IsDomandaReversibilita(datiPensione) && (tipologiaFondo == Utility.TipoFondo.FS || tipologiaFondo == Utility.TipoFondo.PT))
            {
                if (danteCausa != null && !danteCausa.DataMorte.HasValue)
                {
                    errori = "Data Morte non presente. Verificare in Arca";
                    return true;
                }
            }

            if (!RecuperaDatiTGP1(ref datiPensione, prelievo, Utility.TipoAppartenenza.FS, sedePensione, isRiapertura, numeroCertificato, out errori))
                return true;

            //INPDAP - Il controllo deve essere effettuato solo sulle ricostituzioni e le trasformazioni, non sulle reversibilità.
            //ENG - Pensioni Ovunque: gestione nuovo pannello
            short sedeLavorazione = sedePensione;
            GestioneControlliDinamici.ControlloDinamico ctrlMetaProcesso = null;
            if ((Utility.IsRicostituzione(datiPensione.Gruppo) || isRiapertura) && Utility.IsPensioniOvunqueAttiva(Utility.TipoAppartenenza.FS) && datiPensione.CodiceSedeGP1ALZ6.HasValue)
            {
                sedeLavorazione = datiPensione.CodiceSedeGP1ALZ6.Value;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("SbloccaMetaProcesso", out ctrlMetaProcesso);
            }

            if ((Utility.IsSperimentazioneSediINPDAP() || Utility.IsRegimeSediINPDAP()) && Utility.IsDomandaINPDAP(datiPensione.Gestione) &&
                (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura) &&
                (sedeLavorazione != datiPensione.CodiceSede &&
                ((!Utility.IsDomandaAPEPrecoci(datiPensione) &&
                !Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) && !Utility.IsGestioneENPALSConSedeDestinazione(datiPensione)) || (!Utility.IsPensioniOvunqueAttiva(Utility.TipoAppartenenza.FS) && sedePensione != prelievoFs.Risposta.DatiPensione.CodiceSedeDestinazione.Value))) &&
                !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Eliminazione_Controllo_Sede.BYPASS_META_PROCESSO_FS) && (ctrlMetaProcesso == null || String.IsNullOrEmpty(ctrlMetaProcesso.ValoreControllo) || ctrlMetaProcesso.ValoreControllo.Trim().ToUpperInvariant() == "NO"))
            {
                errori = "ATTENZIONE! La sede della domanda (" + datiPensione.CodiceSede.ToString().PadLeft(4, '0') + ") non è corretta rispetto alla sede di gestione della pensione da ricostituire (" + sedeLavorazione.ToString().PadLeft(4, '0') + ").";

                mostraPanelloMessBloccantePensioniOvunque = true;
                sedePensioneGP1ALZ6 = sedeLavorazione.ToString().PadLeft(4, '0');
                codCategoriaPensione = datiPensione.GetCodCategoria();

                if (Utility.IsPolarizzazionePerGestioneENPALSAttiva(datiPensione) &&
                    !(Utility.IsRicostituzione_MotiviContributivi(datiPensione) || Utility.IsRicostituzione_Supplemento(datiPensione) || isRiapertura))
                    errori = string.Format("{0} Trasferire la domanda alla sede {1:0000} che ha in carico la pensione.", errori, sedeLavorazione);
                return true;
            }

            return true;
        }

        private static bool PrelevaCi(Entity.ParametriARCA parametriArca, ServiceReferences.WebDom.DatiDomanda datiDomanda, short sedeOperatore, short centroOperativoOperatore,
            Entity.ParametriARCA parametriARCA, Utility.TipoDomanda tipoDomanda, GestionePensione.DatiPensione datiPensione,
            ref GestioneLavorazione.DatiLavorazione datiLavorazione, out Entity.Anagrafica anagraficaDA,
            out BLCommon.GestioneDanteCausa.DatiDanteCausa danteCausa, out List<BLCommon.GestioneDatiContributiviCi.DatiPostDecOriginaria> listaDatiPostDecOriginaria, out object prelievo,
            out bool isRicRev, out bool isDiretta, out string errori, out bool mostraPanelloMessBloccantePensioniOvunque, out string sedePensioneGP1ALZ6, out string codCategoriaPensione, out bool isAnte96Ci)
        {
            isAnte96Ci = false;
            bool isRiapertura = false;
            anagraficaDA = null;
            danteCausa = null;
            listaDatiPostDecOriginaria = null;
            isRicRev = false;
            isDiretta = false;
            errori = "";
            datiLavorazione = new GestioneLavorazione.DatiLavorazione();
            prelievo = null;
            ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoCi = null;
            string numDomanda = datiDomanda.Dati.Domanda[0].NumDomanda;
            //ENG - Pensioni Ovunque: gestione nuovo pannello
            mostraPanelloMessBloccantePensioniOvunque = false;
            sedePensioneGP1ALZ6 = string.Empty;
            codCategoriaPensione = string.Empty;


            DataRow[] RelSoggDC = null;
            DataRow[] SoggDC = null;
            string dataMorteDC = string.Empty;

            if ((tipoDomanda == Utility.TipoDomanda.Superstiti) || ((tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti || tipoDomanda == Utility.TipoDomanda.RiliquidazioneSuperstiti) && (datiPensione.Tipo == "0026" || datiPensione.Tipo == "0027")))
            {
                RelSoggDC = datiDomanda.Dati.RelazioneSoggetto.Select("CodRelazioneSoggetto = 'DA'");
                SoggDC = datiDomanda.Dati.Soggetto.Select("IdSoggetto = '" + RelSoggDC[0]["IdSoggetto"] + "'");
                dataMorteDC = SoggDC != null ? SoggDC[0]["DataMorte"].ToString() : string.Empty;
            }

            if (datiDomanda.Dati != null && datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Count > 0)
                isRiapertura = Utility.IsRiaperturaDomanda(datiDomanda.Dati.Fase.LastOrDefault().CodFase);

            short sedePensione = 0;
            int numeroCertificato = 0;
            if (isRiapertura)
            {
                ServiceReferences.WebDom.DataSetDomanda.PensioneGenerataRow pensioneGenerata = datiDomanda.Dati.PensioneGenerata.FirstOrDefault(x => x.IndAnnullata == "0");
                sedePensione = short.Parse(pensioneGenerata.CodProvinciaGenAttuale.Substring(1) + pensioneGenerata.CodZonaGenAttuale.Substring(1));
                numeroCertificato = int.Parse(pensioneGenerata.NumCertificatoGenAttuale);
                if (!GestioneLiquidazioneCi.PrelevaDomanda(numDomanda, short.Parse(pensioneGenerata.CodProvinciaGenAttuale.Substring(1) + pensioneGenerata.CodZonaGenAttuale.Substring(1)),
                        short.Parse(pensioneGenerata.CodCatPensioneGenAttuale), int.Parse(pensioneGenerata.NumCertificatoGenAttuale),
                        sedeOperatore, centroOperativoOperatore, datiDomanda.Dati.Istanza[0].CodGruppo, datiDomanda.Dati.Istanza[0].CodProdotto, dataMorteDC, isRiapertura, out prelievoCi, out errori))
                    return true;
                else
                    prelievo = prelievoCi;

            }
            else
            {
                //caso reversibilità indiretta (no GACI)
                if (!(tipoDomanda == Utility.TipoDomanda.Superstiti && (datiDomanda.Dati.PensioneRiferimento.Rows.Count == 0 || isPensioneRiferimentoNull(datiDomanda.Dati.PensioneRiferimento[0]))))
                {
                    sedePensione = short.Parse(datiDomanda.Dati.PensioneRiferimento[0].CodProvinciaRifAttuale.Substring(1) + datiDomanda.Dati.PensioneRiferimento[0].CodZonaRifAttuale.Substring(1));
                    numeroCertificato = int.Parse(datiDomanda.Dati.PensioneRiferimento[0].NumCertificatoRifAttuale);
                    if (!GestioneLiquidazioneCi.PrelevaDomanda(numDomanda, short.Parse(datiDomanda.Dati.PensioneRiferimento[0].CodProvinciaRifAttuale.Substring(1) + datiDomanda.Dati.PensioneRiferimento[0].CodZonaRifAttuale.Substring(1)),
                        short.Parse(datiDomanda.Dati.PensioneRiferimento[0].CodCatPensioneRifAttuale), int.Parse(datiDomanda.Dati.PensioneRiferimento[0].NumCertificatoRifAttuale),
                        sedeOperatore, centroOperativoOperatore, datiDomanda.Dati.Istanza[0].CodGruppo, datiDomanda.Dati.Istanza[0].CodProdotto, dataMorteDC, isRiapertura, out prelievoCi, out errori))
                        return true;
                    else
                        prelievo = prelievoCi;
                }
            }


            if ((tipoDomanda == Utility.TipoDomanda.Superstiti && !isRiapertura) || ((tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti || tipoDomanda == Utility.TipoDomanda.RiliquidazioneSuperstiti) && (datiPensione.Tipo == "0026" || datiPensione.Tipo == "0027")))
            {
                GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
                richiestaArca.Applicazione = parametriARCA.Applicazione;
                richiestaArca.Matricola = parametriARCA.Matricola;
                richiestaArca.Provenienza = parametriARCA.Provenienza;
                richiestaArca.Ruolo = parametriARCA.Ruolo;

                //per reversibilità indiretta recupero codice fiscale DC da WebDom altrimenti da GACI
                if ((datiDomanda.Dati.PensioneRiferimento.Rows.Count == 0 || isPensioneRiferimentoNull(datiDomanda.Dati.PensioneRiferimento[0])) || ((tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti || tipoDomanda == Utility.TipoDomanda.RiliquidazioneSuperstiti) && (datiPensione.Tipo == "0026" || datiPensione.Tipo == "0027")))
                {
                    if (SoggDC != null)
                    {
                        richiestaArca.CodiceFiscaleRichiedente = SoggDC[0]["CodiceFiscale"].ToString();
                        richiestaArca.CodiceFiscale = SoggDC[0]["CodiceFiscale"].ToString();
                    }
                    danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                    danteCausa.DecorrenzaPensione = null;
                    danteCausa.Sede = null;
                    danteCausa.Certificato = null;
                    danteCausa.SiglaCategoria = null;
                }
                else
                {
                    isDiretta = true;

                    if (prelievoCi != null && prelievoCi.Risposta != null && !string.IsNullOrEmpty(prelievoCi.Risposta.CodiceFiscale))
                    {
                        richiestaArca.CodiceFiscaleRichiedente = prelievoCi.Risposta.CodiceFiscale;
                        richiestaArca.CodiceFiscale = prelievoCi.Risposta.CodiceFiscale;
                    }
                    else
                    {
                        richiestaArca.CodiceFiscaleRichiedente = SoggDC[0]["CodiceFiscale"].ToString();
                        richiestaArca.CodiceFiscale = SoggDC[0]["CodiceFiscale"].ToString();
                    }

                    danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                    danteCausa.DecorrenzaPensione = prelievoCi.Risposta.DatiDanteCausa.DecorrenzaPensione;
                    danteCausa.Sede = prelievoCi.Richiesta._Sede.ToString().PadLeft(4, '0');
                    danteCausa.Certificato = prelievoCi.Richiesta._Certificato;
                    //nuova gestione di recupero Sigla categoria
                    // Per le reversibilità la Sigla Categoria data da WebDom è errata, quindi utilizziamo direttamente quella recuperata dal prelievo
                    // danteCausa.SiglaCategoria = datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav.Trim().ToUpperInvariant();
                    danteCausa.SiglaCategoria = prelievoCi.Risposta.DatiDanteCausa.SiglaCategoria;

                    //danteCausa = prelievoCi.Risposta.DatiDanteCausa;
                    if (prelievoCi != null && prelievoCi.Risposta != null && prelievoCi.Risposta.DatiDanteCausa != null && prelievoCi.Risposta.DatiDanteCausa.Maggiorazione781Contributi != null)
                    {
                        danteCausa.Maggiorazione781Contributi = prelievoCi.Risposta.DatiDanteCausa.Maggiorazione781Contributi != null ? prelievoCi.Risposta.DatiDanteCausa.Maggiorazione781Contributi : null;
                        danteCausa.CessazioneAltraPensione = prelievoCi.Risposta.DatiDanteCausa.CessazioneAltraPensione != null ? prelievoCi.Risposta.DatiDanteCausa.CessazioneAltraPensione : null;
                        danteCausa.DecorrenzaAltraPensione = prelievoCi.Risposta.DatiDanteCausa.DecorrenzaAltraPensione != null ? prelievoCi.Risposta.DatiDanteCausa.DecorrenzaAltraPensione : null;
                        danteCausa.CodiceImportoAltraPensione = prelievoCi.Risposta.DatiDanteCausa.CodiceImportoAltraPensione != null ? prelievoCi.Risposta.DatiDanteCausa.CodiceImportoAltraPensione : null;
                        danteCausa.CategoriaAltraPensione = prelievoCi.Risposta.DatiDanteCausa.CategoriaAltraPensione != null ? prelievoCi.Risposta.DatiDanteCausa.CategoriaAltraPensione : null;
                        danteCausa.CodiceUCAltraPensione = prelievoCi.Risposta.DatiDanteCausa.CodiceUCAltraPensione != null ? prelievoCi.Risposta.DatiDanteCausa.CodiceUCAltraPensione : null;
                        danteCausa.EnteAltraPensione = prelievoCi.Risposta.DatiDanteCausa.EnteAltraPensione != null ? prelievoCi.Risposta.DatiDanteCausa.EnteAltraPensione : null;


                    }
                }

                if (!GestioneARCA.GetAnagraficaArcaByCodiceFiscale(richiestaArca, datiPensione.NDomus.ToString(), out anagraficaDA, out errori) || !string.IsNullOrEmpty(errori))
                    return false;

                danteCausa.DataMorte = anagraficaDA.DataMorte;
                danteCausa.DataMorteOrigine = anagraficaDA.DataMorte;


                if (datiDomanda.Dati.Istanza[0].CodProdotto == "0021")
                {
                    datiLavorazione.TipoReversibilita = 'R';
                    datiLavorazione.TipoLiquidazione = "A2";
                }
                else if (datiDomanda.Dati.Istanza[0].CodProdotto == "0022")
                {
                    datiLavorazione.TipoReversibilita = 'I';
                    datiLavorazione.TipoLiquidazione = "A1";
                }
            }
            else if (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura)
            {
                if (prelievoCi != null && prelievoCi.Risposta != null)
                {
                    DateTime dataEstremoSuperiore = new DateTime(1995, 12, 31);
                    if (datiPensione.SiglaCategoria != null && datiPensione.SiglaCategoria.StartsWith("S") && prelievoCi.Risposta.DatiDanteCausa != null && prelievoCi.Risposta.DatiDanteCausa.DecorrenzaPensione != null)
                        isAnte96Ci = Utility.DataSuccessivaA(dataEstremoSuperiore, prelievoCi.Risposta.DatiDanteCausa.DecorrenzaPensione.GetValueOrDefault());
                    else if (prelievoCi.Risposta.DataDecorrenza != null)
                        isAnte96Ci = Utility.DataSuccessivaA(dataEstremoSuperiore, prelievoCi.Risposta.DataDecorrenza.GetValueOrDefault());

                    //salvataggio DC per ricRev
                    if (prelievoCi.Risposta.DatiDanteCausa != null && !prelievoCi.Risposta.DatiDanteCausa.IsNull())
                    {
                        isRicRev = true;
                        List<Entity.Anagrafica> elencoAnagrafiche = null;

                        GetDatiParziali(parametriArca, prelievoCi.Risposta.DatiAnagDanteCausa.Nome, prelievoCi.Risposta.DatiAnagDanteCausa.Cognome,
                            prelievoCi.Risposta.DatiAnagDanteCausa.DataNascita, prelievoCi.Risposta.DatiAnagDanteCausa.Sesso.HasValue ? prelievoCi.Risposta.DatiAnagDanteCausa.Sesso.Value.ToString() : null,
                            numDomanda, out elencoAnagrafiche, out errori);
                        if (elencoAnagrafiche != null)
                        {
                            if (elencoAnagrafiche.Count == 1)
                            {
                                //singolo dante causa trovato
                                anagraficaDA = elencoAnagrafiche[0];
                            }
                            else
                            {
                                //trovati sinonimi
                                foreach (Entity.Anagrafica anag in elencoAnagrafiche)
                                {
                                    int codComuneInps = 0;
                                    GestioneDBSComuni.GetCodInpsComuneByCodCatastale(anag.CodiceComuneNascita, Utility.TipoAppartenenza.CI.ToString(), 0, false, out codComuneInps);
                                    if (codComuneInps == prelievoCi.Risposta.DatiAnagDanteCausa.CodiceComuneInps)
                                    {
                                        GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
                                        richiestaArca.Applicazione = parametriARCA.Applicazione;
                                        richiestaArca.Matricola = parametriARCA.Matricola;
                                        richiestaArca.Provenienza = parametriARCA.Provenienza;
                                        richiestaArca.Ruolo = parametriARCA.Ruolo;
                                        richiestaArca.CodiceFiscaleRichiedente = anag.CodiceFiscale;
                                        richiestaArca.CodiceFiscale = anag.CodiceFiscale;

                                        if (!GestioneARCA.GetAnagraficaArcaByCodiceFiscale(richiestaArca, datiPensione.NDomus.ToString(), out anagraficaDA, out errori))
                                            return false;
                                        break;
                                    }
                                }
                            }
                            if (anagraficaDA != null)
                            {
                                danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                                if (prelievoCi.Risposta.DatiDanteCausa.DecorrenzaPensione.HasValue && !String.IsNullOrEmpty(prelievoCi.Risposta.DatiDanteCausa.Sede) &&
                                    !String.IsNullOrEmpty(prelievoCi.Risposta.DatiDanteCausa.SiglaCategoria) && prelievoCi.Risposta.DatiDanteCausa.Certificato.HasValue)
                                    isDiretta = true;
                                danteCausa = prelievoCi.Risposta.DatiDanteCausa;

                                if (!danteCausa.DataMorte.HasValue)
                                    danteCausa.DataMorte = anagraficaDA.DataMorte;
                                if (!danteCausa.DataMorteOrigine.HasValue)
                                    danteCausa.DataMorteOrigine = anagraficaDA.DataMorte;

                                // Se la data matrimonio non proviene dal prelievo allora mantengo il valore di ARCA
                                if (prelievoCi.Risposta.DatiAnagDanteCausa != null && prelievoCi.Risposta.DatiAnagDanteCausa.DataMatrimonio.HasValue)
                                    anagraficaDA.DataMatrimonio = prelievoCi.Risposta.DatiAnagDanteCausa.DataMatrimonio;
                            }
                        }
                        else /*if (isAnte96Ci)*/
                        {
                            danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                            anagraficaDA = new Entity.Anagrafica();
                            if (prelievoCi.Risposta.DatiDanteCausa.DecorrenzaPensione.HasValue && !String.IsNullOrEmpty(prelievoCi.Risposta.DatiDanteCausa.Sede) &&
                                !String.IsNullOrEmpty(prelievoCi.Risposta.DatiDanteCausa.SiglaCategoria) && prelievoCi.Risposta.DatiDanteCausa.Certificato.HasValue)
                                isDiretta = true;
                            danteCausa = prelievoCi.Risposta.DatiDanteCausa;

                            // Se la data matrimonio non proviene dal prelievo allora mantengo il valore di ARCA
                            if (prelievoCi.Risposta.DatiAnagDanteCausa != null && prelievoCi.Risposta.DatiAnagDanteCausa.DataMatrimonio.HasValue)
                            {
                                anagraficaDA.DataMatrimonio = prelievoCi.Risposta.DatiAnagDanteCausa.DataMatrimonio;
                                danteCausa.DataMatrimonioByPrelievo = true;
                            }
                            //if (prelievoCi.Risposta.DatiAnagDanteCausa != null && !string.IsNullOrEmpty(prelievoCi.Risposta.DatiAnagDanteCausa.Cittadinanza))
                            //{
                            //    anagraficaDA.Cittadinanza = prelievoCi.Risposta.DatiAnagDanteCausa.Cittadinanza;
                            //    danteCausa.CittadinanzaByArca = true;
                            //}
                            if (prelievoCi.Risposta.DatiDanteCausa != null && !string.IsNullOrEmpty(prelievoCi.Risposta.DatiDanteCausa.StatoEEResidenza))
                            {
                                danteCausa.StatoEEResidenza = prelievoCi.Risposta.DatiDanteCausa.StatoEEResidenza;
                                danteCausa.StatoEEResidenzaByArca = true;
                            }

                            anagraficaDA.CodiceFiscale = "DANTEC_";
                            anagraficaDA.Nome = prelievoCi.Risposta.DatiAnagDanteCausa.Nome;
                            anagraficaDA.Cognome = prelievoCi.Risposta.DatiAnagDanteCausa.Cognome;
                            anagraficaDA.DataNascita = prelievoCi.Risposta.DatiAnagDanteCausa.DataNascita;
                            anagraficaDA.Sesso = prelievoCi.Risposta.DatiAnagDanteCausa.Sesso.HasValue ? (char?)prelievoCi.Risposta.DatiAnagDanteCausa.Sesso.Value : (char?)null;
                        }
                    }
                }

                if (prelievoCi != null && prelievoCi.Risposta != null && prelievoCi.Risposta.ListaDatiPostDecOriginaria != null && prelievoCi.Risposta.ListaDatiPostDecOriginaria.Length > 0)
                {
                    listaDatiPostDecOriginaria = new List<GestioneDatiContributiviCi.DatiPostDecOriginaria>();
                    for (int i = 0; i < prelievoCi.Risposta.ListaDatiPostDecOriginaria.Length; i++)
                    {
                        GestioneDatiContributiviCi.DatiPostDecOriginaria datiPostDecOriginaria = new GestioneDatiContributiviCi.DatiPostDecOriginaria();
                        Utility.ValorizzaOggetti(prelievoCi.Risposta.ListaDatiPostDecOriginaria[i], datiPostDecOriginaria);
                        listaDatiPostDecOriginaria.Add(datiPostDecOriginaria);
                    }
                }

                if (prelievoCi != null && prelievoCi.Risposta != null)
                {
                    //Questa operazione era già effettuata prima delle modifiche inerenti il Memo Albania
                    datiPensione.DecorrenzaOriginaria = prelievoCi.Risposta.DataDecorrenza;
                }

                datiLavorazione.TipoReversibilita = null;
                datiLavorazione.TipoLiquidazione = "B1";

                if (prelievoCi != null && prelievoCi.Risposta != null && prelievoCi.Risposta.ListaBititolarita != null && prelievoCi.Risposta.ListaBititolarita.Count() > 0 &&
                    prelievoCi.Risposta.ListaBititolarita.Any(x => !x.Ente.HasValue || x.Ente.Value == 0))
                {
                    List<GestioneDecodifica.CatEnteAltraPensione> listaDecEnteAltrePensioni = null;
                    GestioneDecodifica.GetCatEnteAltrePensioni(out listaDecEnteAltrePensioni);
                    foreach (GestioneAltrePensioni.AltraPensione datiBititolarita in prelievoCi.Risposta.ListaBititolarita.Where(x => !x.Ente.HasValue || x.Ente.Value == 0))
                    {
                        int categoriaNumerica = 0;
                        int.TryParse(datiBititolarita.Categoria, out categoriaNumerica);
                        if (listaDecEnteAltrePensioni.Exists(x => x.CodCategoria.Trim().ToUpperInvariant() == (categoriaNumerica != 0 ? categoriaNumerica.ToString() : datiBititolarita.Categoria.Trim().ToUpperInvariant()) && x.TipoApp == "CI"))
                            datiBititolarita.Ente = Utility.StringToNullableByte(listaDecEnteAltrePensioni.First(x => x.CodCategoria.Trim().ToUpperInvariant() == (categoriaNumerica != 0 ? categoriaNumerica.ToString() : datiBititolarita.Categoria.Trim().ToUpperInvariant()) && x.TipoApp == "CI").CodEnte.ToString());
                    }
                    if (!Utility.IsRicostituzione(datiPensione.Gruppo) && prelievoCi.Risposta.ListaBititolarita.Any(x => !x.Ente.HasValue || x.Ente.Value == 0))
                    {
                        errori = "Attenzione: I dati della Bititolarità sono incompleti e non è possibile proseguire con l'acquisizione della domanda";
                        return true;
                    }
                }
            }

            if (tipoDomanda == Utility.TipoDomanda.Ripristino || tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti)
            {
                if (prelievoCi != null && prelievoCi.Risposta != null)
                {
                    datiPensione.DecorrenzaOriginaria = prelievoCi.Risposta.DataDecorrenza;
                    if (prelievoCi.Risposta.DatiPensione != null)
                        datiPensione.DataPerfezionamentoRequisiti = prelievoCi.Risposta.DatiPensione.DataPerfezionamentoRequisiti;
                }
            }

            if (!RecuperaDatiTGP1(ref datiPensione, prelievo, Utility.TipoAppartenenza.CI, sedePensione, isRiapertura, numeroCertificato, out errori))
                return true;

            //ENG - Modifica Supplementi CI Memo 177/2012
            if (prelievoCi != null && prelievoCi.Risposta != null && prelievoCi.Risposta.ListaSupplementi.Count() > 0 && prelievoCi.Risposta.ListaSupplementi.ToList().Exists(x => x.QuotaSupplemento.ToString() == " "))
            {
                errori = "Attenzione: il tipo quota è blank e non è possibile proseguire con l'acquisizione della domanda";
                return true;
            }

            //ENG - Pensioni Ovunque: gestione nuovo pannello
            GestioneControlliDinamici.ControlloDinamico ctrlMetaProcesso = null;
            if ((tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura))
            {
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("SbloccaMetaProcesso", out ctrlMetaProcesso);
            }
            if (Utility.IsPensioniOvunqueAttiva(Utility.TipoAppartenenza.CI) && (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura) && datiPensione.CodiceSedeGP1ALZ6.GetValueOrDefault() != datiPensione.CodiceSede &&
                !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Eliminazione_Controllo_Sede.BYPASS_META_PROCESSO_CI) && (ctrlMetaProcesso == null || String.IsNullOrEmpty(ctrlMetaProcesso.ValoreControllo) || ctrlMetaProcesso.ValoreControllo.Trim().ToUpperInvariant() == "NO"))
            {
                errori = "ATTENZIONE! La sede della domanda (" + datiPensione.CodiceSede.ToString().PadLeft(4, '0') + ") non è corretta rispetto alla sede di gestione della pensione da ricostituire (" + datiPensione.CodiceSedeGP1ALZ6.GetValueOrDefault().ToString().PadLeft(4, '0') + ").";

                mostraPanelloMessBloccantePensioniOvunque = true;
                sedePensioneGP1ALZ6 = datiPensione.CodiceSedeGP1ALZ6.GetValueOrDefault().ToString().PadLeft(4, '0');
                codCategoriaPensione = datiPensione.GetCodCategoria();

                if (!(Utility.IsRicostituzione_MotiviContributivi(datiPensione) || Utility.IsRicostituzione_Supplemento(datiPensione) || isRiapertura))
                    errori = string.Format("{0} Trasferire la domanda alla sede {1:0000} che ha in carico la pensione.", errori, datiPensione.CodiceSedeGP1ALZ6.GetValueOrDefault());
                return true;
            }

            //ENG - Implementata la gestione mancante per le Reversibilità
            //Aggiunta gestione ImportoPagamentoDataMorte49593
            bool checkPresenzaDatiDanteCausaPrelievoCi = (prelievoCi != null && prelievoCi.Risposta != null && prelievoCi.Risposta.DatiDanteCausa != null);
            if (checkPresenzaDatiDanteCausaPrelievoCi)
            {
                if (danteCausa == null)
                    danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();

                if (prelievoCi.Risposta.DatiDanteCausa.CodiceTipoPerequazione != null)
                    danteCausa.CodiceTipoPerequazione = prelievoCi.Risposta.DatiDanteCausa.CodiceTipoPerequazione;

                if (prelievoCi.Risposta.DatiDanteCausa.VirtualeIntegrata != null)
                    danteCausa.VirtualeIntegrata = prelievoCi.Risposta.DatiDanteCausa.VirtualeIntegrata;

                if (prelievoCi.Risposta.DatiDanteCausa.VirtualePura != null)
                    danteCausa.VirtualePura = prelievoCi.Risposta.DatiDanteCausa.VirtualePura;

                if (prelievoCi.Risposta.DatiDanteCausa.Adeguata != null)
                    danteCausa.Adeguata = prelievoCi.Risposta.DatiDanteCausa.Adeguata;

                if (prelievoCi.Risposta.DatiDanteCausa.TotaleQuoteFisse != null)
                    danteCausa.TotaleQuoteFisse = prelievoCi.Risposta.DatiDanteCausa.TotaleQuoteFisse;

                if (prelievoCi.Risposta.DatiDanteCausa.ImportoPagamentoDataMorte49593 != null)
                    danteCausa.ImportoPagamentoDataMorte49593 = prelievoCi.Risposta.DatiDanteCausa.ImportoPagamentoDataMorte49593;
            }

            return true;
        }

        private static bool PrelevaAgo(Entity.ParametriARCA parametriArca, ServiceReferences.WebDom.DatiDomanda datiDomanda, short sedeOperatore, short centroOperativoOperatore,
            Entity.ParametriARCA parametriARCA, Utility.TipoDomanda tipoDomanda, GestionePensione.DatiPensione datiPensione, Entity.DatiPersonaliParziali datiParzialiDA,
            ref string chiavePensione, ref GestioneLavorazione.DatiLavorazione datiLavorazione, out Entity.Anagrafica anagraficaDA,
            out BLCommon.GestioneDanteCausa.DatiDanteCausa danteCausa, out object prelievo, out bool isRicRev, out bool isDiretta, out bool isRicercaManualeDA, out DateTime? maxDecDatiCalcoloAnte96, out string errori, out string msgNonBloccante,
            out bool mostraPanelloMessBloccantePensioniOvunque, out string sedePensioneGP1ALZ6, out string codCategoriaPensione, out string certificatoInseguimentoPensione)
        {
            bool isRiapertura = false;
            anagraficaDA = null;
            danteCausa = null;
            isRicRev = false;
            isDiretta = false;
            errori = "";
            msgNonBloccante = "";
            datiLavorazione = new GestioneLavorazione.DatiLavorazione();
            prelievo = null;
            isRicercaManualeDA = false;
            ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = null;
            List<Entity.Pensione> elencoPensioniDA = null;
            short codiceCategoria = 0;
            string numDomanda = datiDomanda.Dati.Domanda[0].NumDomanda;
            bool isAnte96ByDatiCalcolo = false;
            maxDecDatiCalcoloAnte96 = null;
            //ENG - Pensioni Ovunque: gestione nuovo pannello
            mostraPanelloMessBloccantePensioniOvunque = false;
            sedePensioneGP1ALZ6 = string.Empty;
            codCategoriaPensione = string.Empty;
            certificatoInseguimentoPensione = string.Empty;
            long NDomus;


            if (datiDomanda.Dati != null && datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Count > 0)
                isRiapertura = Utility.IsRiaperturaDomanda(datiDomanda.Dati.Fase.LastOrDefault().CodFase);

            if (isRiapertura)
            {
                ServiceReferences.WebDom.DataSetDomanda.PensioneGenerataRow pensioneGenerata = datiDomanda.Dati.PensioneGenerata.FirstOrDefault(x => x.IndAnnullata == "0");
                codiceCategoria = short.Parse(pensioneGenerata.CodCatPensioneGenAttuale);
                if (!GestioneLiquidazioneAgo.PrelevaDomanda(numDomanda, short.Parse(pensioneGenerata.CodProvinciaGenAttuale.Substring(1) + pensioneGenerata.CodZonaGenAttuale.Substring(1)),
                        codiceCategoria, int.Parse(pensioneGenerata.NumCertificatoGenAttuale), sedeOperatore, centroOperativoOperatore, datiDomanda.Dati.Istanza[0].CodGruppo,
                        datiDomanda.Dati.Istanza[0].CodProdotto, isRiapertura, datiPensione.Tipo, out prelievoAgo, out errori))
                    return true;
                else
                    prelievo = prelievoAgo;
            }
            else
            {
                //caso reversibilità indiretta (no GAIN)
                if (!(tipoDomanda == Utility.TipoDomanda.Superstiti && (datiDomanda.Dati.PensioneRiferimento.Rows.Count == 0 || isPensioneRiferimentoNull(datiDomanda.Dati.PensioneRiferimento[0]))))
                {
                    codiceCategoria = short.Parse(datiDomanda.Dati.PensioneRiferimento[0].CodCatPensioneRifAttuale);
                    if (!GestioneLiquidazioneAgo.PrelevaDomanda(numDomanda, short.Parse(datiDomanda.Dati.PensioneRiferimento[0].CodProvinciaRifAttuale.Substring(1) + datiDomanda.Dati.PensioneRiferimento[0].CodZonaRifAttuale.Substring(1)),
                        codiceCategoria, int.Parse(datiDomanda.Dati.PensioneRiferimento[0].NumCertificatoRifAttuale),
                        sedeOperatore, centroOperativoOperatore, datiDomanda.Dati.Istanza[0].CodGruppo, datiDomanda.Dati.Istanza[0].CodProdotto, isRiapertura, datiPensione.Tipo, out prelievoAgo, out errori))
                        return true;
                    else
                        prelievo = prelievoAgo;
                }
            }

            if (tipoDomanda == Utility.TipoDomanda.Superstiti && !isRiapertura)
            {
                GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
                richiestaArca.Applicazione = parametriARCA.Applicazione;
                richiestaArca.Matricola = parametriARCA.Matricola;
                richiestaArca.Provenienza = parametriARCA.Provenienza;
                richiestaArca.Ruolo = parametriARCA.Ruolo;

                //per reversibilità indiretta recupero codice fiscale DC da WebDom altrimenti da GAIN
                if ((datiDomanda.Dati.PensioneRiferimento.Rows.Count == 0 || isPensioneRiferimentoNull(datiDomanda.Dati.PensioneRiferimento[0])))
                {
                    DataRow[] RelSoggDC = datiDomanda.Dati.RelazioneSoggetto.Select("CodRelazioneSoggetto = 'DA'");
                    DataRow[] SoggDC = datiDomanda.Dati.Soggetto.Select("IdSoggetto = '" + RelSoggDC[0]["IdSoggetto"] + "'");

                    richiestaArca.CodiceFiscaleRichiedente = SoggDC[0]["CodiceFiscale"].ToString();
                    richiestaArca.CodiceFiscale = SoggDC[0]["CodiceFiscale"].ToString();

                    danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                    danteCausa.DecorrenzaPensione = null;
                    danteCausa.Sede = null;
                    danteCausa.Certificato = null;
                    danteCausa.SiglaCategoria = null;
                }
                else
                {
                    isDiretta = true;
                    if (prelievoAgo != null && prelievoAgo.Risposta != null)
                    {
                        richiestaArca.CodiceFiscaleRichiedente = prelievoAgo.Risposta.CodiceFiscale;
                        richiestaArca.CodiceFiscale = prelievoAgo.Risposta.CodiceFiscale;

                        danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                        danteCausa.DecorrenzaPensione = prelievoAgo.Risposta.DataDecorrenza;
                        danteCausa.Sede = prelievoAgo.Richiesta._Sede.ToString().PadLeft(4, '0');
                        danteCausa.Certificato = prelievoAgo.Richiesta._Certificato;

                        //nuova gestione di recupero Sigla categoria
                        danteCausa.SiglaCategoria = datiDomanda.Dati.PensioneRiferimento[0].SiglaCatLav.Trim().ToUpperInvariant();
                    }
                }

                if (!GestioneARCA.GetAreaArcaByCodiceFiscale(richiestaArca, datiPensione.NDomus.ToString(), out anagraficaDA, out elencoPensioniDA, out errori) || !string.IsNullOrEmpty(errori))
                    return false;

                if (danteCausa == null)
                    danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();

                danteCausa.DataMorte = anagraficaDA.DataMorte;
                danteCausa.DataMorteOrigine = anagraficaDA.DataMorte;

                if (datiPensione != null && Utility.IsDomandaSOSPED(datiPensione.SiglaCategoria) && anagraficaDA.DataMorte != null && !Utility.DataSuccessivaA((DateTime)anagraficaDA.DataMorte, new DateTime(1997, 12, 1)))
                {
                    errori = "Per le SOSPED la data di morte del dante causa deve essere maggiore o uguale al 01/12/1997.";
                    return false;
                }

                if (datiDomanda.Dati.Istanza[0].CodProdotto == "0021")
                {
                    datiLavorazione.TipoReversibilita = 'R';
                    datiLavorazione.TipoLiquidazione = "A2";
                }
                else if (datiDomanda.Dati.Istanza[0].CodProdotto == "0022")
                {
                    datiLavorazione.TipoReversibilita = 'I';
                    datiLavorazione.TipoLiquidazione = "A1";
                }
            }
            else if (tipoDomanda == Utility.TipoDomanda.Ricostituzione || tipoDomanda == Utility.TipoDomanda.Ripristino || tipoDomanda == Utility.TipoDomanda.RipristinoSuperstiti || tipoDomanda == Utility.TipoDomanda.Riliquidazione || tipoDomanda == Utility.TipoDomanda.RiliquidazioneSuperstiti || isRiapertura)
            {
                if (prelievoAgo != null && prelievoAgo.Risposta != null)
                {
                    DateTime dataEstremoSuperiore = new DateTime(1995, 12, 31);
                    isAnte96ByDatiCalcolo = ((prelievoAgo.Risposta.ListaCalcoloRetributivo == null || prelievoAgo.Risposta.ListaCalcoloRetributivo.Length == 0) || (prelievoAgo.Risposta.ListaCalcoloRetributivo != null && prelievoAgo.Risposta.ListaCalcoloRetributivo.OrderByDescending(x => x.DecorrenzaOriginariaPensione).FirstOrDefault(y => y.DecorrenzaOriginariaPensione <= dataEstremoSuperiore) != null))
                        && ((prelievoAgo.Risposta.ListaCalcoloContributivo == null || prelievoAgo.Risposta.ListaCalcoloContributivo.Length == 0) || (prelievoAgo.Risposta.ListaCalcoloContributivo != null && prelievoAgo.Risposta.ListaCalcoloContributivo.OrderByDescending(x => x.DecorrenzaCalcoloContibutivo).FirstOrDefault(y => y.DecorrenzaCalcoloContibutivo <= dataEstremoSuperiore) != null));

                    if (isAnte96ByDatiCalcolo)
                    {
                        var decRetr = prelievoAgo.Risposta.ListaCalcoloRetributivo != null && prelievoAgo.Risposta.ListaCalcoloRetributivo.OrderByDescending(x => x.DecorrenzaOriginariaPensione).FirstOrDefault(y => y.DecorrenzaOriginariaPensione <= dataEstremoSuperiore) != null ? prelievoAgo.Risposta.ListaCalcoloRetributivo.OrderByDescending(x => x.DecorrenzaOriginariaPensione).FirstOrDefault(y => y.DecorrenzaOriginariaPensione <= dataEstremoSuperiore).DecorrenzaOriginariaPensione : null;
                        var decContr = prelievoAgo.Risposta.ListaCalcoloContributivo != null && prelievoAgo.Risposta.ListaCalcoloContributivo.OrderByDescending(x => x.DecorrenzaCalcoloContibutivo).FirstOrDefault(y => y.DecorrenzaCalcoloContibutivo <= dataEstremoSuperiore) != null ? prelievoAgo.Risposta.ListaCalcoloContributivo.OrderByDescending(x => x.DecorrenzaCalcoloContibutivo).FirstOrDefault(y => y.DecorrenzaCalcoloContibutivo <= dataEstremoSuperiore).DecorrenzaCalcoloContibutivo : null;
                        maxDecDatiCalcoloAnte96 = new[] { decRetr, decContr }.Max();
                    }
                }
                //salvataggio DC per ricRev
                if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiDanteCausa != null && !(prelievoAgo.Risposta.DatiDanteCausa.IsNull() && datiParzialiDA == null))
                {
                    isRicRev = true;
                    List<Entity.Anagrafica> elencoAnagrafiche = null;

                    string codiceFiscale = string.Empty;
                    string nome = prelievoAgo.Risposta.DatiAnagDanteCausa.Nome;
                    string cognome = prelievoAgo.Risposta.DatiAnagDanteCausa.Cognome;
                    DateTime? dataNascita = prelievoAgo.Risposta.DatiAnagDanteCausa.DataNascita;
                    string sesso = prelievoAgo.Risposta.DatiAnagDanteCausa.Sesso.HasValue ? prelievoAgo.Risposta.DatiAnagDanteCausa.Sesso.Value.ToString() : null;

                    if (datiParzialiDA != null)
                    {
                        if (string.IsNullOrEmpty(datiParzialiDA.Nome) && string.IsNullOrEmpty(datiParzialiDA.Cognome) && !datiParzialiDA.DataNascita.HasValue &&
                            string.IsNullOrEmpty(datiParzialiDA.CodiceFiscale))
                        {
                            isRicercaManualeDA = true;
                            if (!isAnte96ByDatiCalcolo)
                            {
                                errori = "Criteri di ricerca manuale del Dante Causa non validi.";
                                return true;
                            }
                        }

                        nome = datiParzialiDA.Nome;
                        cognome = datiParzialiDA.Cognome;
                        dataNascita = datiParzialiDA.DataNascita;
                        sesso = null;
                        codiceFiscale = datiParzialiDA.CodiceFiscale;
                    }

                    if (!string.IsNullOrEmpty(codiceFiscale))
                    {
                        GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
                        richiestaArca.Applicazione = parametriARCA.Applicazione;
                        richiestaArca.Matricola = parametriARCA.Matricola;
                        richiestaArca.Provenienza = parametriARCA.Provenienza;
                        richiestaArca.Ruolo = parametriARCA.Ruolo;
                        richiestaArca.CodiceFiscaleRichiedente = codiceFiscale;
                        richiestaArca.CodiceFiscale = codiceFiscale;

                        if (!GestioneARCA.GetAreaArcaByCodiceFiscale(richiestaArca, datiPensione.NDomus.ToString(), out anagraficaDA, out elencoPensioniDA, out errori))
                            return false;
                    }
                    else
                    {
                        if (!GetDatiParziali(parametriArca, nome, cognome, dataNascita, sesso, numDomanda, out elencoAnagrafiche, out errori))
                            isRicercaManualeDA = true;

                        if (isAnte96ByDatiCalcolo)
                        {
                            errori = string.Empty;
                        }

                        if (!string.IsNullOrEmpty(errori))
                            return true;

                        if (elencoAnagrafiche != null)
                        {
                            if (elencoAnagrafiche.Count == 1)
                            {
                                //singolo dante causa trovato
                                anagraficaDA = elencoAnagrafiche[0];
                            }
                            else
                            {
                                //trovati sinonimi
                                foreach (Entity.Anagrafica anag in elencoAnagrafiche)
                                {
                                    if (Utility.IsNullOrWhiteSpace(anag.CodiceFiscale) || anag.CodiceFiscale.Trim().Length < 16 || (!string.IsNullOrEmpty(prelievoAgo.Risposta.DatiAnagDanteCausa.CodiceFiscale) &&
                                        prelievoAgo.Risposta.DatiAnagDanteCausa.CodiceFiscale.Length == 16 && anag.CodiceFiscale != prelievoAgo.Risposta.DatiAnagDanteCausa.CodiceFiscale))
                                        continue;
                                    int codComuneInps = 0;
                                    GestioneDBSComuni.GetCodInpsComuneByCodCatastale(anag.CodiceComuneNascita, Utility.TipoAppartenenza.AGO.ToString(), 0, false, out codComuneInps);
                                    if (codComuneInps == prelievoAgo.Risposta.DatiAnagDanteCausa.CodiceComuneInps)
                                    {
                                        GestioneARCA.RichiestaARCA richiestaArca = new GestioneARCA.RichiestaARCA();
                                        richiestaArca.Applicazione = parametriARCA.Applicazione;
                                        richiestaArca.Matricola = parametriARCA.Matricola;
                                        richiestaArca.Provenienza = parametriARCA.Provenienza;
                                        richiestaArca.Ruolo = parametriARCA.Ruolo;
                                        richiestaArca.CodiceFiscaleRichiedente = anag.CodiceFiscale;
                                        richiestaArca.CodiceFiscale = anag.CodiceFiscale;

                                        if (!GestioneARCA.GetAreaArcaByCodiceFiscale(richiestaArca, datiPensione.NDomus.ToString(), out anagraficaDA, out elencoPensioniDA, out errori))
                                            return false;
                                        break;
                                    }
                                }
                            }
                        }
                    }

                    if (anagraficaDA != null)
                    {
                        danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                        if (prelievoAgo.Risposta.DatiDanteCausa.DecorrenzaPensione.HasValue && !String.IsNullOrEmpty(prelievoAgo.Risposta.DatiDanteCausa.Sede) &&
                            !String.IsNullOrEmpty(prelievoAgo.Risposta.DatiDanteCausa.SiglaCategoria) && prelievoAgo.Risposta.DatiDanteCausa.Certificato.HasValue)
                            isDiretta = true;
                        danteCausa = prelievoAgo.Risposta.DatiDanteCausa;

                        if (!danteCausa.DataMorte.HasValue || danteCausa.DataMorte.Value.CompareTo(anagraficaDA.DataMorte) != 0)
                            danteCausa.DataMorte = anagraficaDA.DataMorte;
                        if (!danteCausa.DataMorteOrigine.HasValue)
                            danteCausa.DataMorteOrigine = anagraficaDA.DataMorte;

                        // Se la data matrimonio non proviene dal prelievo allora mantengo il valore di ARCA
                        if (prelievoAgo.Risposta.DatiAnagDanteCausa != null && prelievoAgo.Risposta.DatiAnagDanteCausa.DataMatrimonio.HasValue)
                        {
                            anagraficaDA.DataMatrimonio = prelievoAgo.Risposta.DatiAnagDanteCausa.DataMatrimonio;
                            danteCausa.DataMatrimonioByPrelievo = true;
                        }
                        if (prelievoAgo.Risposta.DatiAnagDanteCausa != null && !string.IsNullOrEmpty(prelievoAgo.Risposta.DatiAnagDanteCausa.Cittadinanza))
                        {
                            anagraficaDA.Cittadinanza = prelievoAgo.Risposta.DatiAnagDanteCausa.Cittadinanza;
                            danteCausa.CittadinanzaByArca = true;
                        }
                        if (prelievoAgo.Risposta.DatiDanteCausa != null && !string.IsNullOrEmpty(prelievoAgo.Risposta.DatiDanteCausa.StatoEEResidenza))
                        {
                            danteCausa.StatoEEResidenza = prelievoAgo.Risposta.DatiDanteCausa.StatoEEResidenza;
                            danteCausa.StatoEEResidenzaByArca = true;
                        }
                    }
                    else /*if (isAnte96ByDatiCalcolo)*/
                    {
                        danteCausa = new BLCommon.GestioneDanteCausa.DatiDanteCausa();
                        anagraficaDA = new Entity.Anagrafica();
                        if (prelievoAgo.Risposta.DatiDanteCausa.DecorrenzaPensione.HasValue && !String.IsNullOrEmpty(prelievoAgo.Risposta.DatiDanteCausa.Sede) &&
                            !String.IsNullOrEmpty(prelievoAgo.Risposta.DatiDanteCausa.SiglaCategoria) && prelievoAgo.Risposta.DatiDanteCausa.Certificato.HasValue)
                            isDiretta = true;
                        danteCausa = prelievoAgo.Risposta.DatiDanteCausa;

                        // Se la data matrimonio non proviene dal prelievo allora mantengo il valore di ARCA
                        if (prelievoAgo.Risposta.DatiAnagDanteCausa != null && prelievoAgo.Risposta.DatiAnagDanteCausa.DataMatrimonio.HasValue)
                        {
                            anagraficaDA.DataMatrimonio = prelievoAgo.Risposta.DatiAnagDanteCausa.DataMatrimonio;
                            danteCausa.DataMatrimonioByPrelievo = true;
                        }
                        if (prelievoAgo.Risposta.DatiAnagDanteCausa != null && !string.IsNullOrEmpty(prelievoAgo.Risposta.DatiAnagDanteCausa.Cittadinanza))
                        {
                            anagraficaDA.Cittadinanza = prelievoAgo.Risposta.DatiAnagDanteCausa.Cittadinanza;
                            danteCausa.CittadinanzaByArca = true;
                        }
                        if (prelievoAgo.Risposta.DatiDanteCausa != null && !string.IsNullOrEmpty(prelievoAgo.Risposta.DatiDanteCausa.StatoEEResidenza))
                        {
                            danteCausa.StatoEEResidenza = prelievoAgo.Risposta.DatiDanteCausa.StatoEEResidenza;
                            danteCausa.StatoEEResidenzaByArca = true;
                        }

                        anagraficaDA.CodiceFiscale = "DANTEC_";
                        anagraficaDA.Nome = prelievoAgo.Risposta.DatiAnagDanteCausa.Nome;
                        anagraficaDA.Cognome = prelievoAgo.Risposta.DatiAnagDanteCausa.Cognome;
                        anagraficaDA.DataNascita = prelievoAgo.Risposta.DatiAnagDanteCausa.DataNascita;
                        anagraficaDA.Sesso = prelievoAgo.Risposta.DatiAnagDanteCausa.Sesso.HasValue ? (char?)prelievoAgo.Risposta.DatiAnagDanteCausa.Sesso.Value : (char?)null;
                    }
                }

                if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) && danteCausa == null)
                {
                    isRicercaManualeDA = true;
                    if (!isAnte96ByDatiCalcolo)
                    {
                        if (datiParzialiDA != null)
                        {
                            if (!string.IsNullOrEmpty(datiParzialiDA.CodiceFiscale))
                                errori = string.Format("Dati anagrafici del Dante causa non trovati per il codice fiscale '{0}'", datiParzialiDA.CodiceFiscale);
                            else
                                errori = string.Format("Il Dante Causa ricercato manualmente non è presente su ARCA.<br /><b>Cognome:</b> {0}<br /><b>Nome:</b> {1}<br /><b>Data Nascita:</b> {2:dd/MM/yyyy}<br />",
                                            datiParzialiDA.Cognome, datiParzialiDA.Nome, datiParzialiDA.DataNascita);
                        }
                        else
                        {
                            if (prelievoAgo == null || prelievoAgo.Risposta == null || prelievoAgo.Risposta.DatiAnagDanteCausa == null)
                                errori = "Dati anagrafici del Dante Causa non presenti sull'archivio pensione.";
                            else if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiDanteCausa != null)
                                errori = string.Format("Il dante causa recuperato dall’archivio pensioni potrebbe non essere presente su ARCA oppure avere dei sinonimi. Si prega di controllare ARCA, di seguito i dati di interesse per la verifica." +
                                    "<br/><b>Cognome:</b> {0}" +
                                    "<br/><b>Nome:</b> {1}" +
                                    "<br/><b>Data Nascita:</b> {2:dd/MM/yyyy}" +
                                    "<br/><b>Sesso:</b> {3}",
                                    prelievoAgo.Risposta.DatiAnagDanteCausa.Cognome, prelievoAgo.Risposta.DatiAnagDanteCausa.Nome, prelievoAgo.Risposta.DatiAnagDanteCausa.DataNascita,
                                    prelievoAgo.Risposta.DatiAnagDanteCausa.Sesso.HasValue ? prelievoAgo.Risposta.DatiAnagDanteCausa.Sesso.Value.ToString() : string.Empty);
                        }
                        return true;
                    }
                }

                if (prelievoAgo != null && prelievoAgo.Risposta != null)
                {
                    if (!(Utility.IsDomandaRiliquidazione(datiPensione).GetValueOrDefault() && tipoDomanda != Utility.TipoDomanda.Ricostituzione && !isRiapertura))
                        datiPensione.DecorrenzaOriginaria = prelievoAgo.Risposta.DataDecorrenza;
                    if (Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione) && isRiapertura)
                        datiPensione.TrasformazioneAOI = false;
                }

                datiLavorazione.TipoReversibilita = null;
                datiLavorazione.TipoLiquidazione = "B1";
            }

            //ENG - Spacchettate SOPGI         
            if (Utility.IsDomandaSOPGI(datiPensione.SiglaCategoria))
            {
                if (danteCausa == null || !danteCausa.DataMorte.HasValue)
                {
                    errori = "Data Morte non presente. Verificare in Arca";
                    return true;
                }

                if (Utility.IsRicostituzione(datiPensione.Gruppo))
                {
                    if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.ListaDatiContributiviINPGI != null && prelievoAgo.Risposta.ListaDatiContributiviINPGI.Count() > 0)
                    {
                        List<GestioneDecodifica.CodeGestioneQuotaFondoINPGI> elencoCodeGestioneQuotaFondoINPGI = null;
                        GestioneDecodifica.GetCodeGestioneQuotaFondoINPGI(out elencoCodeGestioneQuotaFondoINPGI);

                        if (elencoCodeGestioneQuotaFondoINPGI != null && elencoCodeGestioneQuotaFondoINPGI.Count() > 0)
                        {
                            foreach (GestioneQuotaFondoINPGI.DatiCalcoloContributivoINPGI datiContributivi in prelievoAgo.Risposta.ListaDatiContributiviINPGI)
                            {
                                if (elencoCodeGestioneQuotaFondoINPGI.Exists(x => x.Id == datiContributivi.CodiceGestione && x.TraduzioneSuGP == "FA"))
                                    datiPensione.GP1AV91B = "2";
                            }
                        }
                    }
                }
            }

            GestioneControlliDinamici.ControlloDinamico controlloDinamicoSOPGI = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("BloccoSOPGIAnte072022", out controlloDinamicoSOPGI);

            if (!String.IsNullOrEmpty(datiPensione.SiglaCategoria) && Utility.IsDomandaSOPGI(datiPensione.SiglaCategoria))
            {
                GestioneControlliDinamici.ControlloDinamico ctrlAperturaSOPGI_Migrate = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AperturaSOPGI_Migrate", out ctrlAperturaSOPGI_Migrate);
                if (!(ctrlAperturaSOPGI_Migrate != null && !String.IsNullOrEmpty(ctrlAperturaSOPGI_Migrate.ValoreControllo) && !String.IsNullOrEmpty(ctrlAperturaSOPGI_Migrate.ValoreControllo.Trim()) && ctrlAperturaSOPGI_Migrate.ValoreControllo == "SI" &&
                    Utility.IsRicostituzione(datiPensione.Gruppo) && prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiPensione != null && !string.IsNullOrEmpty(prelievoAgo.Risposta.DatiPensione.GP1AV91B) && prelievoAgo.Risposta.DatiPensione.GP1AV91B == "2"))
                {
                    if (controlloDinamicoSOPGI != null && !String.IsNullOrEmpty(controlloDinamicoSOPGI.ValoreControllo) && controlloDinamicoSOPGI.ValoreControllo.Trim().ToUpperInvariant() == "SI"
                        && danteCausa != null && danteCausa.DataMorte.HasValue && !Utility.DataSuccessivaA(danteCausa.DataMorte.Value, new DateTime(2022, 7, 1)))
                    {
                        errori = "Non è possibile acquisire la domanda. Data Morte precedente al 01/07/2022";
                        return true;
                    }
                }
            }

            if (Utility.IsRicostituzione(datiPensione.Gruppo) || isRiapertura)
            {
                if (!String.IsNullOrEmpty(datiPensione.SiglaCategoria) && !String.IsNullOrEmpty(datiPensione.SiglaCategoria.Trim()))
                {
                    if (datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SO" || datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SOCOM" || datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SOART"
                        || datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SR")
                    {
                        if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiPensione != null && prelievoAgo.Risposta.DatiPensione.GP1AJSP.HasValue
                            && prelievoAgo.Risposta.DatiPensione.GP1AJSP == '1')
                        {
                            datiPensione.GP1AJSP = '1';
                        }
                    }

                }
            }


            if (Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) || Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiapertura)
                || Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiapertura) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiapertura))
            {
                short codiceCategoriaSuperstite = 0;
                string codCategoriaSuperstite = datiPensione.GetCodCategoria();
                short.TryParse(codCategoriaSuperstite, out codiceCategoriaSuperstite);

                Entity.Pensione pensioneFascicolo = null;
                //ENG - PL Reversibilita/Indiretta eliminata più volte (NO RIC/TRF)
                bool chiamaTGP4pensioniEliminate = false;

                if (tipoDomanda != Utility.TipoDomanda.Ricostituzione && !isRiapertura)
                {
                    if (elencoPensioniDA != null && elencoPensioniDA.Count > 0)
                    {
                        if (Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa))
                        {
                            Entity.Pensione pensioneTempSopgi = elencoPensioniDA.Where(x => x.Categoria == "SOINPGI").FirstOrDefault();
                            if (pensioneTempSopgi != null)
                                pensioneTempSopgi.Categoria = "SOPGI";

                            Entity.Pensione pensioneTempVopgi = elencoPensioniDA.Where(x => x.Categoria == "VOINPGI").FirstOrDefault();
                            if (pensioneTempVopgi != null)
                                pensioneTempVopgi.Categoria = "VOPGI";

                            Entity.Pensione pensioneTempIopgi = elencoPensioniDA.Where(x => x.Categoria == "IOINPGI").FirstOrDefault();
                            if (pensioneTempIopgi != null)
                                pensioneTempIopgi.Categoria = "IOPGI";
                        }

                        pensioneFascicolo = elencoPensioniDA.Find(x => x.Categoria.Trim() == datiPensione.SiglaCategoria.Trim() && string.IsNullOrEmpty(x.Eliminazione) && x.TipoComponente.GetValueOrDefault() == 'P');
                        if (pensioneFascicolo == null)
                        {
                            pensioneFascicolo = elencoPensioniDA.Find(x => x.Categoria.Trim() == datiPensione.SiglaCategoria.Trim() && x.Eliminazione != "5" && x.TipoComponente.GetValueOrDefault() == 'P');
                            //ENG - Se ci sono più pensioni eliminate devo chiamare il TGP4 per ogni pensione eliminata
                            if (elencoPensioniDA.Count(x => x.Categoria.Trim() == datiPensione.SiglaCategoria.Trim() && x.Eliminazione != "5" && x.TipoComponente.GetValueOrDefault() == 'P') > 1)
                                chiamaTGP4pensioniEliminate = true;
                        }
                    }
                }

                if (anagraficaDA != null)
                {
                    if (BLCommon.GestioneDanteCausa.IsPresenteDomandaInLiquidazionePerControlloSpacENPALS(anagraficaDA.CodiceFiscale, null, null, null, false, out NDomus))
                    {
                        errori = string.Format("Non è possibile acquisire la domanda in presenza di altre domande in liquidazione sullo stesso dante causa. Numero domanda: {0}", NDomus);
                        return true;
                    }
                }

                if (pensioneFascicolo != null || tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura)
                {
                    short? categoriaFascicolo = null;
                    short? sedeFascicolo = null;
                    int? numeroFascicolo = null;

                    if (tipoDomanda != Utility.TipoDomanda.Ricostituzione && !isRiapertura)
                        chiavePensione = codiceCategoriaSuperstite.ToString().PadLeft(3, '0') + pensioneFascicolo.Sede.PadLeft(4, '0') + pensioneFascicolo.Certificato.PadLeft(8, '0');
                    else if (prelievoAgo != null && prelievoAgo.Risposta != null)
                        chiavePensione = codiceCategoriaSuperstite.ToString().PadLeft(3, '0') + prelievoAgo.Risposta.SedePensione.ToString().PadLeft(4, '0') + prelievoAgo.Risposta.CertificatoPensione.ToString().PadLeft(8, '0');

                    //ENG - PL Reversibilità/Indirette (la variabile chiamaTGP4pensioniEliminate rimane a false per le RIC/TRF che non devono essere coinvolte dal nuovo flusso)
                    if (chiamaTGP4pensioniEliminate == true)
                    {
                        if (elencoPensioniDA != null && elencoPensioniDA.Count > 0)
                        {
                            List<Entity.Pensione> elencoPensioniEliminate = elencoPensioniDA.FindAll(x => x.Categoria.Trim() == datiPensione.SiglaCategoria.Trim() && x.Eliminazione != "5" && x.TipoComponente.GetValueOrDefault() == 'P');
                            if (elencoPensioniEliminate != null && elencoPensioniEliminate.Count > 0)
                            {
                                foreach (Entity.Pensione pensioneEliminataDC in elencoPensioniEliminate)
                                {
                                    chiavePensione = codiceCategoriaSuperstite.ToString().PadLeft(3, '0') + pensioneEliminataDC.Sede.PadLeft(4, '0') + pensioneEliminataDC.Certificato.PadLeft(8, '0');
                                    GestioneDatiPensioni.GetCodiceFascicoloByChiavePensione(datiPensione.NDomus, chiavePensione, out categoriaFascicolo, out sedeFascicolo, out numeroFascicolo, out errori);
                                    if (numeroFascicolo.HasValue) //interrompo la chiamata al TGP4 appena si trova una pensione per la quale viene restituito il numero fascicolo
                                        break;
                                }
                            }
                        }

                    }
                    else
                        GestioneDatiPensioni.GetCodiceFascicoloByChiavePensione(datiPensione.NDomus, chiavePensione, out categoriaFascicolo, out sedeFascicolo, out numeroFascicolo, out errori);


                    if (!string.IsNullOrEmpty(errori))
                        return true;

                    if ((danteCausa.CategoriaFascicolo.HasValue && danteCausa.CategoriaFascicolo.Value != categoriaFascicolo) ||
                        (danteCausa.SedeFascicolo.HasValue && danteCausa.SedeFascicolo.Value != sedeFascicolo) ||
                        (danteCausa.NumeroFascicolo.HasValue && danteCausa.NumeroFascicolo.Value != numeroFascicolo))
                    {
                        errori = "Il codice fascicolo presente sull'Archivio Pensione è diverso da quello presente su ARCA.";
                        return true;
                    }

                    if (BLCommon.GestioneDanteCausa.IsPresenteDomandaInLiquidazionePerControlloSpacENPALS(anagraficaDA.CodiceFiscale, categoriaFascicolo, sedeFascicolo, numeroFascicolo, true, out NDomus))
                    {
                        errori = string.Format("Non è possibile acquisire la domanda in presenza di altre domande in liquidazione sullo stesso dante causa. Numero domanda: {0}", NDomus);
                        return true;
                    }

                    danteCausa.CategoriaFascicolo = categoriaFascicolo;
                    danteCausa.SedeFascicolo = sedeFascicolo;
                    danteCausa.NumeroFascicolo = numeroFascicolo;
                    danteCausa.IsFascicoloGenerato = false;
                }
                else if (anagraficaDA != null)
                {
                    ServiceReferences.GeneraCertificati.FascicoloOutput fascicolo = null;
                    GestioneGeneraCertificati.GeneraFascicolo(numDomanda, codiceCategoriaSuperstite.ToString(), "9990", anagraficaDA.CodiceFiscale, out fascicolo, out errori);

                    if (!string.IsNullOrEmpty(errori))
                        return true;

                    danteCausa.CategoriaFascicolo = codiceCategoriaSuperstite;
                    danteCausa.SedeFascicolo = 9990;
                    danteCausa.NumeroFascicolo = (int)fascicolo.NumeroFascicolo;
                    danteCausa.IsFascicoloGenerato = true;
                }
            }

            if (prelievoAgo != null && prelievoAgo.Risposta != null)
            {
                if (new List<short> { 82, 83, 84 }.Contains(prelievoAgo.Risposta.CategoriaPensione) && prelievoAgo.Risposta.DatiPensioniDatiGenerici != null &&
                    prelievoAgo.Risposta.DatiPensioniDatiGenerici.DataAssunzioneCarico.HasValue)
                {
                    GestioneControlliDinamici.ControlloDinamico controlloDinamicoDAI = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("Abilita_DAI_ante_2003", out controlloDinamicoDAI);
                    if (controlloDinamicoDAI != null && !String.IsNullOrEmpty(controlloDinamicoDAI.ValoreControllo) && controlloDinamicoDAI.ValoreControllo.Trim().ToUpperInvariant() != "SI" &&
                        !Utility.DataSuccessivaA(prelievoAgo.Risposta.DatiPensioniDatiGenerici.DataAssunzioneCarico.Value, new DateTime(2003, 12, 1)))
                    {
                        errori = "Attenzione si sta prelevando una domanda della gestione DAI, la cui prima liquidata è stata presa in carico prima del 12/2003.";
                        return true;
                    }
                }

                short sedePensione = prelievoAgo.Risposta.SedePensione;
                GestioneControlliDinamici.ControlloDinamico ctrlMetaProcesso = null;
                if ((Utility.IsRicostituzione(datiPensione.Gruppo) || isRiapertura) && Utility.IsPensioniOvunqueAttiva(Utility.TipoAppartenenza.AGO))
                {
                    sedePensione = prelievoAgo.Risposta.DatiPensione.CodiceSedeGP1ALZ6.GetValueOrDefault();
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("SbloccaMetaProcesso", out ctrlMetaProcesso);
                }

                //Il controllo deve essere effettuato solo sulle ricostituzioni e le trasformazioni, non sulle reversibilità della linea AGO (ENPALS e non).
                //ENG - Pensioni Ovunque: gestione nuovo pannello
                if ((tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura) &&
                    (sedePensione != datiPensione.CodiceSede &&
                    ((!Utility.IsDomandaAPEPrecoci(datiPensione) && !(prelievoAgo.Risposta.DatiMaggiorazioniBenefici != null && prelievoAgo.Risposta.DatiMaggiorazioniBenefici.TipoSettimaneBeneficio == "11") &&
                    !Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) && !Utility.IsGestioneENPALSConSedeDestinazione(datiPensione)) || (!Utility.IsPensioniOvunqueAttiva(Utility.TipoAppartenenza.AGO) && sedePensione != prelievoAgo.Risposta.DatiPensione.CodiceSedeDestinazione.Value))) &&
                    !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Eliminazione_Controllo_Sede.BYPASS_META_PROCESSO_AGO) && (ctrlMetaProcesso == null || String.IsNullOrEmpty(ctrlMetaProcesso.ValoreControllo) || ctrlMetaProcesso.ValoreControllo.Trim().ToUpperInvariant() == "NO"))
                {
                    errori = "ATTENZIONE! La sede della domanda (" + datiPensione.CodiceSede.ToString().PadLeft(4, '0') + ") non è corretta rispetto alla sede di gestione della pensione da ricostituire (" + sedePensione.ToString().PadLeft(4, '0') + ").";

                    mostraPanelloMessBloccantePensioniOvunque = true;
                    sedePensioneGP1ALZ6 = sedePensione.ToString().PadLeft(4, '0');
                    codCategoriaPensione = datiPensione.GetCodCategoria();

                    if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.CertificatoPensione > 0)
                        certificatoInseguimentoPensione = prelievoAgo.Risposta.CertificatoPensione.ToString().PadLeft(8, '0');
                    else
                        certificatoInseguimentoPensione = string.Empty;

                    if (Utility.IsPolarizzazionePerGestioneENPALSAttiva(datiPensione) &&
                        !(Utility.IsRicostituzione_MotiviContributivi(datiPensione) || Utility.IsRicostituzione_Supplemento(datiPensione) || isRiapertura))
                        errori = string.Format("{0} Trasferire la domanda alla sede {1:0000} che ha in carico la pensione.", errori, sedePensione);
                    return true;
                }

                if (prelievoAgo.Risposta.DatiENPALS != null
                    && !string.IsNullOrEmpty(prelievoAgo.Risposta.DatiENPALS.TipoLiquidazioneProvvisoria)
                    && prelievoAgo.Risposta.DatiENPALS.TipoLiquidazioneProvvisoria != "0"
                    && prelievoAgo.Risposta.DatiENPALS.TipoLiquidazioneProvvisoria != "3"
                    && prelievoAgo.Risposta.DatiENPALS.TipoLiquidazioneProvvisoria != "4")
                {
                    errori = "ATTENZIONE! Sul campo GP1AZ11F sono presenti codici diversi da 0, 3 o 4";
                    return true;
                }

                // Caso ricostituzione non contributiva
                if (tipoDomanda == Utility.TipoDomanda.Ricostituzione && !Utility.IsRicostituzione_MotiviContributivi(datiPensione) && Utility.IsDomandaENPALS(datiPensione.Gestione))
                {
                    // Caso ENPALS in cui esiste la quota D, ma non esiste l'importo del comma 707
                    if (prelievoAgo.Risposta.ListaCalcoloContributivo != null && prelievoAgo.Risposta.ListaCalcoloContributivo.FirstOrDefault(x => x.IsQuotaDL214Presente()) != null &&
                        prelievoAgo.Risposta.DatiENPALS != null && !prelievoAgo.Risposta.DatiENPALS.ImportoPensione707.HasValue)
                    {
                        errori = "Attenzione il doppio calcolo non è stato effettuato per la pensione " + string.Format("{0:000}-{1:0000}-{2:00000000}", prelievoAgo.Risposta.CategoriaPensione, prelievoAgo.Risposta.SedePensione, prelievoAgo.Risposta.CertificatoPensione) + ". Effettuare la ricostituzione contributiva della pensione per comma 707";
                        return true;
                    }

                    //3.12 Determinazione del tipo di calcolo in assenza delle quote dei dati di calcolo (ENPALS)
                    //come già fatto per reversibilità ENPALS
                    if (!prelievoAgo.Risposta.DatiPensione.TipoCalcolo.HasValue &&
                        !((prelievoAgo.Risposta.CategoriaPensione == 801 || prelievoAgo.Risposta.CategoriaPensione == 802) && prelievoAgo.Risposta.SedePensione == 9933))
                    {
                        List<string> codiciGP1AF03Ammessi = new List<string> { "1", "2", "3", "4", "8" };
                        if (!codiciGP1AF03Ammessi.Contains(prelievoAgo.Risposta.GP1AF03))
                        {
                            errori = "Attenzione tipo calcolo non determinabile (GP1AF03 = '" + (prelievoAgo.Risposta.GP1AF03 != null ? prelievoAgo.Risposta.GP1AF03 : string.Empty) + "')";
                            return true;
                        }
                    }
                }

                // Caso reversibilità ENPALS
                if (Utility.IsDomandaReversibilita(datiPensione) && Utility.IsDomandaENPALS(datiPensione.Gestione))
                {
                    // Caso ENPALS in cui esiste la quota D, ma non esiste l'importo del comma 707
                    if (prelievoAgo.Risposta.ListaCalcoloContributivo != null && prelievoAgo.Risposta.ListaCalcoloContributivo.FirstOrDefault(x => x.IsQuotaDL214Presente()) != null &&
                        prelievoAgo.Risposta.DatiENPALS != null && !prelievoAgo.Risposta.DatiENPALS.ImportoPensione707.HasValue)
                    {
                        errori = "Attenzione il doppio calcolo non è stato effettuato per la pensione " + string.Format("{0:000}-{1:0000}-{2:00000000}", prelievoAgo.Risposta.CategoriaPensione, prelievoAgo.Risposta.SedePensione, prelievoAgo.Risposta.CertificatoPensione) + ". Effettuare la ricostituzione contributiva sulla pensione del dante causa per comma 707";
                        return true;
                    }

                    if (danteCausa != null && danteCausa.IsFascicoloGenerato.HasValue && danteCausa.IsFascicoloGenerato.GetValueOrDefault() &&
                        !prelievoAgo.Risposta.DatiPensione.TipoCalcolo.HasValue &&
                        !((prelievoAgo.Risposta.CategoriaPensione == 801 || prelievoAgo.Risposta.CategoriaPensione == 802) && prelievoAgo.Risposta.SedePensione == 9933))
                    {
                        List<string> codiciGP1AF03Ammessi = new List<string> { "1", "2", "3", "4", "8" };
                        if (!codiciGP1AF03Ammessi.Contains(prelievoAgo.Risposta.GP1AF03))
                        {
                            errori = "Attenzione tipo calcolo non determinabile (GP1AF03 = '" + (prelievoAgo.Risposta.GP1AF03 != null ? prelievoAgo.Risposta.GP1AF03 : string.Empty) + "')";
                            return true;
                        }
                    }
                }

                //riapertura o ricostituzione caso superstiti
                //Eng - il blocco deve essere rimosso e cambiato in messaggio informativo per le ricostituzioni con prodotto 0413 che non abbiano categoria "SOSPETT" o "SOSPORT"
                //Inserito controllo dinamico SbloccoRIC_SO_TitDomDiversoTitPens per attivare o disattivare la modifica
                if ((tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura) && datiPensione.SiglaCategoria.StartsWith("S"))
                {
                    ServiceReferences.WebDom.DataSetDomanda.SoggettoRow rigaTitolareFromWebDom = null;
                    RecuperaTitolareFromWebDom(datiDomanda, out rigaTitolareFromWebDom);
                    GestioneControlliDinamici.ControlloDinamico ctrl = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("SbloccoRIC_SO_TitDomDiversoTitPens", out ctrl);
                    if (prelievoAgo.Risposta.ListaFamiliari.FirstOrDefault(x => x.Familiare.CodiceFiscale == rigaTitolareFromWebDom.CodiceFiscale && x.Familiare.FlagTitolare.GetValueOrDefault()) == null)
                    {
                        if (ctrl != null && ctrl.ValoreControllo == "SI" && tipoDomanda == Utility.TipoDomanda.Ricostituzione && datiPensione.SiglaCategoria.Trim() != "SOSPETT" && datiPensione.SiglaCategoria.Trim() != "SOSPORT" && datiPensione.Prodotto == "0413")
                        {
                            msgNonBloccante = "Il Titolare della domanda è diverso dal titolare della pensione. SI precisa che i dati presenti nei pannelli (ad esclusione del pannello TITOLARE) si riferiscono al titolare della pensione.";
                        }
                        else
                        {
                            errori = "Attenzione! Non è possibile acquisire una domanda di ricostituzione o trasformazione da provvisoria se il titolare della domanda non coincide con l'intestatario della pensione";
                            return true;
                        }
                    }

                    // Rimosso a seguito dell'intervento richiesto sul documento LiqPens_Analisi_Spacchettamento_ENPALS@20170901_v4.8.docx
                    ////Per tutte le domande di ricostituzione/trasformazione di pensioni ai superstiti ENPALS
                    ////se la “Data Revisione Sanitaria” è >= “Data Domanda” OPPURE >= “Data di Acquisizione” ALLORA l’acquisizione sarà bloccata
                    //DateTime dataOdierna = DateTime.Now;
                    //if (prelievoAgo.Risposta.DatiIstruttoria != null && prelievoAgo.Risposta.DatiIstruttoria.ScadenzaRevisioneSanitaria != null &&
                    //    (Utility.DataSuccessivaA(prelievoAgo.Risposta.DatiIstruttoria.ScadenzaRevisioneSanitaria.GetValueOrDefault(), Utility.DataFromString(datiDomanda.Dati.Istanza[0].DataPresentazione, Utility.FormatoData.AAAAmmGG).Value) ||
                    //    Utility.DataSuccessivaA(prelievoAgo.Risposta.DatiIstruttoria.ScadenzaRevisioneSanitaria.GetValueOrDefault(), dataOdierna)))
                    //{
                    //    errori = "Attenzione è presente una data revisione sanitaria. Lavorare la domanda con la procedura REVSAN.";
                    //    return true;
                    //}
                }

                //riapertura o ricostituzione caso NON superstiti
                if ((tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura) && !datiPensione.SiglaCategoria.StartsWith("S"))
                {
                    if ((prelievoAgo.Risposta.DatiDetrazioni.DetrazioniReddito == 3) ^
                        (new List<long> { 1, 2, 3, 4 }.Contains(prelievoAgo.Risposta.DatiBeneficioVittimeTerrorismo.TipologiaPrestazione.GetValueOrDefault())))
                    {
                        errori = "Attenzione! Non è possibile acquisire una domanda di ricostituzione o trasformazione da provvisoria se esiste solo il campo delle detrazioni = 3 senza GP1AC01 pari a 1, 2, 3 o 4 o viceversa";
                        return true;
                    }
                }

                if (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura)
                {
                    if (prelievoAgo.Risposta.DatiEliminazione != null)
                    {
                        if (prelievoAgo.Risposta.DatiEliminazione.CodiceMotivo.HasValue)
                        {
                            GestioneControlliDinamici.ControlloDinamico ctrl = null;
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneControlloRicPensioniEliminate", out ctrl);
                            if (ctrl != null && ctrl.ValoreControllo == "SI")
                            {
                                //Memo 50
                                //è possibile ricostituire pensioni eliminate senza alcuna rata estratta solo se:
                                //sono state eliminate per decesso
                                //il mese della data evento è diverso dalla data decorrenza
                                if (!(prelievoAgo.Risposta.DatiEliminazione.CodiceMotivo.Value == 1 && prelievoAgo.Risposta.DatiEliminazione.DataEvento.HasValue && datiPensione.DecorrenzaOriginaria.HasValue &&
                                    prelievoAgo.Risposta.DatiEliminazione.DataEvento.Value.Month != datiPensione.DecorrenzaOriginaria.Value.Month) && !prelievoAgo.Risposta.IsRataEstratta)
                                {
                                    errori = "Attenzione! Non è possibile acquisire una domanda di ricostituzione o trasformazione da provvisoria se la pensione è stata eliminata e non è stata estratta nessuna rata.";
                                    return true;
                                }
                            }
                            else
                            {
                                // Se la pensione è eliminata e non è ancora stata estratta la rata allora non è possibile acquisire la domanda di ricostituzione / trasformazione
                                if (!prelievoAgo.Risposta.IsRataEstratta)
                                {
                                    errori = "Attenzione! Non è possibile acquisire una domanda di ricostituzione o trasformazione da provvisoria se la pensione è stata eliminata e non è stata estratta nessuna rata.";
                                    return true;
                                }
                            }


                            // Se il motivo dell'eliminazione è diverso dai codici 1, 3, 4, A, N allora non è possibile acquisire la ricostituzione / trasformazione
                            // Tabella di decodifica: DecodificaCodiceEliminazione
                            // 1 = 1
                            // 3 = 3
                            // 4 = 4
                            // A = 28
                            // N = 29
                            if (!new byte[] { 1, 3, 4, 28, 29 }.Contains(prelievoAgo.Risposta.DatiEliminazione.CodiceMotivo.Value))
                            {
                                errori = "Attenzione! Non è possibile acquisire una domanda di ricostituzione o trasformazione da provvisoria se il motivo dell'eliminazione è diverso dai codici 1, 3, 4, A, N";
                                return true;
                            }
                            ctrl = null;
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo102", out ctrl);

                            if (ctrl != null && ctrl.ValoreControllo == "SI")
                            {
                                if (isRiapertura && (prelievoAgo.Risposta.DatiEliminazione.CodiceMotivo.Value == 3 || prelievoAgo.Risposta.DatiEliminazione.CodiceMotivo.Value == 28) && (Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) ||
                                Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) || Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria)))
                                {
                                    errori = "prestazione eliminata e non trasformabile";
                                    return true;
                                }
                            }

                            if (!prelievoAgo.Risposta.DatiEliminazione.DataEvento.HasValue)
                            {
                                errori = "Attenzione! Inserire la data evento tramite la procedura “Variazione dati eliminazione” quindi riacquisire nuovamente la domanda";
                                return true;
                            }
                        }

                        if (prelievoAgo.Risposta.DatiEliminazione.DataFineCalcoloArretrati.HasValue && prelievoAgo.Risposta.DataDecorrenza.HasValue &&
                            !Utility.DataStrettamenteSuccessivaA(prelievoAgo.Risposta.DatiEliminazione.DataFineCalcoloArretrati.Value, prelievoAgo.Risposta.DataDecorrenza.Value)
                            && !(prelievoAgo.Risposta.DatiEliminazione.CodiceMotivo == 1 && prelievoAgo.Risposta.DatiEliminazione.DataEvento.HasValue
                            && prelievoAgo.Risposta.DatiEliminazione.DataEvento.Value.Month == prelievoAgo.Risposta.DataDecorrenza.Value.Month
                            && prelievoAgo.Risposta.DatiEliminazione.DataEvento.Value.Month == prelievoAgo.Risposta.DatiEliminazione.DataFineCalcoloArretrati.Value.Month))
                        {
                            errori = "Attenzione! Non è possibile acquisire una domanda di ricostituzione o trasformazione da provvisoria se la Data Fine Calcolo Arretrati (GP1AP2) è antecedente o uguale alla Decorrenza Pensione.";
                            return true;
                        }
                    }

                    if (!Utility.IsDomandaENPALS(datiPensione.Gestione))
                    {
                        if ((ConfigurationManager.AppSettings["BypassControlliSviluppo"] == null ||
                                ConfigurationManager.AppSettings["BypassControlliSviluppo"] != "SI")
                            && prelievoAgo.Risposta.DataDecorrenza.HasValue && (!Utility.DataSuccessivaA(prelievoAgo.Risposta.DataDecorrenza.Value, new DateTime(1996, 01, 01)))
                            && !(Utility.IsDomandaVOST(datiPensione.SiglaCategoria) || Utility.IsRenditaFacoltativa(datiPensione) || Utility.IsRenditaCasalinghe(datiPensione) || Utility.IsDomandaSPED(datiPensione) || Utility.IsDomandaBancari(datiPensione.SiglaCategoria)
                            || Utility.IsDomandaPescatori(datiPensione.SiglaCategoria) || Utility.IsDomandaMIN(datiPensione.SiglaCategoria) || Utility.IsDomandaFPLD(datiPensione.SiglaCategoria) || Utility.IsDomandaGestioneAutonomi(datiPensione.SiglaCategoria) ||
                            Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria) || Utility.IsDomandaPMO(datiPensione.SiglaCategoria) || Utility.IsDomandaPSO(datiPensione.SiglaCategoria)
                            || Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) || Utility.IsDomandaIOPGI(datiPensione.SiglaCategoria) || Utility.IsDomandaSOPGI(datiPensione.SiglaCategoria)))
                        {
                            errori = "La decorrenza pensione non può essere inferiore al 01/1996.";
                            return true;
                        }
                    }
                    //else 
                    //{
                    //    if (datiPensione.TipoCalcolo == (byte)Utility.TipoCalcolo.MistoL214 || datiPensione.TipoCalcolo == (byte)Utility.TipoCalcolo.RetributivoComma707)
                    //    {
                    //        if (prelievoAgo.Risposta.CalcoloRetributivoENPALS.GiorniQuotaA707 == 0)
                    //            prelievoAgo.Risposta.CalcoloRetributivoENPALS.GiorniQuotaA707 = null;
                    //        if (prelievoAgo.Risposta.CalcoloRetributivoENPALS.GiorniQuotaB707 == 0)
                    //            prelievoAgo.Risposta.CalcoloRetributivoENPALS.GiorniQuotaB707 = null;
                    //        if (prelievoAgo.Risposta.CalcoloRetributivoENPALS.ImportoQuotaA707 == 0)
                    //            prelievoAgo.Risposta.CalcoloRetributivoENPALS.ImportoQuotaA707 = null;
                    //        if (prelievoAgo.Risposta.CalcoloRetributivoENPALS.ImportoQuotaB707 == 0)
                    //            prelievoAgo.Risposta.CalcoloRetributivoENPALS.ImportoQuotaB707 = null;
                    //        if (prelievoAgo.Risposta.DatiENPALS.ImportoPensione707 == 0)
                    //            prelievoAgo.Risposta.DatiENPALS.ImportoPensione707 = null;
                    //    }
                    //    else
                    //    {
                    //        prelievoAgo.Risposta.CalcoloRetributivoENPALS.GiorniQuotaA707 = null;
                    //        prelievoAgo.Risposta.CalcoloRetributivoENPALS.GiorniQuotaB707 = null;
                    //        prelievoAgo.Risposta.CalcoloRetributivoENPALS.ImportoQuotaA707 = null;
                    //        prelievoAgo.Risposta.CalcoloRetributivoENPALS.ImportoQuotaB707 = null;
                    //        prelievoAgo.Risposta.DatiENPALS.ImportoPensione707 = null;
                    //    }
                    //}
                    if (Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, prelievoAgo.Risposta.DatiBeneficioVittimeTerrorismo) ||
                        Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, prelievoAgo.Risposta.DatiBeneficioVittimeTerrorismo))
                    {
                        if (prelievoAgo.Risposta.ListaDatiOneri == null || prelievoAgo.Risposta.ListaDatiOneri.Count() == 0 ||
                            prelievoAgo.Risposta.ListaDatiOneri.Any(x => !(x.IdCodeGruppo == 12 && (x.IdCodeSottoGruppo == 53 || x.IdCodeSottoGruppo == 54 || x.IdCodeSottoGruppo == 55 || x.IdCodeSottoGruppo == 10088 || x.IdCodeSottoGruppo == 10089 || x.IdCodeSottoGruppo == 10090)
                            && x.Decorrenza.HasValue && x.Scadenza.HasValue)))
                        {
                            GestioneControlliDinamici.ControlloDinamico eliminazioneScartoOneri0031_0105_0112 = null;
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("EliminazioneScartoOneri0031_0105_0112", out eliminazioneScartoOneri0031_0105_0112);
                            bool eseguiScartoOneri = true;
                            if (eliminazioneScartoOneri0031_0105_0112 != null && !String.IsNullOrEmpty(eliminazioneScartoOneri0031_0105_0112.ValoreControllo) &&
                                eliminazioneScartoOneri0031_0105_0112.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                            {
                                if (Utility.IsDomandaBeneficioTerrorismoLegge206_2004(datiPensione))
                                {
                                    if (prelievoAgo.Risposta.IsGP1AC01Valorizzato)
                                        eseguiScartoOneri = false;
                                }
                            }

                            if (eseguiScartoOneri)
                            {
                                errori = "Attenzione! Oneri non presenti per la domanda con benefici L. 206/2004";
                                return true;
                            }

                        }
                    }
                }

                if (Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, danteCausa) && Utility.IsDomandaENPALS(datiPensione.Gestione) && Utility.IsPensioneInvaliditaInabilitaENPALSOrCasellario(danteCausa) &&
                    ((tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura) || (danteCausa != null && danteCausa.IsFascicoloGenerato.HasValue && danteCausa.IsFascicoloGenerato.GetValueOrDefault())))
                {
                    if (danteCausa.DecorrenzaPensione.HasValue && Utility.DataSuccessivaA(danteCausa.DecorrenzaPensione.Value, new DateTime(1984, 8, 1)) &&
                    (string.IsNullOrEmpty(prelievoAgo.Risposta.DatiPensione.NaturaPensione) || (prelievoAgo.Risposta.DatiPensione.NaturaPensione.Substring(0, 1) != "3" && prelievoAgo.Risposta.DatiPensione.NaturaPensione.Substring(0, 1) != "4" && prelievoAgo.Risposta.DatiPensione.NaturaPensione.Substring(0, 1) != "5" && (danteCausa.SiglaCategoria == "IOSPORT" || prelievoAgo.Risposta.DatiPensione.NaturaPensione.Substring(1, 1) != "1"))))
                    {
                        errori = string.Format("Attenzione! La diretta del dante causa ha categoria {0}: è necessario verificare che il primo byte del codice natura sia 3 o 4 (inabilità) o 5 (pensione supplementare) " +
                            (danteCausa.SiglaCategoria != "IOSPORT" ? " oppure che il secondo byte sia uguale a 1 (invalidità specifica)" : string.Empty), danteCausa.SiglaCategoria.Trim().ToUpperInvariant());
                        return true;
                    }
                }

                if (datiPensione.Gruppo == "0031" && datiPensione.Prodotto == "0107" && datiPensione.Tipo == "0177" && !Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria))
                {
                    errori = string.Format("Attenzione! Categoria '{0}' non ammessa per questa tipologia di domanda", datiPensione.SiglaCategoria.Trim());
                    return true;
                }

                if (Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && Utility.IsRicostituzione(datiPensione.Gruppo) && prelievoAgo.Risposta.DatiPensioniDatiGenerici != null)
                {
                    if (Utility.IsRicostituzioneCumuloProgressiva(datiPensione))
                    {
                        if (!prelievoAgo.Risposta.DatiPensioniDatiGenerici.CumuloEsterno.HasValue || prelievoAgo.Risposta.DatiPensioniDatiGenerici.CumuloEsterno.Value != 'M')
                        {
                            errori = "Pensione in cumulo completa – prodotto WebDom incompatibile.";
                            return true;
                        }
                    }
                    else
                    {
                        if (!prelievoAgo.Risposta.DatiPensioniDatiGenerici.TipoCumulo.HasValue ||
                            (!prelievoAgo.Risposta.DatiPensioniDatiGenerici.TipoCumulo.GetValueOrDefault() && !new List<string> { "E", "M" }.Contains(prelievoAgo.Risposta.DatiPensioniDatiGenerici.CumuloEsterno.Value.ToString())))
                        {
                            errori = "Non è possibile acquisire questa domanda in Cumulo";
                            return true;
                        }
                    }
                }

                //Nel caso di trasformazioni/ricostituzioni di domande IOCUM o SOCUM IND sarà quindi necessario inserire un controllo all’acquisizione della domanda atto a verificare che non giunga mai GP1AJ10 = “M” (Cumulo Esterno Incompleto) per tali domande.
                if ((Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria) || (Utility.IsDomandaSOCUM(datiPensione.SiglaCategoria) && Utility.IsDomandaPensioneIndiretta(datiPensione))) && Utility.IsRicostituzioneOrRiapertura(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id)) && prelievoAgo.Risposta.DatiPensioniDatiGenerici != null)
                {
                    if (!prelievoAgo.Risposta.DatiPensioniDatiGenerici.TipoCumulo.HasValue ||
                           (!prelievoAgo.Risposta.DatiPensioniDatiGenerici.TipoCumulo.GetValueOrDefault() && prelievoAgo.Risposta.DatiPensioniDatiGenerici.CumuloEsterno.Value.ToString() == "M"))
                    {
                        errori = "Non è possibile acquisire questa domanda in Cumulo";
                        return true;
                    }

                }

                if (prelievoAgo.Risposta.ListaBititolarita != null && prelievoAgo.Risposta.ListaBititolarita.Count() > 0 &&
                prelievoAgo.Risposta.ListaBititolarita.Any(x => !x.Ente.HasValue || x.Ente.Value == 0))
                {
                    List<GestioneDecodifica.CatEnteAltraPensione> listaDecEnteAltrePensioni = null;
                    GestioneDecodifica.GetCatEnteAltrePensioni(out listaDecEnteAltrePensioni);
                    foreach (GestioneAltrePensioni.AltraPensione datiBititolarita in prelievoAgo.Risposta.ListaBititolarita.Where(x => !x.Ente.HasValue || x.Ente.Value == 0))
                    {
                        int categoriaNumerica = 0;
                        int.TryParse(datiBititolarita.Categoria, out categoriaNumerica);
                        if (listaDecEnteAltrePensioni.Exists(x => x.CodCategoria.Trim().ToUpperInvariant() == (categoriaNumerica != 0 ? categoriaNumerica.ToString() : datiBititolarita.Categoria.Trim().ToUpperInvariant()) && x.TipoApp == "AGO"))
                            datiBititolarita.Ente = Utility.StringToNullableByte(listaDecEnteAltrePensioni.First(x => x.CodCategoria.Trim().ToUpperInvariant() == (categoriaNumerica != 0 ? categoriaNumerica.ToString() : datiBititolarita.Categoria.Trim().ToUpperInvariant()) && x.TipoApp == "AGO").CodEnte.ToString());
                    }
                    if (!Utility.IsRicostituzione(datiPensione.Gruppo) && prelievoAgo.Risposta.ListaBititolarita.Any(x => !x.Ente.HasValue || x.Ente.Value == 0))
                    {
                        errori = "Attenzione: I dati della Bititolarità sono incompleti e non è possibile proseguire con l'acquisizione della domanda";
                        return true;
                    }
                }

                if ((ConfigurationManager.AppSettings["NuoviControlliAssegniMemo152"] != null && ConfigurationManager.AppSettings["NuoviControlliAssegniMemo152"] == "SI" && Utility.IsRicostituzione(datiPensione.Gruppo)) && (Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaVOCRED(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCOOP(datiPensione.SiglaCategoria) || Utility.IsDomandaCOOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaCRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria)))
                {
                    ServiceReferences.DatiPensioni.DatiTGP1Response datiGP1 = null;
                    short codiceCategoriaSuperstite = 0;
                    string codCategoriaSuperstite = datiPensione.GetCodCategoria();
                    short.TryParse(codCategoriaSuperstite, out codiceCategoriaSuperstite);

                    if (prelievoAgo != null && prelievoAgo.Risposta != null)
                    {
                        chiavePensione = codiceCategoriaSuperstite.ToString().PadLeft(3, '0') + prelievoAgo.Risposta.SedePensione.ToString().PadLeft(4, '0') + prelievoAgo.Risposta.CertificatoPensione.ToString().PadLeft(8, '0');
                    }
                    GestioneDatiPensioni.GetDatiTGP1ByChiavePensione(datiPensione.NDomus.ToString(), chiavePensione, out datiGP1, out errori);

                    if (datiGP1 != null && datiGP1.ElementoDatiTGP1 != null && datiGP1.ElementoDatiTGP1.GP1AM01 != null &&
                        datiGP1.ElementoDatiTGP1.GP1T11 != null && datiGP1.ElementoDatiTGP1.GP1T11[0].GP1CMPNTIP != null && datiGP1.ElementoDatiTGP1.GP1AS01 != null)
                    {
                        int annoEstrazioneRata;
                        int meseEstrazioneRata;
                        int giornoEstrazioneRata = 1;
                        DateTime? dataEstrazioneRata = new DateTime();

                        if (datiGP1.ElementoDatiTGP1.GP1AZ51Z.Valore.Codice != null && datiGP1.ElementoDatiTGP1.GP1ALZ5 != null &&
                            int.TryParse(datiGP1.ElementoDatiTGP1.GP1AZ51Z.Valore.Codice, out annoEstrazioneRata) && int.TryParse(datiGP1.ElementoDatiTGP1.GP1ALZ5.Valore.Codice, out meseEstrazioneRata))
                        {

                            dataEstrazioneRata = Utility.DataFromInt(annoEstrazioneRata, meseEstrazioneRata, giornoEstrazioneRata);
                            if (dataEstrazioneRata != null)
                            {
                                dataEstrazioneRata = dataEstrazioneRata.GetValueOrDefault().AddMonths(1);
                                datiPensione.DataEstrazioneRata = dataEstrazioneRata;
                            }
                        }

                        if (!string.IsNullOrEmpty(datiGP1.ElementoDatiTGP1.GP1AM01.Valore.Codice) && datiGP1.ElementoDatiTGP1.GP1AM01.Valore.Codice != "0" && !(datiGP1.ElementoDatiTGP1.GP1T11.Any(x => x.GP1CMPNTIP.Valore.Codice == "JB")))
                        {
                            errori = "La prestazione eliminata non è ancora consuntivata. La Ricostituzione dovrà essere effettuata dopo la consuntivazione";
                            return true;
                        }
                    }
                }
            }

            return true;
        }

        internal static bool ValorizzaPensioneToDB(ServiceReferences.WebDom.DatiDomanda datiDomanda, bool isRiapertura, out GestionePensione.DatiPensione pensione, out string errori)
        {
            errori = "";
            pensione = null;

            try
            {
                pensione = new GestionePensione.DatiPensione();
                pensione.NDomus = long.Parse(datiDomanda.Dati.Domanda[0].NumDomanda);
                pensione.NDomusPrincipale = !string.IsNullOrEmpty(datiDomanda.Dati.Domanda[0].NumDomandaPrincipale) ? long.Parse(datiDomanda.Dati.Domanda[0].NumDomanda) : (long?)null;
                pensione.CodiceSede = short.Parse(datiDomanda.Dati.Domanda[0].CodProvincia.Substring(1, 2) +
                    datiDomanda.Dati.Domanda[0].CodZona.Substring(1, 2));
                pensione.CentroOperativo = Utility.StringToNullableByte(datiDomanda.Dati.Domanda[0].CodCentroOperativo);
                pensione.DataPresentazioneDomanda = Utility.DataFromString(datiDomanda.Dati.Istanza[0].DataPresentazione, Utility.FormatoData.AAAAmmGG).Value;
                pensione.DataAcquisizione = Utility.DataFromString(datiDomanda.Dati.Domanda[0].DataInserimento, Utility.FormatoData.AAAAmmGG).Value;

                if (datiDomanda.Dati.Istanza != null && datiDomanda.Dati.Istanza.Rows.Count > 0)
                {
                    pensione.SiglaCategoria = datiDomanda.Dati.Istanza[0].SiglaCatLav;
                    pensione.Gruppo = datiDomanda.Dati.Istanza[0].CodGruppo;
                    pensione.Prodotto = datiDomanda.Dati.Istanza[0].CodProdotto;
                    pensione.Tipo = datiDomanda.Dati.Istanza[0].CodTipo;
                    pensione.Gestione = datiDomanda.Dati.Istanza[0].CodGestione;
                    pensione.Fondo = datiDomanda.Dati.Istanza[0].CodFondo;
                    pensione.Ente = datiDomanda.Dati.Istanza[0].CodEnte;
                    pensione.IndConvInt = datiDomanda.Dati.Istanza[0].IndConvInt == "1";
                    pensione.CodiceTipoRichiesta = GestioneWebDom.GetCodTipoRichiesta(datiDomanda.Dati);

                    GestioneControlliDinamici.ControlloDinamico ctrl = null;
                    GestioneControlliDinamici.ControlloDinamico sediDaControllare = null;
                    if (Utility.IsBonusBooking(pensione))
                    {
                        if (pensione.Tipo == "0167") //BONUS 14°
                        {
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneBonusBooking" + Utility.GetTipoAppartenenza(pensione.IndConvInt, pensione.Gestione), out ctrl);
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneBonusBookingSedi" + Utility.GetTipoAppartenenza(pensione.IndConvInt, pensione.Gestione), out sediDaControllare);
                        }
                        else //BONUS 154
                        {
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneBonus154" + Utility.GetTipoAppartenenza(pensione.IndConvInt, pensione.Gestione), out ctrl);
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneBonus154Sedi" + Utility.GetTipoAppartenenza(pensione.IndConvInt, pensione.Gestione), out sediDaControllare);
                        }
                    }

                    short sede = Utility.GetCodiceSedeLavorazione(pensione, isRiapertura);
                    if (ctrl != null && ctrl.ValoreControllo == "SI" &&
                        (sediDaControllare != null && (string.IsNullOrEmpty(sediDaControllare.ValoreControllo) ||
                         sediDaControllare.ValoreControllo.Split(';').ToList().Exists(x => x.PadLeft(4, '0') == sede.ToString().PadLeft(4, '0')))) &&
                        datiDomanda.Dati.Istanza[0].AnnoDecorsoRichiesta14 != null)
                        pensione.AnnoDecorrenzaBonus = datiDomanda.Dati.Istanza[0].AnnoDecorsoRichiesta14;

                }
                if (pensione.SiglaCategoria != null && pensione.SiglaCategoria.Trim().EndsWith("TELE"))
                    pensione.StatoPensione = (int)Utility.StatoPensione.NonLavorabile; //NON LAVORABILE
                else
                    pensione.StatoPensione = (int)Utility.StatoPensione.InAcquisizione; // IN ACQUISIZIONE

                if (datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Rows.Count > 0)
                {
                    pensione.CodiceProcedura = GetCodiceProcedura(datiDomanda);
                }

                if (datiDomanda.DatiInternet != null && datiDomanda.DatiInternet.domanda != null && !string.IsNullOrEmpty(datiDomanda.DatiInternet.domanda.LinkIntranet))
                    pensione.LinkIntranet = datiDomanda.DatiInternet.domanda.LinkIntranet;

                if (pensione.Tipo == "0190" && (pensione.CodiceTipoRichiesta == "KW" || pensione.CodiceTipoRichiesta == "KX" || pensione.CodiceTipoRichiesta == "KY" || pensione.CodiceTipoRichiesta == "KZ"))
                    GetNumeroFigliOpzioneDonnaFromInternet(datiDomanda.DatiInternet, isRiapertura, ref pensione);
                else
                    GetDatiLavoratriciMadriFromInternet(datiDomanda.DatiInternet, isRiapertura, ref pensione);

                //ENG - Implementazione Meta Processo - Per la linea FS/AGO bisogna valorizzare il Codice Sede Lavorazione anche per le PL
                GestioneControlliDinamici.ControlloDinamico ctrlMetaProcesso = null;
                Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(pensione.IndConvInt, pensione.Gestione);
                if (Utility.IsRicostituzione(pensione.Gruppo) || isRiapertura || tipoAppartenenza == Utility.TipoAppartenenza.FS || tipoAppartenenza == Utility.TipoAppartenenza.AGO)
                {
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("SbloccaMetaProcesso", out ctrlMetaProcesso);
                    if (ctrlMetaProcesso != null && !String.IsNullOrEmpty(ctrlMetaProcesso.ValoreControllo) && ctrlMetaProcesso.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                    {
                        //Il codice sede lavorazione è il codProvincia e codZona che provengono da webdom
                        pensione.CodiceSedeLavorazione = short.Parse(datiDomanda.Dati.Domanda[0].CodProvincia.Substring(1, 2) + datiDomanda.Dati.Domanda[0].CodZona.Substring(1, 2));
                    }
                }

            }
            catch (Exception Ex)
            {
                errori = Ex.Message;
                INPS.DNA.Logging.Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        internal static bool ValorizzaAnagraficaToDB(ServiceReferences.WebDom.DatiDomanda datiDomanda, out GestioneAnagrafica.DatiAnagrafici anagrafica, out string errori)
        {
            errori = "";
            anagrafica = null;
            try
            {
                ServiceReferences.WebDom.DataSetDomanda.SoggettoRow rigaTitolareFromWebDom = null;
                RecuperaTitolareFromWebDom(datiDomanda, out rigaTitolareFromWebDom);

                GestioneWebDom.NormalizzaAnagraficaWebDomToDB(rigaTitolareFromWebDom, out anagrafica);

                var cittadinanza = RecuperaCittadinanza(datiDomanda);
                if (cittadinanza != null && cittadinanza == "I") anagrafica.Cittadinanza = "Z000";

            }
            catch (Exception Ex)
            {
                errori = Ex.Message;
                INPS.DNA.Logging.Logger.LogException(Ex);
                return false;
            }
            return true;
        }

        private static void RecuperaTitolareFromWebDom(ServiceReferences.WebDom.DatiDomanda datiDomanda, out ServiceReferences.WebDom.DataSetDomanda.SoggettoRow rigaTitolare)
        {
            rigaTitolare = null;
            string idTitolare = "";
            foreach (ServiceReferences.WebDom.DataSetDomanda.RelazioneSoggettoRow riga in datiDomanda.Dati.RelazioneSoggetto.Rows)
            {
                if (riga["CodRelazioneSoggetto"] != null && riga["CodRelazioneSoggetto"].ToString() == "TI")
                {
                    idTitolare = riga["IdSoggetto"] != null ? riga["IdSoggetto"].ToString() : "";
                    break;
                }
            }
            if (idTitolare != "")
            {
                foreach (ServiceReferences.WebDom.DataSetDomanda.SoggettoRow riga in datiDomanda.Dati.Soggetto.Rows)
                {
                    if (riga["IdSoggetto"] != null && riga["IdSoggetto"].ToString() == idTitolare)
                    {
                        rigaTitolare = riga;
                        break;
                    }
                }
            }
        }

        private static string RecuperaCittadinanza(ServiceReferences.WebDom.DatiDomanda datiDomanda)
        {
            string idTitolare = "";
            string cittadinanza = null;
            if (datiDomanda.DatiInternet != null && datiDomanda.DatiInternet.relazioniSoggetto != null && datiDomanda.DatiInternet.soggetti != null)
            {
                foreach (var riga in datiDomanda.DatiInternet.relazioniSoggetto)
                {
                    if (riga.CodParentela != null && riga.CodParentela.ToString() == "TI")
                    {
                        idTitolare = riga.IdSoggetto != null ? riga.IdSoggetto.ToString() : "";
                        break;
                    }
                }
                foreach (var riga in datiDomanda.DatiInternet.soggetti)
                {
                    if (riga.IdSoggetto == idTitolare)
                    {
                        cittadinanza = riga.Cittadinanza;
                        break;
                    }
                }
            }
            return cittadinanza;
        }

        private static bool CheckLiquidazioniAbilitate(GestionePensione.DatiPensione datiDomanda, bool isRiapertura)
        {
            bool IsLiquidazioneAbilitata = false;

            if (datiDomanda != null)
            {
                Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiDomanda.IndConvInt, datiDomanda.Gestione);
                GestioneLiquidazioniAbilitate.LiquidazioneAbilitata liquidazioneAbilitata = new GestioneLiquidazioniAbilitate.LiquidazioneAbilitata();
                liquidazioneAbilitata.SiglaCategoria = !String.IsNullOrEmpty(datiDomanda.SiglaCategoria) ? datiDomanda.SiglaCategoria.Trim() : "";
                liquidazioneAbilitata.Sede = Utility.GetCodiceSedeLavorazione(datiDomanda, isRiapertura);

                if (tipoAppartenenza.HasValue)
                {
                    switch (tipoAppartenenza.Value)
                    {
                        case Utility.TipoAppartenenza.AGO:
                            liquidazioneAbilitata.Tipologia = "AGO";
                            break;
                        case Utility.TipoAppartenenza.CI:
                            liquidazioneAbilitata.Tipologia = "CI";
                            break;
                        case Utility.TipoAppartenenza.FS:
                            liquidazioneAbilitata.Tipologia = "FS";
                            break;
                    }
                }
                Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(!String.IsNullOrEmpty(datiDomanda.Gruppo) ? datiDomanda.Gruppo : "",
                    !String.IsNullOrEmpty(datiDomanda.Prodotto) ? datiDomanda.Prodotto : "");
                bool isAutomatica = Utility.IsDomandaAutomatica(datiDomanda) || Utility.IsDomandaInabilitaAmianto(datiDomanda) ||
                    (Utility.IsDomandaCumulo(datiDomanda.SiglaCategoria) && Utility.IsDomandaAPEPrecoci(datiDomanda));

                GestioneLiquidazioniAbilitate.CheckLiquidazioneAbilitata(liquidazioneAbilitata, tipoDomanda, isAutomatica, datiDomanda.IsPLUnicarpe, out IsLiquidazioneAbilitata);
            }
            return IsLiquidazioneAbilitata;
        }

        private static bool CheckTrasformazioniAbilitate(GestionePensione.DatiPensione datiDomanda, bool isRiaperturaDomanda)
        {
            bool IsTrasformazioneAbilitata = false;

            if (datiDomanda != null)
            {
                Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiDomanda.IndConvInt, datiDomanda.Gestione);
                GestioneTrasformazioniAbilitate.TrasformazioneAbilitata trasformazioneAbilitata = new GestioneTrasformazioniAbilitate.TrasformazioneAbilitata();
                trasformazioneAbilitata.SiglaCategoria = !String.IsNullOrEmpty(datiDomanda.SiglaCategoria) ? datiDomanda.SiglaCategoria.Trim() : "";
                trasformazioneAbilitata.Sede = Utility.GetCodiceSedeLavorazione(datiDomanda, isRiaperturaDomanda);

                if (tipoAppartenenza.HasValue)
                {
                    switch (tipoAppartenenza.Value)
                    {
                        case Utility.TipoAppartenenza.AGO:
                            trasformazioneAbilitata.Tipologia = "AGO";
                            break;
                        case Utility.TipoAppartenenza.CI:
                            trasformazioneAbilitata.Tipologia = "CI";
                            break;
                        case Utility.TipoAppartenenza.FS:
                            trasformazioneAbilitata.Tipologia = "FS";
                            break;
                    }
                }

                GestioneTrasformazioniAbilitate.CheckTrasformazioneAbilitata(trasformazioneAbilitata, isRiaperturaDomanda, Utility.IsDomandaUnicarpe(datiDomanda, true), out IsTrasformazioneAbilitata);
            }
            return IsTrasformazioneAbilitata;
        }

        private static bool CheckDomandaSuStessaPensione(ServiceReferences.WebDom.DatiDomanda datiDomanda, Utility.TipoAppartenenza? tipoAppartenenza, out bool? isPLUnicarpeFromDB, out bool? isPLPrepensionamentoEditoriaTipo0162FiltroEAA, out bool? isPLPrepensionamentoEditoriaTipo0162FiltroEBA, out bool? isPLESPAFiltroL26,
            out bool? isPLVESO33FiltroDAP, out string errori)
        {
            errori = string.Empty;
            isPLUnicarpeFromDB = null;
            isPLPrepensionamentoEditoriaTipo0162FiltroEAA = null;
            isPLPrepensionamentoEditoriaTipo0162FiltroEBA = null;
            isPLESPAFiltroL26 = null;
            isPLVESO33FiltroDAP = null;
            try
            {
                if (datiDomanda != null && datiDomanda.Dati != null &&
                    datiDomanda.Dati.PensioneRiferimento != null && datiDomanda.Dati.PensioneRiferimento.Count > 0)
                {
                    string siglaCategoria = datiDomanda.Dati.PensioneRiferimento[datiDomanda.Dati.PensioneRiferimento.Count - 1].SiglaCatLav.ToUpperInvariant().Trim();
                    short sede = short.Parse(datiDomanda.Dati.PensioneRiferimento[datiDomanda.Dati.PensioneRiferimento.Count - 1].CodProvinciaRif.Trim().PadLeft(3, '0').Substring(1) +
                        datiDomanda.Dati.PensioneRiferimento[datiDomanda.Dati.PensioneRiferimento.Count - 1].CodZonaRif.Trim().PadLeft(3, '0').Substring(1));
                    int certificato = int.Parse(datiDomanda.Dati.PensioneRiferimento[datiDomanda.Dati.PensioneRiferimento.Count - 1].NumCertificatoRif.Trim());
                    List<GestionePensione.DatiPensione> elencoDatiPensioni = null;
                    GestionePensione.GetPensioneByChiavePensione(siglaCategoria, sede, certificato, tipoAppartenenza, out elencoDatiPensioni);
                    if (elencoDatiPensioni != null && elencoDatiPensioni.Count > 0)
                    {
                        foreach (GestionePensione.DatiPensione datiPensione in elencoDatiPensioni)
                        {
                            if (datiPensione.NDomus != long.Parse(datiDomanda.Dati.Domanda[0].NumDomanda.Trim()))
                            {
                                Utility.StatoPensione statoPensione = Utility.GetStatoPensioneByCodice(datiPensione.StatoPensione.GetValueOrDefault()).GetValueOrDefault();
                                switch (statoPensione)
                                {
                                    case Utility.StatoPensione.Calcolata:
                                    case Utility.StatoPensione.CalcolataNoFelpe:
                                    case Utility.StatoPensione.CalcolataNoOneri:
                                    case Utility.StatoPensione.CalcolataNoWebDom:
                                    case Utility.StatoPensione.CalcolataNoSAI:
                                    case Utility.StatoPensione.CalcolataNoStazLavoro:
                                    case Utility.StatoPensione.CalcolataNoTotal:
                                    case Utility.StatoPensione.CalcolataNoTot:
                                    case Utility.StatoPensione.CalcolataNoSIN:
                                    case Utility.StatoPensione.CalcolataNoNoteDebito:
                                    case Utility.StatoPensione.CalcolataNo6Scatti:
                                        if (datiDomanda.Dati.Istanza != null && Utility.IsRicostituzione(datiDomanda.Dati.Istanza[0].CodGruppo) &&
                                            !Utility.IsRicostituzioneOrRiapertura(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id)))
                                        {
                                            isPLUnicarpeFromDB = Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica;
                                            //i datiPensione sono relativi alla PL che si sta ricostituendo
                                            if (Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione))
                                            {
                                                isPLPrepensionamentoEditoriaTipo0162FiltroEAA = true;
                                            }

                                            if (Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione))
                                            {
                                                isPLPrepensionamentoEditoriaTipo0162FiltroEBA = true;
                                            }

                                            if (Utility.IsDomandaESPA_L26(datiPensione))
                                            {
                                                isPLESPAFiltroL26 = true;
                                            }

                                            if (Utility.IsDomandaVESO33_DAP(datiPensione))
                                            {
                                                isPLVESO33FiltroDAP = true;
                                            }
                                        }
                                        continue;
                                    default:
                                        errori = "Domanda non lavorabile. E' presente la domanda " + datiPensione.NDomus.ToString() +
                                            " nello stato " + Utility.GetDescription(statoPensione) + " sulla stessa chiave pensione";
                                        return true;
                                }
                            }
                        }
                    }
                    else
                        return false;
                }
            }
            catch (Exception)
            {
                return false;
            }
            return false;
        }

        private static bool CheckDomandaSuStessaPensione(GestionePensione.DatiPensione datiDomanda, short sedeChiavePensioneDB, out string errori)
        {
            errori = string.Empty;
            try
            {
                if (datiDomanda != null)
                {
                    Utility.StatoPensione statoPensione = Utility.GetStatoPensioneByCodice(datiDomanda.StatoPensione.GetValueOrDefault()).GetValueOrDefault();
                    switch (statoPensione)
                    {
                        case Utility.StatoPensione.Calcolata:
                        case Utility.StatoPensione.CalcolataNoFelpe:
                        case Utility.StatoPensione.CalcolataNoOneri:
                        case Utility.StatoPensione.CalcolataNoWebDom:
                        case Utility.StatoPensione.CalcolataNoSAI:
                        case Utility.StatoPensione.CalcolataNoStazLavoro:
                        case Utility.StatoPensione.CalcolataNoTotal:
                        case Utility.StatoPensione.CalcolataNoTot:
                        case Utility.StatoPensione.CalcolataNoSIN:
                        case Utility.StatoPensione.CalcolataNoBooking:
                        case Utility.StatoPensione.CalcolataNoNoteDebito:
                        case Utility.StatoPensione.CalcolataNo6Scatti:
                            break;
                        default:
                            List<GestionePensione.DatiPensione> elencoDatiPensioni = null;
                            GestionePensione.GetPensioneByChiavePensione(datiDomanda.SiglaCategoria, sedeChiavePensioneDB, datiDomanda.NCertificato.GetValueOrDefault(), null, out elencoDatiPensioni);
                            if (elencoDatiPensioni != null && elencoDatiPensioni.Count > 0)
                            {
                                foreach (GestionePensione.DatiPensione datiPensione in elencoDatiPensioni)
                                {
                                    if (datiPensione.NDomus != datiDomanda.NDomus)
                                    {
                                        statoPensione = Utility.GetStatoPensioneByCodice(datiPensione.StatoPensione.GetValueOrDefault()).GetValueOrDefault();
                                        switch (statoPensione)
                                        {
                                            case Utility.StatoPensione.Calcolata:
                                            case Utility.StatoPensione.CalcolataNoFelpe:
                                            case Utility.StatoPensione.CalcolataNoOneri:
                                            case Utility.StatoPensione.CalcolataNoWebDom:
                                            case Utility.StatoPensione.CalcolataNoSAI:
                                            case Utility.StatoPensione.CalcolataNoStazLavoro:
                                            case Utility.StatoPensione.CalcolataNoTotal:
                                            case Utility.StatoPensione.CalcolataNoTot:
                                            case Utility.StatoPensione.CalcolataNoSIN:
                                            case Utility.StatoPensione.CalcolataNoBooking:
                                            case Utility.StatoPensione.CalcolataNoNoteDebito:
                                            case Utility.StatoPensione.CalcolataNo6Scatti:
                                                continue;
                                            default:
                                                errori = "Domanda non lavorabile. E' presente la domanda " + datiPensione.NDomus.ToString() +
                                                    " nello stato " + Utility.GetDescription(statoPensione) + " sulla stessa chiave pensione";
                                                return true;
                                        }
                                    }
                                }
                            }
                            else
                                return false;
                            break;
                    }
                }
            }
            catch (Exception)
            {
                return false;
            }
            return false;
        }

        internal static bool CheckSedi(ServiceReferences.WebDom.DatiDomanda datiDomanda, short sedeOperatore, short centroOperativoOperatore, out short sedeDomanda, out short centroOperativoDomanda)
        {
            bool IsSediOK = false;
            sedeDomanda = 0;
            centroOperativoDomanda = 0;
            try
            {
                sedeDomanda = short.Parse(datiDomanda.Dati.Domanda[0].CodProvincia.Substring(1, 2) +
                    datiDomanda.Dati.Domanda[0].CodZona.Substring(1, 2));

                centroOperativoDomanda = short.Parse(datiDomanda.Dati.Domanda[0].CodCentroOperativo);
            }
            catch (Exception)
            {
                sedeDomanda = 0;
            }

            if (sedeOperatore == sedeDomanda && centroOperativoOperatore == centroOperativoDomanda)
                IsSediOK = true;

            return IsSediOK;
        }

        private static bool RecuperaFamiliari(ServiceReferences.WebDom.DatiDomanda datiDomanda, GestionePensione.DatiPensione datiPensione, out List<GestioneFamiliari.FamiliareRecuperato> CFFamiliari, out bool isConiugePresente, out bool isUnitoCivilePresente, bool isRiapertura, bool isSpacchettamentoSOPGI)
        {
            CFFamiliari = null;
            isConiugePresente = false;
            isUnitoCivilePresente = false;

            GestioneControlliDinamici.ControlloDinamico controlloDinamicoSpacchettate024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneSpacchettate024", out controlloDinamicoSpacchettate024);

            try
            {
                DataRow[] righeFam;
                if (datiDomanda.Dati.Istanza != null && datiDomanda.Dati.Istanza.Count > 0 && !string.IsNullOrEmpty(datiDomanda.Dati.Istanza[0].SiglaCatLav) &&
                    datiDomanda.Dati.Istanza[0].SiglaCatLav.StartsWith("S"))
                {
                    righeFam = datiDomanda.Dati.RelazioneSoggetto.Select("CodRelazioneSoggetto = 'TI'");
                    if (righeFam != null && righeFam.Length > 0)
                    {
                        if (CFFamiliari == null)
                            CFFamiliari = new List<GestioneFamiliari.FamiliareRecuperato>();
                        foreach (DataRow r in righeFam)
                        {
                            DataRow[] s = datiDomanda.Dati.Soggetto.Select("IdSoggetto = '" + r["IdSoggetto"] + "'");
                            if (s != null && s.Length > 0)
                            {
                                if (!CFFamiliari.Exists(x => x.CodiceFiscale == s[0]["CodiceFiscale"].ToString()))
                                {
                                    char? siglaFamiliare = null;
                                    string tipoUnione = null;
                                    GestioneDecodifica.GetSiglaFamiliareByParentela(r["CodRelazioneParentela"].ToString(), out siglaFamiliare, out tipoUnione);
                                    CFFamiliari.Add(new GestioneFamiliari.FamiliareRecuperato(s[0]["CodiceFiscale"].ToString(), siglaFamiliare, 'T', tipoUnione));
                                }
                            }
                        }
                    }

                    //ENG - Spacchettate SOPGI
                    if (!Utility.IsDomandaSpacchettamentoENPALS(datiPensione) && !Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) && !isSpacchettamentoSOPGI &&
                        !(controlloDinamicoSpacchettate024 != null && controlloDinamicoSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, isRiapertura))
                        && !Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiapertura) && !Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiapertura) && !Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiapertura)
                        && !Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiapertura))
                    {
                        righeFam = datiDomanda.Dati.RelazioneSoggetto.Select("CodRelazioneSoggetto = 'CT'");
                        if (righeFam != null && righeFam.Length > 0)
                        {
                            if (CFFamiliari == null)
                                CFFamiliari = new List<GestioneFamiliari.FamiliareRecuperato>();
                            foreach (DataRow r in righeFam)
                            {
                                DataRow[] s = datiDomanda.Dati.Soggetto.Select("IdSoggetto = '" + r["IdSoggetto"] + "'");
                                if (s != null && s.Length > 0)
                                {
                                    if (!CFFamiliari.Exists(x => x.CodiceFiscale == s[0]["CodiceFiscale"].ToString()))
                                    {
                                        char? siglaFamiliare = null;
                                        string tipoUnione = null;
                                        GestioneDecodifica.GetSiglaFamiliareByParentela(r["CodRelazioneParentela"].ToString(), out siglaFamiliare, out tipoUnione);
                                        CFFamiliari.Add(new GestioneFamiliari.FamiliareRecuperato(s[0]["CodiceFiscale"].ToString(), siglaFamiliare, 'C', tipoUnione));
                                    }
                                }
                            }
                        }
                    }
                    else
                    {
                        righeFam = datiDomanda.Dati.RelazioneSoggetto.Select("CodRelazioneSoggetto = 'AF'");
                        if (righeFam != null && righeFam.Length > 0)
                        {
                            if (CFFamiliari == null)
                                CFFamiliari = new List<GestioneFamiliari.FamiliareRecuperato>();

                            foreach (DataRow r in righeFam)
                            {
                                DataRow[] s = datiDomanda.Dati.Soggetto.Select("IdSoggetto = '" + r["IdSoggetto"] + "'");
                                if (s != null && s.Length > 0)
                                {
                                    if (!CFFamiliari.Exists(x => x.CodiceFiscale == s[0]["CodiceFiscale"].ToString()))
                                    {
                                        char? siglaFamiliare = null;
                                        string tipoUnione = null;
                                        GestioneDecodifica.GetSiglaFamiliareByParentela(r["CodRelazioneParentela"].ToString(), out siglaFamiliare, out tipoUnione);
                                        //occorre recuperare da WebDom solo il coniuge o l'unito/a civilmente
                                        if (siglaFamiliare.GetValueOrDefault() == 'C')
                                        {
                                            if (tipoUnione == "M")
                                                isConiugePresente = true;
                                            else if (tipoUnione == "U")
                                                isUnitoCivilePresente = true;
                                            CFFamiliari.Add(new GestioneFamiliari.FamiliareRecuperato(s[0]["CodiceFiscale"].ToString(), siglaFamiliare, null, tipoUnione));
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                else
                {
                    righeFam = datiDomanda.Dati.RelazioneSoggetto.Select("CodRelazioneSoggetto = 'AF'");
                    if (righeFam != null && righeFam.Length > 0)
                    {
                        if (CFFamiliari == null)
                            CFFamiliari = new List<GestioneFamiliari.FamiliareRecuperato>();

                        foreach (DataRow r in righeFam)
                        {
                            DataRow[] s = datiDomanda.Dati.Soggetto.Select("IdSoggetto = '" + r["IdSoggetto"] + "'");
                            if (s != null && s.Length > 0)
                            {
                                if (!CFFamiliari.Exists(x => x.CodiceFiscale == s[0]["CodiceFiscale"].ToString()))
                                {
                                    char? siglaFamiliare = null;
                                    string tipoUnione = null;
                                    GestioneDecodifica.GetSiglaFamiliareByParentela(r["CodRelazioneParentela"].ToString(), out siglaFamiliare, out tipoUnione);
                                    //occorre recuperare da WebDom solo il coniuge o l'unito/a civilmente
                                    if (siglaFamiliare.GetValueOrDefault() == 'C')
                                    {
                                        if (tipoUnione == "M")
                                            isConiugePresente = true;
                                        else if (tipoUnione == "U")
                                            isUnitoCivilePresente = true;
                                        CFFamiliari.Add(new GestioneFamiliari.FamiliareRecuperato(s[0]["CodiceFiscale"].ToString(), siglaFamiliare, null, tipoUnione));
                                    }
                                }
                            }
                        }
                    }
                }

                return true;
            }
            catch (Exception ex)
            {
                INPS.DNA.Logging.Logger.WriteError("Errore nel recupero dei familiari da WebDom: " + ex.Message);
                return false;
            }
        }

        //Indicazioni Di Virgilio
        private static byte? GetRicorsoByFasi(ServiceReferences.WebDom.DataSetDomanda.FaseDataTable elencoFasi, Utility.TipoAppartenenza? tipoAppartenenza)
        {
            byte? codRicorso = null;

            if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO &&
                elencoFasi != null && elencoFasi.Count > 0)
            {
                //Viene precompilato nel modo seguente e non va variato
                //Leggere carattere per carattere il campo DO-ITER di 5 caratteri proveniente dalla domanda (I0-GE20) dal carattere di sinistra:
                //Se il carattere contiene un numero verificare il contenuto e comportarsi come di seguito indicato:
                //se = a 9 mettere 9 al Codice Ricorso (RACODRIC) e terminare la lettura del campo DO-ITER
                //se = a zero mettere 7 al Codice Ricorso (RACODRIC) e terminare la lettura del campo DO-ITER
                //se = a 8 mettere 5 al Codice Ricorso (RACODRIC) e terminare la lettura del campo DO-ITER
                //se = a 2, 3, 4, 5, 6, 7 mettere 2 al Codice Ricorso (RACODRIC) e continuare la lettura del campo DO-ITER dal carattere successivo
                //se non è un numero dei precedenti esaminare il Codice Ricorso (RACODRIC) e se è diverso da 2 mettere 1 allo stesso Codice Ricorso (RACODRIC) e 
                //continuare la lettura del campo DO-ITER dal carattere successivo
                //Se il carattere non contiene un numero verificare il contenuto e comportarsi come di seguito indicato:
                //se è = a "A" mettere 1 al Codice Ricorso (RACODRIC) e continuare la lettura del campo DO-ITER dal carattere successivo
                //se è = a "B" mettere 8 al Codice Ricorso (RACODRIC) e terminare la lettura del campo DO-ITER
                //se è diverso da "A" e"B" e ci si trova all'esame del primo carattere mettere 1 al Codice Ricorso (RACODRIC) e terminare la lettura del campo DO-ITER

                if (elencoFasi.Count <= 1)
                    codRicorso = 1;
                else
                {
                    ServiceReferences.WebDom.DataSetDomanda.FaseRow fasePerRicorso = elencoFasi[elencoFasi.Count - 2];
                    if (fasePerRicorso != null && !string.IsNullOrEmpty(fasePerRicorso.CodFase))
                    {
                        string codiceFase = fasePerRicorso.CodFase.TrimStart('0').ToUpperInvariant();
                        for (int i = 0; i < codiceFase.Length; i++)
                        {
                            bool stop = false;
                            switch (codiceFase.Substring(i, 1))
                            {
                                case "9":
                                    codRicorso = 9;
                                    stop = true;
                                    break;
                                case "0":
                                    codRicorso = 7;
                                    stop = true;
                                    break;
                                case "8":
                                    codRicorso = 5;
                                    stop = true;
                                    break;
                                case "2":
                                case "3":
                                case "4":
                                case "5":
                                case "6":
                                case "7":
                                    codRicorso = 2;
                                    break;
                                case "A":
                                    codRicorso = 1;
                                    break;
                                case "B":
                                    codRicorso = 8;
                                    stop = true;
                                    break;
                                case "1":
                                    if (codRicorso != 2)
                                        codRicorso = 1;
                                    break;
                                default:
                                    if (i == 0)
                                    {
                                        codRicorso = 1;
                                        stop = true;
                                    }
                                    break;
                            }
                            if (stop)
                                break;
                        }
                    }
                    else
                        codRicorso = 1;
                }
            }

            return codRicorso;
        }

        //Indicazioni Sorrentino            
        private static byte? GetRicorsoByFasi_New(ServiceReferences.WebDom.DataSetDomanda.FaseDataTable elencoFasi, Utility.TipoAppartenenza? tipoAppartenenza)
        {
            byte? codRicorso = null;

            if (tipoAppartenenza.HasValue &&
                (tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO || tipoAppartenenza.Value == Utility.TipoAppartenenza.CI) &&
                elencoFasi != null && elencoFasi.Count > 0)
            {
                //EVALUATE I0-DB2 (123:3)                          
                //  WHEN '   '                                     
                //  WHEN '000'                                     
                //  WHEN '002'                                     
                //       MOVE '1' TO ICTB3-FLG-FASE                PRIMA ISTANZA
                //  WHEN '003'                                     
                //       MOVE '7' TO ICTB3-FLG-FASE                RIESAME
                //  WHEN '033'                                     
                //  WHEN '034'                                     
                //  WHEN '035'                                     
                //  WHEN '038'                                     
                //       MOVE '2' TO ICTB3-FLG-FASE                RICORSO
                //  WHEN '036'                                     
                //       MOVE '5' TO ICTB3-FLG-FASE                CAUSA
                //  WHEN OTHER                                     
                //       DISPLAY 'FASE DOMANDA NON COMPATIBILE'    
                //END-EVALUATE                         
                switch (elencoFasi[elencoFasi.Count - 1].CodFase.Trim())
                {
                    case "":
                    case "0000":
                    case "0002":
                        codRicorso = 1;
                        break;
                    case "0003":
                        codRicorso = 7;
                        break;
                    case "0033":
                    case "0034":
                    case "0035":
                    case "0038":
                        codRicorso = 2;
                        break;
                    case "0036":
                        codRicorso = 5;
                        break;
                    default:
                        break;
                }
            }

            return codRicorso;
        }

