        }

        internal static void IsDomandaLavorabile(string codSituazione, string codFase, bool? indConvInt, string gestione, string siglaCategoria, string gruppo, string prodotto, string tipo,
            string codiceTipoRichiesta, bool isDomandaLavorabilePerEccezione, out string errore)
        {
            errore = string.Empty;

            if (!string.IsNullOrEmpty(codSituazione) && codSituazione != "0001")
            {
                errore = "Domanda non lavorabile: Stato non giacente.";
                return;
            }

            if (IsFaseNonLavorabile(codFase, gruppo, prodotto, indConvInt, gestione))
            {
                errore = "Domanda non lavorabile: Fase = " + GestioneDecodifica.GetDescFase(codFase);
                return;
            }

            if (!isDomandaLavorabilePerEccezione)
                IsDomandaLavorabileDB(indConvInt, gestione, siglaCategoria, gruppo, prodotto, tipo, codiceTipoRichiesta, out errore);
        }

        internal static void IsDomandaLavorabileDB(bool? indConvInt, string gestione, string siglaCategoria, string gruppo, string prodotto, string tipo, string codiceTipoRichiesta, out string errore)
        {
            errore = string.Empty;
            string filtro = string.Empty;

            //Ai fini della gestione delle “Tipologie non abilitate” il “codice tipo richiesta” valorizzato a null dovrà corrispondere funzionalmente al valore ALL del campo filtro
            if (codiceTipoRichiesta == null)
                filtro = "ALL";
            else
                filtro = Utility.GetFiltroByCodTipoRichiesta(codiceTipoRichiesta);

            if (filtro == null)
                filtro = string.Empty;

            if (!string.IsNullOrEmpty(gruppo) && !string.IsNullOrEmpty(prodotto) && !string.IsNullOrEmpty(tipo))
            {
                Utility.TipoAppartenenza? tipoApp = Utility.GetTipoAppartenenza(indConvInt, gestione);
                Utility.TipoFondo? fondo = Utility.GetTipoFondoByCategoria(tipoApp, siglaCategoria);

                if (!GestionePensione.IsDomandaLavorabile(tipoApp, fondo, gruppo, prodotto, tipo, filtro, siglaCategoria, Utility.IsDomandaINPDAP(gestione))
                    || !Utility.IsTipologiaAbilitataByCategoria(tipoApp, gruppo, prodotto, tipo, siglaCategoria, filtro))
                {
                    errore = "Domanda non lavorabile: Gruppo, Prodotto e Tipo non lavorabile.";
                }
            }
            else
                errore = "Domanda non lavorabile: Gruppo, Prodotto o Tipo mancanti.";
        }


        internal static bool IsPresaInCaricoWebDom(ServiceReferences.WebDom.DatiDomanda datiDomanda, out string errori)
        {
            errori = string.Empty;
            if (datiDomanda != null && datiDomanda.Dati != null &&
                datiDomanda.Dati.Domanda != null && datiDomanda.Dati.Domanda.Rows.Count > 0 &&
                datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Rows.Count > 0)
            {
                string dataCaricoTelematica = datiDomanda.Dati.Domanda[0]["DataCaricoTelematica"] != DBNull.Value && datiDomanda.Dati.Domanda[0].DataCaricoTelematica != null ? datiDomanda.Dati.Domanda[0].DataCaricoTelematica.Trim() : string.Empty;
                string indTrasferimento = datiDomanda.Dati.Domanda[0]["IndTrasferimento"] != DBNull.Value && datiDomanda.Dati.Domanda[0].IndTrasferimento != null ? datiDomanda.Dati.Domanda[0].IndTrasferimento.Trim() : string.Empty;
                if (IsDomandaTelematica(datiDomanda) && string.IsNullOrEmpty(dataCaricoTelematica))
                {
                    string matricolaUltimaVar = string.Empty;
                    bool isMatricolaUltimaVarNumerica = false;
                    bool isMatricolaUltimaVarContinuaNumerica = false;
                    bool isMatricolaOperatore = false;
                    try
                    {
                        matricolaUltimaVar = datiDomanda.Dati.Fase[datiDomanda.Dati.Fase.Rows.Count - 1].MatricolaUltimaVar;
                        int resInt = 0;
                        int.TryParse(matricolaUltimaVar, out resInt);
                        isMatricolaUltimaVarNumerica = resInt > 0;
                        if (matricolaUltimaVar.Length > 1)
                        {
                            int.TryParse(matricolaUltimaVar.Substring(1), out resInt);
                            isMatricolaUltimaVarContinuaNumerica = resInt > 0;
                        }
                        isMatricolaOperatore = (isMatricolaUltimaVarNumerica || (matricolaUltimaVar.StartsWith("E") && isMatricolaUltimaVarContinuaNumerica));
                    }
                    catch (Exception)
                    {
                        //Eccezione ignorata
                    }

                    if (string.IsNullOrEmpty(matricolaUltimaVar) || !isMatricolaOperatore)
                    {
                        errori = "La domanda telematica non è stata presa in carico su WebDom ed è quindi non lavorabile";
                        return false;
                    }
                }

                if (indTrasferimento == "1")
                {
                    errori = "La domanda è stata trasferita ma non ancora presa in carico su WebDom ed è quindi non lavorabile";
                    return false;
                }

                if (Utility.GetTipoDomanda(datiDomanda.Dati.Istanza[0].CodGruppo, datiDomanda.Dati.Istanza[0].CodProdotto) == Utility.TipoDomanda.Ricostituzione &&
                    new List<string> { "0120", "0320", "0420" }.Contains(datiDomanda.Dati.Istanza[0].CodProdotto))
                {
                    List<Processo> listaCodUnitaProcesso = null;
                    string messaggioVideoDiErrore = null;
                    if (!GestioneWebDom.GetListCodUnitaProcessoBySedeDestinazione(datiDomanda.Dati.Domanda[0].CodProvincia, datiDomanda.Dati.Domanda[0].CodZona, datiDomanda.Dati.Domanda[0].CodCentroOperativo, out listaCodUnitaProcesso, out messaggioVideoDiErrore))
                    {
                        errori = messaggioVideoDiErrore;
                        return false;
                    }

                    if (listaCodUnitaProcesso != null && listaCodUnitaProcesso.Count() > 0 && !listaCodUnitaProcesso.Any(x => x.Codice == datiDomanda.Dati.Domanda[0].CodUnitaProcesso))
                    {
                        errori = "Domanda da prendere in carico attraverso i tasti Modifica o Definizione su procedura Webdom";
                        return false;
                    }
                }
            }
            return true;
        }

        internal static bool CheckMatricolaAcquisizione(string matricolaCorrente, string matricolaAcquisizione, Utility.Ruolo ruolo, bool isAutomatizzata, bool isGestionePubblica, Utility.TipoAppartenenza? tipoAppartenenza)
        {
            if (matricolaCorrente == null)
                matricolaCorrente = string.Empty;
            if (matricolaAcquisizione == null)
                matricolaAcquisizione = string.Empty;

            bool bypass = isAutomatizzata || (ruolo == Utility.Ruolo.AMMINISTRATORE || ruolo == Utility.Ruolo.DIRETTORE_RDP);

            if (bypass || matricolaCorrente.Trim().ToUpperInvariant() == matricolaAcquisizione.Trim().ToUpperInvariant() || isGestionePubblica || (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO))
                return true;
            return false;
        }

        private static bool isPensioneRiferimentoNull(INPS.Pensioni.Liquidazione.ServiceReferences.WebDom.DataSetDomanda.PensioneRiferimentoRow pensioneRiferimento)
        {
            if (string.IsNullOrEmpty(pensioneRiferimento.CodCatPensioneRif) && string.IsNullOrEmpty(pensioneRiferimento.CodCatPensioneRifAttuale) &&
                string.IsNullOrEmpty(pensioneRiferimento.CodProvinciaRif) && string.IsNullOrEmpty(pensioneRiferimento.CodProvinciaRifAttuale) && string.IsNullOrEmpty(pensioneRiferimento.CodZonaRif) &&
                string.IsNullOrEmpty(pensioneRiferimento.CodZonaRifAttuale) && string.IsNullOrEmpty(pensioneRiferimento.NumCertificatoRif) && string.IsNullOrEmpty(pensioneRiferimento.NumCertificatoRifAttuale) &&
                string.IsNullOrEmpty(pensioneRiferimento.NumDomanda) && string.IsNullOrEmpty(pensioneRiferimento.SiglaCatLav))
                return true;

            return false;
        }

