        private static bool IsFaseNonLavorabile(string codFase, string gruppo, string prodotto, bool? indConvInt, string gestione)
        {
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(indConvInt, gestione);
            switch (codFase)
            {
                case "0001":
                case "0004":
                //case "0005": // Rimosso come indicato nella mail con oggetto "LIQPENS - Contro modifica controllo bititolarità + acquisizione fase autoimpugnativa" del 04/04/2018 di Alessio Benedetti
                case "0006":
                case "0007":
                case "0009":
                case "0061":
                    return true;
                case "0062":
                case "0063":
                case "0060":
                    if (gruppo == "0031" || ((gruppo == "0003" && prodotto != "0022") && tipoAppartenenza.GetValueOrDefault() != Utility.TipoAppartenenza.CI))
                        return true;
                    return false;
                default:
                    return false;
            }
        }

        private static void GetDataMorteTitolareFromWebdom(ServiceReferences.WebDom.DatiDomanda datiDomanda, out DateTime? dataMorteTitolare)
        {
            dataMorteTitolare = null;

            try
            {
                ServiceReferences.WebDom.DataSetDomanda.SoggettoRow rigaTitolare = null;
                string idTitolare = "";
                foreach (ServiceReferences.WebDom.DataSetDomanda.RelazioneSoggettoRow riga in datiDomanda.Dati.RelazioneSoggetto.Rows)
                {
                    if (riga["CodRelazioneSoggetto"] != null && riga["CodRelazioneSoggetto"].ToString() == "TI")
                    {
                        idTitolare = riga["IdSoggetto"] != null ? riga["IdSoggetto"].ToString() : "";
                        break;
                    }
                }
                if (idTitolare != "")
                {
                    foreach (ServiceReferences.WebDom.DataSetDomanda.SoggettoRow riga in datiDomanda.Dati.Soggetto.Rows)
                    {
                        if (riga["IdSoggetto"] != null && riga["IdSoggetto"].ToString() == idTitolare)
                        {
                            rigaTitolare = riga;
                            break;
                        }
                    }
                }

                dataMorteTitolare = rigaTitolare["DataMorte"] != DBNull.Value && rigaTitolare.DataMorte != null ? Utility.DataFromString(rigaTitolare.DataMorte, Utility.FormatoData.AAAAmmGG) : null;

            }
            catch (Exception)
            {
                //Eccezione ignorata
            }
        }

        private static string GetCodiceProcedura(ServiceReferences.WebDom.DatiDomanda datiDomanda)
        {
            string codiceProcedura = string.Empty;

            if (IsDomandaTelematica(datiDomanda))
                codiceProcedura = "NI";
            else
                codiceProcedura = "NW";

            return codiceProcedura;
        }

        private static bool IsDomandaTelematica(ServiceReferences.WebDom.DatiDomanda datiDomanda)
        {
            bool isTelematica = false;
            string codCanale = string.Empty;
            string matricolaWebDom = string.Empty;

            if (datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Rows.Count > 0)
                codCanale = !string.IsNullOrEmpty(datiDomanda.Dati.Fase[datiDomanda.Dati.Fase.Count - 1].CodCanale) ?
                    datiDomanda.Dati.Fase[datiDomanda.Dati.Fase.Count - 1].CodCanale.Trim() : string.Empty;

            if (datiDomanda.Dati.Istanza != null && datiDomanda.Dati.Istanza.Rows.Count > 0)
                matricolaWebDom = !string.IsNullOrEmpty(datiDomanda.Dati.Istanza[0].MatricolaCaricamento) ?
                    datiDomanda.Dati.Istanza[0].MatricolaCaricamento.Trim().ToUpperInvariant() : string.Empty;

            if (!string.IsNullOrEmpty(codCanale) && codCanale.Trim() == "005")
                isTelematica = true;
            else
            {
                switch (matricolaWebDom)
                {
                    case "DOMAPENS":
                    case "POFFLINE":
                    case "DOMAPEN0":
                        isTelematica = true;
                        break;
                    default:
                        break;
                }
            }
            return isTelematica;
        }

        private static string GetNameControlloDinamico(Utility.TipoDomanda tipoDomanda, Utility.TipoAppartenenza? tipoAppartenenza, bool isRiapertura)
        {
            string nomeControlloDinamico = "BloccoPrelievo";
            if (!isRiapertura)
            {
                nomeControlloDinamico = "BloccoPrelievo";
                //Per le ricostituzioni, superstiti e ripristini ci sono 3 controlli dinamici differenti per ogni tipoAppartenenza
                switch (tipoDomanda)
                {
                    case Utility.TipoDomanda.Superstiti:
                        nomeControlloDinamico += "Sup";
                        break;
                    case Utility.TipoDomanda.Ricostituzione:
                        nomeControlloDinamico += "Ric";
                        break;
                    case Utility.TipoDomanda.Ripristino:
                    case Utility.TipoDomanda.RipristinoSuperstiti:
                        nomeControlloDinamico += "Ripr";
                        break;
                }
            }
            else
            {
                //per le riaperture il nome del controllo dinamico è 'BloccoPrelievoRiap(TipoApp)'
                nomeControlloDinamico += "Riap";
            }
            nomeControlloDinamico += tipoAppartenenza.GetValueOrDefault().ToString();
            return nomeControlloDinamico;
        }

        private static void UnisciFamiliariPrelievoWebdom(List<GestioneFamiliari.FamiliareRecuperato> CFfamiliari, Utility.TipoAppartenenza tipoAppartenenza, ref object AreaPrelievo)
        {
            switch (tipoAppartenenza)
            {
                case Utility.TipoAppartenenza.FS:
                    ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFs = (ServiceReferences.LiquidazioneFs.AreaPrelievo)AreaPrelievo;
                    if (prelievoFs != null && prelievoFs.Risposta != null)
                    {
                        if (CFfamiliari == null)
                            return;

