        /// <summary>
        /// Recupera le informazioni della modalità di pagamento da WebDom
        /// Se i dati sono inesistenti oppure non sono validi allora torna un oggetto null
        /// </summary>
        /// <param name="datiDomanda"></param>
        /// <param name="datiPagamento"></param>
        private static void RecuperaModPagamento(ServiceReferences.WebDom.DatiDomanda datiDomanda, Utility.TipoAppartenenza? tipoAppartenenza, Utility.TipoFondo? tipoFondo,
            out GestionePagamento.DatiPagamento datiPagamento)
        {
            datiPagamento = null;
            string errori = string.Empty;

            if (datiDomanda != null && datiDomanda.Dati != null && datiDomanda.Dati.ModalitaPagamento != null && datiDomanda.Dati.ModalitaPagamento.Count > 0)
            {
                char? modPagamento = null;
                string codCatastaleStatoPagamentoEstero = "";
                string iban = "";
                string bic = "";
                int? abi = null;
                int? cab = null;
                int? frazionario = null;
                string numeroLibretto = "";
                char? tipoPagamento = null;

                INPS.Pensioni.Liquidazione.ServiceReferences.WebDom.DataSetDomanda.ModalitaPagamentoRow modalitaPagamento = datiDomanda.Dati.ModalitaPagamento[0];

                if (modalitaPagamento.Abi != null)
                    abi = Utility.StringToNullableInt(modalitaPagamento.Abi.Trim());
                if (modalitaPagamento.Bic != null)
                    bic = modalitaPagamento.Bic.Trim();
                if (modalitaPagamento.Cab != null)
                    cab = Utility.StringToNullableInt(modalitaPagamento.Cab.Trim());
                if (modalitaPagamento.Iban != null)
                    iban = modalitaPagamento.Iban.Trim().ToUpperInvariant();
                if (modalitaPagamento.TipoPagamento != null)
                    modPagamento = Utility.StringToNullableChar(modalitaPagamento.TipoPagamento.Trim().ToUpperInvariant());
                if (modalitaPagamento.StatoPagamentoEstero != null)
                    codCatastaleStatoPagamentoEstero = modalitaPagamento.StatoPagamentoEstero.Trim().ToUpperInvariant();
                if (modalitaPagamento.LibrettoUfficioPostale != null)
                    numeroLibretto = modalitaPagamento.LibrettoUfficioPostale.Trim();
                if (modalitaPagamento.ModPagamento != null)
                    tipoPagamento = Utility.StringToNullableChar(modalitaPagamento.ModPagamento.Trim());

                if (!abi.HasValue && (bic == null || bic.Trim() == "") && !cab.HasValue &&
                    (iban == null || iban.Trim() == "") && !modPagamento.HasValue &&
                    !tipoPagamento.HasValue && string.IsNullOrEmpty(codCatastaleStatoPagamentoEstero))
                    return;

                if (modPagamento.HasValue)
                {
                    switch (modPagamento)
                    {
                        case '1':
                            modPagamento = 'S';
                            break;
                        case '2':
                            modPagamento = 'C';
                            break;
                        case '3':
                            modPagamento = 'L';
                            break;
                        case '4':
                            modPagamento = 'K';
                            break;
                        case '5':
                            modPagamento = 'A';
                            break;
                        default:
                            break;
                    }
                }

                if (tipoPagamento.HasValue)
                {
                    switch (tipoPagamento)
                    {
                        case '1':
                            tipoPagamento = 'B';
                            break;
                        case '2':
                            tipoPagamento = 'P';
                            break;
                        case '3':
                            tipoPagamento = 'E';
                            break;
                        default:
                            break;
                    }
                }

                if (bic != "")

                    bic = bic.PadLeft(11, '0');
                if (iban != "" && tipoPagamento.GetValueOrDefault() != 'E' && iban.Length != 27)
                    return;

                if (numeroLibretto != "")
                    numeroLibretto = numeroLibretto.PadLeft(12, '0');

                if (tipoPagamento.GetValueOrDefault() == 'B')
                {
                    if (!string.IsNullOrEmpty(iban) && !abi.HasValue && !cab.HasValue)
                    {
                        abi = Utility.StringToNullableInt(iban.Substring(5, 5));
                        cab = Utility.StringToNullableInt(iban.Substring(10, 5));
                    }
                }

                if (tipoPagamento.GetValueOrDefault() == 'P' && abi == 07601)
                {
                    frazionario = cab;
                    cab = null;
                }

                GestioneUfficiPagatori.AreaUfficioPagatore ufficioPagatore = null;
                List<GestioneUfficiPagatori.AreaUfficioPagatore> listaUfficiPagatori = null;
                switch (tipoPagamento)
                {
                    case 'B':
                        if (!abi.HasValue || !cab.HasValue)
                            return;

                        if (!GestioneUfficiPagatori.GetUfficiPagatoriNew(abi.GetValueOrDefault(), cab.GetValueOrDefault(), out listaUfficiPagatori, out errori))
                            return;
                        ufficioPagatore = listaUfficiPagatori.FirstOrDefault();

                        break;
                    case 'P':
                        if (!abi.HasValue || (abi.GetValueOrDefault() == 07601 && !frazionario.HasValue) || (abi.GetValueOrDefault() == 36081 && !cab.HasValue))
                            return;
                        int? cab_frazionario = abi.GetValueOrDefault() == 07601 ? frazionario : cab;
                        if (!GestioneUfficiPagatori.GetUfficiPagatoriNew(abi.GetValueOrDefault(), cab_frazionario.GetValueOrDefault(), out listaUfficiPagatori, out errori))
                            return;
                        ufficioPagatore = listaUfficiPagatori.FirstOrDefault();

                        break;
                    case 'E':
                        if (String.IsNullOrEmpty(codCatastaleStatoPagamentoEstero) || codCatastaleStatoPagamentoEstero.Trim() == string.Empty)
                            return;

                        List<GestioneAreaPagamento.DatiStatoEstero> listaStatiEsteri = null;
                        if (!GestioneUfficiPagatori.GetStatiEsteri(out listaStatiEsteri, out errori))
                            return;

                        GestioneAreaPagamento.DatiStatoEstero statoEstero = listaStatiEsteri.FirstOrDefault(x => x.CodCatastale == codCatastaleStatoPagamentoEstero);

                        if (statoEstero != null)
                        {
                            abi = Utility.StringToNullableInt(statoEstero.ABI);
                            cab = Utility.StringToNullableInt(statoEstero.CAB);

                            if (!GestioneUfficiPagatori.GetUfficiPagatoriNew(abi.GetValueOrDefault(), cab.GetValueOrDefault(), out listaUfficiPagatori, out errori))
                                return;
                            ufficioPagatore = listaUfficiPagatori.FirstOrDefault();
                        }

                        break;
                }

                if (ufficioPagatore == null)
                    return;

                if (tipoPagamento == 'E')
                    datiPagamento = new GestionePagamento.DatiPagamento(iban, null, modPagamento, ufficioPagatore.CodiceMeccanizzazione, ufficioPagatore.Abi,
                        ufficioPagatore.Cab, frazionario, bic, numeroLibretto, null, null, null, null, null, null, tipoPagamento, ufficioPagatore.Citta, null,
                        ufficioPagatore.Nome, ufficioPagatore.Agenzia, ufficioPagatore.Cap, ufficioPagatore.Citta, ufficioPagatore.Indirizzo, codCatastaleStatoPagamentoEstero, true);
                else
                    datiPagamento = new GestionePagamento.DatiPagamento(iban, null, modPagamento, ufficioPagatore.CodiceMeccanizzazione, abi,
                        cab, frazionario, bic, numeroLibretto, null, null, null, null, null, null, tipoPagamento, null, null,
                        ufficioPagatore.Nome, ufficioPagatore.Agenzia, ufficioPagatore.Cap, ufficioPagatore.Citta, ufficioPagatore.Indirizzo, null, true);

                #region Gestione di circolarità legate al tipo Appartenenza

                if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.FS && tipoFondo.HasValue)
                {
                    switch (tipoFondo.Value)
                    {
                        case Utility.TipoFondo.PT:
                            if (tipoPagamento == 'P')
                                if (modPagamento == 'S')
                                    datiPagamento.ModalitaPagamento = 'X';
                                else
                                    if (modPagamento == 'X')
                                        datiPagamento.ModalitaPagamento = 'S';
                            break;
                    }
                }

                #endregion Gestione di circolarità legate al tipo Appartenenza

                #region Validazione

                if (!GestioneUfficiPagatori.ValidaUfficioPagatore(datiPagamento, out errori))
                {
                    datiPagamento = null;
                    return;
                }

                #endregion Validazione
            }
        }

        internal static bool RecuperaAventiDirittoFromWebDom(ServiceReferences.WebDom.DatiDomanda datiDomanda, out List<GestioneAventiDiritto.AventeDirittoRecuperato> listaAventiDiritto, out string errore)
        {
            errore = string.Empty;
            listaAventiDiritto = null;
            if (datiDomanda != null && datiDomanda.Dati != null)
            {
                if (datiDomanda.Dati.AventiDiritto != null && datiDomanda.Dati.AventiDiritto.Count > 0)
                {
                    listaAventiDiritto = new List<GestioneAventiDiritto.AventeDirittoRecuperato>();

                    foreach (var aventeDirittoWebDom in datiDomanda.Dati.AventiDiritto)
                    {
                        if (string.IsNullOrEmpty(aventeDirittoWebDom.IdSoggetto))
                            continue;

                        GestioneAventiDiritto.AventeDirittoRecuperato aventeDiritto = new GestioneAventiDiritto.AventeDirittoRecuperato();
                        aventeDiritto.NucleoTitolare = aventeDirittoWebDom.IsNucleo == "S";

                        if (datiDomanda.Dati.RelazioneSoggetto != null && datiDomanda.Dati.RelazioneSoggetto.Count > 0)
                        {
                            if (!datiDomanda.Dati.RelazioneSoggetto.Any(x => x.IdSoggetto == aventeDirittoWebDom.IdSoggetto))
                            {
                                errore = "Controllare gli identificativi anagrafici degli aventi diritto in Webdom. Non è possibile acquisire la domanda";
                                return false;
                            }
                            var relazioneSoggetto = datiDomanda.Dati.RelazioneSoggetto.First(x => x.IdSoggetto == aventeDirittoWebDom.IdSoggetto);
                            aventeDiritto.IsTitolare = relazioneSoggetto.CodRelazioneSoggetto == "TI";
                            char? siglaParentela = null;
                            string tipoUnione = null;
                            GestioneDecodifica.GetSiglaFamiliareByParentela(relazioneSoggetto.CodRelazioneParentela, out siglaParentela, out tipoUnione);
                            aventeDiritto.DecParentelaDA = siglaParentela;
                            aventeDiritto.TipoUnione = tipoUnione;
                        }

                        if (aventeDirittoWebDom["PercGiudice"] != DBNull.Value && !string.IsNullOrEmpty(aventeDirittoWebDom.PercGiudice))
                        {
                            decimal percGiudice = 0M;
                            decimal.TryParse(aventeDirittoWebDom.PercGiudice, out percGiudice);
                            if (aventeDiritto.DecParentelaDA == 'R')
                                aventeDiritto.PercGiudice = percGiudice;
                        }

                        if (datiDomanda.Dati.Soggetto != null && datiDomanda.Dati.Soggetto.Count > 0)
                        {
                            if (!datiDomanda.Dati.Soggetto.Any(x => x.IdSoggetto == aventeDirittoWebDom.IdSoggetto))
                            {
                                errore = "Controllare gli identificativi anagrafici degli aventi diritto in Webdo. Non è possibile acquisire la domanda";
                                return false;
                            }
                            var soggetto = datiDomanda.Dati.Soggetto.First(x => x.IdSoggetto == aventeDirittoWebDom.IdSoggetto);
                            aventeDiritto.CodiceFiscale = soggetto.CodiceFiscale;
                        }

                        aventeDiritto.PresenzaWebDom = true;
                        listaAventiDiritto.Add(aventeDiritto);
                    }
                }
            }
            return true;
        }
        private static bool IsFormatoScadenzaAssegnoGGMMAAAA(ref GestionePensione.DatiPensione datiPensione,
            short codiceAziendaTraduzioneSuGP, byte? progressivoBancaFideiussoria)
        {
            List<GestioneAziendeScadenzaAssegnoGGmmAAAA.DecAziendeScadenzaAssegnoGGmmAAAA> elencoDecAziendeScadenzaAssegnoGGmmAAAA = null;
            GestioneAziendeScadenzaAssegnoGGmmAAAA.GetDecodificaAziendeScadenzaAssegnoGGmmAAAA(out elencoDecAziendeScadenzaAssegnoGGmmAAAA);
            if (((Utility.IsDomandaVESO92_L92(datiPensione) || Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria)) &&
                elencoDecAziendeScadenzaAssegnoGGmmAAAA.Exists(x => x.TraduzioneSuGP.Trim() == codiceAziendaTraduzioneSuGP.ToString() &&
                    (!x.ProgressivoRichiesto.HasValue || x.ProgressivoRichiesto == progressivoBancaFideiussoria)))
                //oppure non è una RIC di  VESO29/VOESO con CodiceTipoRichiesta != "74"
                    || (!Utility.IsRicostituzione(datiPensione.Gruppo) && ((Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) && datiPensione.CodiceTipoRichiesta != "74") ||
                        (Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) && datiPensione.CodiceTipoRichiesta != "74" && datiPensione.CodiceTipoRichiesta != "71" && datiPensione.CodiceTipoRichiesta != "70"))))
                return true;

            return false;
        }

        internal static void RecuperaDatiAggiuntiviJSONFromWebDom(ServiceReferences.WebDom.DatiDomanda datiDomanda,
            ref GestionePensione.DatiPensione datiPensione, ref GestioneIstruttoria.DatiIstruttoria datiIstruttoria,
            ref GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiPensioniDatiGenerici,
            ref GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici datiMaggiorazioniBenefici)
        {
            GestioneWebDom.WebDomJson.Rootobject datiAggiuntivi = null;
            try
            {
                bool isAreaJsonNotEmpty = false;
                //sostituito da verifica valorizzazione area JSON (datiPensione.IsDatiAggiuntiviFromJSON)
                //GestioneControlliDinamici.ControlloDinamico ctrl = null;
                //GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneDatiWebDomJSON", out ctrl);
                //if (ctrl == null || ctrl.ValoreControllo != "SI")
                //    return;

                if (datiDomanda != null && !string.IsNullOrEmpty(datiDomanda.DatiAggiuntiviJSON))
                {
                    datiAggiuntivi = Newtonsoft.Json.JsonConvert.DeserializeObject<GestioneWebDom.WebDomJson.Rootobject>(datiDomanda.DatiAggiuntiviJSON);
                }

                if (datiAggiuntivi != null && datiAggiuntivi.DatiAggiuntiviRichiestaEsodo != null)
                {
                    GestioneWebDom.WebDomJson.Periodoassicurativo periodo = datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.PeriodoAssicurativo;
                    GestioneWebDom.WebDomJson.Contribuzionecorrelata contribuzione = datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.ContribuzioneCorrelata;
                    GestioneWebDom.WebDomJson.Assegnostraordinario assegno = datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.AssegnoStraordinario;
                    GestioneWebDom.WebDomJson.Calcolotfr calcolotfr = datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.CalcoloTFR;
                    GestioneWebDom.WebDomJson.Pianoesodo pianoEsodo = datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.PianoEsodo;

                    if (Utility.IsDomandaUnicarpe(datiPensione, true) != Utility.TipoUnicarpe.Automatica && periodo != null)
                    {
                        if (periodo.DataInizio != null && periodo.DataInizio.value != null)
                        {
                            isAreaJsonNotEmpty = true;
                            datiPensione.InizioAssicurazione = Utility.DataFromString(periodo.DataInizio.value.Replace("-", ""), Utility.FormatoData.GGmmAAAA);
                        }
                        if (periodo.DataFine != null && periodo.DataFine.value != null)
                        {
                            isAreaJsonNotEmpty = true;
                            datiPensione.FineAssicurazione = Utility.DataFromString(periodo.DataFine.value.Replace("-", ""), Utility.FormatoData.GGmmAAAA);
                        }

                        if (datiPensione.FineAssicurazione != null)
                        {
                            var dataMeseAggiunto = datiPensione.FineAssicurazione.Value.AddMonths(1);
                            var dataFinale = new DateTime(dataMeseAggiunto.Year, dataMeseAggiunto.Month, 1);
                            datiPensione.DecorrenzaOriginaria = dataFinale;
                        }

                    }
                    if (contribuzione != null)
                    {
                        if (contribuzione.DataFineVersamenti != null && contribuzione.DataFineVersamenti.value != null)
                        {
                            isAreaJsonNotEmpty = true;
                            datiPensione.DataPerfezionamentoRequisiti = Utility.DataFromString(contribuzione.DataFineVersamenti.value.Replace("-", ""), Utility.FormatoData.GGmmAAAA);
                        }
                    }

                    short codiceAziendaTraduzioneSuGP = 0;
                    if (datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.CodiceEnte != null &&
                        datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.CodiceEnte.value != null &&
                        !Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) && !Utility.IsDomandaESPA(datiPensione.SiglaCategoria))
                    {
                        isAreaJsonNotEmpty = true;
                        List<GestioneDecodificaAzienda.DecAzienda> listaDecAzienda = null;
                        GestioneDecodificaAzienda.GetElencoAziendaBySiglaCategoria(datiPensione.SiglaCategoria, datiPensione.Tipo, out listaDecAzienda);
                        if (listaDecAzienda != null && listaDecAzienda.Count > 0)
                        {
                            string codEnte = string.Empty;
                            if (Utility.IsDomandaCRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED(datiPensione.SiglaCategoria) || Utility.IsDomandaCOOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCOOP(datiPensione.SiglaCategoria))
                                codEnte = Utility.StringToNullableInt(datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.CodiceEnte.value) != null ? Utility.StringToNullableInt(datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.CodiceEnte.value).ToString() : string.Empty;
                            else
                                codEnte = datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.CodiceEnte.value;

                            var azienda = listaDecAzienda.FirstOrDefault(x => x.TraduzioneSuGP.Trim() == codEnte.Trim());
                            if (azienda != null)
                            {
                                datiPensione.CodiceBancaEsodati = azienda.Id;
                                codiceAziendaTraduzioneSuGP = short.Parse(azienda.TraduzioneSuGP);
                            }
                        }
                    }

                    if (calcolotfr != null)
                    {
                        if (datiPensioniDatiGenerici == null)
                            datiPensioniDatiGenerici = new GestioneDatiGenericiAgoCi.PensioniDatiGenerici();
                        if (calcolotfr.DataInizio != null)
                        {
                            isAreaJsonNotEmpty = true;
                            datiPensioniDatiGenerici.InizioUltimoLavoro = Utility.DataFromString(calcolotfr.DataInizio.value.Replace("-", ""), Utility.FormatoData.GGmmAAAA);
                        }
                        if (calcolotfr.DataFine != null)
                        {
                            isAreaJsonNotEmpty = true;
                            datiPensioniDatiGenerici.FineUltimoLavoro = Utility.DataFromString(calcolotfr.DataFine.value.Replace("-", ""), Utility.FormatoData.GGmmAAAA);
                        }

                        if (calcolotfr.DataFine != null)
                        {
                            isAreaJsonNotEmpty = true;
                            decimal resDec = 0;
                            decimal.TryParse(calcolotfr.Aliquota.value.Replace(".", ","), out resDec);
                            if (resDec > 0)
                                datiPensione.AliquotaTFREsodati = resDec;
                        }
                    }

                    if (datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.RetribuzioneMensile != null &&
                        datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.RetribuzioneMensile.value != null)
                    {
                        isAreaJsonNotEmpty = true;
                        if (datiPensioniDatiGenerici == null)
                            datiPensioniDatiGenerici = new GestioneDatiGenericiAgoCi.PensioniDatiGenerici();
                        decimal resDec = 0;
                        decimal.TryParse(datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.RetribuzioneMensile.value.Replace(".", ","), out resDec);
                        if (resDec > 0)
                            datiPensioniDatiGenerici.ImportoUltimaRetribuzione = resDec;
                    }
                    if (datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.SettimaneIncremento != null &&
                        datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.SettimaneIncremento.value != null)
                    {
                        isAreaJsonNotEmpty = true;
                        if (datiMaggiorazioniBenefici == null)
                            datiMaggiorazioniBenefici = new GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici();
                        decimal resDec = 0;
                        if (decimal.TryParse(datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.SettimaneIncremento.value.Replace(".", ","), out resDec) && resDec > 0)
                            datiMaggiorazioniBenefici.NSettimaneBeneficio = (int)resDec;
                    }

                    if (datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.RiduzioneAssegno != null &&
                        datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.RiduzioneAssegno.value != null)
                    {
                        isAreaJsonNotEmpty = true;
                        if (datiIstruttoria == null)
                            datiIstruttoria = new GestioneIstruttoria.DatiIstruttoria();
                        decimal resDec = 0;
                        if (decimal.TryParse(datiAggiuntivi.DatiAggiuntiviRichiestaEsodo.RiduzioneAssegno.value.Replace(".", ","), out resDec) && resDec > 0)
                            datiIstruttoria.RiduzioneAssegno = (int)resDec;
                    }

                    if (pianoEsodo != null)
                    {
                        if (pianoEsodo.AnnoPiano != null && pianoEsodo.AnnoPiano.value != null)
                        {
                            isAreaJsonNotEmpty = true;
                            short resShort = 0;
                            short.TryParse(pianoEsodo.AnnoPiano.value, out resShort);
                            if (resShort > 0)
                            {
                                if (datiPensioniDatiGenerici == null)
                                    datiPensioniDatiGenerici = new GestioneDatiGenericiAgoCi.PensioniDatiGenerici();
                                datiPensioniDatiGenerici.AnnoBancaFideiussoria = resShort;
                            }
                        }
                        if (pianoEsodo.NumeroProgressivo != null && pianoEsodo.NumeroProgressivo.value != null)
                        {
                            isAreaJsonNotEmpty = true;
                            byte resByte = 0;
                            byte.TryParse(pianoEsodo.NumeroProgressivo.value, out resByte);
                            if (resByte > 0 || (Utility.IsDomandaESPA(datiPensione.SiglaCategoria) && resByte >= 0))
                            {
                                if (datiPensioniDatiGenerici == null)
                                    datiPensioniDatiGenerici = new GestioneDatiGenericiAgoCi.PensioniDatiGenerici();
                                datiPensioniDatiGenerici.ProgressivoBancaFideiussoria = resByte;
                            }
                        }
                    }

                    var isFormatoScadenzaAssegnoGGMMAAAA = IsFormatoScadenzaAssegnoGGMMAAAA(ref datiPensione, codiceAziendaTraduzioneSuGP, datiPensioniDatiGenerici.ProgressivoBancaFideiussoria);
                    if (assegno != null)
                    {
                        if (assegno.DataFineErogazione != null && assegno.DataFineErogazione.value != null && !string.IsNullOrEmpty(assegno.DataFineErogazione.value))
                        {
                            isAreaJsonNotEmpty = true;
                            if (datiPensioniDatiGenerici == null)
                                datiPensioniDatiGenerici = new GestioneDatiGenericiAgoCi.PensioniDatiGenerici();

                            datiPensioniDatiGenerici.ScadenzaAssegno = Utility.DataFromString(assegno.DataFineErogazione.value.Replace("-", ""), Utility.FormatoData.GGmmAAAA);
                            //Il campo "DatiAggiuntiviRichiestaEsodo > AssegnoStraordinario	> DataFineErogazione" quando IVS ha la "Data Scadenza Assegno" nel formato MM/AAAA dovrà essere post elaborato. In questi casi sarà pari al mese successivo a quello ricevuto nel campo "DataFineErogazione".
                            if (!isFormatoScadenzaAssegnoGGMMAAAA && datiPensioniDatiGenerici.ScadenzaAssegno.HasValue)
                            {
                                var dataMeseAggiunto = datiPensioniDatiGenerici.ScadenzaAssegno.Value.AddMonths(1);
                                var dataFinale = new DateTime(dataMeseAggiunto.Year, dataMeseAggiunto.Month, 1);
                                datiPensioniDatiGenerici.ScadenzaAssegno = dataFinale;
                            }
                        }
                    }

                    if (isAreaJsonNotEmpty)
                    {
                        datiPensione.IsDatiAggiuntiviFromJSON = true;
                    }
                }
            }
            catch (Exception Ex)
            {
                INPS.DNA.Logging.Logger.LogException(Ex);
            }
            return;
        }

        private static void RecuperaModPagamentoFromTotalIVS(INPS.Pensioni.Liquidazione.ServiceReferences.TotalIvs.pagamentoCumulo pagamentoCumulo, out GestionePagamento.DatiPagamento datiPagamento)
        {
            datiPagamento = null;
            string errori = string.Empty;

            char? modPagamento = null;
            string iban = "";
            string bic = "";
            int? abi = null;
            int? cab = null;
            int? frazionario = null;
            string numeroLibretto = "";
            char? tipoPagamento = null;
            bool isEstero = false;
            string statoPagamentoEstero = string.Empty;

            if (!string.IsNullOrEmpty(pagamentoCumulo.Abi))
                abi = Utility.StringToNullableInt(pagamentoCumulo.Abi.Trim());
            if (pagamentoCumulo.Bic != null)
                bic = pagamentoCumulo.Bic.Trim();
            if (pagamentoCumulo.Cab != null)
                cab = Utility.StringToNullableInt(pagamentoCumulo.Cab.Trim());
            if (pagamentoCumulo.Iban != null)
                iban = pagamentoCumulo.Iban.Trim().ToUpperInvariant();
            if (pagamentoCumulo.ModPagamento != null)
                modPagamento = Utility.StringToNullableChar(pagamentoCumulo.ModPagamento.Trim().ToUpperInvariant());
            if (pagamentoCumulo.NumLibr_CcBanca != null)
                numeroLibretto = pagamentoCumulo.NumLibr_CcBanca.Trim();
            isEstero = pagamentoCumulo.Estero;

            if (!abi.HasValue && (bic == null || bic.Trim() == "") && !cab.HasValue &&
                (iban == null || iban.Trim() == "") && !modPagamento.HasValue &&
                !tipoPagamento.HasValue)
                return;

            if (modPagamento.HasValue)
            {
                switch (modPagamento)
                {
                    case '1':
                        modPagamento = 'A';
                        break;
                    case '2':
                        modPagamento = 'S';
                        break;
                    case '3':
                        modPagamento = 'C';
                        break;
                    case '4':
                        modPagamento = 'L';
                        break;
                    case '5':
                        modPagamento = 'K';
                        break;
                    default:
                        break;
                }
            }

            if (abi == 07601 || (abi == 36081 && cab == 05138))
                tipoPagamento = 'P';
            else if (string.IsNullOrEmpty(bic))
                tipoPagamento = 'B';
            else if (isEstero)
                tipoPagamento = 'E';

            if (bic != string.Empty)
                bic = bic.PadLeft(11, '0');

            if (iban != string.Empty && tipoPagamento.GetValueOrDefault() != 'E' && iban.Length != 27)
                return;

            if (numeroLibretto != string.Empty)
                numeroLibretto = numeroLibretto.PadLeft(12, '0');

            if (tipoPagamento.GetValueOrDefault() == 'P' && abi.GetValueOrDefault() == 07601)
            {
                frazionario = cab;
                cab = null;
            }

            GestioneUfficiPagatori.AreaUfficioPagatore ufficioPagatore = null;
            List<GestioneUfficiPagatori.AreaUfficioPagatore> listaUfficiPagatori = null;
            switch (tipoPagamento)
            {
                case 'B':
                case 'E':
                    if (!abi.HasValue || !cab.HasValue)
                        return;

                    if (!GestioneUfficiPagatori.GetUfficiPagatoriNew(abi.GetValueOrDefault(), cab.GetValueOrDefault(), out listaUfficiPagatori, out errori))
                        return;
                    ufficioPagatore = listaUfficiPagatori.FirstOrDefault();

                    break;
                case 'P':
                    if (!abi.HasValue || (abi.GetValueOrDefault() == 07601 && !frazionario.HasValue) || (abi.GetValueOrDefault() == 36081 && !cab.HasValue))
                        return;
                    int? cab_frazionario = abi.GetValueOrDefault() == 07601 ? frazionario : cab;
                    if (!GestioneUfficiPagatori.GetUfficiPagatoriNew(abi.GetValueOrDefault(), cab_frazionario.GetValueOrDefault(), out listaUfficiPagatori, out errori))
                        return;
                    ufficioPagatore = listaUfficiPagatori.FirstOrDefault();

                    break;
            }

            if (ufficioPagatore == null)
                return;

            if (tipoPagamento == 'E')
                statoPagamentoEstero = ufficioPagatore.Citta;

            datiPagamento = new GestionePagamento.DatiPagamento(iban, null, modPagamento, ufficioPagatore.CodiceMeccanizzazione, abi,
                cab, frazionario, bic, numeroLibretto, null, null, null, null, null, null, tipoPagamento, statoPagamentoEstero, null,
                ufficioPagatore.Nome, ufficioPagatore.Agenzia, ufficioPagatore.Cap, ufficioPagatore.Citta, ufficioPagatore.Indirizzo, null, false);

            #region Validazione

            if (!GestioneUfficiPagatori.ValidaUfficioPagatore(datiPagamento, out errori))
            {
                datiPagamento = null;
                return;
            }

            #endregion Validazione
        }

