        private static void RecuperaDatiFromFELPE_AGO(ServiceReferences.AggPec.csAggiornamentoPECO_AGO dati, Utility.TipoAppartenenza? tipoAppartenenza, int categoriaWebDom,
            ref GestionePensione.DatiPensione datiPensione, object prelievo, ref GestioneIstruttoria.DatiIstruttoria datiIstruttoria, bool isRiapertura, ref bool isRidRetrPresent, ref bool isStoricoVisible,
            ref bool bSaveIstruttoria, ref bool isBeneficioAmianto181Present, ref GestioneNuoveLiquidate.NuoveLiquidate datiNuoveLiquidate,
            ref GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici datiMaggiorazioniBenefici, ref GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiPensioniDatiGenerici,
            ref GestioneDatiControlloFelpe.ControlloFelpe controlloFelpe, GestioneDatiStoricoGP.DatiStoricoGP datiStoricoGP, out object datiAGGPECO, out byte? numeroFigliOpzioneDonna, out string errori)
        {
            errori = string.Empty;
            datiAGGPECO = null;
            numeroFigliOpzioneDonna = null;

            // Per le ricostituzioni e le trasformazioni da provvisoria il valore di CPDPROV deve essere 0
            if (Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione || isRiapertura)
                if (dati.PL_CpdProv != 0)
                    throw new INPS.DNA.DnaValidationException("Domanda proveniente da Unicarpe non acquisibile per codice provvisorietà impostato.");

            #region Storico
            if ((Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione || isRiapertura) && prelievo != null)
            {
                isStoricoVisible = true;
            }
            #endregion Storico

            datiPensione.FlagUnicarpe = true;
            datiPensione.TipoLetturaUnicarpe = !String.IsNullOrEmpty(dati.PL_Funzione) ? Convert.ToChar(dati.PL_Funzione) : (char?)null;

            //ENG - Memo 06_2024
            GestioneControlliDinamici.ControlloDinamico controlloDinamicoAbilitazioneMemo06_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo06_2024", out controlloDinamicoAbilitazioneMemo06_2024);
            if (controlloDinamicoAbilitazioneMemo06_2024 != null && !String.IsNullOrEmpty(controlloDinamicoAbilitazioneMemo06_2024.ValoreControllo) &&
                controlloDinamicoAbilitazioneMemo06_2024.ValoreControllo.ToUpperInvariant() == "SI")
            {
                datiPensione.CodProPE = dati.PL_CodProPE;
            }

            #region Pensione

            if (dati.PL_Iniass.ToString().Length == 8)
                datiPensione.InizioAssicurazione = Utility.DataFromString(dati.PL_Iniass.ToString(), Utility.FormatoData.AAAAmmGG);
            else
                datiPensione.InizioAssicurazione = dati.PL_Iniass != 0 ? Utility.DataFromInt(short.Parse(dati.PL_Iniass.ToString().Substring(0, 4)),
                                                                                      short.Parse(dati.PL_Iniass.ToString().Substring(4, 2)), 1) : null;
            if (dati.PL_Finass.ToString().Length == 8)
                datiPensione.FineAssicurazione = Utility.DataFromString(dati.PL_Finass.ToString(), Utility.FormatoData.AAAAmmGG);
            else
                datiPensione.FineAssicurazione = dati.PL_Finass != 0 ? Utility.DataFromInt(short.Parse(dati.PL_Finass.ToString().Substring(0, 4)),
                                                                                    short.Parse(dati.PL_Finass.ToString().Substring(4, 2)), 1) : null;

            datiPensione.AttivitaEconomica = dati.PL_Att_econ != 0 ? dati.PL_Att_econ : (int?)null;
            datiPensione.ProfessioneIndividuale = dati.PL_Prof_indiv != 0 ? dati.PL_Prof_indiv : (int?)null;
            datiPensione.AttivitaEconomicaFELPE = dati.PL_Att_econ != 0 ? dati.PL_Att_econ : (int?)null;
            datiPensione.ProfessioneIndividualeFELPE = dati.PL_Prof_indiv != 0 ? dati.PL_Prof_indiv : (int?)null;

            if (Utility.IsGestioneLavoratriciMadri(datiPensione))
            {
                datiPensione.NumeroFigli = dati.PL_NumFigli == 0 ? (byte?)null : byte.Parse(dati.PL_NumFigli.ToString());
                datiPensione.SceltaLavMadri = dati.PL_SceltaLM == 0 ? (byte?)null : byte.Parse(dati.PL_SceltaLM.ToString());
                if (Utility.IsDomandaTipoContributivo(datiPensione, null, null))
                {
                    if (!String.IsNullOrEmpty(dati.PL_DatOPZ) && dati.PL_DatOPZ.Trim() != string.Empty)
                    {
                        if (dati.PL_DatOPZ.Trim().Length == 8)
                            datiPensione.DataOpzione = Utility.DataFromString(dati.PL_DatOPZ, Utility.FormatoData.AAAAmmGG);
                        else
                            datiPensione.DataOpzione = Utility.DataFromInt(short.Parse(dati.PL_DatOPZ.Substring(0, 4)), short.Parse(dati.PL_DatOPZ.Substring(4, 2)), 1);
                    }
                }
            }
            else
                numeroFigliOpzioneDonna = dati.PL_NumFigli == 0 ? (byte?)null : byte.Parse(dati.PL_NumFigli.ToString());

            if (Utility.IsDomandaConBeneficioAmianto181(datiPensione.AttivitaEconomica, datiPensione.ProfessioneIndividuale))
                datiPensione.Amianto181Unicarpe = true;

            // solo per funzione di lettura = "L", "H" o "G"
            if (!String.IsNullOrEmpty(dati.PL_Funzione) && (dati.PL_Funzione == "L" || dati.PL_Funzione == "H" || dati.PL_Funzione == "G" || dati.PL_Funzione == "A" || dati.PL_Funzione == "D"))
            {
                if (dati.PL_Decorre.ToString().Length == 8)
                    datiPensione.DecorrenzaOriginaria = Utility.DataFromString(dati.PL_Decorre.ToString(), Utility.FormatoData.AAAAmmGG);
                else
                    datiPensione.DecorrenzaOriginaria = dati.PL_Decorre != 0 ? Utility.DataFromInt(short.Parse(dati.PL_Decorre.ToString().Substring(0, 4)),
                                                                                            short.Parse(dati.PL_Decorre.ToString().Substring(4, 2)), 1) : null;

                if (!String.IsNullOrEmpty(dati.PL_Datreq) && dati.PL_Datreq.Trim() != string.Empty)
                {
                    if (dati.PL_Datreq.Trim().Length == 8)
                        datiPensione.DataPerfezionamentoRequisiti = datiPensione.DataPerfezionamentoRequisitiUnicarpe = Utility.DataFromString(dati.PL_Datreq, Utility.FormatoData.AAAAmmGG);
                    else
