                {
                    datiPensioniDatiGenerici.RiduzioneRetributiva = !String.IsNullOrEmpty(dati.PL_FlagRiduz) && !String.IsNullOrEmpty(dati.PL_FlagRiduz.Trim()) && dati.PL_FlagRiduz.Trim().ToUpperInvariant() == "S";
                    datiPensioniDatiGenerici.RiduzioneRetributivaPercentuale = !Utility.IsDoubleEquals(dati.PL_PercRiduz, 0.0) ? Convert.ToDecimal(dati.PL_PercRiduz) : (decimal?)null;
                    if (datiPensioniDatiGenerici.RiduzioneRetributiva)
