                    for (int i = 0; i < dati.aONERI.Length; i++)
                    {
                        if (!String.IsNullOrEmpty(dati.aONERI[i].PL_Scadenza.Trim()) && dati.aONERI[i].PL_CodGrup == "4900")
                        {
                            datiPensioniDatiGenerici.ScadenzaAssegno = Utility.DataFromInt(short.Parse(dati.aONERI[i].PL_Scadenza.Substring(0, 4)),
                                                                         short.Parse(dati.aONERI[i].PL_Scadenza.Substring(4, 2)), 1);
                            break;
                        }
                    }
                }
            }

            datiPensioniDatiGenerici.TipoCertificazioneFelpe = !string.IsNullOrEmpty(dati.PL_TipCert) ? dati.PL_TipCert.Trim() : null;
            if (Utility.IsDomandaVESO92_L92(datiPensione) || Utility.IsDomandaESPA_L26(datiPensione) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria))
            {
                datiPensioniDatiGenerici.ImportoLordoAllaDecorrenza = dati.PL_Importor != 0 ? (decimal)dati.PL_Importor : (decimal?)null;

                if (dati.aONERI != null && dati.aONERI.Length > 0 && !String.IsNullOrEmpty(dati.aONERI[0].PL_Scadenza.Trim()))
                {
                    if (dati.aONERI.Length == 8)
                    {
                        datiPensioniDatiGenerici.ScadenzaAssegno = Utility.DataFromInt(short.Parse(dati.aONERI[0].PL_Scadenza.Substring(0, 4)),
                                                 short.Parse(dati.aONERI[0].PL_Scadenza.Substring(4, 2)),
                                                 short.Parse(dati.aONERI[0].PL_Scadenza.Substring(6, 2)));
                    }
                    else
                    {
                        datiPensioniDatiGenerici.ScadenzaAssegno = Utility.DataFromInt(short.Parse(dati.aONERI[0].PL_Scadenza.Substring(0, 4)),
                                                                        short.Parse(dati.aONERI[0].PL_Scadenza.Substring(4, 2)), 1);
                    }
                }
            }

            if (datiPensioniDatiGenerici.Equals(new GestioneDatiGenericiAgoCi.PensioniDatiGenerici()))
                datiPensioniDatiGenerici = null;
            #endregion DatiGenericiAgo

            #region DatiControlloFelpe
            if (dati.PL_Iniziobonus != 0 || dati.PL_Finebonus != 0)
            {
                controlloFelpe = new GestioneDatiControlloFelpe.ControlloFelpe();
                if (dati.PL_Iniziobonus.ToString().Length == 8)
                    controlloFelpe.InizioBonus = Utility.DataFromString(dati.PL_Iniziobonus.ToString(), Utility.FormatoData.AAAAmmGG);
                else
                    controlloFelpe.InizioBonus = dati.PL_Iniziobonus != 0 ? Utility.DataFromInt(short.Parse(dati.PL_Iniziobonus.ToString().Substring(0, 4)),
                                                                                            short.Parse(dati.PL_Iniziobonus.ToString().Substring(4, 2)), 1) : null;
                if (dati.PL_Finebonus.ToString().Length == 8)
                    controlloFelpe.FineBonus = Utility.DataFromString(dati.PL_Finebonus.ToString(), Utility.FormatoData.AAAAmmGG);
                else
                    controlloFelpe.FineBonus = dati.PL_Finebonus != 0 ? Utility.DataFromInt(short.Parse(dati.PL_Finebonus.ToString().Substring(0, 4)),
                                                                                            short.Parse(dati.PL_Finebonus.ToString().Substring(4, 2)), 1) : null;
            }
            #endregion DatiControlloFelpe

            datiAGGPECO = dati;
        }

        private static bool RecuperaPLUnicarpe(ref GestionePensione.DatiPensione datiPensione, object prelievo, Utility.TipoAppartenenza? tipoAppartenenza, bool? isPLUnicarpeFromDB, bool? isPLPrepensionamentoEditoriaTipo0162FiltroEAA, bool? isPLPrepensionamentoEditoriaTipo0162FiltroEBA, bool? isPLESPAFiltroL26, bool? isPLVESO33FiltroDAP, ServiceReferences.WebDom.DatiDomanda datiDomanda, short sedeChiavePensione, bool isRiapertura, byte? numeroFigliOpzioneDonna, string codTipoRichiesta, out string gp1Af03, out string gp1Tipo, out string gp1Prodotto, out string gp1Gruppo, out bool isPLAnticipata0017, out bool isPLAnticipata0045PAV, out string errori)
        {
            errori = string.Empty;
            gp1Af03 = string.Empty;
            gp1Prodotto = string.Empty;
            gp1Tipo = string.Empty;
            gp1Gruppo = string.Empty;
            isPLAnticipata0017 = false;
            isPLAnticipata0045PAV = false;

            if (Utility.IsRicostituzione(datiPensione.Gruppo) || isRiapertura)
            {
                string categorieInpdap = datiPensione.SiglaCategoria.Trim().Substring(2);
                List<string> lCategorieInpdap = new List<string> { "CPDEL", "CPS", "CPI", "CPUG" };
                bool verificaGp1Freq1 = ((Utility.IsRicostituzione_MotiviContributivi(datiPensione) && !(datiDomanda != null && datiDomanda.Dati != null && datiDomanda.Dati.Fase != null && datiDomanda.Dati.Fase.Count > 0 &&
                        (datiDomanda.Dati.Fase.LastOrDefault().CodFase == "0033" || datiDomanda.Dati.Fase.LastOrDefault().CodFase == "0034" || datiDomanda.Dati.Fase.LastOrDefault().CodFase == "0035" || datiDomanda.Dati.Fase.LastOrDefault().CodFase == "0036" || datiDomanda.Dati.Fase.LastOrDefault().CodFase == "0038"))) || isRiapertura) &&
                        lCategorieInpdap.Exists(x => x == categorieInpdap) && (Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Not);

                if (isPLUnicarpeFromDB.HasValue && Utility.IsRicostituzione(datiPensione.Gruppo))
                    datiPensione.IsPLUnicarpe = isPLUnicarpeFromDB;

                string gp1Freq1 = string.Empty;
                string sede = string.Empty;
                string categoria = datiPensione.GetCodCategoria().Substring(1, 3);
                string certificato = datiPensione.NCertificato.ToString().PadLeft(8, '0');
                switch (tipoAppartenenza)
                {
                    case Utility.TipoAppartenenza.AGO:
                        if (Utility.IsGestioneENPALSConSedeDestinazione(datiPensione) || Utility.IsDomandaAPEPrecoci(datiPensione) || Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria))
                        {
                            ServiceReferences.LiquidazioneAgo.AreaPrelievo prelievoAgo = prelievo as ServiceReferences.LiquidazioneAgo.AreaPrelievo;
                            if (prelievoAgo != null && prelievoAgo.Risposta != null && prelievoAgo.Risposta.DatiPensione != null && prelievoAgo.Risposta.DatiPensione.CodiceSedeDestinazione != null &&
                                prelievoAgo.Risposta.DatiPensione.CodiceSedeDestinazione > 0)
                                sede = prelievoAgo.Risposta.DatiPensione.CodiceSedeDestinazione.ToString().PadLeft(4, '0');
                            else
                                sede = (Utility.IsPensioniOvunqueAttiva(Utility.TipoAppartenenza.AGO)) ? sedeChiavePensione.ToString().PadLeft(4, '0') : datiPensione.CodiceSede.ToString().PadLeft(4, '0');
                        }
                        else
                            sede = (Utility.IsPensioniOvunqueAttiva(Utility.TipoAppartenenza.AGO)) ? sedeChiavePensione.ToString().PadLeft(4, '0') : datiPensione.CodiceSede.ToString().PadLeft(4, '0');
                        break;
                    case Utility.TipoAppartenenza.FS:
                        ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFS = prelievo as ServiceReferences.LiquidazioneFs.AreaPrelievo;
                        if (prelievoFS != null && prelievoFS.Risposta != null && prelievoFS.Risposta.DatiPensione != null && prelievoFS.Risposta.DatiPensione.CodiceSedeDestinazione != null &&
                            prelievoFS.Risposta.DatiPensione.CodiceSedeDestinazione > 0)
                            sede = prelievoFS.Risposta.DatiPensione.CodiceSedeDestinazione.ToString().PadLeft(4, '0');
                        else
                            sede = (Utility.IsPensioniOvunqueAttiva(Utility.TipoAppartenenza.FS)) ? sedeChiavePensione.ToString().PadLeft(4, '0') : datiPensione.CodiceSede.ToString().PadLeft(4, '0');
                        break;
                    case Utility.TipoAppartenenza.CI:
                        ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoCI = prelievo as ServiceReferences.LiquidazioneCi.AreaPrelievo;
                        if (prelievoCI != null && prelievoCI.Risposta != null && prelievoCI.Risposta.DatiPensione != null && prelievoCI.Risposta.DatiPensione.CodiceSedeDestinazione != null &&
                            prelievoCI.Risposta.DatiPensione.CodiceSedeDestinazione > 0)
                            sede = prelievoCI.Risposta.DatiPensione.CodiceSedeDestinazione.ToString().PadLeft(4, '0');
                        else
                            sede = (Utility.IsPensioniOvunqueAttiva(Utility.TipoAppartenenza.CI)) ? sedeChiavePensione.ToString().PadLeft(4, '0') : datiPensione.CodiceSede.ToString().PadLeft(4, '0');
                        break;
                }
                string chiavePensione = categoria + sede + certificato;
                bool? isPLInvalidita;
                bool? isPLOpzioneDonnaFiltroKWA;
                bool? isPLOpzioneDonnaFiltroKXM;
                bool? isPLOpzioneDonnaFiltroKYA;
                bool? isPLOpzioneDonnaFiltroKZM;
                bool? isPLOpzioneDonnaFiltroKUA;
                bool? isPLOpzioneDonnaFiltroKVM;
                //ENG - Gestione RIC Anticipate Computo Senza Filtro PAV
                bool? isPLAnticipateComputoSenzaFiltroPAV;
                bool? isPLAnticipateComputoConFiltroPAV = false;
                //ENG - Gestione RIC Vecchiaia Computo
                bool? isPLVecchiaiaComputo = false;
                //ENG - Gestione RIC Vecchiaia Ordinario
                bool? isPlVecchiaiaOrdinario = false;
                //ENG - RIC Lavoratori Faticosi e Pesanti
                bool? isPLLavoratoriFaticosiEPesanti = false;
                //ENG - Memo 116/2025 
                bool? isVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE = false;
                bool? isVOAUTAnticipataTipoContributivoFiltroGSE = false;
                bool? isVOAUTVecchiaiaTipoContributivoFiltroGSE = false;
                //ENG - Memo 79/2025
                bool? isPLOIVecchiaiaInvaliditaFiltroC9A = false;
                bool? isPLOISuperstitiFiltroC9A = false;
                bool? isPLOIAnticipateFiltroC9A = false;
                //ENG - Memo 91/2026 
                bool? isPLCOOP28FiltroDAP = false;
                bool isDomandaCOOP28 = false;
                if (Utility.IsDomandaCOOP28(datiPensione.SiglaCategoria))
                    isDomandaCOOP28 = true;

                //ENG - VOPGI filtro L80
                bool? isRIcVopgiFiltroL80 = false;

                if (!GestioneDatiPensioni.GetDatiTGP1ByChiavePensione(datiPensione.NDomus, chiavePensione, codTipoRichiesta, out gp1Freq1, out isPLInvalidita, out isPLPrepensionamentoEditoriaTipo0162FiltroEAA, out isPLESPAFiltroL26, out isPLVESO33FiltroDAP,
                    out isPLOpzioneDonnaFiltroKWA, out isPLOpzioneDonnaFiltroKXM, out isPLOpzioneDonnaFiltroKYA, out isPLOpzioneDonnaFiltroKZM, out isPLOpzioneDonnaFiltroKUA, out isPLOpzioneDonnaFiltroKVM, out isPLAnticipateComputoSenzaFiltroPAV, out isPLAnticipateComputoConFiltroPAV, out isPLVecchiaiaComputo, out isPlVecchiaiaOrdinario, out gp1Af03, out gp1Tipo, out gp1Prodotto, out gp1Gruppo, out isPLAnticipata0017, out isPLLavoratoriFaticosiEPesanti,
                    out isVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE, out isVOAUTAnticipataTipoContributivoFiltroGSE, out isVOAUTVecchiaiaTipoContributivoFiltroGSE
                    , out isPLOIVecchiaiaInvaliditaFiltroC9A, out isPLOISuperstitiFiltroC9A, out isPLOIAnticipateFiltroC9A, out isPLCOOP28FiltroDAP, isDomandaCOOP28, out isRIcVopgiFiltroL80, out errori))
                    return false;

                //Eng - modifica su tutte e tre le linee (AGO, FS, CI) eliminare il seguente blocco in fase di prelievo: 
                //"E' necessaria la preventiva gestione del conto con l'applicazione UNICARPE"- memo 114_2022
                //per le domande INPDAP resta il controllo
                if (verificaGp1Freq1)
                {
                    if (gp1Freq1 == "2" || gp1Freq1 == "3" || gp1Freq1 == "4")
                    {
                        if (Utility.IsDomandaINPDAP(datiPensione.Gestione))
                        {
                            var label = "le procedure di diritto misura";
                            errori = "E' necessaria la preventiva gestione del conto con " + label;
                            return false;
                        }
                    }
                }

                if (Utility.IsRicostituzione(datiPensione.Gruppo))
                {
                    if (!isPLUnicarpeFromDB.HasValue)
                        datiPensione.IsPLUnicarpe = gp1Freq1 == "2";

                    datiPensione.IsPLInvalidita = isPLInvalidita;

                    if (isPLOpzioneDonnaFiltroKWA.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicOpzioneDonnaFiltroKWA;
                    else if (isPLOpzioneDonnaFiltroKXM.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicOpzioneDonnaFiltroKXM;
                    else if (isPLOpzioneDonnaFiltroKYA.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicOpzioneDonnaFiltroKYA;
                    else if (isPLOpzioneDonnaFiltroKZM.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicOpzioneDonnaFiltroKZM;
                    else if (isPLOpzioneDonnaFiltroKUA.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicOpzioneDonnaFiltroKUA;
                    else if (isPLOpzioneDonnaFiltroKVM.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicOpzioneDonnaFiltroKVM;
                    //ENG - Gestione RIC Anticipate Computo Senza Filtro PAV
                    else if (isPLAnticipateComputoSenzaFiltroPAV.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicAnticipateComputoSenzaFiltroPAV;
                    //ENG - Memo 116/2025
                    else if (isVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE;
                    else if (isVOAUTAnticipataTipoContributivoFiltroGSE.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicVOAUTAnticipataTipoContributivoFiltroGSE;
                    else if (isVOAUTVecchiaiaTipoContributivoFiltroGSE.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicVOAUTVecchiaiaTipoContributivoFiltroGSE;
                    //ENG - Memo 79 2025
                    else if (isPLOIVecchiaiaInvaliditaFiltroC9A.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicOIVecchiaiaInvaliditaFiltroC9A;
                    else if (isPLOISuperstitiFiltroC9A.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicOISuperstitiFiltroC9A;
                    else if (isPLOIAnticipateFiltroC9A.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicOIAnticipateFiltroC9A;
                    //
                    if (isPLPrepensionamentoEditoriaTipo0162FiltroEAA.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicPrepensionamentoEditoriaArt37L416_1981_LetteraA.GetHashCode();
                    else if (Utility.IsDomandaESPA(datiPensione.SiglaCategoria) && isPLESPAFiltroL26.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicESPAFiltroL26.GetHashCode();
                    else if (Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) && isPLVESO33FiltroDAP.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicVESO33FiltroDAP.GetHashCode();
                    else if (isDomandaCOOP28 && isPLCOOP28FiltroDAP.GetValueOrDefault())
                        datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicCOOP28FiltroDAP.GetHashCode();
                }

                //ENG - Gestione TRF Anticipate Computo Senza Filtro PAV
                if (isRiapertura && isPLAnticipateComputoSenzaFiltroPAV.GetValueOrDefault() && !string.IsNullOrEmpty(codTipoRichiesta) && codTipoRichiesta != "AV")
                    datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicAnticipateComputoSenzaFiltroPAV;

                //ENG - RIC/TRF Anticipate Computo Con Filtro PAV
                if (isPLAnticipateComputoConFiltroPAV.GetValueOrDefault())
                {
                    datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicAnticipateComputoConFiltroPAV;
                    isPLAnticipata0045PAV = true;
                }

                //ENG - Gestione RIC/TRF Vecchiaia Computo
                if ((isRiapertura || Utility.IsRicostituzione(datiPensione.Gruppo)) && isPLVecchiaiaComputo.GetValueOrDefault())
                    datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicVecchiaiaComputo;

                //ENG - Gestione RIC Vecchiaia Ordinario
                if (Utility.IsRicostituzione(datiPensione.Gruppo) && isPlVecchiaiaOrdinario.GetValueOrDefault())
                    datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicVecchiaiaOrdinario;

                //ENG - RIC Lavoratori Faticosi e Pesanti
                if (Utility.IsRicostituzione(datiPensione.Gruppo) && isPLLavoratoriFaticosiEPesanti.GetValueOrDefault())
                    datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicLavoratoriFaticosiEPesanti;

                //ENG - RIC VOPGI filtro L80
                if (Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) && isRIcVopgiFiltroL80.HasValue && isRIcVopgiFiltroL80.Value)
                    datiPensione.IdTipoPLPerRIC = (byte)Utility.TipoPLPerRIC.RicVOPGIFiltroL80;

            }

            if (Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true) ||
                Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione) || Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione))
                datiPensione.NumeroFigli = numeroFigliOpzioneDonna;



            return true;
        }

        private static void GetDatiLavoratriciMadriFromInternet(DatiDPI datiInternet, bool isRiapertura, ref GestionePensione.DatiPensione datiPensione)
        {
            try
            {
                if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) && datiInternet != null && datiInternet.domanda != null)
                {
                    if (!string.IsNullOrEmpty(datiInternet.domanda.NumFigliMaggiorazioneCoeff))
                    {
                        //se numFigliMaggiorazioneCoeff = 1 allora per i nostri campi “Numero figli” = 1 e “Lavoratrici madri” = “Coefficiente più favorevole”
                        //se numFigliMaggiorazioneCoeff = 2 allora per i nostri campi “Numero figli” = 2 e “Lavoratrici madri” = “Coefficiente più favorevole”
                        //se numFigliMaggiorazioneCoeff = 99 allora per i nostri campi “Numero figli” = 3 e “Lavoratrici madri” = “Coefficiente più favorevole”
                        switch (datiInternet.domanda.NumFigliMaggiorazioneCoeff.Trim())
                        {
                            case "1":
                                datiPensione.NumeroFigli = 1;
                                datiPensione.SceltaLavMadri = 2;
                                break;
                            case "2":
                                datiPensione.NumeroFigli = 2;
                                datiPensione.SceltaLavMadri = 2;
                                break;
                            case "99":
                                datiPensione.NumeroFigli = 3;
                                datiPensione.SceltaLavMadri = 2;
                                break;
                        }
                    }
                    if (!string.IsNullOrEmpty(datiInternet.domanda.NumFigliEtaPens))
                    {
                        //se numFigliEtaPens = 1 allora per i nostri campi “Numero figli” = 1 e “Lavoratrici madri” = “Anticipo età pensionabile”
                        //se numFigliEtaPens = 2 allora per i nostri campi “Numero figli” = 2 e “Lavoratrici madri” = “Anticipo età pensionabile”
                        //se numFigliEtaPens = 99 allora per i nostri campi “Numero figli” = 3 e “Lavoratrici madri” = “Anticipo età pensionabile”
                        switch (datiInternet.domanda.NumFigliEtaPens.Trim())
                        {
                            case "1":
                                datiPensione.NumeroFigli = 1;
                                datiPensione.SceltaLavMadri = 1;
                                break;
                            case "2":
                                datiPensione.NumeroFigli = 2;
                                datiPensione.SceltaLavMadri = 1;
                                break;
                            case "99":
                                datiPensione.NumeroFigli = 3;
                                datiPensione.SceltaLavMadri = 1;
                                break;
                        }
                    }
                }
            }
            catch (Exception) { }
        }

        private static void GetNumeroFigliOpzioneDonnaFromInternet(DatiDPI datiInternet, bool isRiapertura, ref GestionePensione.DatiPensione datiPensione)
        {
            try
            {
                if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) && datiInternet != null && datiInternet.domanda != null)
                {
                    if (!string.IsNullOrEmpty(datiInternet.domanda.NumFigliEtaPens))
                    {
                        //se numFigliEtaPens = 1 allora per i nostri campi “Numero figli” = 1
                        //se numFigliEtaPens = 2 allora per i nostri campi “Numero figli” = 2 
                        //se numFigliEtaPens = 99 allora per i nostri campi “Numero figli” = 3
                        switch (datiInternet.domanda.NumFigliEtaPens.Trim())
                        {
                            case "1":
                                datiPensione.NumeroFigli = 1;
                                break;
                            case "2":
                                datiPensione.NumeroFigli = 2;
                                break;
                            case "99":
                                datiPensione.NumeroFigli = 3;
                                break;
                        }
                    }
                }
            }
            catch (Exception) { }
        }

        private static void CheckAttivitaForINPDAP(DataSetDomanda.AttivitaDataTable listaAttivita, out bool isFlussoAmg, out Utility.TipoFelpe? isFlussoAmgSin)
        {
            isFlussoAmg = false;
            isFlussoAmgSin = null;
            if (listaAttivita == null || listaAttivita.Rows == null || listaAttivita.Rows.Count == 0)
                return;

            var filtered = listaAttivita.Where(x => x["CodAttivita"] != DBNull.Value &&
                !string.IsNullOrEmpty(x["CodAttivita"].ToString()) &&
                (int.Parse(x["CodAttivita"].ToString()) == (int)GestioneWebDom.CodiceAttivita.InTrattazioneUnicarpe ||
                int.Parse(x["CodAttivita"].ToString()) == (int)GestioneWebDom.CodiceAttivita.AccoglimentoSIN ||
                int.Parse(x["CodAttivita"].ToString()) == (int)GestioneWebDom.CodiceAttivita.InTrattazioneSPI)).ToList();

            if (filtered != null && filtered.Count > 0)
            {
                var ordered = filtered.OrderByDescending(x => x.ProgFase).ThenByDescending(y => y.ProgAttivita);
                if (int.Parse(ordered.FirstOrDefault()["CodAttivita"].ToString()) == (int)GestioneWebDom.CodiceAttivita.AccoglimentoSIN)
                    isFlussoAmgSin = Utility.TipoFelpe.SIN;
                else if (int.Parse(ordered.FirstOrDefault()["CodAttivita"].ToString()) == (int)GestioneWebDom.CodiceAttivita.InTrattazioneSPI)
                    isFlussoAmgSin = Utility.TipoFelpe.SPI;

                if (filtered.Exists(y => y["CodAttivita"] != DBNull.Value &&
                     !string.IsNullOrEmpty(y["CodAttivita"].ToString()) &&
                     int.Parse(y["CodAttivita"].ToString()) == (int)GestioneWebDom.CodiceAttivita.InTrattazioneUnicarpe
                    //&& y["DataFine"] != DBNull.Value && !string.IsNullOrEmpty(y["DataFine"].ToString())
                     ))
                    isFlussoAmg = true;
            }
        }

