        private static void GetListaCausaCessazione(GestionePensione.DatiPensione datiPensione, ref List<GestioneDecodifica.DecodificaCausaCessazione> listaCodiceCausaCessazioneDB)
        {
            char codNatura1, codNatura2, codNatura3;
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(Utility.TipoAppartenenza.FS, datiPensione.SiglaCategoria);

            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNatura1, out codNatura2, out codNatura3);

            if (listaCodiceCausaCessazioneDB != null)
            {
                if (tipoFondo.HasValue)
                {
                    switch (tipoFondo.Value)
                    {
                        case Utility.TipoFondo.FS:
                            if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001")    //Anzianità. Ritorniamo alla web solo i record con TipoPensione A
                                listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == tipoFondo.Value.ToString() && x.TipoPensione == 'A');
                            else if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002")    //Vecchiaia. Ritorniamo alla web solo i record con TipoPensione V
                                listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == tipoFondo.Value.ToString() && x.TipoPensione == 'V');
                            else if (datiPensione.Gruppo == "0003")    //Reversibilità. Ritorniamo alla web solo i record con TipoPensione S
                                listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == tipoFondo.Value.ToString() && x.TipoPensione == 'S');
                            else if (datiPensione.Gruppo == "0002")    //Invalidità. Ritorniamo alla web solo i record con TipoPensione I
                                listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == tipoFondo.Value.ToString() && x.TipoPensione == 'I');
                            else
                                listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == "FS");
                            break;
                        case Utility.TipoFondo.PT:
                            listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == tipoFondo.Value.ToString());
                            break;
                    }
                }
                else if (Utility.IsDomandaINPDAP(datiPensione.Gestione))
                {
                    if (
                        (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001") ||  //Anzianità. Ritorniamo alla web solo i record con TipoPensione A 
                        (datiPensione.Gruppo == "0031" && datiPensione.SiglaCategoria.StartsWith("V") && (codNatura1 == '1' || codNatura1 == '2'))
                       )
                        listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == "DAP" && x.TipoPensione == 'A');
                    else if (
                        (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002") ||   //Vecchiaia. Ritorniamo alla web solo i record con TipoPensione V
                        (datiPensione.Gruppo == "0031" && datiPensione.SiglaCategoria.StartsWith("V") && (codNatura1 == ' ' || codNatura1 == '6'))
                            )
                        listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == "DAP" && x.TipoPensione == 'V');
                    else if (
                        (datiPensione.Gruppo == "0003") ||   //Reversibilità. Ritorniamo alla web solo i record con TipoPensione S
                        (datiPensione.Gruppo == "0031" && datiPensione.SiglaCategoria.StartsWith("S"))
                            )
                        listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == "DAP" && x.TipoPensione == 'S');
                    else if (
                        (datiPensione.Gruppo == "0002") ||   //Invalidità. Ritorniamo alla web solo i record con TipoPensione I
                        (datiPensione.Gruppo == "0031" && datiPensione.SiglaCategoria.StartsWith("I"))
                            )
                        listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == "DAP" && x.TipoPensione == 'I');
                    else
                        listaCodiceCausaCessazioneDB = listaCodiceCausaCessazioneDB.FindAll(x => x.Fondo == "DAP");
                }



            }
        }

        private static bool RecuperaDatiTGP1(ref GestionePensione.DatiPensione datiPensione, object prelievo, Utility.TipoAppartenenza? tipoAppartenenza, short sedeChiavePensione, bool isRiapertura, int numeroCertificato, out string errori)
        {
            errori = string.Empty;

            if ((Utility.IsRicostituzione(datiPensione.Gruppo) || isRiapertura) && Utility.IsPensioniOvunqueAttiva(tipoAppartenenza) && (tipoAppartenenza == Utility.TipoAppartenenza.FS || tipoAppartenenza == Utility.TipoAppartenenza.CI))
            {
                INPS.Pensioni.Liquidazione.ServiceReferences.DatiPensioni.DatiTGP1Response risposta = null;
                string sede = string.Empty;
                string categoria = datiPensione.GetCodCategoria().Substring(1, 3);
                string certificato = numeroCertificato.ToString().PadLeft(8, '0');
                short sedeGP1ALZ6 = 0;
                byte centroOperativoGP1ALZ6 = 0;
                short gp1av11 = 0;
                switch (tipoAppartenenza)
                {
                    case Utility.TipoAppartenenza.FS:
                        ServiceReferences.LiquidazioneFs.AreaPrelievo prelievoFS = prelievo as ServiceReferences.LiquidazioneFs.AreaPrelievo;
                        if (prelievoFS != null && prelievoFS.Risposta != null && prelievoFS.Risposta.DatiPensione != null && prelievoFS.Risposta.DatiPensione.CodiceSedeDestinazione != null &&
                            prelievoFS.Risposta.DatiPensione.CodiceSedeDestinazione > 0)
                            sede = prelievoFS.Risposta.DatiPensione.CodiceSedeDestinazione.ToString().PadLeft(4, '0');
                        else
                            sede = sedeChiavePensione.ToString().PadLeft(4, '0');
                        break;
                    case Utility.TipoAppartenenza.CI:
                        ServiceReferences.LiquidazioneCi.AreaPrelievo prelievoCI = prelievo as ServiceReferences.LiquidazioneCi.AreaPrelievo;
                        if (prelievoCI != null && prelievoCI.Risposta != null && prelievoCI.Risposta.DatiPensione != null && prelievoCI.Risposta.DatiPensione.CodiceSedeDestinazione != null &&
                            prelievoCI.Risposta.DatiPensione.CodiceSedeDestinazione > 0)
                            sede = prelievoCI.Risposta.DatiPensione.CodiceSedeDestinazione.ToString().PadLeft(4, '0');
                        else
                            sede = sedeChiavePensione.ToString().PadLeft(4, '0');
                        break;
                }
                string chiavePensione = categoria + sede + certificato;

                if (!GestioneDatiPensioni.GetDatiTGP1ByChiavePensione(datiPensione.NDomus.ToString(), chiavePensione, out risposta, out errori))
                    return false;

                if (risposta != null && risposta.ElementoDatiTGP1 != null)
                {
                    if (risposta.ElementoDatiTGP1.GP1ALZ6 != null && risposta.ElementoDatiTGP1.GP1ALZ6.Valore != null && !String.IsNullOrEmpty(risposta.ElementoDatiTGP1.GP1ALZ6.Valore.Codice)
                        && risposta.ElementoDatiTGP1.GP1ALZ6.Valore.Codice.Length == 6)
                    {
                        short.TryParse(risposta.ElementoDatiTGP1.GP1ALZ6.Valore.Codice.Substring(0, 4), out sedeGP1ALZ6);
                        byte.TryParse(risposta.ElementoDatiTGP1.GP1ALZ6.Valore.Codice.Substring(4, 2), out centroOperativoGP1ALZ6);
                        datiPensione.CodiceSedeGP1ALZ6 = sedeGP1ALZ6;
                        datiPensione.CentroOperativoGP1ALZ6 = centroOperativoGP1ALZ6;
                    }

                    if (risposta.ElementoDatiTGP1.GP1AV11 != null && risposta.ElementoDatiTGP1.GP1AV11.Valore != null && !String.IsNullOrEmpty(risposta.ElementoDatiTGP1.GP1AV11.Valore.Codice))
                    {
                        short.TryParse(risposta.ElementoDatiTGP1.GP1AV11.Valore.Codice, out gp1av11);
                        datiPensione.GP1AV11 = gp1av11;
                    }
                }
            }

            return true;
        }
        #endregion private members
    }
